const V3_STAMP_PAGES = new Set(["home", "projets", "services", "agence", "journal", "contact"]);
function v3PathToPageId(path: string): string | undefined {
  const seg = String(path).split(".");
  if (seg[0] !== "v3") return undefined;
  if (seg[1] === "meta") return V3_STAMP_PAGES.has(seg[2]) ? `v3-${seg[2]}` : undefined;
  if (seg[1] === "cfg") return seg[2] === "nav" && seg[3] === "hide" && V3_STAMP_PAGES.has(seg[4]) ? `v3-${seg[4]}` : undefined;
  if (seg[1] === "work") return "v3-projets";                                           
  if (seg[1] === "service" || seg[1] === "services") return "v3-services";
  return V3_STAMP_PAGES.has(seg[1]) ? `v3-${seg[1]}` : undefined;
}

function useNowMs(intervalMs = 60000) {
  const [nowMs, setNowMs] = useState(APP_BOOT_NOW_MS);
  useEffect(() => {
    const tick = () => setNowMs(Date.now());
    tick();
    const id = window.setInterval(tick, intervalMs);
    return () => window.clearInterval(id);
  }, [intervalMs]);
  return nowMs;
}

                                                                                                                                          
                                                     
                                                             
                                                                                                                                             
