type View = "home" | "homev2" | "homev3" | "projects" | "project" | "expertises" | "atelier" | "blog" | "contact" | "briefing" | "legal" | "privacy" | "cookies" | "dashboard" | "login" | "admin" | "apresentacao" | "proposta";

                                                                               
function slugifyProject(name: string): string {
  return name
    .toLowerCase()
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .replace(/[^a-z0-9\s-]/g, "")
    .trim()
    .replace(/\s+/g, "-")
    .replace(/-+/g, "-");
}

type ProjectRouteLike = {
  id?: string;
  slug?: string;
  title?: string;
  nome?: string;
  titleByLang?: Partial<Record<Lang, string>>;
};

function projectRouteCandidateValues(project: ProjectRouteLike, lang?: Lang): string[] {
  const values = [
    project.slug,
    lang ? project.titleByLang?.[lang] : undefined,
    project.title,
    project.nome,
    ...Object.values(project.titleByLang ?? {}),
    project.id,
  ];
  return Array.from(new Set(values.map((value) => String(value || "").trim()).filter(Boolean)));
}

function projectMatchesRouteToken(project: ProjectRouteLike, token: string | null | undefined, lang?: Lang): boolean {
  const raw = String(token || "").trim();
  if (!raw) return false;
  let decoded = raw;
  try { decoded = decodeURIComponent(raw); } catch {                }
  const decodedSlug = slugifyProject(decoded);
  return projectRouteCandidateValues(project, lang).some((candidate) => {
    return candidate === decoded || candidate === raw || slugifyProject(candidate) === decodedSlug;
  });
}

function projectRouteSlug(project: ProjectRouteLike, lang?: Lang): string {
  const preferred = projectRouteCandidateValues(project, lang)
    .find((candidate) => candidate !== project.id && candidate !== project.slug) || project.slug || project.id || "project";
  return slugifyProject(preferred) || "project";
}

function findProjectByRouteToken(token: string, lang?: Lang): ProjectRouteLike | null {
  const value = String(token || "").trim();
  if (!value) return null;
  const allProjects: ProjectRouteLike[] = [
    ...TRAVAUX_DESTAQUE.map((p) => ({ id: p.id, nome: p.nome })),
    ...PROJETS_TODOS.map((p) => ({ nome: p.nome })),
  ];
  try {
    const dashRaw = typeof window !== "undefined" ? window.localStorage.getItem("abil_projects_v3") : null;
    if (dashRaw) {
      const dashList = JSON.parse(dashRaw) as ProjectRouteLike[];
      if (Array.isArray(dashList)) allProjects.push(...dashList);
    }
  } catch {            }
  return allProjects.find((project) => projectMatchesRouteToken(project, value, lang)) || null;
}

function resolveProjectSlugFromRouteToken(token: string, lang?: Lang): string {
  const value = String(token || "").trim();
  const found = findProjectByRouteToken(value, lang);
  return projectRouteSlug(found || { title: value }, lang);
}

