function deepMerge<T extends Record<string, any>>(base: T, override: Partial<T> | undefined): T {
  if (!override) return base;
  const out: any = { ...base };
  for (const k of Object.keys(override)) {
    const ov = (override as any)[k];
    const bv = (base as any)[k];
    if (ov && typeof ov === "object" && !Array.isArray(ov) && bv && typeof bv === "object" && !Array.isArray(bv)) {
      out[k] = deepMerge(bv, ov);
    } else if (ov !== undefined) {
      out[k] = ov;
    }
  }
  return out;
}

                                                                                  
const NATIVE_DASH_LANGS = ["fr", "de", "en", "pt", "it"];
const _trInFlight = new Set<string>();
                                                                                                           
                                                                                                       
function _makeTrProxy(obj: any, fromLang: Lang, toLang: Lang): any {
  if (obj == null || typeof obj !== "object") return obj;
  return new Proxy(obj, {
    get(target, prop, receiver) {
      const v = Reflect.get(target, prop, receiver);
      if (typeof v === "string") {
        if (!v.trim()) return v;
        const c = getCachedTranslation(v, toLang);
        if (c) return c;
        const key = toLang + "|" + v;
        if (typeof window !== "undefined" && !_trInFlight.has(key)) {
          _trInFlight.add(key);
          translateTextCached(v, fromLang, toLang).then(() => window.dispatchEvent(new CustomEvent("abil:translation"))).catch(() => {       });
        }
        return v;
      }
      if (typeof v === "function") {
                                                                                                         
        return (...args: any[]) => {
          const out = v.apply(target, args);
          if (typeof out !== "string" || !out.trim()) return out;
          const c2 = getCachedTranslation(out, toLang);
          if (c2) return c2;
          const k2 = toLang + "|" + out;
          if (typeof window !== "undefined" && !_trInFlight.has(k2)) {
            _trInFlight.add(k2);
            translateTextCached(out, fromLang, toLang).then(() => window.dispatchEvent(new CustomEvent("abil:translation"))).catch(() => {       });
          }
          return out;
        };
      }
      if (v && typeof v === "object") return _makeTrProxy(v, fromLang, toLang);
      return v;
    },
  });
}
                                                                                                             
                                                                                                            
                                                                                        
function _trO(o: any, lang: Lang): string {
  if (!o) return "";
  const direct = o[lang];
  if (NATIVE_DASH_LANGS.indexOf(lang) >= 0) return (direct ?? o.fr ?? o.pt ?? o.en ?? "");
  if (typeof direct === "string" && direct) return direct;
  const src = (o.pt || o.fr || o.en || o.de || o.it || "") as string;
  if (!src) return (typeof direct === "string" ? direct : "");
  const c = getCachedTranslation(src, lang);
  if (c) return c;
  const key = lang + "|" + src;
  if (typeof window !== "undefined" && !_trInFlight.has(key)) {
    _trInFlight.add(key);
    const from: Lang = (o.pt ? "pt" : o.fr ? "fr" : "en") as Lang;
    translateTextCached(src, from, lang).then(() => window.dispatchEvent(new CustomEvent("abil:translation"))).catch(() => {       });
  }
  return src;
}
function useMod() {
  const { t, lang } = useApp();
  const fr = (DICT as any).fr.dashboard.mod;
  const cur = (t.dashboard as any)?.mod;
  if (NATIVE_DASH_LANGS.indexOf(lang) < 0 && cur) return cur;
  return cur ? deepMerge(fr, cur) : fr;
}

                                                                                                                                          
                                                  
                                                                                                                                             
function useLocalStorageState<T>(key: string, initial: T): [T, (v: T | ((p: T) => T)) => void] {
                                                             
                                                                                          
                                                                    
  if (PUBLIC_CLOUD_KEY_SET.has(key)) {
    // eslint-disable-next-line react-hooks/rules-of-hooks
    return useCloudState<T>(key, initial);
  }
                                                                                                    
                                                                                                      
                                                                                                         
  if (key === "abil_crm_leads") {
    // eslint-disable-next-line react-hooks/rules-of-hooks
    return useLeadsIDBState<T>(initial);
  }
  if (VAULT_KEY_SET.has(key)) {
    // eslint-disable-next-line react-hooks/rules-of-hooks
    return useVaultState<T>(key, initial);
  }
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const [state, setState] = useState<T>(() => {
    try {
      const raw = typeof window !== "undefined" ? window.localStorage.getItem(key) : null;
      if (raw === null) return initial;
      const parsed = JSON.parse(raw) as T;
      if (parsed === null && initial !== null && initial !== undefined) return initial;
      return parsed;
    } catch {
      return initial;
    }
  });
                                                                               
                                                                                
                                                                           
                                                                                 
                                                                                   
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const isFirstWrite = useRef(true);
  // eslint-disable-next-line react-hooks/rules-of-hooks
  useEffect(() => {
    if (isFirstWrite.current) {
      isFirstWrite.current = false;
      return;                                                                        
    }
    const tryWrite = (retries = 0): void => {
      try {
        const json = JSON.stringify(state);
        window.localStorage.setItem(key, json);
      } catch (err: any) {
        const isQuota = /quota|exceeded|maximum/i.test(String(err?.name || err?.message || err));
        if (isQuota && retries === 0) {
                                                                                                                      
          const PURGEABLE = ["abil_blog_drafts", "abil_social_calendar", "abil_blog_autoplan_v2", "abil_social_autoplan_li", "abil_social_autoplan_ig", "abil_email_autoplan"];
          let purgedBytes = 0;
          for (const purgeKey of PURGEABLE) {
            if (purgeKey === key) continue;
            const v = localStorage.getItem(purgeKey);
            if (v) { purgedBytes += v.length; localStorage.removeItem(purgeKey); }
          }
          const transKeys: string[] = [];
          for (let i=0; i<localStorage.length; i++) { const k = localStorage.key(i); if (k?.startsWith("trans_")) transKeys.push(k); }
          transKeys.forEach((k) => { purgedBytes += (localStorage.getItem(k)||'').length; localStorage.removeItem(k); });
          console.warn(`[useLocalStorageState] Quota exceeded, auto-purged ${(purgedBytes/1024).toFixed(0)}KB (blog/social/translation caches). Retrying save...`);
          tryWrite(1);
          return;
        }
        if (typeof window !== "undefined") {
          const msg = isQuota
            ? `localStorage cheio mesmo após purge, '${key}' não foi gravado. Limpe localStorage manual via DevTools > Application.`
            : `Erro ao gravar '${key}': ${String(err?.message || err).slice(0, 100)}`;
          console.error("[useLocalStorageState]", msg, err);
          try {
            window.dispatchEvent(new CustomEvent("abil:storage-error", { detail: { key, error: msg } }));
          } catch {            }
        }
      }
    };
    tryWrite();
  }, [key, state]);

  return [state, setState];
}

                                                                     
                                                                           
                                                                             
                                                                            
                                                                     
                                                                      
                                                                     
                                                                                
                                                                                
                                                                 
const DEFAULT_ENABLED_LANGS: Lang[] = ["fr", "en", "pt", "de", "it"];

const LANGS_LS_KEY = "abil_enabled_langs";
                                                                              
                                                                             
const LANGS_EVENT = "abil:enabled-langs";
                                                                                   
let _siteLangsHydrating = false;
function hydrateEnabledLangsFromServer() {
  if (_siteLangsHydrating) return;
  _siteLangsHydrating = true;
  fetchSiteLangs()
    .then((langs) => {
      if (!langs || !langs.length) return;
      try {
        window.localStorage.setItem(LANGS_LS_KEY, JSON.stringify(langs));
        window.dispatchEvent(new CustomEvent(LANGS_EVENT, { detail: langs }));
      } catch {
                    
      }
    })
    .catch(() => {
                                                    
    });
}

                                                                           
                                                                              
                                                                               
                                                                         
function useEnabledLanguages(): {
  enabled: Lang[];
  isEnabled: (l: Lang) => boolean;
  toggle: (l: Lang) => Promise<boolean>;
} {
  const [enabled, setEnabled] = useLocalStorageState<Lang[]>(LANGS_LS_KEY, DEFAULT_ENABLED_LANGS);
  useEffect(() => {
    hydrateEnabledLangsFromServer();
    const onUpdate = (e: Event) => {
      const detail = (e as CustomEvent).detail;
      if (Array.isArray(detail)) setEnabled(detail as Lang[]);
    };
    window.addEventListener(LANGS_EVENT, onUpdate);
    return () => window.removeEventListener(LANGS_EVENT, onUpdate);
  }, [setEnabled]);
  const isEnabled = (l: Lang) => enabled.includes(l);
                                                                                                     
                                                                                                         
                                                                                                        
                                                                                                       
  const toggle = async (l: Lang): Promise<boolean> => {
    if (l === "fr") return true;                                         
    const prev = enabled;
    const next = enabled.includes(l) ? enabled.filter((x) => x !== l) : [...enabled, l];
    setEnabled(next);
    try { window.dispatchEvent(new CustomEvent(LANGS_EVENT, { detail: next })); } catch {              }
    const ok = await saveSiteLangs(next as SiteLang[]);
    if (!ok) {
      setEnabled(prev);
      try { window.dispatchEvent(new CustomEvent(LANGS_EVENT, { detail: prev })); } catch {              }
    }
    return ok;
  };
  return { enabled, isEnabled, toggle };
}

                                                                                                                                          
                                                                         
                                                                                     
                                                                        
                                                                         
                                             
                                                                                                                                             
const PROJECTS_IDB_NAME = "abil-projects-db";
const PROJECTS_IDB_STORE = "projects";
const PROJECTS_IDB_KEY = "v1";
const PROJECTS_BC_NAME = "abil-projects-sync";

function idbOpen(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open(PROJECTS_IDB_NAME, 1);
    req.onupgradeneeded = () => {
      const db = req.result;
      if (!db.objectStoreNames.contains(PROJECTS_IDB_STORE)) {
        db.createObjectStore(PROJECTS_IDB_STORE);
      }
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

                                                                             
                                                                               
                                                                                      
                                                                           
function normalizeProject(p: any): DashboardProject {
  if (!p || typeof p !== "object") {
    return { id: `id-${Math.random().toString(36).slice(2, 10)}`, title: "", categories: [], assets: [] } as DashboardProject;
  }
  return {
    ...p,
    id: typeof p.id === "string" && p.id ? p.id : `id-${Math.random().toString(36).slice(2, 10)}`,
    title: typeof p.title === "string" ? p.title : "",
    categories: Array.isArray(p.categories) ? p.categories : [],
    assets: Array.isArray(p.assets) ? p.assets : [],
    teamIds: Array.isArray(p.teamIds) ? p.teamIds : (p.teamIds === undefined ? undefined : []),
    publishedAt: p.publishedAt || undefined,
  } as DashboardProject;
}

function normalizeProjects(arr: any): DashboardProject[] {
  if (!Array.isArray(arr)) return [];
  return arr.map(normalizeProject);
}

                                                                                 
                                                                                     
                                                                                        
                                                                                   
async function compressDataUrl(src: string, maxDim = 1280, quality = 0.82): Promise<string> {
  try {
    if (!src || (!src.startsWith("data:") && !src.startsWith("blob:"))) return src;
    if (typeof document === "undefined") return src;
    const img = await new Promise<HTMLImageElement>((resolve, reject) => {
      const im = new Image();
      im.onload = () => resolve(im);
      im.onerror = reject;
      im.src = src;
    });
    const scale = Math.min(1, maxDim / Math.max(img.naturalWidth || maxDim, img.naturalHeight || maxDim));
    const w = Math.max(1, Math.round((img.naturalWidth || maxDim) * scale));
    const h = Math.max(1, Math.round((img.naturalHeight || maxDim) * scale));
    const canvas = document.createElement("canvas");
    canvas.width = w; canvas.height = h;
    const ctx = canvas.getContext("2d");
    if (!ctx) return src;
    ctx.drawImage(img, 0, 0, w, h);
    const out = canvas.toDataURL("image/jpeg", quality);
    return out && out.length < src.length ? out : src;
  } catch { return src; }
}

                                                                                                      
                                                                                                  
                                                        
async function readImageFileCompressed(file: File, maxDim = 1920, quality = 0.82): Promise<string> {
  const raw: string = await new Promise((res, rej) => { const r = new FileReader(); r.onload = () => res(String(r.result || "")); r.onerror = rej; r.readAsDataURL(file); });
  if (!raw.startsWith("data:image")) return raw;                                                 
  try { return await compressDataUrl(raw, maxDim, quality); } catch { return raw; }
}

async function idbGetProjects(): Promise<DashboardProject[] | null> {
  try {
    const db = await idbOpen();
    return await new Promise<DashboardProject[] | null>((resolve, reject) => {
      const tx = db.transaction(PROJECTS_IDB_STORE, "readonly");
      const req = tx.objectStore(PROJECTS_IDB_STORE).get(PROJECTS_IDB_KEY);
                                                                                    
      req.onsuccess = () => {
        const raw = req.result as DashboardProject[] | undefined;
        if (!raw) { resolve(null); return; }
        const normalized = normalizeProjects(raw);
                                                                                         
                                                                                  
        import("@/lib/localAssetStore")
          .then((m) => m.hydrateProjectRefs(normalized))
          .then(() => resolve(normalized))
          .catch(() => resolve(normalized));
      };
      req.onerror = () => reject(req.error);
    });
  } catch { return null; }
}

                                                                            
                                                                               
                                                                            
                                                                                
const IDB_INLINE_BUDGET_BYTES = 8 * 1024 * 1024;                             

function measureInlineBase64(projects: DashboardProject[]): { bytes: number; fields: number } {
  let bytes = 0, fields = 0;
  for (const p of projects) {
    for (const obj of [p.cover, ...(p.assets || [])]) {
      if (!obj) continue;
      for (const f of MIGRATE_ASSET_FIELDS) {
        const v = (obj as any)[f];
        if (isInlineBase64(v)) { fields++; bytes += approxBase64Bytes(v); }
      }
    }
  }
  return { bytes, fields };
}

async function idbSetProjects(projects: DashboardProject[]): Promise<void> {
                                                                               
                                                                                
  try {
    const { bytes, fields } = measureInlineBase64(projects);
    if (bytes > IDB_INLINE_BUDGET_BYTES && typeof console !== "undefined") {
      const budgetMB = (IDB_INLINE_BUDGET_BYTES / 1024 / 1024).toFixed(0);
      console.warn(
        `[storage guard] IndexedDB contains ${(bytes / 1024 / 1024).toFixed(1)}MB of inline base64 ` +
        `across ${fields} fields, budget ${budgetMB}MB. ` +
        `Run window.__abilMigrateAssets() while Blob storage is active.`
      );
    }
  } catch {                                         }
  const db = await idbOpen();
                                                                             
                                                                              
  let toStore: DashboardProject[] = projects;
  try {
    const m = await import("@/lib/localAssetStore");
    toStore = m.dehydrateProjectRefs(projects);
  } catch {                                 }
  return new Promise<void>((resolve, reject) => {
    const tx = db.transaction(PROJECTS_IDB_STORE, "readwrite");
    tx.objectStore(PROJECTS_IDB_STORE).put(toStore, PROJECTS_IDB_KEY);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

                                                                                                
                                                                                        
                                                                                             
                                                                                         
                                                                                              
                                                                                             
                                                                                               
                                                                                               
                                                                                             
                                                                                                                                             
const LEADS_IDB_NAME = "abil-leads-db";
const LEADS_IDB_STORE = "leads";
const LEADS_IDB_KEY = "v1";

function leadsIdbOpen(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open(LEADS_IDB_NAME, 1);
    req.onupgradeneeded = () => {
      const db = req.result;
      if (!db.objectStoreNames.contains(LEADS_IDB_STORE)) db.createObjectStore(LEADS_IDB_STORE);
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

async function idbGetLeads(): Promise<Lead[] | null> {
  try {
    const db = await leadsIdbOpen();
    return await new Promise<Lead[] | null>((resolve, reject) => {
      const tx = db.transaction(LEADS_IDB_STORE, "readonly");
      const req = tx.objectStore(LEADS_IDB_STORE).get(LEADS_IDB_KEY);
      req.onsuccess = () => { const raw = req.result as Lead[] | undefined; resolve(Array.isArray(raw) ? raw : null); };
      req.onerror = () => reject(req.error);
    });
  } catch { return null; }
}

async function idbSetLeads(leads: Lead[]): Promise<void> {
  const db = await leadsIdbOpen();
  return new Promise<void>((resolve, reject) => {
    const tx = db.transaction(LEADS_IDB_STORE, "readwrite");
    tx.objectStore(LEADS_IDB_STORE).put(Array.isArray(leads) ? leads : [], LEADS_IDB_KEY);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

                                                                                    
                                                                                        
                                                                                        
                                                                                
let leadsMem: Lead[] | undefined;
const leadsListeners = new Set<() => void>();
let leadsIdbHydrated = false;
let leadsIdbHydrating: Promise<void> | null = null;
let leadsWriteTimer: ReturnType<typeof setTimeout> | null = null;

function notifyLeads() { leadsListeners.forEach((cb) => { try { cb(); } catch {            } }); }
function getLeadsMem(): Lead[] { return Array.isArray(leadsMem) ? leadsMem : []; }

                                                                                        
                                                                                    
                                                                                        
                                                                                           
function hydrateLeadsOnce(): Promise<void> {
  if (leadsIdbHydrated) return Promise.resolve();
  if (leadsIdbHydrating) return leadsIdbHydrating;
  leadsIdbHydrating = (async () => {
    try {
      let fromIdb = await idbGetLeads();
      if (!fromIdb || !fromIdb.length) {
        try {
          const rawLegacy = typeof window !== "undefined" ? window.localStorage.getItem("abil_crm_leads") : null;
          if (rawLegacy) {
            const parsed = JSON.parse(rawLegacy);
            if (Array.isArray(parsed) && parsed.length) { fromIdb = parsed as Lead[]; try { await idbSetLeads(parsed as Lead[]); } catch {                            } }
          }
        } catch {                           }
      }
                                                                                              
      try { if (typeof window !== "undefined") window.localStorage.removeItem("abil_crm_leads"); } catch {            }
      if (leadsMem === undefined && Array.isArray(fromIdb)) { leadsMem = fromIdb; notifyLeads(); }
    } catch {            }
    finally { leadsIdbHydrated = true; }
  })();
  return leadsIdbHydrating;
}

function scheduleLeadsPersist() {
  if (leadsWriteTimer) clearTimeout(leadsWriteTimer);
  leadsWriteTimer = setTimeout(() => {
    leadsWriteTimer = null;
    idbSetLeads(getLeadsMem()).catch((e) => { try { console.warn("[leads-idb] persist falhou:", e); } catch {            } });
  }, 600);
}

function setLeadsMem(next: Lead[]) {
  leadsMem = Array.isArray(next) ? next : [];
  notifyLeads();                                                           
  scheduleLeadsPersist();                                                          
}

                                                                                      
                                                                                    
function useLeadsIDBState<T>(initial: T): [T, (v: T | ((p: T) => T)) => void] {
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const [, force] = useState(0);
  // eslint-disable-next-line react-hooks/rules-of-hooks
  useEffect(() => {
    const cb = () => force((n) => n + 1);
    leadsListeners.add(cb);
    void hydrateLeadsOnce();
    return () => { leadsListeners.delete(cb); };
  }, []);
  const value = (leadsMem === undefined ? initial : (leadsMem as unknown as T));
  const setValue = (v: T | ((p: T) => T)) => {
    const prev = (getLeadsMem() as unknown as T);
    const next = typeof v === "function" ? (v as (p: T) => T)(prev) : v;
    setLeadsMem(next as unknown as Lead[]);
  };
  return [value, setValue];
}

                                                                                                                                                                                                                           
                                                                                  
                                                                                                                                                                                                                           
                                                                                  
                                                                                  
                                                                                
                                                                                  
  
                                                                                   
                                                                                    
                                                                                
                                                                           
  
                                                          
                                                                                    
                                                                                      
                                                                                        
                                                                                       
                                                              
                                                                                   
                                                                                    
  
                                                                                 
                                                                                
                  
                                                                                                                                                                                                                           
const MIGRATE_ASSET_FIELDS = ["src", "posterSrc", "previewSrc", "compressedFullSrc"] as const;

function mimeToExt(mime: string): string {
  const map: Record<string, string> = {
    "image/jpeg": "jpg", "image/jpg": "jpg", "image/png": "png", "image/webp": "webp",
    "image/gif": "gif", "image/avif": "avif", "image/svg+xml": "svg",
    "video/mp4": "mp4", "video/webm": "webm", "video/quicktime": "mov", "video/x-m4v": "m4v",
    "application/pdf": "pdf",
  };
  return map[mime] || "bin";
}

const isInlineBase64 = (v: unknown): v is string =>
  typeof v === "string" && v.startsWith("data:");

                                                                             
function approxBase64Bytes(dataUrl: string): number {
  const comma = dataUrl.indexOf(",");
  if (comma < 0) return 0;
  return Math.floor((dataUrl.length - comma - 1) * 0.75);
}

type MigratePhase = "scan" | "upload" | "persist" | "cloud" | "done";
type MigrateProgress = {
  phase: MigratePhase;
  current: number;                                                                    
  total: number;
  migrated: number;
  failed: number;
  bytesFreed: number;
  projectTitle?: string;
  field?: string;
};
type MigrateResult = {
  ok: boolean;
  dryRun: boolean;
  totalFields: number;
  migrated: number;
  failed: number;
  skipped: number;                                  
  bytesFreed: number;
  projectsCleaned: number;                                         
  cloudPushed: boolean;
  errors: string[];
};

async function migrateProjectAssetsToBlob(
  opts: { onProgress?: (p: MigrateProgress) => void; dryRun?: boolean; push?: boolean } = {}
): Promise<MigrateResult> {
  const { onProgress, dryRun = false, push = true } = opts;
  const errors: string[] = [];
  const projects = await idbGetProjects();
  if (!projects || projects.length === 0) {
    return { ok: true, dryRun, totalFields: 0, migrated: 0, failed: 0, skipped: 0, bytesFreed: 0, projectsCleaned: 0, cloudPushed: false, errors: ["IDB sem projetos"] };
  }

                                                                                          
  const { cloudUploadFile, dataUrlToFile } = await import("@/lib/cloudProjects");

                                                                                                               
  let totalFields = 0, scannedBytes = 0;
  const eachAssetLike = (p: DashboardProject): any[] => [p.cover, ...(p.assets || [])].filter(Boolean) as any[];
  for (const p of projects) {
    for (const obj of eachAssetLike(p)) {
      for (const f of MIGRATE_ASSET_FIELDS) {
        if (isInlineBase64(obj[f])) { totalFields++; scannedBytes += approxBase64Bytes(obj[f]); }
      }
    }
  }
  onProgress?.({ phase: "scan", current: 0, total: totalFields, migrated: 0, failed: 0, bytesFreed: 0 });

  let migrated = 0, failed = 0, bytesFreed = 0;
  const skipped = 0;

  if (dryRun) {
    return {
      ok: true, dryRun: true, totalFields, migrated: 0, failed: 0,
      skipped: 0, bytesFreed: 0, projectsCleaned: 0, cloudPushed: false,
      errors: [`[dryRun] ${totalFields} campos base64 (~${(scannedBytes / 1024 / 1024).toFixed(1)}MB) prontos para migrar`],
    };
  }

                                                            
  async function migrateField(obj: any, field: string, prefix: "covers" | "assets", baseName: string): Promise<void> {
    const val = obj[field];
    if (!isInlineBase64(val)) { return; }
    const bytes = approxBase64Bytes(val);
    const file = dataUrlToFile(val, "tmp");
    if (!file) {
      failed++;
      errors.push(`${baseName}.${field}: dataURL inválido (mantido inline)`);
      onProgress?.({ phase: "upload", current: migrated + failed, total: totalFields, migrated, failed, bytesFreed, projectTitle: baseName, field });
      return;
    }
    const ext = mimeToExt(file.type);
    const filename = `${baseName}-${field}.${ext}`;
    try {
      const res = await cloudUploadFile(file, { prefix, filename });
      if (res.ok && res.url) {
        obj[field] = res.url;                                  
        migrated++;
        bytesFreed += bytes;
      } else {
        failed++;                                                         
        errors.push(`${baseName}.${field}: upload falhou, ${res.error || "?"} (mantido inline)`);
      }
    } catch (e) {
      failed++;                                                           
      errors.push(`${baseName}.${field}: exceção, ${String((e as Error).message || e)} (mantido inline)`);
    }
    onProgress?.({ phase: "upload", current: migrated + failed, total: totalFields, migrated, failed, bytesFreed, projectTitle: baseName, field });
  }

                                                                                                                    
  for (let pi = 0; pi < projects.length; pi++) {
    const p = projects[pi];
    const base = String(p.id || `proj${pi}`).replace(/[^a-zA-Z0-9_-]/g, "").slice(0, 48) || `proj${pi}`;
    if (p.cover) {
      for (const f of MIGRATE_ASSET_FIELDS) await migrateField(p.cover, f, "covers", `${base}-cover`);
    }
    for (let ai = 0; ai < (p.assets || []).length; ai++) {
      const a = p.assets[ai];
      if (!a) continue;                                                          
      for (const f of MIGRATE_ASSET_FIELDS) await migrateField(a, f, "assets", `${base}-a${ai}`);
    }
    try {
      await idbSetProjects(projects);                                                    
      onProgress?.({ phase: "persist", current: pi + 1, total: projects.length, migrated, failed, bytesFreed });
    } catch (e) {
      errors.push(`persist projeto ${pi}: ${String((e as Error).message || e)}`);
    }
  }

                                                                                                                     
                                                                                 
                                                                              
                                                  
  const projectStillHasBase64 = (p: DashboardProject): boolean =>
    eachAssetLike(p).some((obj) => MIGRATE_ASSET_FIELDS.some((f) => isInlineBase64(obj[f])));
  const cleanProjects = projects.filter((p) => !projectStillHasBase64(p));
  let cloudPushed = false;
  if (push && cleanProjects.length > 0) {
    try {
      onProgress?.({ phase: "cloud", current: 0, total: cleanProjects.length, migrated, failed, bytesFreed });
      const r = await cloudUpsertMany(cleanProjects as any);
      cloudPushed = !!r.ok;
      if (!r.ok) errors.push(`cloud push: ${r.error || "?"}`);
    } catch (e) {
      errors.push(`cloud push exceção: ${String((e as Error).message || e)}`);
    }
  }

  onProgress?.({ phase: "done", current: totalFields, total: totalFields, migrated, failed, bytesFreed });
  return {
    ok: failed === 0,
    dryRun: false,
    totalFields,
    migrated,
    failed,
    skipped,
    bytesFreed,
    projectsCleaned: cleanProjects.length,
    cloudPushed,
    errors,
  };
}

                                                                                
                                                                             
                                                                                
if (typeof window !== "undefined") {
  (window as any).__abilMigrateAssets = migrateProjectAssetsToBlob;
}

                                                                                                                                                                                                                           
                                                                                       
                                                                                                                                                                                                                           
                                                                                    
                                                                                 
                                                                            
                                                                                         
                                                                                        
                                                                               
                                                                                        
const PROJECTS_BACKUP_KEY = (PROJECTS_IDB_KEY as string) + "-backup-localdrain";

async function rawGetIDB(key: IDBValidKey): Promise<DashboardProject[] | null> {
  try {
    const db = await idbOpen();
    return await new Promise((resolve, reject) => {
      const tx = db.transaction(PROJECTS_IDB_STORE, "readonly");
      const req = tx.objectStore(PROJECTS_IDB_STORE).get(key);
      req.onsuccess = () => resolve((req.result as DashboardProject[]) || null);
      req.onerror = () => reject(req.error);
    });
  } catch { return null; }
}
async function rawPutIDB(key: IDBValidKey, value: DashboardProject[]): Promise<void> {
  const db = await idbOpen();
  return new Promise<void>((resolve, reject) => {
    const tx = db.transaction(PROJECTS_IDB_STORE, "readwrite");
    tx.objectStore(PROJECTS_IDB_STORE).put(value, key);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

async function drainProjectAssetsToLocal(
  opts: { onProgress?: (p: MigrateProgress) => void; dryRun?: boolean } = {}
): Promise<MigrateResult> {
  const { onProgress, dryRun = false } = opts;
  const errors: string[] = [];
  const { putAssetBlob, makeAssetRef, newAssetId, dataUrlToBlob } = await import("@/lib/localAssetStore");
                                                                            
  const projects = await rawGetIDB(PROJECTS_IDB_KEY);
  if (!projects || projects.length === 0) {
    return { ok: true, dryRun, totalFields: 0, migrated: 0, failed: 0, skipped: 0, bytesFreed: 0, projectsCleaned: 0, cloudPushed: false, errors: ["IDB sem projetos"] };
  }
  const eachAssetLike = (p: DashboardProject): any[] => [p.cover, ...(p.assets || [])].filter(Boolean) as any[];
  let totalFields = 0, scannedBytes = 0;
  for (const p of projects) for (const obj of eachAssetLike(p)) for (const f of MIGRATE_ASSET_FIELDS)
    if (isInlineBase64(obj[f])) { totalFields++; scannedBytes += approxBase64Bytes(obj[f]); }
  onProgress?.({ phase: "scan", current: 0, total: totalFields, migrated: 0, failed: 0, bytesFreed: 0 });
  if (dryRun) {
    return { ok: true, dryRun: true, totalFields, migrated: 0, failed: 0, skipped: 0, bytesFreed: 0, projectsCleaned: 0, cloudPushed: false,
      errors: [`[dryRun] ${totalFields} campos base64 (~${(scannedBytes / 1024 / 1024).toFixed(1)}MB) → gaveta local`] };
  }
                                                                         
  try {
    const existing = await rawGetIDB(PROJECTS_BACKUP_KEY);
    if (!existing) await rawPutIDB(PROJECTS_BACKUP_KEY, projects);
  } catch (e) { errors.push(`backup falhou: ${String((e as Error).message || e)}`); }

  let migrated = 0, failed = 0, bytesFreed = 0;
  for (let pi = 0; pi < projects.length; pi++) {
    const p = projects[pi];
    for (const obj of eachAssetLike(p)) {
      for (const f of MIGRATE_ASSET_FIELDS) {
        const v = obj[f];
        if (!isInlineBase64(v)) continue;
        const bytes = approxBase64Bytes(v);
        const blob = dataUrlToBlob(v);
        if (!blob) { failed++; errors.push(`${p.id}.${f}: dataURL inválido (mantido inline)`); continue; }
        try {
          const id = newAssetId(obj === p.cover ? "cover" : "asset");
          await putAssetBlob(id, blob);
          obj[f] = makeAssetRef(id);                                       
          migrated++; bytesFreed += bytes;
        } catch (e) { failed++; errors.push(`${p.id}.${f}: ${String((e as Error).message || e)} (mantido inline)`); }
        onProgress?.({ phase: "upload", current: migrated + failed, total: totalFields, migrated, failed, bytesFreed });
      }
    }
    try { await rawPutIDB(PROJECTS_IDB_KEY, projects); } catch (e) { errors.push(`persist ${pi}: ${String((e as Error).message || e)}`); }
  }
  onProgress?.({ phase: "done", current: totalFields, total: totalFields, migrated, failed, bytesFreed });
  return { ok: failed === 0, dryRun: false, totalFields, migrated, failed, skipped: 0, bytesFreed, projectsCleaned: projects.length, cloudPushed: false, errors };
}

async function restoreLocalDrainBackup(): Promise<{ ok: boolean; restored: number; error?: string }> {
  try {
    const backup = await rawGetIDB(PROJECTS_BACKUP_KEY);
    if (!backup || backup.length === 0) return { ok: false, restored: 0, error: "sem backup" };
    await rawPutIDB(PROJECTS_IDB_KEY, backup);
    return { ok: true, restored: backup.length };
  } catch (e) { return { ok: false, restored: 0, error: String((e as Error).message || e) }; }
}

                                                                                                                                                                                                                           
                                                                            
                                                                                                                                                                                                                           
                                                                             
                                                                                
                                                                                 
                                                                                    
                                                                              
                                                                                    
                                         
                                                                                  
                                                                                     
                                                                               
async function promoteGavetaToBlob(
  opts: { onProgress?: (p: MigrateProgress) => void; dryRun?: boolean; push?: boolean } = {}
): Promise<MigrateResult> {
  const { onProgress, dryRun = false, push = true } = opts;
  const errors: string[] = [];
  const { cloudUploadFile } = await import("@/lib/cloudProjects");
  const { getAssetBlob, isAssetRef, assetRefId } = await import("@/lib/localAssetStore");
  const projects = await rawGetIDB(PROJECTS_IDB_KEY);
  if (!projects || projects.length === 0) {
    return { ok: true, dryRun, totalFields: 0, migrated: 0, failed: 0, skipped: 0, bytesFreed: 0, projectsCleaned: 0, cloudPushed: false, errors: ["IDB sem projetos"] };
  }
  const eachAssetLike = (p: DashboardProject): any[] => [p.cover, ...(p.assets || [])].filter(Boolean) as any[];
                                                                                                                                                     
  let totalFields = 0;
  for (const p of projects) for (const obj of eachAssetLike(p)) for (const f of MIGRATE_ASSET_FIELDS)
    if (isAssetRef(obj[f])) totalFields++;
  onProgress?.({ phase: "scan", current: 0, total: totalFields, migrated: 0, failed: 0, bytesFreed: 0 });
  if (dryRun) {
    return { ok: true, dryRun: true, totalFields, migrated: 0, failed: 0, skipped: 0, bytesFreed: 0, projectsCleaned: 0, cloudPushed: false,
      errors: [`[dryRun] ${totalFields} refs de gaveta prontas para subir ao Blob`] };
  }
  let migrated = 0, failed = 0, bytesFreed = 0;
  const touched = new Set<string>();
  async function promoteField(p: DashboardProject, obj: any, field: string, prefix: "covers" | "assets", baseName: string): Promise<void> {
    const v = obj[field];
    if (!isAssetRef(v)) return;
    const blob = await getAssetBlob(assetRefId(v));
    if (!blob) { failed++; errors.push(`${baseName}.${field}: gaveta sem blob (mantida ref)`); return; }
    const ext = mimeToExt(blob.type);
    const file = new File([blob], `${baseName}-${field}.${ext}`, { type: blob.type || "application/octet-stream" });
    try {
      const res = await cloudUploadFile(file, { prefix, filename: file.name });
      if (res.ok && res.url) { obj[field] = res.url; migrated++; bytesFreed += blob.size; touched.add(p.id); }
      else { failed++; errors.push(`${baseName}.${field}: upload falhou, ${res.error || "?"} (mantida ref)`); }
    } catch (e) {
      failed++; errors.push(`${baseName}.${field}: exceção, ${String((e as Error).message || e)} (mantida ref)`);
    }
    onProgress?.({ phase: "upload", current: migrated + failed, total: totalFields, migrated, failed, bytesFreed, projectTitle: baseName, field });
  }
                                                                                                                             
  for (let pi = 0; pi < projects.length; pi++) {
    const p = projects[pi];
    const base = String(p.id || `proj${pi}`).replace(/[^a-zA-Z0-9_-]/g, "").slice(0, 48) || `proj${pi}`;
    if (p.cover) {
      for (const f of MIGRATE_ASSET_FIELDS) await promoteField(p, p.cover, f, "covers", `${base}-cover`);
    }
    for (let ai = 0; ai < (p.assets || []).length; ai++) {
      const a = p.assets[ai];
      if (!a) continue;
      for (const f of MIGRATE_ASSET_FIELDS) await promoteField(p, a, f, "assets", `${base}-a${ai}`);
    }
    try {
      await rawPutIDB(PROJECTS_IDB_KEY, projects);
      onProgress?.({ phase: "persist", current: pi + 1, total: projects.length, migrated, failed, bytesFreed });
    } catch (e) { errors.push(`persist projeto ${pi}: ${String((e as Error).message || e)}`); }
  }
                                                                                              
  const stillRef = (p: DashboardProject): boolean =>
    eachAssetLike(p).some((obj) => MIGRATE_ASSET_FIELDS.some((f) => isAssetRef(obj[f])));
  const promoted = projects.filter((p) => touched.has(p.id) && !stillRef(p));
  let cloudPushed = false;
  if (push && promoted.length > 0) {
    try {
      onProgress?.({ phase: "cloud", current: 0, total: promoted.length, migrated, failed, bytesFreed });
      const r = await cloudUpsertMany(promoted as any);
      cloudPushed = !!r.ok;
      if (!r.ok) errors.push(`cloud push: ${r.error || "?"}`);
    } catch (e) { errors.push(`cloud push exceção: ${String((e as Error).message || e)}`); }
  }
  onProgress?.({ phase: "done", current: totalFields, total: totalFields, migrated, failed, bytesFreed });
  return { ok: failed === 0, dryRun: false, totalFields, migrated, failed, skipped: 0, bytesFreed, projectsCleaned: promoted.length, cloudPushed, errors };
}

if (typeof window !== "undefined") {
  (window as any).__abilDrainLocal = drainProjectAssetsToLocal;
  (window as any).__abilRestoreLocalBackup = restoreLocalDrainBackup;
  (window as any).__abilPromoteGaveta = promoteGavetaToBlob;
}

                                                                            
                                                                            
                                                                              
                                                                             
                                                      
const ProjectsContext = createContext<[DashboardProject[], (v: DashboardProject[] | ((p: DashboardProject[]) => DashboardProject[])) => void] | null>(null);

                                                                                        
                                                                                         
                                                                                        
                                                                                      
                                                                                        
                                                                                  
                                                                                   
                                                                                            
const PROJECTS_HYDRATION_VIEWS = new Set(["dashboard", "login", "project", "apresentacao", "proposta"]);

function ProjectsProvider({ children, hidratar = true }: { children: React.ReactNode; hidratar?: boolean }) {
  const value = useDashProjectsIDBInternal([], hidratar);
  return <ProjectsContext.Provider value={value}>{children}</ProjectsContext.Provider>;
}

function useDashProjectsIDB(_initial: DashboardProject[]): [DashboardProject[], (v: DashboardProject[] | ((p: DashboardProject[]) => DashboardProject[])) => void] {
  const ctx = useContext(ProjectsContext);
  if (ctx) return ctx;
                                                                             
  if (typeof console !== "undefined") console.warn("[useDashProjectsIDB] called outside ProjectsProvider, use useProjects() inside provider for memory efficiency");
  // eslint-disable-next-line react-hooks/rules-of-hooks
  return useDashProjectsIDBInternal(_initial);
}

const SITE_FALLBACK_IMAGES = [
  "/brand/mock-cartaz-2.jpg",
  "/brand/mock-website-2.jpg",
  "/brand/kv-men-1.jpg",
  "/brand/mock-billboard-2.jpg",
  "/brand/mock-glass-card.jpg",
  "/brand/kv-woman-2.jpg",
];

function siteFallbackImage(seed: string | number | undefined): string {
  const key = String(seed ?? "abil-fallback");
  let hash = 0;
  for (let i = 0; i < key.length; i++) hash = ((hash * 31) + key.charCodeAt(i)) >>> 0;
  return SITE_FALLBACK_IMAGES[hash % SITE_FALLBACK_IMAGES.length];
}

                                                                                  
                                                                              
                                                                  
                                                                      
                                                                 
                                                                                  
                                                                                   
                                                                                
                                                      
  
                                                                          
                                                                      
                                                                            
                                                                            
                                                                        
                                                                         
                                                         
                                                                      
const DEFAULT_DEMO_PROJECTS_SEED_VERSION = "v6-fetch-on-no-customs";
const CANONICAL_SEED_URL = "/abil-projects-seed.json";
                                                                                         
                                                                                             
                                                                                     
                                                                              
const DEFAULT_DEMO_PROJECTS: DashboardProject[] = [];

                                                                            
                                                                         
                                                                         
                                                                                
  
         
                                                                              
                                                                            
                                                   
  
                                                                           
async function fetchCanonicalSeed(): Promise<DashboardProject[] | null> {
  if (typeof fetch === "undefined") return null;
  try {
    const resp = await fetch(CANONICAL_SEED_URL, { cache: "force-cache" });
    if (!resp.ok) {
      console.warn("[seed] fetch non-ok:", resp.status);
      return null;
    }
    const data = await resp.json();
    if (!Array.isArray(data) || data.length === 0) return null;
                                                   
    if (!data.every((p) => p && typeof p.id === "string" && typeof p.title === "string")) {
      console.warn("[seed] malformed entries");
      return null;
    }
    return data as DashboardProject[];
  } catch (e) {
    console.warn("[seed] fetch failed:", e);
    return null;
  }
}


   
                                                                      
  
                                                                                
                                                                          
                                                                             
                                                                             
                                                                              
                                                                       
   
type EstadoGravacao = { estado: "limpo" | "aGravar" | "erro"; erro?: string; quando?: number };
let _gravacao: EstadoGravacao = { estado: "limpo" };
const _ouvintesGravacao = new Set<() => void>();
function marcarGravacao(e: EstadoGravacao) {
  _gravacao = e;
  _ouvintesGravacao.forEach((f) => { try { f(); } catch {            } });
}
                                                          
function useEstadoGravacaoProjectos(): EstadoGravacao {
  const [, redesenhar] = useState(0);
  useEffect(() => {
    const f = () => redesenhar((n) => n + 1);
    _ouvintesGravacao.add(f);
    return () => { _ouvintesGravacao.delete(f); };
  }, []);
  return _gravacao;
}
                                                                                
                                                                                     
async function gravarProjectosAgora(projectos: DashboardProject[]): Promise<{ ok: boolean; erro?: string }> {
  marcarGravacao({ estado: "aGravar" });
  try {
    await idbSetProjects(projectos);
    const r = await cloudUpsertMany(projectos);
    if (!r.ok) {
      const erro = String(r.error || "desconhecido").slice(0, 140);
      marcarGravacao({ estado: "erro", erro });
      return { ok: false, erro };
    }
    marcarGravacao({ estado: "limpo", quando: Date.now() });
    return { ok: true };
  } catch (e) {
    const erro = String((e as Error)?.message || e).slice(0, 140);
    marcarGravacao({ estado: "erro", erro });
    return { ok: false, erro };
  }
}

function useDashProjectsIDBInternal(initial: DashboardProject[], hidratar: boolean = true): [DashboardProject[], (v: DashboardProject[] | ((p: DashboardProject[]) => DashboardProject[])) => void] {
                                                                        
  const [state, setState] = useState<DashboardProject[]>(initial);
  const initializedRef = useRef(false);
  const initialRef = useRef(initial);

                                                                      
                                                                          
                                                                            
                                                                                   
                                                                                     
                                                                          
                                                                               
                                                                                       
  useEffect(() => {
                                                                                      
                                                                                    
                                                                         
    if (!hidratar) return;
    if (initializedRef.current) return;
    initializedRef.current = true;
    (async () => {
      try {
        const SEED_KEY = "abil_demo_seed_version";
        const lsSeedVersion = typeof window !== "undefined"
          ? window.localStorage.getItem(SEED_KEY)
          : null;
                                                                
        const fromIDB = await idbGetProjects();
        if (fromIDB && fromIDB.length > 0) setState(fromIDB);

                                                                      
                                                                            
                                                                        
        const cloudResp = await cloudFetchProjects({ force: true });
                                                                                     
        const cloudProjects = (cloudResp.changed && cloudResp.projects && cloudResp.projects.length > 0)
          ? normalizeProjects(cloudResp.projects)
          : null;

        if (cloudProjects && cloudProjects.length > 0) {
                                                                                          
            
                                 
                                                                                                   
                                                                        
                                                                                       
                                                                                        
                                                                                 
            
                                                                                       
                                                                                  
                                                                              
                                                                                 
                                                                                          
          const localArr = (fromIDB || []) as DashboardProject[];
          const cloudIds = new Set(cloudProjects.map((c) => c.id));
          const orphanCustoms = localArr.filter((l) => l.id.startsWith("id-") && !cloudIds.has(l.id));
          const orphanDemos = localArr.filter((l) => l.id.startsWith("demo-") && !cloudIds.has(l.id));
                                                                                 
                                                                                   
                                                                                    
                                                                                    
                                                                                       
                                                                                 
          const hasUnpromotedLocalAsset = (p: DashboardProject): boolean =>
            ([p.cover, ...((p.assets) || [])].filter(Boolean) as any[]).some((o) =>
              MIGRATE_ASSET_FIELDS.some((f) => typeof o[f] === "string" && (o[f].startsWith("idb-asset://") || o[f].startsWith("blob:"))));
          const preservedCustoms = orphanCustoms.filter(hasUnpromotedLocalAsset);
          const discardedCustoms = orphanCustoms.filter((p) => !preservedCustoms.includes(p));
          const adopted = preservedCustoms.length > 0 ? [...cloudProjects, ...preservedCustoms] : cloudProjects;
                                                                                         
                                                                                             
                                                                                             
                                                                      
          const deadIds = new Set<string>(getRecentlyDeletedIds());
          try { (await cloudFetchTombstones()).forEach((idd) => deadIds.add(idd)); } catch {            }
          const adoptedLive = deadIds.size > 0 ? adopted.filter((p) => !deadIds.has(p.id)) : adopted;
          if (orphanCustoms.length > 0 || orphanDemos.length > 0 || adoptedLive.length !== adopted.length) {
            console.log(`[cloud-sync] cloud=${cloudProjects.length} adoptado. Preservados ${preservedCustoms.length} customs locais por promover:`, preservedCustoms.map(p => p.id), `| Descartados ${discardedCustoms.length} órfãos:`, discardedCustoms.map(p => p.id), `+ ${orphanDemos.length} demos órfãos | mortos filtrados: ${adopted.length - adoptedLive.length}`);
          }
          await idbSetProjects(adoptedLive);
          if (typeof window !== "undefined") window.localStorage.setItem(SEED_KEY, DEFAULT_DEMO_PROJECTS_SEED_VERSION);
          setState(adoptedLive);
                                                                                          
          return;
        }

                                                               
          
                                                                                      
                                                                              
          
                                                                                    
                                                                                                 
                                                                                        
          
                                                                                          
                                                                 
        let seedToCloud: DashboardProject[] = [];
        const hasSeededBefore = lsSeedVersion !== null;                                    
        if (fromIDB && fromIDB.length > 0) {
          const customs = fromIDB.filter((p) => !p.id.startsWith("demo-"));
          seedToCloud = customs.length > 0 ? customs : fromIDB;
        } else if (typeof window !== "undefined") {
          try {
            const lsRaw = window.localStorage.getItem("abil_projects_v3");
            if (lsRaw) {
              const lsData = JSON.parse(lsRaw) as DashboardProject[];
              if (Array.isArray(lsData) && lsData.length > 0) {
                seedToCloud = lsData;
                window.localStorage.removeItem("abil_projects_v3");
              }
            }
          } catch {            }
        }
                                                                       
          
                                                                                      
                                                                                      
                                                                                     
          
                                                                                       
                                                                       
                                                                                        
                                                                                  
        if (seedToCloud.length === 0) {
          const canonical = await fetchCanonicalSeed();
          if (canonical && canonical.length > 0) {
            seedToCloud = canonical;
            console.log(`[recovery] IDB+cloud vazios → recuperados ${canonical.length} projetos do seed canónico (estático)`);
          } else if (!hasSeededBefore) {
                                                                       
            const fallbackInitial = initialRef.current;
            seedToCloud = fallbackInitial.length > 0 ? fallbackInitial : DEFAULT_DEMO_PROJECTS;
            console.log("[cloud-sync] primeira visita sem canonical, demos hardcoded");
          } else {
            console.warn("[cloud-sync] IDB+cloud vazios, sem seed canónico, já visitou, state vazio até cloud recuperar.");
          }
        }
                                                                                               
                                                                                            
                                                                                             
                                                                                            
        if (seedToCloud.length > 0) {
          const seedDead = new Set<string>(getRecentlyDeletedIds());
          try { (await cloudFetchTombstones()).forEach((idd) => seedDead.add(idd)); } catch {            }
          if (seedDead.size > 0) {
            const beforeN = seedToCloud.length;
            seedToCloud = seedToCloud.filter((p) => !seedDead.has(p.id));
            if (seedToCloud.length !== beforeN) console.log(`[seed] removed ${beforeN - seedToCloud.length} deleted IDs before seeding`);
          }
        }
        if (seedToCloud.length > 0) {
          await idbSetProjects(seedToCloud);
          if (typeof window !== "undefined") window.localStorage.setItem(SEED_KEY, DEFAULT_DEMO_PROJECTS_SEED_VERSION);
          setState(seedToCloud);
                                                                              
                                                                                         
          if (!hasSeededBefore) {
            cloudResetProjects(seedToCloud).then((r) => {
              if (!r.ok) console.warn("[cloud-sync] initial seed upload failed:", r.error);
              else console.log("[cloud-sync] seed inicial uploaded, snapshot:", r.snapshotKey);
            });
          }
        } else if (fromIDB && fromIDB.length > 0) {
                                                                                            
                                                                                             
                                                                                             
                                                                                            
                                                                                                  
          await idbSetProjects([]);
          setState([]);
          console.log("[seed] local storage only contained deleted projects, cleared IndexedDB and state");
        }
      } catch (e) {
        console.error("[useDashProjectsIDB] hydrate failed:", e);
      }
    })();
  }, [hidratar]);

                                                                          
                                                                                    
  useEffect(() => {
    if (typeof window === "undefined") return;
                                                                                        
                                                                                  
    if (!hidratar) return;
    let active = true;
    const POLL_MS = 8000;

    const checkCloud = async () => {
      if (!active || (typeof document !== "undefined" && document.hidden)) return;
      const resp = await cloudFetchProjects();
                                                                             
                                                                                             
      if (!resp.changed || !resp.projects) {
        if (resp.error && resp.error.startsWith("STORE_DOWN")) {
          console.warn("[cloud-poll] backend storage indisponível, mantendo state local intacto:", resp.error);
        }
        return;
      }
      const fresh = normalizeProjects(resp.projects);
                                                                               
                                                                                           
                                                     
      if (fresh.length === 0) {
        console.warn("[cloud-poll] cloud returned empty, mantendo state local intacto");
        return;
      }
                                                                                      
                                                                                                  
                                                                                           
                                                                                        
                                
      const pollDeadIds = new Set<string>(getRecentlyDeletedIds());
      try { (await cloudFetchTombstones()).forEach((idd) => pollDeadIds.add(idd)); } catch {            }
      setState((prev) => {
                                                                                                 
                                                                                             
        if (prev.length > 0) {
          const lossRatio = 1 - (fresh.length / prev.length);
          if (lossRatio > 0.5) {
            console.warn(`[cloud-poll] DRIFT SUSPEITO: cloud=${fresh.length} vs local=${prev.length} (${(lossRatio*100).toFixed(0)}% loss), skip, mantendo local`);
            return prev;
          }
        }
                                                              
                                                                                               
                                                                                     
                                                                                            
                                                                                           
        const { merged, addedFromCloud, preservedLocal, conflicts } = mergeWithLocal(
          fresh as DashboardProjectLike[],
          prev as DashboardProjectLike[],
                                          
        );
                                                                                      
                                                                                                           
        const mergedLive = pollDeadIds.size > 0
          ? (merged as DashboardProject[]).filter((p) => !pollDeadIds.has(p.id))
          : (merged as DashboardProject[]);
                                                              
        const sigPrev = prev.length + ":" + prev.map((p) => p.id).sort().join(",");
        const sigNew = mergedLive.length + ":" + mergedLive.map((p) => p.id).sort().join(",");
        if (sigPrev === sigNew && conflicts === 0) return prev;
        if (addedFromCloud > 0 || conflicts > 0) {
          console.log(`[cloud-poll] +${addedFromCloud} new, ${conflicts} updated, ${preservedLocal} local preserved`);
        }
        idbSetProjects(mergedLive).catch((e) => console.warn("[cloud-poll] idb failed:", e));
        return mergedLive;
      });
    };

    const intervalId = setInterval(checkCloud, POLL_MS);
    const onVisible = () => { if (!document.hidden) checkCloud(); };
    document.addEventListener("visibilitychange", onVisible);
    return () => {
      active = false;
      clearInterval(intervalId);
      document.removeEventListener("visibilitychange", onVisible);
    };
  }, [hidratar]);


  const setStateAndPersist = useCallback((v: DashboardProject[] | ((p: DashboardProject[]) => DashboardProject[])) => {
    setState((prev) => {
      const next = typeof v === "function" ? (v as (p: DashboardProject[]) => DashboardProject[])(prev) : v;
                                                      
      idbSetProjects(next).catch((e) => {
        console.error("[useDashProjectsIDB] save failed:", e);
        if (typeof window !== "undefined") {
          try {
            window.dispatchEvent(new CustomEvent("abil:storage-error", {
              detail: { key: "abil_projects_v3", error: `IndexedDB save falhou: ${String(e?.message || e).slice(0, 100)}` }
            }));
          } catch {            }
        }
      });
                                                                          
                                                                                   
                                                                               
                                                                             
                                                                                   
                                                                                     
                                                                                       
      const prevById = new Map(prev.map((p) => [p.id, p] as const));
      const nextIds = new Set(next.map((p) => p.id));
      const added = next.filter((p) => !prevById.has(p.id));
                                                                               
      const updated = next.filter((p) => {
        const prevP = prevById.get(p.id);
        return prevP !== undefined && prevP !== p;
      });
      const removed = prev.filter((p) => !nextIds.has(p.id));

                                                            
      if (added.length + updated.length > 0) {
        marcarGravacao({ estado: "aGravar" });
        cloudUpsertMany([...added, ...updated]).then((r) => {
                                                                            
                                                                      
          if (r.ok) marcarGravacao({ estado: "limpo", quando: Date.now() });
          else marcarGravacao({ estado: "erro", erro: String(r.error || "desconhecido").slice(0, 140) });
          if (!r.ok) {
            console.warn("[cloud] upsert failed:", r.error);
                                                                                    
                                                                                     
                                                                                    
                                                                                       
            const errStr = String(r.error || "");
            const isCloudDown = /no token found|blob_read_write_token|has been suspended|store is blocked|storage unavailable|store_down|http 503/i.test(errStr);
            if (typeof window !== "undefined" && !isCloudDown) {
              try {
                window.dispatchEvent(new CustomEvent("abil:storage-error", {
                  detail: { key: "cloud_projects", error: `Cloud sync falhou: ${errStr.slice(0, 100)}` }
                }));
              } catch {            }
            }
          }
        });
      }
                                                  
      if (removed.length > 0) {
        import("@/lib/cloudProjects").then(({ cloudDeleteProject }) => {
          for (const p of removed) {
            cloudDeleteProject(p.id).then((r) => {
              if (!r.ok) console.warn("[cloud] delete failed:", p.id, r.error);
            });
          }
        });
      }
                                                                      
      try {
        if (typeof window !== "undefined" && "BroadcastChannel" in window) {
          const bc = new BroadcastChannel(PROJECTS_BC_NAME);
          bc.postMessage({ type: "update", count: next.length });
          bc.close();
        }
      } catch {            }
      return next;
    });
  }, []);

                                                                                    
                                                                             
                                                                             
                                                                            
                                                                                     
                                                                                    
                                                   
  useEffect(() => {
    if (typeof window === "undefined" || !("BroadcastChannel" in window)) return;
    const bc = new BroadcastChannel(PROJECTS_BC_NAME);
    bc.onmessage = async (ev) => {
      if (ev.data?.type === "update") {
        try {
          const fresh = await idbGetProjects();
          if (fresh) {
            const freshSig = fresh.length + ":" + fresh.map((p) => p.id).join(",");
            setState((prev) => {
              const prevSig = prev.length + ":" + prev.map((p) => p.id).join(",");
              return prevSig === freshSig ? prev : fresh;
            });
          }
        } catch {            }
      }
    };
    return () => bc.close();
  }, []);

  return [state, setStateAndPersist];
}

                                                                                                                                                                              
                                                        
                                                                               
                                                                             
                                                                            
                                                                                    
                                                                   
                                                                                    
                                              
                                                                                                                                                                                 
const PRES_IDB_NAME = "abil-presentations-db";
const PRES_IDB_STORE = "presentations";
const PRES_IDB_KEY = "v1";
const PRES_BC_NAME = "abil-presentations-sync";

function presIdbOpen(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open(PRES_IDB_NAME, 1);
    req.onupgradeneeded = () => {
      const db = req.result;
      if (!db.objectStoreNames.contains(PRES_IDB_STORE)) db.createObjectStore(PRES_IDB_STORE);
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}
async function presIdbGet(): Promise<DashboardProject[] | null> {
  try {
    const db = await presIdbOpen();
    return await new Promise<DashboardProject[] | null>((resolve, reject) => {
      const tx = db.transaction(PRES_IDB_STORE, "readonly");
      const req = tx.objectStore(PRES_IDB_STORE).get(PRES_IDB_KEY);
      req.onsuccess = () => {
        const raw = req.result as DashboardProject[] | undefined;
        if (!raw) { resolve(null); return; }
        const normalized = normalizeProjects(raw);
                                                                                       
        import("@/lib/localAssetStore").then((m) => m.hydrateProjectRefs(normalized)).then(() => resolve(normalized)).catch(() => resolve(normalized));
      };
      req.onerror = () => reject(req.error);
    });
  } catch { return null; }
}
async function presIdbSet(items: DashboardProject[]): Promise<void> {
  try {
    const db = await presIdbOpen();
    await new Promise<void>((resolve, reject) => {
      const tx = db.transaction(PRES_IDB_STORE, "readwrite");
      tx.objectStore(PRES_IDB_STORE).put(items, PRES_IDB_KEY);
      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error);
    });
  } catch (e) { console.warn("[pres-idb] set failed:", e); }
}

function useDashPresentationsIDB(): [DashboardProject[], (v: DashboardProject[] | ((p: DashboardProject[]) => DashboardProject[])) => void] {
  const [state, setState] = useState<DashboardProject[]>([]);
  const initializedRef = useRef(false);

                                                                                            
  useEffect(() => {
    if (initializedRef.current) return;
    initializedRef.current = true;
    (async () => {
      try {
        const fromIDB = await presIdbGet();
        if (fromIDB && fromIDB.length > 0) setState(fromIDB);
        const cloudResp = await cloudFetchProjects({ force: true, collection: "presentations" });
        const cloud = (cloudResp.changed && cloudResp.projects && cloudResp.projects.length > 0)
          ? normalizeProjects(cloudResp.projects) : null;
        if (cloud && cloud.length > 0) {
          const deadIds = new Set<string>(getRecentlyDeletedIds());
          try { (await cloudFetchTombstones("presentations")).forEach((d) => deadIds.add(d)); } catch {            }
          const live = deadIds.size > 0 ? cloud.filter((p) => !deadIds.has(p.id)) : cloud;
          await presIdbSet(live);
          setState(live);
          return;
        }
                                                                                           
        if (fromIDB && fromIDB.length > 0) {
          const deadIds = new Set<string>(getRecentlyDeletedIds());
          try { (await cloudFetchTombstones("presentations")).forEach((d) => deadIds.add(d)); } catch {            }
          if (deadIds.size > 0) {
            const live = fromIDB.filter((p) => !deadIds.has(p.id));
            if (live.length !== fromIDB.length) { await presIdbSet(live); setState(live); }
          }
        }
      } catch (e) { console.error("[pres-store] hydrate failed:", e); }
    })();
  }, []);

                                                                            
  useEffect(() => {
    if (typeof window === "undefined") return;
    let active = true;
    const checkCloud = async () => {
      if (!active || (typeof document !== "undefined" && document.hidden)) return;
      const resp = await cloudFetchProjects({ collection: "presentations" });
      if (!resp.changed || !resp.projects) return;
      const fresh = normalizeProjects(resp.projects);
      if (fresh.length === 0) return;                                              
      const deadIds = new Set<string>(getRecentlyDeletedIds());
      try { (await cloudFetchTombstones("presentations")).forEach((d) => deadIds.add(d)); } catch {            }
      setState((prev) => {
        const { merged } = mergeWithLocal(fresh as DashboardProjectLike[], prev as DashboardProjectLike[]);
        const live = deadIds.size > 0 ? (merged as DashboardProject[]).filter((p) => !deadIds.has(p.id)) : (merged as DashboardProject[]);
        const sigPrev = prev.length + ":" + prev.map((p) => p.id).sort().join(",");
        const sigNew = live.length + ":" + live.map((p) => p.id).sort().join(",");
        if (sigPrev === sigNew) return prev;
        presIdbSet(live).catch(() => {});
        return live;
      });
    };
    const id = setInterval(checkCloud, 8000);
    const onVis = () => { if (!document.hidden) checkCloud(); };
    document.addEventListener("visibilitychange", onVis);
    return () => { active = false; clearInterval(id); document.removeEventListener("visibilitychange", onVis); };
  }, []);

  const setStateAndPersist = useCallback((v: DashboardProject[] | ((p: DashboardProject[]) => DashboardProject[])) => {
    setState((prev) => {
      const next = typeof v === "function" ? (v as (p: DashboardProject[]) => DashboardProject[])(prev) : v;
      presIdbSet(next).catch((e) => console.error("[pres-store] save failed:", e));
                                                                                         
      const prevById = new Map(prev.map((p) => [p.id, p] as const));
      const nextIds = new Set(next.map((p) => p.id));
      const added = next.filter((p) => !prevById.has(p.id));
      const updated = next.filter((p) => { const pp = prevById.get(p.id); return pp !== undefined && pp !== p; });
      const removed = prev.filter((p) => !nextIds.has(p.id));
      if (added.length + updated.length > 0) {
        cloudUpsertMany([...added, ...updated] as DashboardProjectLike[], "presentations").then((r) => { if (!r.ok) console.warn("[pres-cloud] upsert failed:", r.error); });
      }
      if (removed.length > 0) {
        import("@/lib/cloudProjects").then(({ cloudDeleteProject }) => {
          for (const p of removed) cloudDeleteProject(p.id, "presentations").then((r) => { if (!r.ok) console.warn("[pres-cloud] delete failed:", p.id, r.error); });
        });
      }
      try {
        if (typeof window !== "undefined" && "BroadcastChannel" in window) {
          const bc = new BroadcastChannel(PRES_BC_NAME); bc.postMessage({ type: "update", count: next.length }); bc.close();
        }
      } catch {            }
      return next;
    });
  }, []);

                                       
  useEffect(() => {
    if (typeof window === "undefined" || !("BroadcastChannel" in window)) return;
    const bc = new BroadcastChannel(PRES_BC_NAME);
    bc.onmessage = async (ev) => {
      if (ev.data?.type === "update") {
        try {
          const fresh = await presIdbGet();
          if (fresh) {
            const freshSig = fresh.length + ":" + fresh.map((p) => p.id).join(",");
            setState((prev) => { const prevSig = prev.length + ":" + prev.map((p) => p.id).join(","); return prevSig === freshSig ? prev : fresh; });
          }
        } catch {            }
      }
    };
    return () => bc.close();
  }, []);

  return [state, setStateAndPersist];
}

                                                                            
                                                                           
                                     
