function dictTranslate(text: string, toLang: Lang): string | null {
                                                                                        
                                                                                         
  const COMBINING_MARKS_RE = new RegExp("[" + String.fromCharCode(0x0300) + "-" + String.fromCharCode(0x036f) + "]", "g");
  const norm = text.toLowerCase().normalize("NFD").replace(COMBINING_MARKS_RE, "").trim();
  const entry = FALLBACK_DICT[norm];
  if (entry && entry[toLang]) {
                                                                      
    const result = entry[toLang]!;
    if (text === text.toUpperCase()) return result.toUpperCase();
    if (text[0] === text[0].toUpperCase()) return result[0].toUpperCase() + result.slice(1);
    return result;
  }
  return null;
}

const TRANSLATION_INVARIANT_TEXTS = new Set<string>([
                                                                               
                                                                                
                                                                          
  "ABiL",
  "ABiL MEDiAS",
  "AMD COMMUNICATION",
  "Samuel Dahan",
  "Stephen Bellotto",
  "Genève",
  "Rue de Berne",
]);

function isTranslationInvariantText(text: string): boolean {
  return TRANSLATION_INVARIANT_TEXTS.has(text.trim().replace(/\s+/g, " "));
}

                                                                           
                                              
                                                                                 
                                                                
                                     
                                            

                                                                                 
                                                                              
                                                                       
                              
type AIConfig = {
  apiKey?: string;
  model?: string;
  systemPrompt?: string;
  knowledgeFiles?: { name: string; content: string; size: number }[];
};
function readAIConfig(): AIConfig {
  if (typeof window === "undefined") return {};
  try {
    const raw = localStorage.getItem("abil_ai_config_v1");
    if (!raw) return {};
    return JSON.parse(raw) as AIConfig;
  } catch { return {}; }
}
async function tryOpenAITranslate(text: string, from: Lang | "auto", to: Lang): Promise<string | null> {
  if (typeof window === "undefined") return null;
  try {
    const cfg = readAIConfig();
    const ctrl = new AbortController();
    const tid = setTimeout(() => ctrl.abort(), 15000);
    const headers: Record<string, string> = getAIHeaders();
                                                                                               
    const knowledge = (cfg.knowledgeFiles || []).map((f) => f.content);
                                                                                                       
                                                                                                              
    const persona = (() => { try { return getAIPersonaContext(); } catch { return {} as AIPersonaContext; } })();
    const voiceBits = [persona.brandPersona?.prompt, persona.referenceNotes].filter(Boolean).join("\n\n");
    const sysBase = (cfg.systemPrompt && cfg.systemPrompt.trim()) ? cfg.systemPrompt.trim() : "";
    const TRANSLATE_RULES = "You are a translator preserving this brand's voice. Output ONLY the translation, no preface. Keep {{placeholders}}, line breaks, URLs, emails and proper names verbatim.";
    const sysPrompt = voiceBits
      ? `${TRANSLATE_RULES}\n\n${sysBase}${sysBase ? "\n\n" : ""}=== LIVE BRAND VOICE TO PRESERVE IN TRANSLATION (dashboard persona) ===\n${voiceBits}`
      : (sysBase || undefined);
    const res = await fetch("/api/translate", {
      method: "POST",
      signal: ctrl.signal,
      headers,
      body: JSON.stringify({
        text, from, to,
        model: cfg.model || "gpt-4o-mini",
        systemPrompt: sysPrompt,
        knowledge: knowledge.length > 0 ? knowledge : undefined,
      }),
    });
    clearTimeout(tid);
    if (!res.ok) return null;
    const data = await res.json();
    const translated = data?.translated;
    if (typeof translated === "string" && translated.trim().length > 0) return translated;
    return null;
  } catch { return null; }
}

async function tryGoogleTranslate(text: string, from: Lang | "auto", to: Lang): Promise<string | null> {
                                                                     
                                                               
                                                                            
                                                                         
  try {
    const ctrl = new AbortController();
    const tid = setTimeout(() => ctrl.abort(), 3000);
    const url = `https://translate.googleapis.com/translate_a/single?client=gtx&sl=${from}&tl=${to}&dt=t&q=${encodeURIComponent(text)}`;
    const res = await fetch(url, { signal: ctrl.signal });
    clearTimeout(tid);
    if (!res.ok) return null;
    const data = await res.json();
                                                                     
    const translated = data?.[0]?.[0]?.[0];
    if (typeof translated === "string" && translated.trim().length > 0) return translated;
    return null;
  } catch { return null; }
}

async function tryMyMemory(text: string, from: Lang, to: Lang): Promise<string | null> {
  try {
    const ctrl = new AbortController();
    const tid = setTimeout(() => ctrl.abort(), 3000);
    const url = `https://api.mymemory.translated.net/get?q=${encodeURIComponent(text)}&langpair=${from}|${to}`;
    const res = await fetch(url, { signal: ctrl.signal });
    clearTimeout(tid);
    if (!res.ok) return null;
    const data = await res.json();
    const translated = data?.responseData?.translatedText;
    if (typeof translated === "string" && !translated.includes("MYMEMORY WARNING") && translated.trim().length > 0) {
      return translated;
    }
    return null;
  } catch { return null; }
}

                            
                                               
                                                                              
                                                        
                                       
                      
                                                
                                                                                
                                                                                 
async function translateText(text: string, fromLang: Lang | "auto", toLang: Lang): Promise<string> {
  if (!text || !text.trim()) return text;
  if (fromLang === toLang) return text;
  if (isTranslationInvariantText(text)) return text;
  if (text.length > 500) {
                                                                        
    const llm = await tryOpenAITranslate(text, fromLang, toLang);
    if (llm) {
      if (typeof window !== "undefined") console.log(`[translate llm-long] (${text.length} chars) (${fromLang}) → (${toLang})`);
      return llm;
    }
    return text;
  }
                                            
  if (fromLang !== "auto") {
    const dictResult = dictTranslate(text, toLang);
    if (dictResult) {
      if (typeof window !== "undefined") console.log(`[translate dict] "${text}" (${fromLang}) → "${dictResult}" (${toLang})`);
      return dictResult;
    }
  }
                                                          
  const llm = await tryOpenAITranslate(text, fromLang, toLang);
  if (llm) {
    if (typeof window !== "undefined") console.log(`[translate llm] "${text.slice(0,50)}..." (${fromLang}) → "${llm.slice(0,50)}..." (${toLang})`);
    return llm;
  }
                        
  const goog = await tryGoogleTranslate(text, fromLang, toLang);
  if (goog) {
    if (typeof window !== "undefined") console.log(`[translate goog] "${text}" (${fromLang}) → "${goog}" (${toLang})`);
    return goog;
  }
                                                          
  const mymFrom: Lang = fromLang === "auto" ? "fr" : fromLang;
  const mym = await tryMyMemory(text, mymFrom, toLang);
  if (mym) {
    if (typeof window !== "undefined") console.log(`[translate mym] "${text}" (${mymFrom}) → "${mym}" (${toLang})`);
    return mym;
  }
                                
  if (typeof window !== "undefined") console.warn(`[translate] all APIs failed for "${text}" → ${toLang}, using original`);
  return text;
}

                                                                                                                               
                                                                        
                                                                       
                                                                             

                                                                       
function hashStr(s: string): string {
  let h = 2166136261 >>> 0;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return (h >>> 0).toString(36);
}

                                                                                  
                                                                          
                                                   
function getCachedTranslation(text: string, to: Lang): string | null {
  if (typeof window === "undefined") return null;
  try { return localStorage.getItem(`trans_${hashStr(text)}_${to}`); } catch { return null; }
}
function setCachedTranslation(text: string, to: Lang, translated: string): void {
  if (typeof window === "undefined") return;
  try { localStorage.setItem(`trans_${hashStr(text)}_${to}`, translated); } catch {            }
}

                                                                            
async function translateTextCached(text: string, fromLang: Lang | "auto", toLang: Lang): Promise<string> {
  if (!text || !text.trim() || fromLang === toLang) return text;
  const cached = getCachedTranslation(text, toLang);
  if (cached) return cached;
  const result = await translateText(text, fromLang, toLang);
  if (result && result !== text) setCachedTranslation(text, toLang, result);
  return result;
}

                                                                                                
                                                                                               
                                              
function _collectStrings(o: any, out: string[]): void {
  if (typeof o === "string") { if (o.trim()) out.push(o); return; }
  if (Array.isArray(o)) { for (const x of o) _collectStrings(x, out); return; }
  if (o && typeof o === "object") { for (const k in o) _collectStrings(o[k], out); }
}
function _mapStrings(o: any, fn: (s: string) => string): any {
  if (typeof o === "string") return o.trim() ? fn(o) : o;
  if (Array.isArray(o)) return o.map((x) => _mapStrings(x, fn));
  if (o && typeof o === "object") { const r: any = {}; for (const k in o) r[k] = _mapStrings(o[k], fn); return r; }
  return o;
}
                                                                                                      
                                                                                               
                                                                               
function useTranslatedContent<T>(base: T, fromLang: Lang): T {
  const ctx = useApp();
  const lang = (ctx as any).lang as Lang;
  const [ver, setVer] = useState(0);
  const passthrough = !base || lang === fromLang;
  useEffect(() => {
    if (typeof window === "undefined") return undefined;
    const h = () => setVer((v) => v + 1);
    window.addEventListener("abil:translation", h);
    return () => window.removeEventListener("abil:translation", h);
  }, []);
  useEffect(() => {
    if (passthrough || typeof window === "undefined") return undefined;
    let cancelled = false;
    const all: string[] = []; _collectStrings(base, all);
    const missing = Array.from(new Set(all)).filter((s) => !getCachedTranslation(s, lang) && !_trInFlight.has(lang + "|" + s));
    if (!missing.length) return undefined;
    (async () => {
      let n = 0;
      for (const s of missing) {
        if (cancelled) break;
        const key = lang + "|" + s; _trInFlight.add(key);
        try { await translateTextCached(s, fromLang, lang); } catch {       }
        if (++n % 8 === 0) window.dispatchEvent(new CustomEvent("abil:translation"));
      }
      window.dispatchEvent(new CustomEvent("abil:translation"));
    })();
    return () => { cancelled = true; };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [base, lang]);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  return useMemo(() => (passthrough ? base : (_mapStrings(base, (s) => getCachedTranslation(s, lang) || s) as T)), [base, lang, ver, passthrough]);
}

                                                                               
const ALL_LANGS_AUTO_TRANSLATE: Lang[] = ["fr", "pt", "en", "de", "it"];

                                                                           
                                                                       
async function autoTranslateAllLangs(text: string, sourceLang: Lang | "auto" = "auto"): Promise<Record<Lang, string>> {
  const out: Record<Lang, string> = { fr: text, pt: text, en: text, de: text, it: text };
  (out as any).es ??= out.fr;
  await Promise.all(
    ALL_LANGS_AUTO_TRANSLATE.map(async (target) => {
      if (sourceLang !== "auto" && sourceLang === target) {
        out[target] = text;
        return;
      }
      out[target] = await translateTextCached(text, sourceLang, target);
    })
  );
  return out;
}

                                                                         
                                                                            
                                                                                
function AutoTranslatedText({ source, sourceLang = "fr" }: {
  source: string;
  sourceLang?: Lang | "auto";
}) {
  const text = useAutoTranslated(source, sourceLang);
  return <>{text}</>;
}

                                                                          
                                                                           
function useAutoTranslated(text: string, sourceLang: Lang | "auto" = "fr"): string {
  const ctx = useApp();
  const lang = (ctx as any).lang as Lang;
  const cacheKey = `${sourceLang}:${lang}:${text}`;
  const cachedOut = useMemo(() => {
    if (!text || sourceLang === lang) return text;
    return getCachedTranslation(text, lang) || text;
  }, [text, sourceLang, lang]);
  const [asyncOut, setAsyncOut] = useState<{ key: string; value: string } | null>(null);
  useEffect(() => {
    if (!text || sourceLang === lang || cachedOut !== text) return;
    let cancelled = false;
    (async () => {
      const result = await translateTextCached(text, sourceLang, lang);
      if (!cancelled) setAsyncOut({ key: cacheKey, value: result });
    })();
    return () => { cancelled = true; };
  }, [text, sourceLang, lang, cachedOut, cacheKey]);
  if (!text || sourceLang === lang || cachedOut !== text) return cachedOut;
  return asyncOut?.key === cacheKey ? asyncOut.value : text;
}

                                                        
                                                                    
                                    
function useIsMdUp(): boolean {
  const [isMdUp, setIsMdUp] = useState(false);
  useEffect(() => {
    if (typeof window === "undefined" || !window.matchMedia) return;
    const mq = window.matchMedia("(min-width: 768px)");
    const update = () => setIsMdUp(mq.matches);
    update();
    mq.addEventListener("change", update);
    return () => mq.removeEventListener("change", update);
  }, []);
  return isMdUp;
}

                                                                                                                                          
                                         
                                                                              
                                                                   
                                                                                                                                             
