function resolveProjectNameFromRouteToken(token: string): string {
  const value = String(token || "").trim();
  if (!value) return value;
  const found = findProjectByRouteToken(value);
  if (!found) return value;
  return found.title || found.nome || projectRouteCandidateValues(found)[0] || value;
}

                                                                           
                                                               
                                                                              
                          
                                                                             
                                                                        
                                                                          
                                                      
                                                                        
                                                                              
                                          
