function localizePost(post: BlogPost, lang: Lang): BlogPost {
  if (lang === "fr") return post;
  const tr = BLOG_TRANSLATIONS[post.id]?.[lang as Exclude<Lang, "fr">];
  if (!tr) return post;
  return { ...post, ...tr };
}

type BlogRouteLike = {
  id?: string;
  title?: string;
  byLang?: Partial<Record<Lang, { title?: string }>>;
};

function blogRouteCandidateValues(post: BlogRouteLike, lang?: Lang): string[] {
  const values = [
    lang ? post.byLang?.[lang]?.title : undefined,
    post.title,
    ...Object.values(post.byLang ?? {}).map((entry) => entry?.title),
    post.id,
  ];
  return Array.from(new Set(values.map((value) => String(value || "").trim()).filter(Boolean)));
}

function blogMatchesRouteToken(post: BlogRouteLike, token: string | null | undefined, lang?: Lang): boolean {
  const raw = String(token || "").trim();
  if (!raw) return false;
  let decoded = raw;
  try { decoded = decodeURIComponent(raw); } catch {                }
  const decodedSlug = slugifyProject(decoded);
  return blogRouteCandidateValues(post, lang).some((value) => {
    const candidate = String(value || "").trim();
    return candidate === decoded || slugifyProject(candidate) === decodedSlug;
  });
}

function blogRouteSlug(post: BlogRouteLike, lang?: Lang): string {
  const title = (lang ? post.byLang?.[lang]?.title : undefined) || post.title || post.id || "article";
  return slugifyProject(title) || String(post.id || "article");
}

function canonicalBlogPostRoute(post: BlogRouteLike, lang?: Lang): string {
  return `/blog/${blogRouteSlug(post, lang)}`;
}

function blogStaticPostMatchesRouteToken(post: BlogPost, token: string | null | undefined, lang: Lang): boolean {
  if (blogMatchesRouteToken(post, token, lang) || blogMatchesRouteToken(localizePost(post, lang), token, lang)) return true;
  return Object.values(BLOG_TRANSLATIONS[post.id] ?? {}).some((translation) =>
    blogMatchesRouteToken({ id: post.id, title: translation?.title }, token, lang)
  );
}

function resolveBlogTitleFromRouteToken(token: string | null | undefined, lang: Lang): string | null {
  const staticPost = BLOG_POSTS.find((post) => blogStaticPostMatchesRouteToken(post, token, lang));
  if (staticPost) return localizePost(staticPost, lang).title;
  if (typeof window === "undefined") return null;
  try {
    const drafts = JSON.parse(window.localStorage.getItem("abil_blog_drafts") || "[]") as Array<BlogRouteLike & { status?: string }>;
    const draft = drafts.find((item) => item.status === "published" && blogMatchesRouteToken(item, token, lang));
    return (lang ? draft?.byLang?.[lang]?.title : undefined) || draft?.title || null;
  } catch {
    return null;
  }
}

                                                                                                       
                                                                                                        
                                                                                                        
                                                                                    
                                                                                                 
                                                                                                         
type BlogSeoDraftLike = BlogRouteLike & {
  status?: string;
  subtitle?: string;
  excerpt?: string;
  seoTitle?: string;
  seoDescription?: string;
  byLang?: Partial<Record<Lang, { title?: string; subtitle?: string; excerpt?: string; seoTitle?: string; seoDescription?: string }>>;
};
function resolveBlogSeoFromRouteToken(token: string | null | undefined, lang: Lang): { title: string; description: string } | null {
  const staticPost = BLOG_POSTS.find((post) => blogStaticPostMatchesRouteToken(post, token, lang));
  if (staticPost) {
    const loc = localizePost(staticPost, lang);
    return { title: "", description: (loc.subtitle || "").trim() };
  }
  if (typeof window === "undefined") return null;
  try {
    const drafts = JSON.parse(window.localStorage.getItem("abil_blog_drafts") || "[]") as BlogSeoDraftLike[];
    const draft = drafts.find((item) => item.status === "published" && blogMatchesRouteToken(item, token, lang));
    if (!draft) return null;
    const loc = (lang ? draft.byLang?.[lang] : undefined) || {};
    return {
      title: (loc.seoTitle || draft.seoTitle || "").trim(),
      description: (loc.seoDescription || draft.seoDescription || loc.excerpt || draft.excerpt || loc.subtitle || draft.subtitle || "").trim(),
    };
  } catch {
    return null;
  }
}

                                                                                                                                          
                                         
                                                                          
                                                                                                                                             
type BlogCat =
  | "strategie"
  | "branding"
  | "direction_artistique"
  | "production"
  | "case_study";
type BlogColor = "noir" | "rouge" | "violet" | "beige";
type BlogBlock =
  | { kind: "h2"; text: string }
  | { kind: "p"; text: string }
  | { kind: "img"; bg: BlogColor; caption: string; src: string }
  | { kind: "quote"; text: string };

type BlogPost = {
  id: string;
  title: string;
  subtitle: string;
  cat: BlogCat;
  date: string;
  readMin: number;
  author: string;
  bg: BlogColor;
  heroImg: string;
  tldr: string[];
  body: BlogBlock[];
};

