function CustomCursor({ disabled = false }: { disabled?: boolean }) {
  const cursorRef = useRef<HTMLDivElement>(null);
  const rotatorRef = useRef<HTMLDivElement>(null);
  const [hovering, setHovering] = useState(false);
  const [visible, setVisible] = useState(false);
  const visibleRef = useRef(visible);
  useEffect(() => { visibleRef.current = visible; }, [visible]);

  useEffect(() => {
    if (disabled) return;
    if (typeof window === "undefined") return;
    const isTouch = window.matchMedia("(pointer: coarse)").matches;
    if (isTouch) return;

    let rafId: number | null = null;
    let pendingX = 0;
    let pendingY = 0;
    let prevX = 0;
    let prevY = 0;
    let firstMove = true;
    let rotation = 0;

    const onMove = (e: MouseEvent) => {
      pendingX = e.clientX;
      pendingY = e.clientY;
      if (firstMove) {
        prevX = pendingX;
        prevY = pendingY;
        firstMove = false;
      }
      if (rafId !== null) return;
      rafId = requestAnimationFrame(() => {
        rafId = null;
        const dx = pendingX - prevX;
        const dy = pendingY - prevY;
        prevX = pendingX;
        prevY = pendingY;
                                           
                                                     
                                                     
                                                     
                                                     
                                                    
        rotation += (dx - dy) * 0.5;
        if (cursorRef.current) {
          cursorRef.current.style.transform = `translate3d(${pendingX}px, ${pendingY}px, 0) translate(-50%, -50%)`;
        }
        if (rotatorRef.current) {
          rotatorRef.current.style.transform = `rotate(${rotation}deg)`;
        }
        if (!visibleRef.current) setVisible(true);
      });
    };

                                                                     
                                                                                  
                                                             
                                                                     
                                                         
    let prevHovering = false;
    const onOver = (e: MouseEvent) => {
      const target = e.target as HTMLElement | null;
      if (!target) return;
      const clickable = !!target.closest("a, button, [role='button'], select, label, input, textarea, [data-cursor='clickable']");
      if (clickable !== prevHovering) {
        prevHovering = clickable;
        setHovering(clickable);
      }
    };

    const onLeave = () => setVisible(false);

    document.addEventListener("mousemove", onMove);
    document.addEventListener("mouseover", onOver);
    document.addEventListener("mouseleave", onLeave);
    return () => {
      document.removeEventListener("mousemove", onMove);
      document.removeEventListener("mouseover", onOver);
      document.removeEventListener("mouseleave", onLeave);
      if (rafId !== null) cancelAnimationFrame(rafId);
    };
  }, [disabled]);

  if (disabled) return null;

  return (
    <>
      {                                                                   
                                                                             
                                                                      
                                                                              
                                                                         

                                                                                 
                                                           }
      <style>{`
        @media (pointer: fine) {
          body { cursor: none; }
          a, button, [role='button'], select, label, input, textarea,
          [contenteditable], [data-cursor='clickable'] {
            cursor: none;
          }
        }
      `}</style>
      <div
        ref={cursorRef}
        className="pointer-events-none fixed top-0 left-0 z-[99999] transition-[width,height] duration-500 ease-out"
        style={{
          width: hovering ? "64px" : "32px",
          height: hovering ? "64px" : "32px",
          opacity: visible ? 1 : 0,
          willChange: "transform",
                                                                                 
                                                                                  
                                                                                      
                                                                                    
                                                                       
        }}
      >
        <div ref={rotatorRef} className="w-full h-full" style={{ willChange: "transform" }}>
          <Asterisque className="w-full h-full" color="#d2ff01" />
        </div>
      </div>
    </>
  );
}

                                                                                                                                          
                                                             
                                                                        
                                                                                                                                             
function ViewKeep({ active, children }: { active: boolean; children: React.ReactNode }) {
                                                                               
                                                                             
                                                                            
                                                                               
                                                                             
                                                                                
                                                  
    
                                                                           
                                                                               
                                                                           
                                                                            
                                                                              
                                                                 
                                                                              
                                                                                  
                        
  const [hasBeenActive, setHasBeenActive] = useState(active);
  useEffect(() => {
    if (!active || hasBeenActive) return;
    const id = window.setTimeout(() => setHasBeenActive(true), 0);
    return () => window.clearTimeout(id);
  }, [active, hasBeenActive]);

  return (
    <div
      style={{ display: active ? "contents" : "none" }}
      aria-hidden={!active}
      {...(active ? {} : ({ inert: true } as any))}
    >
      {hasBeenActive ? children : null}
    </div>
  );
}

                                                                                                                                          
      
                                                                                                                                             
   
                                                                          
                                                                           
                                                   
  
                                                                                       
                                                                                               
   
                                                                                 
                                                        
const NEW_VERSION_T: Record<AbilLang, { title: string; server: string; local: string; cta: string }> = {
  fr: { title: "Nouvelle version disponible", server: "Serveur :", local: "Votre navigateur :", cta: "Mettre à jour" },
  en: { title: "New version available", server: "Server:", local: "Your browser:", cta: "Update now" },
  pt: { title: "Nova versão disponível", server: "Servidor:", local: "O seu browser:", cta: "Atualizar" },
  de: { title: "Neue Version verfügbar", server: "Server:", local: "Ihr Browser:", cta: "Jetzt aktualisieren" },
  it: { title: "Nuova versione disponibile", server: "Server:", local: "Il tuo browser:", cta: "Aggiorna ora" },
};

function NewVersionBanner({ lang }: { lang: AbilLang }) {
  const tv = NEW_VERSION_T[lang] ?? NEW_VERSION_T.fr;
  const [mismatch, setMismatch] = useState<{ server: string; local: string } | null>(null);
  useEffect(() => {
    onAppVersionMismatch((server, local) => {
      setMismatch({ server, local });
    });
  }, []);
  if (!mismatch) return null;
  return (
                                                                      
    <div
      className="fixed top-0 inset-x-0 z-[9999] bg-rouge text-noir px-4 py-3 flex items-center justify-between gap-4 shadow-lg"
      style={{ fontSize: "13px" }}
    >
      <div className="flex items-center gap-3">
        <span className="text-xl">*</span>
        <div className="flex flex-col">
          <strong>{tv.title}</strong>
          <span className="opacity-70 text-xs">
            {tv.server} {mismatch.server} · {tv.local} {mismatch.local}
          </span>
        </div>
      </div>
      <button
        type="button"
        onClick={() => {
                                                  
          try {
            if ("caches" in window) {
              caches.keys().then((keys) => Promise.all(keys.map((k) => caches.delete(k))));
            }
          } catch {            }
                                                      
          window.location.reload();
        }}
        className="bg-noir text-white px-4 py-2 font-semibold uppercase tracking-wide text-xs hover:bg-white hover:text-noir transition-colors whitespace-nowrap"
      >
        {tv.cta}
      </button>
    </div>
  );
}

                                                                                                                                          
                                                                        

                                                                                        
                                                                                          
                                                                                      

                                                                                          
                                                                                           
                                                                                             
                                                                                           
                                                                                        
                                                                                                                                             
                                                                          
                                                                            
                                                                    
