function seoDefaultEntries(
  labels?: Partial<Record<"home" | "atelier" | "expertises" | "travaux" | "blog" | "contact", string>>,
): SeoEntry[] {
  return [
    { id: "seo-home", pageTitle: labels?.home || "Accueil", ogTitle: "ABiL MEDiAS · Vraiment habiles", ogDescription: "Agence de communication à Genève. Branding, digital, publicité. La juste solution, au juste budget." },
    { id: "seo-atelier", pageTitle: labels?.atelier || "Atelier", ogTitle: "Atelier · ABiL", ogDescription: "Une agence de communication à Genève, portée par la stratégie." },
    { id: "seo-expertises", pageTitle: labels?.expertises || "Expertises", ogTitle: "Expertises · ABiL", ogDescription: "Stratégie, branding, direction créative, production et activation pour marques ambitieuses." },
    { id: "seo-travaux", pageTitle: labels?.travaux || "Projets", ogTitle: "Projets · ABiL MEDiAS", ogDescription: "Une sélection de ce qui sort de l’atelier. La juste solution, au juste budget." },
    { id: "seo-blog", pageTitle: labels?.blog || "Journal", ogTitle: "Journal · ABiL MEDiAS", ogDescription: "Ce que nous apprenons en travaillant, écrit sans jargon." },
    { id: "seo-contact", pageTitle: labels?.contact || "Contact", ogTitle: "Contact · ABiL MEDiAS", ogDescription: "Genève · Suisse romande. Un briefing en dix minutes." },
  ];
}

                                                                                       
                                                                                              
let __seoBootDescription: string | null = null;
function seoBootDescription(): string {
  if (__seoBootDescription === null) {
    const el = typeof document !== "undefined" ? document.querySelector('meta[name="description"]') : null;
    __seoBootDescription = el?.getAttribute("content") || "";
  }
  return __seoBootDescription;
}
function seoUpsertDescription(content: string) {
  if (typeof document === "undefined") return;
  let el = document.querySelector('meta[name="description"]') as HTMLMetaElement | null;
  if (!el) {
    el = document.createElement("meta");
    el.setAttribute("name", "description");
    document.head.appendChild(el);
  }
  el.setAttribute("content", content);
}
                                                                                      
                                                                         
function seoUpsertRobots(content: string | null) {
  if (typeof document === "undefined") return;
  let el = document.querySelector('meta[name="robots"]') as HTMLMetaElement | null;
  if (content === null) { if (el) el.remove(); return; }
  if (!el) {
    el = document.createElement("meta");
    el.setAttribute("name", "robots");
    document.head.appendChild(el);
  }
  el.setAttribute("content", content);
}
function seoUpsertCanonical(href: string) {
  if (typeof document === "undefined") return;
  let el = document.querySelector('link[rel="canonical"]') as HTMLLinkElement | null;
  if (!el) {
    el = document.createElement("link");
    el.setAttribute("rel", "canonical");
    document.head.appendChild(el);
  }
  el.setAttribute("href", href);
}

function App() {
  const [lang, setLang] = useState<Lang>("fr");
                                                                                  
                                                                                
                                                                                  
                                                                   
  const initialFromUrl = useMemo<{ view: View; project: string | null; post?: string | null }>(() => {
    if (typeof window === "undefined") return { view: "homev3", project: null };
    const path = window.location.pathname;
    if (/^\/apresentacao\/.+$/.test(path)) return { view: "apresentacao", project: null };                                                       
    if (path.startsWith("/proposta/")) return { view: "proposta", project: null };                                                
    if (path === "/dashboard") return { view: "dashboard", project: null };
    if (path === "/login") return { view: "login", project: null };
                                                                       
    if (path === "/admin") return { view: "admin", project: null };
                                                                                 
                                                                                
                                                                                   
                                                 
                                                                                 
                                                 
    return { view: "homev3", project: null };
  }, []);
  const [view, setView] = useState<View>(initialFromUrl.view);
                                                                             
                                                                            
                                                                            
                                                                             
  const [headerTheme, setHeaderTheme] = useState<HeaderTheme>("dark");
  const [selectedPost, setSelectedPost] = useState<string | null>(initialFromUrl.post ?? null);
  const [selectedProject, setSelectedProject] = useState<string | null>(initialFromUrl.project);

                                                                                                            
  const [pageVis] = useCloudState<Record<string, boolean>>("abil_pages_visibility_v2", {});
  useEffect(() => {
    if (!isViewHidden(view, pageVis)) return;
    const id = window.setTimeout(() => {
                                                                                   
                                                                           
      setView("homev3");
      if (typeof window !== "undefined") { try { window.history.replaceState(null, "", "/"); } catch {       } }
    }, 0);
    return () => window.clearTimeout(id);
  }, [view, pageVis]);

                                                                        
                                                                                
                                                                                     
  useEffect(() => {
    if (typeof window === "undefined") return;
    const criticalBanners = [
      "/brand/kv-icon-black-1.jpg",                              
    ];
    criticalBanners.forEach((src) => {
      const img = new Image();
      img.src = src;
    });
  }, []);

                                                                                                  
                                                                                                     
                                                                                              
  const [seoEntries] = useLocalStorageState<SeoEntry[]>("abil_seo", seoDefaultEntries());

                                                            
                                                                                                  
                                                                                                      
  useEffect(() => {
    if (typeof window === "undefined") return;
    const nav = (DICT[lang] as any)?.nav ?? (DICT.fr as any).nav;
    const brand = "ABiL MEDiAS · Vraiment habiles";
    const blogArticleTitle = view === "blog" && selectedPost ? resolveBlogTitleFromRouteToken(selectedPost, lang) : null;
    const pages: Record<string, string> = {
      home:       brand,
      homev2:     `${brand} · V2`,
      homev3:     `${brand} · V3`,
      projects:   `${nav?.projets ?? "Projets"} · ${brand}`,
      expertises: `${nav?.expertises ?? "Expertises"} · ${brand}`,
      atelier:    `${nav?.atelier ?? "Atelier"} · ${brand}`,
      team:       `Studio · ${brand}`,
      blog:       `${blogArticleTitle || (selectedPost ? "Article not found" : (nav?.blog ?? "Blog"))} · ${brand}`,
      contact:    `${nav?.contact ?? "Contact"} · ${brand}`,
      briefing:   `${nav?.briefing ?? "Briefing"} · ${brand}`,
      legal:      `Legal · ${brand}`,
      privacy:    `Privacy · ${brand}`,
      project:    selectedProject ? `${resolveProjectNameFromRouteToken(selectedProject)} · ${brand}` : brand,
    };
                                                                                                          
    const isDetail = (view === "blog" && !!selectedPost) || (view === "project" && !!selectedProject);
    const articleSeo = view === "blog" && selectedPost ? resolveBlogSeoFromRouteToken(selectedPost, lang) : null;
    const seoId = isDetail ? "" : (SEO_ID_BY_VIEW[view] || "");
    const seo = seoId ? seoEntries.find((e) => e.id === seoId) : undefined;
    const seoTitle = (articleSeo?.title || "").trim() || (seo?.ogTitle || "").trim();
    const seoDesc = (articleSeo?.description || "").trim() || (seo?.ogDescription || "").trim();
    const abilPost = view === "blog" && selectedPost ? ABIL_POSTS.find((pp) => pp.slug === selectedPost) : null;
    const abilCase = view === "projects" && selectedProject ? ABIL_CASES.find((cc) => cc.slug === selectedProject) : null;
                                                                                   
                                                                                   
                                                                                       
                                                                                   
    if (view === "homev3") return;
                                                                                             
    seoUpsertRobots(
      SEO_NOINDEX_VIEWS.has(view) ? "noindex, nofollow"
        : SEO_NOINDEX_FOLLOW_VIEWS.has(view) ? "noindex, follow"
        : null,
    );
    document.title = abilPost ? `${abilPost.title.fr} · ABiL MEDiAS` : abilCase ? `${abilCase.title.fr} · ABiL MEDiAS` : (seoTitle || pages[view] || pages.home);
                                                                                                        
                                                                                              
                                                                                 
    seoUpsertDescription(seoDesc || seoBootDescription());
  }, [view, selectedProject, selectedPost, lang, seoEntries]);

                                             
                                                                          
                                                            
  useEffect(() => {
    if (typeof window === "undefined") return;
                                                                                       
                                                                                   
                                                                                    
                                 
    if (view === "apresentacao" || view === "proposta") return;
    if (view === "homev3") {
                                                                                      
                                                                                       
                                                                                       
                                                                                        
                                                                             
      return;
    }
    let path = "/";
    if (view === "project" && selectedProject) {
      path = `/travaux/${resolveProjectSlugFromRouteToken(selectedProject, lang)}`;
    } else if (view === "projects") path = selectedProject && ABIL_CASES.some((c) => c.slug === selectedProject) ? `/work/${encodeURIComponent(selectedProject)}` : "/work";
    else if (view === "expertises") path = "/expertises";
    else if (view === "atelier") path = "/atelier";
    else if (view === "admin") path = "/admin";
    else if (view === "blog" && selectedPost) path = `/blog/${encodeURIComponent(selectedPost)}`;
    else if (view === "blog") path = "/blog";
    else if (view === "contact") path = "/contact";
    else if (view === "briefing") path = "/briefing";
    else if (view === "legal") path = "/mentions";
    else if (view === "privacy") path = "/privacy";
    else if (view === "cookies") path = "/cookies";
    else if (view === "dashboard") path = "/dashboard";
    else if (view === "login") path = "/login";
    if (window.location.pathname !== path) {
      window.history.pushState({ view, project: selectedProject, post: selectedPost }, "", path);
    }
                                                                                                 
                                                                                             
                                                                                                  
    if (view !== "dashboard" && view !== "login") {
      seoUpsertCanonical(`${SEO_SITE_ORIGIN}${path === "/" ? "/" : path}`);
    }
  }, [view, selectedProject, selectedPost, lang]);

  useEffect(() => {
    if (typeof window === "undefined") return;
    const onPop = () => {
      const path = window.location.pathname;
      const projectMatch = path.match(/^\/(?:project|projects|travaux)\/(.+)$/);
      if (projectMatch) {
        setView("project");
                                                                          
        setSelectedProject(resolveProjectNameFromRouteToken(decodeURIComponent(projectMatch[1])));
      } else if (path === "/admin") { setView("admin"); setSelectedProject(null); }
      else if (path === "/dashboard") { setView("dashboard"); setSelectedProject(null); }
      else if (path === "/login") { setView("login"); setSelectedProject(null); }
      else if (/^\/apresentacao\/.+$/.test(path)) { setView("apresentacao"); setSelectedProject(null); }
      else if (path.startsWith("/proposta/")) { setView("proposta"); setSelectedProject(null); }
                                                                                 
                                                                        
      else { setView("homev3"); setSelectedProject(null); }
    };
    window.addEventListener("popstate", onPop);
    return () => window.removeEventListener("popstate", onPop);
  }, []);
                                                                                
                                                                           
  useEffect(() => {
    try {
      document.documentElement.dataset.abilAdmin = view === "admin" ? "1" : "";
    } catch {       }
  }, [view]);
  const [toast, setToast] = useState<string | null>(null);
  const [authedState, setAuthedState] = useState<boolean>(() => {
    if (typeof window === "undefined") return false;
                                                                                                      
                                                                                                       
                                                                                        
                                                                                                          
    try { return abilVaultUnlocked(); } catch { return false; }
  });

                                                                                                                         
  const [chatbotOpen, setChatbotOpen] = useState(false);

                                                                                                                                              
                                                                               
  const [editorMode, setEditorMode] = useState<boolean>(() => {
    if (typeof window === "undefined") return false;
    try { return new URLSearchParams(window.location.search).get("edit") === "1"; } catch { return false; }
  });
                                                                           
                                                                             
  const [previewViewport, setPreviewViewport] = useState<"desktop" | "tablet" | "mobile">("desktop");
                                                                        
                                                                            
                                                                             
  const isEmbeddedPreview = useMemo(() => {
    if (typeof window === "undefined") return false;
    if (window.parent !== window) return true;
    try { return new URLSearchParams(window.location.search).get("_embedded") === "1"; } catch { return false; }
  }, []);
  const [edits, setEditsState] = useState<Record<string, string>>(() => {
    if (typeof window === "undefined") return {};
    try {
      const raw = localStorage.getItem("abil_site_edits_inline");
      const parsed: Record<string, string> = raw ? JSON.parse(raw) : {};
                                                                        
                                                                              
                                  
      const cleaned = { ...parsed };
      let touched = false;
      ["nav.0", "nav.1", "nav.2", "nav.3", "nav.4", "nav.5"].forEach((k) => {
        if (k in cleaned) { delete cleaned[k]; touched = true; }
      });
      if (touched) {
        try { localStorage.setItem("abil_site_edits_inline", JSON.stringify(cleaned)); } catch {            }
      }
      return cleaned;
    } catch { return {}; }
  });
                                                                         
                                                                          
                                                                                 
  const [editsDraft, setEditsDraft] = useState<Record<string, string>>({});
                                                                                                   
                                                                                                
                                                                                 
  const [cloudSiteEdits] = useCloudState<Record<string, string>>("abil_site_edits_inline", {});
  useEffect(() => {
    if (!cloudSiteEdits || typeof cloudSiteEdits !== "object" || !Object.keys(cloudSiteEdits).length) return;
    const id = window.setTimeout(() => {
      setEditsState((prev) => ({ ...prev, ...cloudSiteEdits }));
    }, 0);
    return () => window.clearTimeout(id);
  }, [cloudSiteEdits]);
                                                                                                  
  const isNonTranslatable = useCallback((path: string, value: string): boolean => {
    if (path.endsWith(".href") || path.endsWith(".video") || path.includes("logo.")) return true;
                                                                                 
                                                                                   
                                                                                  
                                                         
    if (path.startsWith("v3.cfg.")) return true;
    if (/^(data:|https?:\/\/|\/|videos\/|view:|#|mailto:|tel:)/i.test(value)) return true;
    return false;
  }, []);
  const { enabled: enabledLangsForEdit } = useEnabledLanguages();
                                                                             
  const pendingTranslationsRef = useRef<Promise<void>[]>([]);
  const setEdit = useCallback((path: string, value: string) => {
                                                                            
                                                                         
                                     
    const ALL = ["fr", "de", "en", "pt", "it"] as Lang[];
    setEditsDraft((prev) => {
      const next = { ...prev };
      if (isNonTranslatable(path, value)) {
        next[path] = value;
      } else {
                                                                             
                                                                          
                                                         
        next[`${path}__${lang}`] = value;
        next[path] = value;
        ALL.forEach((target) => {
          if (target === lang) return;
          const dictResult = dictTranslate(value, target);
          if (dictResult) {
            next[`${path}__${target}`] = dictResult;
            if (typeof window !== "undefined") {
              console.log(`[setEdit sync dict] ${path}__${target}: "${value}" → "${dictResult}"`);
            }
          } else {
                                                                            
                                                    
            next[`${path}__${target}`] = value;                 
          }
        });
      }
      return next;
    });
                                                                             
                                                                                 
    if (!isNonTranslatable(path, value) && value.trim().length >= 2) {
      const otherLangs = ALL.filter((l) => l !== lang);
      const sourceLang = lang;
      const promise = (async () => {
        for (const target of otherLangs) {
                                                            
          const dictResult = dictTranslate(value, target);
          if (dictResult) continue;
          try {
            const translated = await translateText(value, sourceLang, target);
            const finalText = (translated && translated.trim().length > 0 && translated !== value)
              ? translated
              : value;
            setEditsDraft((prev) => ({ ...prev, [`${path}__${target}`]: finalText }));
          } catch {
                                                                              
          }
        }
      })();
      pendingTranslationsRef.current.push(promise);
    }
  }, [isNonTranslatable, lang]);
                                                                               
                                                                               
                                                                                 
  const removeEdit = useCallback((path: string) => {
    const semPath = (m: Record<string, string>): Record<string, string> => {
      let mexeu = false;
      const prox: Record<string, string> = {};
      Object.entries(m).forEach(([k, v]) => {
        if (k === path || k.startsWith(`${path}__`)) { mexeu = true; return; }
        prox[k] = v;
      });
      return mexeu ? prox : m;
    };
    setEditsDraft(semPath);
    setEditsState(semPath);
  }, []);
                                      
                                                                  
                                                                           
                                                                    
                                                            
  const effectiveEdits = useMemo(() => {
    const raw = { ...edits, ...editsDraft };
    const view: Record<string, string> = {};
                                          
    const allPaths = new Set<string>();
    Object.keys(raw).forEach((k) => {
      const m = k.match(/^(.+)__[a-z]{2}$/);
      allPaths.add(m ? m[1] : k);
    });
                                           
    allPaths.forEach((path) => {
      const langKey = `${path}__${lang}`;
      const frKey = `${path}__fr`;
      if (langKey in raw) view[path] = raw[langKey];
      else if (frKey in raw) view[path] = raw[frKey];
      else if (path in raw) view[path] = raw[path];
    });
    return view;
  }, [edits, editsDraft, lang]);

                                                                                  
                                                                                                           
  const tBase = useMemo(() => deepMerge(DICT.fr as any, (DICT[lang as keyof typeof DICT] ?? DICT.fr) as any) as typeof DICT.fr, [lang]);
                                                                                                            
  const [trTick, setTrTick] = useState(0);
  useEffect(() => { if (typeof window === "undefined") return undefined; const h = () => setTrTick((v) => v + 1); window.addEventListener("abil:translation", h); return () => window.removeEventListener("abil:translation", h); }, []);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  const t = useMemo(() => ((NATIVE_DASH_LANGS.indexOf(lang) >= 0 || !(tBase as any)?.dashboard) ? tBase : ({ ...tBase, dashboard: _makeTrProxy((tBase as any).dashboard, "fr" as Lang, lang) } as typeof DICT.fr)), [tBase, lang, trTick]);

  const clearEdits = useCallback(() => {
    setEditsDraft({});
    const ed = (t as any).editor;
    setToast(ed?.toastAnnulee ?? "Modifications annulées");
  }, [t]);
  const saveEdits = useCallback(async () => {
                                                                       
                                                                         
                                                                  
                                         
    if (pendingTranslationsRef.current.length > 0) {
      setToast("* A traduzir via IA...");
      try {
        await Promise.all(pendingTranslationsRef.current);
      } catch {                                     }
      pendingTranslationsRef.current = [];
    }
                                                                          
                                                               
    setEditsDraft((currentDraft) => {
                                                                          
                                                                              
                                                                          
      const ALL = ["fr", "de", "en", "pt", "it"] as Lang[];
      const finalDraft: Record<string, string> = { ...currentDraft };
      Object.entries(currentDraft).forEach(([k, v]) => {
        if (!/__[a-z]{2}$/.test(k) && !isNonTranslatable(k, v)) {
          ALL.forEach((l) => {
            const langKey = `${k}__${l}`;
            if (!(langKey in finalDraft)) {
              const dictResult = dictTranslate(v, l);
              finalDraft[langKey] = dictResult || v;
              if (dictResult && typeof window !== "undefined") {
                console.log(`[saveEdits backfill dict] ${langKey}: "${v}" → "${dictResult}"`);
              }
            }
          });
        }
      });
      const merged = { ...edits, ...finalDraft };
      setEditsState(merged);
      try { localStorage.setItem("abil_site_edits_inline", JSON.stringify(merged)); } catch {            }
                                                                                                  
                                                                           
      try { cloudSet("abil_site_edits_inline", merged); } catch {            }
      const uniquePaths = new Set<string>();
      Object.keys(currentDraft).forEach((k) => {
        const m = k.match(/^(.+)__[a-z]{2}$/);
        uniquePaths.add(m ? m[1] : k);
      });
                                                                                                    
                                                                                                           
                                                                                                       
                                                                      
      try {
        const stamp = new Date().toISOString();
        const touched: Record<string, string> = { ...cloudGet<Record<string, string>>(PAGE_LAST_EDIT_KEY, {}) };
        let any = false;
        uniquePaths.forEach((p) => {
                                                                                       
                                                                                     
          const pid = VIEW_TO_PAGEID[String(p).split(".")[0]] ?? v3PathToPageId(String(p));
          if (pid) { touched[pid] = stamp; any = true; }
        });
        if (any) cloudSet(PAGE_LAST_EDIT_KEY, touched);
      } catch {            }
      const ed = (t as any).editor;
      const baseMsg = typeof ed?.toastSauvee === "function"
        ? ed.toastSauvee(uniquePaths.size)
        : `${uniquePaths.size} modification(s) sauvegardée(s)`;
                                                                               
                                                                             
                                                                             
      setToast(`${baseMsg} · ${_trO({ fr: "envoi au serveur...", pt: "a enviar ao servidor...", en: "sending to server...", de: "senden an Server...", it: "invio al server..." } as never, lang)}`);
      void cloudFlushNow().then((ok) => {
        setToast(ok
          ? `${baseMsg} · ${_trO({ fr: "publié en ligne. Copié dans les 5 langues, à relire.", pt: "publicado na nuvem. Copiado nas 5 línguas, a rever.", en: "published live. Copied across the 5 languages, review needed.", de: "online veröffentlicht. In 5 Sprachen kopiert, bitte prüfen.", it: "pubblicato online. Copiato nelle 5 lingue, da rivedere." } as never, lang)}`
          : `${baseMsg} · ${_trO({ fr: "enregistré seulement dans ce navigateur: le serveur a refusé (coffre?)", pt: "gravado só neste navegador: o servidor recusou (cofre?)", en: "saved only in this browser: server refused (vault?)", de: "nur in diesem Browser gespeichert: Server abgelehnt (Tresor?)", it: "salvato solo in questo browser: il server ha rifiutato (cassaforte?)" } as never, lang)}`);
      });
      return {};               
    });
  }, [edits, isNonTranslatable, t]);

  const showToast = useCallback((msg: string) => setToast(msg), []);
  const hideToast = useCallback(() => setToast(null), []);

                                                                            
                                                                        
                                                                                 
  useEffect(() => {
    if (typeof window === "undefined") return;
    const handler = (e: Event) => {
                                                                                        
      if (view === "homev3") return;
      const detail = (e as CustomEvent).detail;
      if (detail?.error) setToast(detail.error);
    };
    window.addEventListener("abil:storage-error", handler);
    return () => window.removeEventListener("abil:storage-error", handler);
  }, [view]);

                                                                       
                                                                    
                                                                                    
  const setEditorModeSafe = useCallback((next: boolean) => {
    if (next === false) {
      const draftCount = Object.keys(editsDraft).length;
      if (draftCount > 0) {
        const ed = (t as any).editor ?? {};
        const msg = ed?.confirmExitWithDraft ?? `Tem ${draftCount} alteração(ões) não guardada(s). Descartar e sair?`;
        if (typeof window !== "undefined" && !window.confirm(msg)) {
          return;                                    
        }
        setEditsDraft({});                   
      }
    }
    setEditorMode(next);
  }, [editsDraft, t]);
  const setAuthed = (b: boolean) => {
    setAuthedState(b);
    try {
      if (b) sessionStorage.setItem("abil_admin_session", "1");
      else {
        sessionStorage.removeItem("abil_admin_session");
        localStorage.removeItem("abil_admin_session");
                                                                                                           
        abilVaultLogout();
      }
    } catch {            }
  };

  useEffect(() => {
                                                                                       
                                                                                      
                                                                      
    if (ABIL_LANG_OWNED_VIEWS.has(view)) return;
    document.documentElement.lang = lang;
  }, [lang, view]);

                                  
  useEffect(() => {
    window.scrollTo({ top: 0, behavior: "instant" as ScrollBehavior });
  }, [view]);

                                                                          
                                                                         
                                                                        
  useEffect(() => {
                                                                                      
                                                                                          
                                                                             
    if (view === "homev3") return;
    const HEADER_H = 80;
    let rafId: number | null = null;
    let lastTheme: HeaderTheme | null = null;

    const compute = () => {
                                                                           
                                                                          
                                                                         
      const allSections = document.querySelectorAll<HTMLElement>(
        "[data-header-theme]"
      );
      const sections = Array.from(allSections).filter((s) => s.offsetParent !== null);
      let active: HTMLElement | null = null;
      let lastPassed: HTMLElement | null = null;
                                                                                
                                                                                   
                                                                                
                                                                               
      for (const sec of sections) {
        const rect = sec.getBoundingClientRect();
        if (rect.top <= HEADER_H) {
          lastPassed = sec;
          if (rect.bottom > HEADER_H) {
            active = sec;
            break;
          }
        }
      }
      const target = active ?? lastPassed ?? sections[0];
      if (target) {
        const t = target.getAttribute("data-header-theme") as HeaderTheme;
        if ((t === "dark" || t === "light") && t !== lastTheme) {
          lastTheme = t;
          setHeaderTheme(t);
        }
      }
      rafId = null;
    };

    const onScroll = () => {
      if (rafId !== null) return;
      rafId = requestAnimationFrame(compute);
    };

    window.addEventListener("scroll", onScroll, { passive: true });
                                                                      
    const initialTick = setTimeout(compute, 50);

    return () => {
      window.removeEventListener("scroll", onScroll);
      clearTimeout(initialTick);
      if (rafId !== null) cancelAnimationFrame(rafId);
    };
  }, [view]);

                                                                         
                                                                                 
                                                                  
                                                                              
                                                          
  const appContextValue = React.useMemo(() => ({
    lang, setLang, t, view, setView, headerTheme, setHeaderTheme,
    selectedPost, setSelectedPost, selectedProject, setSelectedProject,
    toast, showToast, hideToast,
    authed: authedState, setAuthed,
    editorMode, setEditorMode: setEditorModeSafe,
    edits: effectiveEdits, setEdit, removeEdit, clearEdits, saveEdits,
    chatbotOpen, setChatbotOpen,
    previewViewport, setPreviewViewport,
  }), [
    lang, t, view, headerTheme,
    selectedPost, selectedProject,
    toast,
    authedState,
    editorMode, effectiveEdits,
    chatbotOpen,
    previewViewport,
    clearEdits,
    hideToast,
    saveEdits,
    setEdit,
    removeEdit,
    setEditorModeSafe,
    showToast,
                                                                                
  ]);

  return (
    <AppContext.Provider value={appContextValue}>
      {                                                                                   
                                                                                          
                                                                                         }
      <ProjectsProvider hidratar={authedState || PROJECTS_HYDRATION_VIEWS.has(view)}>
      {                                                                          
                                                                             
                                                                               
                                                                                
                                               }
      <div className={`min-h-screen bg-background text-foreground selection:bg-rouge selection:text-white ${editorMode && !isEmbeddedPreview && view !== "homev3" ? "pt-14" : ""}`}>
        {view === "homev3" ? null : <EditorBanner />}
        {                                                                    
                                                                              
                                                                             
                                                                       
                                                                                  
                                            
                                                                     }
        {editorMode && previewViewport !== "desktop" ? (
          <div className="bg-neutral-200 min-h-[calc(100vh-3.5rem)] py-4 px-2 flex items-start justify-center">
            <div
              className="bg-background shadow-2xl border border-neutral-300 overflow-hidden transition-all duration-300"
              style={{
                width: previewViewport === "mobile" ? 390 : 820,
                height: "calc(100vh - 5rem)",
              }}
            >
              <iframe
                key={previewViewport}
                src={`${window.location.pathname}?edit=1&_embedded=1`}
                title={`Preview ${previewViewport}`}
                className="w-full h-full block"
                style={{ border: "none" }}
              />
            </div>
          </div>
        ) : (
          <ViewportInner view={view} setView={setView} />
        )}
        {                                                                          
                                                                             
                                                                          
                                                                            }
        {view !== "homev3" && <Toast visible={toast !== null} message={toast || ""} onClose={hideToast} />}
        {                                                                            }
        {view !== "dashboard" && view !== "login" && view !== "homev3" && view !== "admin" && <CookieBanner />}
        {                                                                                                                      }
        {view !== "dashboard" && view !== "login" && view !== "homev3" && view !== "admin" && (authedState
          ? <SuperadminAgentBubble lang={lang} currentModule="site-publico" openModule={(id) => { try { localStorage.setItem("abil_dashboard_open_module", id); } catch {       } setView("dashboard"); }} />
          : <ChatbotWidget />)}
        {                                                                                  
                                                                                        
                                                                                          
                                                                                             }
        <CustomCursor disabled />
      </div>
      </ProjectsProvider>
    </AppContext.Provider>
  );
}

                                                                                      
                                                                                   
                                                                                        
                                                                    
