function Testimonials() {
  const { lang } = useApp();
  const [items, setItems] = useState<{ id: string; cliente: string; empresa: string; texto: string; idioma: string }[]>([]);
  useEffect(() => {
    let alive = true;
    (async () => {
      try {
        const r = await fetch("/api/private-store?public=testimonials", { cache: "no-store" });
        if (!r.ok) return;
        const d = await r.json().catch(() => null);
        const arr = Array.isArray(d?.testimonials) ? d.testimonials : [];
        if (alive) setItems(arr.filter((x: { texto?: unknown }) => x && String(x.texto || "").trim()));
      } catch {                                                                                     }
    })();
    return () => { alive = false; };
  }, []);
                                                                             
  const i18n = ({
    fr: { label: "* Témoignages", sub: "Ce qu'en disent nos clients" },
    de: { label: "* Referenzen", sub: "Was unsere Kunden sagen" },
    en: { label: "* Testimonials", sub: "What our clients say" },
    pt: { label: "* Testemunhos", sub: "O que dizem os clientes" },
    it: { label: "* Testimonianze", sub: "Cosa dicono i nostri clienti" },
    es: { label: "* Testimonios", sub: "Lo que dicen nuestros clientes" },
  } as Record<string, { label: string; sub: string }>)[lang] || { label: "* Témoignages", sub: "Ce qu'en disent nos clients" };
  if (!items.length) return null;                                                  
  return (
    <section data-header-theme="light" className="py-16 md:py-20 px-6 lg:px-10 border-t border-neutral-200 bg-white">
      <div className="mx-auto max-w-[1480px]">
        <div className="font-mono text-[10px] uppercase tracking-[0.25em] text-neutral-500 flex items-center gap-2 mb-10">
          <Asterisque className="w-3 h-3" color="#d2ff01" />
          {i18n.label} · <span className="text-neutral-300">{i18n.sub}</span>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-x-6 gap-y-10">
          {items.slice(0, 6).map((t) => (
            <blockquote key={t.id} className="border-t border-neutral-300 pt-6 flex flex-col gap-4">
              <p className="text-base md:text-lg leading-relaxed text-noir/85">« {t.texto} »</p>
              <footer className="font-mono text-[10px] uppercase tracking-[0.2em] text-neutral-500 mt-auto">
                {t.cliente}{t.empresa ? <span className="text-neutral-400"> · {t.empresa}</span> : null}
              </footer>
            </blockquote>
          ))}
        </div>
      </div>
    </section>
  );
}

                                                                                                                                          
          
                                                                                                                                             
