function LegalContentRenderer({ pathPrefix, content }: { pathPrefix: "legalPage" | "privacyPage"; content: LegalContent }) {
  const { setView, edits, lang } = useApp();
  const resolve = (subpath: string, fallback: string): string => {
    const path = `${pathPrefix}.${subpath}`;
    const langKey = `${path}__${lang}`;
    const val = edits[langKey] ?? edits[path];
    return (typeof val === "string" && val.trim() !== "") ? val : fallback;
  };
  return (
    <main data-header-theme="light" className="bg-white pt-16 md:pt-20 min-h-screen">
      <section className="px-6 lg:px-10 py-12 md:py-20">
        <div className="mx-auto max-w-3xl">
          <button
            onClick={() => setView("home")}
            className="eyebrow eyebrow-sm text-neutral-500 hover:text-rouge transition-colors mb-8"
          >
            {resolve("back", content.back)}
          </button>
          <h1 className="font-semibold tracking-[-0.03em] leading-tight text-[clamp(2rem,4.5vw,3.5rem)] mb-3">
            {resolve("title", content.title)}
          </h1>
          <p className="text-base text-neutral-600 mb-2">{resolve("subtitle", content.subtitle)}</p>
          <p className="eyebrow text-neutral-400 mb-8">{resolve("lastUpdated", content.lastUpdated)}</p>
          {                                                                             
                                                                                         
                                                                                           }
          <div className="space-y-8">
            {content.blocks.map((b, i) => (
              <section key={i} className="border-t border-neutral-200 pt-6">
                <h2 className="font-semibold text-lg tracking-[-0.02em] mb-3">{resolve(`block.${i}.heading`, b.heading)}</h2>
                <p className="text-sm text-neutral-700 leading-relaxed whitespace-pre-line">{resolve(`block.${i}.body`, b.body)}</p>
              </section>
            ))}
          </div>
        </div>
      </section>
    </main>
  );
}

function LegalPage() {
  const { lang } = useApp();
  return <LegalContentRenderer pathPrefix="legalPage" content={LEGAL_CONTENT[lang]} />;
}

function PrivacyPage() {
  const { lang } = useApp();
  return <LegalContentRenderer pathPrefix="privacyPage" content={PRIVACY_CONTENT[lang]} />;
}

function CookiesPage() {
  const { lang, setView } = useApp();
  const content = COOKIES_CONTENT[lang];
  return (
    <div>
      <LegalContentRenderer pathPrefix="cookiesPage" content={content} />
      <div className="mx-auto max-w-[1480px] px-6 lg:px-10 pb-16 -mt-8">
        <button
          type="button"
          onClick={() => {
            try { localStorage.removeItem("abil_cookies_v1"); } catch {            }
            setView("home");
            if (typeof window !== "undefined") setTimeout(() => window.location.reload(), 50);
          }}
          className="bg-rouge text-white px-5 py-2.5 eyebrow hover:bg-white hover:text-noir transition-colors"
        >
          {(content as { reopen?: string }).reopen ?? "Reopen cookie settings"}
        </button>
      </div>
    </div>
  );
}

