function ProjectsPage() {
  const { t, setView, setSelectedProject, editorMode, showToast } = useApp();
  const [filter, setFilter] = useState<CatKey | null>(null);
  const isMdUp = useIsMdUp();
                                                                                    
                                                                                      
                                                                                
                                                                         
                                                                                   
                                                                                        
  const ROWS_INITIAL = 2;
  const ROWS_PER_LOAD = 1;
                                                                                    
  const [formOpen, setFormOpen] = useState(false);
  const [visibleRows, setVisibleRows] = useState(ROWS_INITIAL);
  const sentinelRef = useRef<HTMLDivElement | null>(null);
                              
  const ctaHref = useEditedHref("projets.footerCta.href", "view:home#contact");
  const handleSmartHref = (href: string, e: React.MouseEvent) => {
    if (editorMode) { e.preventDefault(); return; }
    if (href.startsWith("view:")) {
      e.preventDefault();
      const target = href.replace("view:", "");
      const [v, anchor] = target.split("#");
      setView(v as any);
      if (typeof window !== "undefined") {
        window.scrollTo({ top: 0, behavior: "instant" as ScrollBehavior });
        if (anchor) setTimeout(() => document.getElementById(anchor)?.scrollIntoView({ behavior: "smooth" }), 60);
      }
    }
  };

  const openProject = (name: string) => {
    setSelectedProject(name);
    setView("project");
    if (typeof window !== "undefined") window.scrollTo({ top: 0, behavior: "instant" as ScrollBehavior });
  };
                                                                         
                                                                   
  const [dashProjects, setDashProjects] = useDashProjectsIDB([]);

                                                                             
                                                                                 
                                                                             
                                                                             
                                                                               
                                                                  
  const destaquesReparados = useRef(false);
  useEffect(() => {
    if (destaquesReparados.current || dashProjects.length === 0) return;
    const dest = dashProjects.filter((p) => p.featured);
    const nums = dest.map((p) => p.featuredOrder);
    const haRepetido = new Set(nums).size !== nums.length || nums.some((n) => typeof n !== "number");
    if (!haRepetido) { destaquesReparados.current = true; return; }
    destaquesReparados.current = true;
    const ordenados = dest.slice().sort((a, b) =>
      ((a.featuredOrder ?? 999) - (b.featuredOrder ?? 999))
      || String(b.updatedAt || b.publishedAt || "").localeCompare(String(a.updatedAt || a.publishedAt || "")));
    const nova = new Map(ordenados.map((p, i) => [p.id, i + 1]));
    setDashProjects((prev) => prev.map((p) => (p.featured && nova.has(p.id) ? { ...p, featuredOrder: nova.get(p.id)! } : p)));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [dashProjects]);

                                                                        
                                                            
  const onProjectSave = (project: DashboardProject) => {
    const isNew = !dashProjects.find((p) => p.id === project.id);
    setDashProjects((prev) => {
      const exists = prev.find((p) => p.id === project.id);
      if (exists) return prev.map((p) => (p.id === project.id ? project : p));
      return [project, ...prev];
    });
    setFormOpen(false);
    showToast(isNew ? `* Projecto « ${project.title} » publicado` : `Projecto « ${project.title} » actualizado`);
  };

                                                                     
                                                                          
                                              
  type UnifiedProject = {
    nome: string;
    cat: CatKey;
    annee: string;
                                                                              
                                                                               
                                                                                  
                                                                                 
                                                                           
    cover?: { type: "image" | "video"; src: string; previewSrc?: string; posterSrc?: string } | null;
    description?: string;
  };
  const unifiedProjects: UnifiedProject[] = useMemo(() => {
    const fromDash: UnifiedProject[] = dashProjects.filter((p) => !p.hidden)
                                                                                  
      .slice()
      .sort((a, b) => String(b?.publishedAt || "").localeCompare(String(a?.publishedAt || "")))
      .map((p) => ({
      nome: p.title ?? "",
      cat: (p.categories?.[0] ?? "branding") as CatKey,
      annee: ((p as any).year && String((p as any).year).trim()) || (p.publishedAt ? String(new Date(p.publishedAt).getFullYear()) : ""),
      cover: p.cover ? {
        type: p.cover.type,
        src: p.cover.src,
        previewSrc: p.cover.previewSrc,                              
        posterSrc: p.cover.posterSrc,                                
      } : null,
      description: p.description,
    }));
    const fromStatic: UnifiedProject[] = PROJETS_TODOS.map((p) => ({
      nome: p.nome,
      cat: p.cat,
      annee: p.annee,
    }));
                                                     
    const dashNames = new Set(fromDash.map((p) => p.nome));
    const staticDeduped = fromStatic.filter((p) => !dashNames.has(p.nome));
    return [...fromDash, ...staticDeduped];
  }, [dashProjects]);

                                                              
  const catsPresent = useMemo(() => {
    const set = new Set<CatKey>();
    unifiedProjects.forEach((p) => set.add(p.cat));
    return Array.from(set);
  }, [unifiedProjects]);

  const projectsFiltered = useMemo(
    () => (filter ? unifiedProjects.filter((p) => p.cat === filter) : unifiedProjects),
    [filter, unifiedProjects]
  );

                                                                                                
  useEffect(() => {
    const id = window.setTimeout(() => setVisibleRows(ROWS_INITIAL), 0);
    return () => window.clearTimeout(id);
  }, [filter]);

                                                                                             
  const totalRows = Math.ceil(projectsFiltered.length / 2);
  const hasMore = visibleRows < totalRows;
  useEffect(() => {
    if (!hasMore) return;
    const sentinel = sentinelRef.current;
    if (!sentinel) return;
    const obs = new IntersectionObserver(
      (entries) => {
        if (entries[0]?.isIntersecting) {
          setVisibleRows((r) => Math.min(r + ROWS_PER_LOAD, totalRows));
        }
      },
      { rootMargin: "150px 0px" }                                                                    
    );
    obs.observe(sentinel);
    return () => obs.disconnect();
  }, [hasMore, totalRows]);

                                          
  const projectsVisible = useMemo(
    () => projectsFiltered.slice(0, visibleRows * 2),
    [projectsFiltered, visibleRows]
  );

                                                                        
                                                                  
  const catBg: Record<CatKey, string> = {
    branding: "bg-noir text-white",
    campagne: "bg-rouge text-white",
    film: "bg-noir text-white",
    digital: "bg-violet text-white",
    editorial: "bg-beige text-white",
    ooh: "bg-rouge text-white",
    social: "bg-violet text-white",
  };

  return (
    <main data-header-theme="light" className="bg-white pt-16 md:pt-20">
      {                                                     }
      <section className="px-6 lg:px-10 py-10 md:py-16 border-b border-neutral-200">
        <div className="mx-auto max-w-[1480px]">
          <button
            onClick={() => setView("home")}
            className="group inline-flex items-center gap-2 font-mono text-[11px] uppercase tracking-[0.2em] text-neutral-500 hover:text-rouge transition-colors mb-8"
          >
            <ArrowLeft className="w-3.5 h-3.5 group-hover:-translate-x-1 transition-transform" />
            <EditableText path="projets.back" defaultText={t.projets.back} maxLength={30} />
          </button>

          <div className="grid grid-cols-12 gap-x-6">
            <div className="col-span-12 lg:col-span-2">
              <div className="font-mono text-[10px] uppercase tracking-[0.25em] text-rouge mb-4">
                <EditableText path="projets.eyebrow" defaultText="* Trabalhos" maxLength={20} />
              </div>
            </div>
            <div className="col-span-12 lg:col-span-10">
              <h1
                className="font-semibold tracking-[-0.04em] leading-[0.95] text-[clamp(2.5rem,6vw,4.5rem)] max-w-[20ch]"
                style={{ textWrap: "balance" as React.CSSProperties["textWrap"] }}
              >
                <TitleLines combinedPath="projets.title.combined" defaults={t.projets.title} />
                <RotatingAsterisque speed={0.6} className="ml-2 w-[0.35em] h-[0.35em] inline-block align-baseline" color="#d2ff01" />
              </h1>
              <p className="mt-5 text-base md:text-lg text-neutral-600 max-w-2xl leading-relaxed">
                <EditableText path="projets.subtitle" defaultText={t.projets.subtitle} maxLength={200} textarea />
              </p>
            </div>
          </div>
        </div>
      </section>

      {             }
      <section className="px-6 lg:px-10 py-6 md:py-8 border-b border-neutral-200 bg-neutral-50 sticky top-16 md:top-20 z-40 backdrop-blur-md bg-neutral-50/90">
        <div className="mx-auto max-w-[1480px] flex flex-wrap items-center gap-2 md:gap-3">
          <span className="font-mono text-[10px] uppercase tracking-[0.25em] text-neutral-500 mr-2 hidden md:inline">
            <EditableText path="projets.filterLabel" defaultText={t.blog.filterLabel} maxLength={30} />
          </span>
          <FilterChip active={filter === null} onClick={() => setFilter(null)}>
            <EditableText path="projets.filterAll" defaultText={t.projets.filterAll} maxLength={20} />
          </FilterChip>
          {catsPresent.map((c) => (
            <FilterChip key={c} active={filter === c} onClick={() => setFilter(c)}>
              {t.categories[c]}
            </FilterChip>
          ))}
          <span className="ml-auto font-mono text-[10px] uppercase tracking-[0.25em] text-neutral-400">
            {t.projets.count(projectsFiltered.length)}
          </span>
        </div>
      </section>

      {                                                                       
                                              
                                           
                                                                               
                                             }
      <section className="px-6 lg:px-10 py-12 md:py-16">
        <div className="mx-auto max-w-[1480px] space-y-1 md:space-y-1.5">
          {                                                                   
                                                                              
                                                 }
          {projectsFiltered.length === 0 && !editorMode && (
            <div className="py-24 md:py-32 text-center">
              <div className="font-mono text-[10px] uppercase tracking-[0.25em] text-rouge mb-4">* Em breve</div>
              <p className="text-2xl md:text-3xl font-semibold tracking-[-0.02em] text-noir max-w-2xl mx-auto">
                Projectos a publicar.
              </p>
              <p className="mt-3 text-sm md:text-base text-neutral-500 max-w-xl mx-auto">
                Estamos a preparar a próxima vaga de casos. Volte em breve.
              </p>
            </div>
          )}
          {Array.from({ length: Math.ceil(projectsVisible.length / 2) }).map((_, rowIdx) => {
            const pair = projectsVisible.slice(rowIdx * 2, rowIdx * 2 + 2);
            const isCinemaFirst = rowIdx % 2 === 0;
            const isOrphanRow = pair.length === 1;

            const renderProject = (p: UnifiedProject | undefined, layout: "cinema" | "portrait", indexInPair: number) => {
              if (!p) return null;
              const globalIndex = rowIdx * 2 + indexInPair + 1;
              const aspect = layout === "cinema" ? "aspect-[16/9]" : "aspect-[4/5]";
                                                                               
                                                                                         
                                                                                    
                                                                                     
                                                       
                                                                                       
                                                                                     
                                                                                  
                                           
              const aspectRatioCSS = layout === "cinema" ? "16/9" : "4/5";
              const imgWidth = 1600;
              const imgHeight = layout === "cinema" ? 900 : 2000;
              const isAboveFold = rowIdx === 0;                          
              return (
                                                                                              
                                                                           
                <button
                  key={`${p.nome}-${rowIdx}-${indexInPair}`}
                  onClick={() => openProject(p.nome)}
                  style={{ aspectRatio: aspectRatioCSS }}
                  className={`text-left group relative overflow-hidden ${aspect} bg-noir transition-all hover:scale-[1.01] w-full`}
                >
                  {                                                               
                                                                             
                                                                                   
                                                                                
                                                                           
                                                                             }
                  <Asterisque
                    className="absolute -right-6 -bottom-8 w-[180px] opacity-10 pointer-events-none text-white"
                    color="currentColor"
                  />
                  {p.cover ? (
                    p.cover.type === "video" ? (
                      <VideoThumb src={p.cover.src} previewSrc={p.cover.previewSrc} posterSrc={p.cover.posterSrc} className="absolute inset-0 w-full h-full" />
                    ) : p.cover.type === "pdf" ? (
                                                                                                                                  
                      <PdfPageCanvas src={p.cover.src} width={(p.cover as any).pdfWidth} height={(p.cover as any).pdfHeight} alt={p.nome} eager={isAboveFold} cover className="absolute inset-0 w-full h-full" />
                    ) : (
                      <SmartImage
                        src={p.cover.src}
                        alt={p.nome}
                        width={imgWidth}
                        height={imgHeight}
                        loading={isAboveFold ? "eager" : "lazy"}
                        decoding="async"
                        fetchPriority={isAboveFold ? "high" : "auto"}
                        className="absolute inset-0 w-full h-full object-cover"
                      />
                    )
                  ) : (
                    <Asterisque
                      className="absolute -right-6 -bottom-8 w-[180px] opacity-10 pointer-events-none"
                      color="currentColor"
                    />
                  )}
                  {                                                                     }
                  <div className="absolute inset-0 bg-black/70 opacity-0 group-hover:opacity-100 transition-opacity duration-700 ease-out p-5 md:p-6 flex flex-col justify-between text-white">
                    <div className="flex items-start justify-between">
                      <span className="font-mono text-[10px] uppercase tracking-[0.25em]">
                        {String(globalIndex).padStart(2, "0")} / {t.categories[p.cat]}
                      </span>
                      <ArrowUpRight className="w-4 h-4 group-hover:rotate-45 transition-transform" />
                    </div>
                    <div>
                      <h3 className="font-semibold tracking-[-0.025em] leading-[1.05] mb-1 text-xl md:text-2xl">
                        {p.nome}
                      </h3>
                      <span className="eyebrow opacity-80">
                        {p.annee}
                      </span>
                    </div>
                  </div>
                </button>
              );
            };

            const colsCinemaFirst = "1.7778fr 0.8fr";
            const colsCinemaLast = "0.8fr 1.7778fr";
            if (isOrphanRow) {
              return (
                <div key={rowIdx} className="grid gap-1 md:gap-1.5" style={{ gridTemplateColumns: "1fr" }}>
                  <RevealItem delay={0} className="w-full">{renderProject(pair[0], "cinema", 0)}</RevealItem>
                </div>
              );
            }
            return (
              <div
                key={rowIdx}
                className="grid gap-1 md:gap-1.5"
                style={{
                  gridTemplateColumns: isMdUp
                    ? (isCinemaFirst ? colsCinemaFirst : colsCinemaLast)
                    : "1fr",
                }}
              >
                {                                                            }
                {isCinemaFirst ? (
                  <>
                    <RevealItem delay={0} className="w-full">{renderProject(pair[0], "cinema", 0)}</RevealItem>
                    <RevealItem delay={100} className="w-full">{renderProject(pair[1], "portrait", 1)}</RevealItem>
                  </>
                ) : (
                  <>
                    <RevealItem delay={0} className="w-full">{renderProject(pair[0], "portrait", 0)}</RevealItem>
                    <RevealItem delay={100} className="w-full">{renderProject(pair[1], "cinema", 1)}</RevealItem>
                  </>
                )}
              </div>
            );
          })}

          {                                                                        }
          {hasMore && (
            <div ref={sentinelRef} className="h-4" aria-hidden="true" />
          )}

          {                                                                  }
          {hasMore && (
            <div className="text-center font-mono text-[10px] uppercase tracking-[0.25em] text-neutral-400 py-6">
              {visibleRows * 2} / {projectsFiltered.length}
            </div>
          )}

          {                                                                            
                                                                                  
                                                                                  
                                              }
          {editorMode && (
            <button
              onClick={() => setFormOpen(true)}
              className="w-full mt-2 md:mt-4 py-12 md:py-16 border-2 border-dashed border-neutral-300 hover:border-rouge hover:bg-rouge/5 transition-colors flex items-center justify-center gap-3 group"
            >
              <span className="font-mono text-base md:text-lg uppercase tracking-[0.15em] text-neutral-500 group-hover:text-rouge transition-colors">
                {(t.projets as any).addProject ?? "+ Add new project"}
              </span>
              <ArrowUpRight className="w-5 h-5 text-neutral-400 group-hover:text-rouge group-hover:rotate-45 transition-all" />
            </button>
          )}
        </div>
      </section>

      {                                                          }
      {formOpen && (
        <ProjectFormModal
          existing={null}
          onClose={() => setFormOpen(false)}
          onSave={onProjectSave}
        />
      )}

      {                               }
      <section data-header-theme="dark" className="px-6 lg:px-10 py-16 md:py-20 border-t border-neutral-200 bg-noir text-white">
        <div className="mx-auto max-w-[1480px] grid grid-cols-12 gap-x-6 items-center">
          <div className="col-span-12 lg:col-span-8">
            <h2 className="font-semibold tracking-[-0.03em] leading-[0.95] text-3xl md:text-5xl">
              {t.contact.title}
              <Asterisque
                className="ml-3 w-[0.5em] h-[0.5em] inline-block translate-y-[0.05em]"
                color="#d2ff01"
              />
            </h2>
          </div>
          <div className="col-span-12 lg:col-span-4 lg:flex lg:justify-end mt-6 lg:mt-0">
            <a
              href={ctaHref.startsWith("view:") ? "#" : ctaHref}
              onClick={(e) => handleSmartHref(ctaHref, e)}
              className="group inline-flex items-center gap-3 bg-rouge text-white px-7 py-4 font-mono text-[11px] uppercase tracking-[0.2em] hover:bg-white hover:text-noir transition-colors"
            >
              <EditableText
                path="projets.footerCta"
                defaultText={t.hero.cta}
                maxLength={40}
                hrefPath="projets.footerCta.href"
                defaultHref="view:home#contact"
              />
              <ArrowUpRight className="w-4 h-4 group-hover:rotate-45 transition-transform" />
            </a>
          </div>
        </div>
      </section>

      <Footer />
    </main>
  );
}

