const VP_SITE = "abil";                                               
const VP_CLOUD_BASE = "";                                                                    
const VP_ORPHAN_MS = 20 * 60 * 1000;
function vpAdminToken(): string { try { return (typeof localStorage !== "undefined" && localStorage.getItem("abil_vault_token")) || ""; } catch { return ""; } }
async function cloudLoadVPs(): Promise<VideoProposal[] | null> {
  const tok = vpAdminToken(); if (!tok) return null;
  try {
    const r = await fetch(`${VP_CLOUD_BASE}/api/video-proposals?site=${VP_SITE}`, { headers: { "x-abil-admin": tok }, cache: "no-store" });
    if (!r.ok) return null;
    const d = await r.json(); return Array.isArray(d?.vps) ? d.vps : [];
  } catch { return null; }
}
async function cloudPushVPs(vps: VideoProposal[]): Promise<void> {
  const tok = vpAdminToken(); if (!tok || !vps.length) return;
  try {
    await fetch(`${VP_CLOUD_BASE}/api/video-proposals?site=${VP_SITE}`, { method: "POST", headers: { "Content-Type": "application/json", "x-abil-admin": tok }, body: JSON.stringify({ vps }) });
  } catch {                   }
}
async function cloudDeleteVP(id: string): Promise<void> {
  const tok = vpAdminToken(); if (!tok || !id) return;
  try { await fetch(`${VP_CLOUD_BASE}/api/video-proposals?site=${VP_SITE}&id=${encodeURIComponent(id)}`, { method: "DELETE", headers: { "x-abil-admin": tok } }); } catch {       }
}
function reconcileOrphanVPs(vps: VideoProposal[]): VideoProposal[] {
  const GEN = new Set(["generating_script", "generating_voiceover", "rendering_video", "script_ready", "voiceover_ready"]);
  const now = Date.now();
  return vps.map((v) => {
    if (v && GEN.has(v.status as string) && !v.jobId) {
      const t = Date.parse(v.updatedAt || v.createdAt || "");
      if (Number.isFinite(t) && (now - t) > VP_ORPHAN_MS) {
        return { ...v, status: "failed", errorMessage: "Geração interrompida (browser fechado a meio). Tenta de novo.", statusDetail: "", updatedAt: new Date().toISOString() } as VideoProposal;
      }
    }
    return v;
  });
}
function mergeVPs(a: VideoProposal[], b: VideoProposal[]): VideoProposal[] {
  const map = new Map<string, VideoProposal>();
  for (const v of [...a, ...b]) {
    if (!v || typeof v.id !== "string") continue;
    const ex = map.get(v.id);
    if (!ex) { map.set(v.id, v); continue; }
    const tv = Date.parse(v.updatedAt || v.createdAt || "") || 0;
    const te = Date.parse(ex.updatedAt || ex.createdAt || "") || 0;
    map.set(v.id, tv >= te ? v : ex);
  }
  return Array.from(map.values());
}
function emptyVideoProposal(quote: Quote): VideoProposal {
  const now = new Date().toISOString();
  return {
    id: `vp_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`,
    quoteId: quote.id,
    briefingId: quote.briefingId,
                                                                                   
                                                                                      
                                                                                      
                                                                                           
    slug: `p-${(globalThis.crypto?.randomUUID?.() || `${Date.now()}${Math.random()}`).replace(/-/g, "").slice(0, 24)}`,
    status: "not_started",
    fullScript: "",
    scenes: [],
    cta: "",
    tone: "close",
    durationMode: "standard",
    includePricing: false,
    videoStyle: "motion",
    createdAt: now,
    updatedAt: now,
  };
}

                                                                         
                                                  
async function autoTranslateQuote(q: Quote, sourceLangHint?: Lang): Promise<Quote> {
  const sourceLang: Lang = sourceLangHint || q.sourceLang || "fr";
  const targets = ALL_LANGS_AUTO_TRANSLATE.filter((l) => l !== sourceLang);
  const byLang: NonNullable<Quote["byLang"]> = { ...(q.byLang || {}) };
  byLang[sourceLang] = {
    projetoTitulo: q.projetoTitulo,
    bienvenueIntro: q.bienvenueIntro,
    condicoesGerais: q.condicoesGerais,
    validade: q.validade,
    processoEtapas: q.processoEtapas,
    phases: q.phases,
  };
  await Promise.all(
    targets.map(async (target) => {
      try {
                                                                                         
                                                                              
        const translatePhases = async (): Promise<QuotePhase[]> => {
                                                                                                     
                                                                                                        
                                                                                                        
                                                                                                  
          const tr = (s?: string) => (s && s.trim() ? translateTextCached(s, sourceLang, target) : Promise.resolve(s));
          return Promise.all(q.phases.map(async (ph) => {
            const [tituloP, subP, linhasP, diag, espec, crono, polit, esc, auto, ideias, obs] = await Promise.all([
              translateTextCached(ph.titulo, sourceLang, target),
              ph.subtitulo ? translateTextCached(ph.subtitulo, sourceLang, target) : Promise.resolve(undefined),
              Promise.all(ph.linhas.map(async (l) => {
                const [tit, desc, bullets] = await Promise.all([
                  translateTextCached(l.titulo, sourceLang, target),
                  l.descricao ? translateTextCached(l.descricao, sourceLang, target) : Promise.resolve(""),
                  Promise.all((l.bullets || []).map((b) => translateTextCached(b, sourceLang, target))),
                ]);
                return { ...l, titulo: tit, descricao: desc, bullets };
              })),
              tr(ph.diagnostico),
              tr(ph.especificacoes),
              tr(ph.cronograma),
              tr(ph.politicaAlteracoes),
              tr(ph.escopo),
              tr(ph.autonomia),
              tr(ph.ideiasConteudo),
              tr(ph.observacoes),
            ]);
            return {
              ...ph,
              titulo: tituloP,
              subtitulo: subP,
              linhas: linhasP,
              diagnostico: diag,
              especificacoes: espec,
              cronograma: crono,
              politicaAlteracoes: polit,
              escopo: esc,
              autonomia: auto,
              ideiasConteudo: ideias,
              observacoes: obs,
            };
          }));
        };
        const [pt, intro, cond, val, etapas, phases] = await Promise.all([
          translateTextCached(q.projetoTitulo, sourceLang, target),
          translateTextCached(q.bienvenueIntro, sourceLang, target),
          translateTextCached(q.condicoesGerais, sourceLang, target),
          translateTextCached(q.validade, sourceLang, target),
          Promise.all(q.processoEtapas.map(async (e) => ({
            numero: e.numero,
            texto: await translateTextCached(e.texto, sourceLang, target),
          }))),
          translatePhases(),
        ]);
        byLang[target] = {
          projetoTitulo: pt,
          bienvenueIntro: intro,
          condicoesGerais: cond,
          validade: val,
          processoEtapas: etapas,
          phases,
        };
      } catch (err) {
        if (typeof window !== "undefined") console.warn(`[autoTranslateQuote] failed ${target}:`, err);
      }
    })
  );
  return { ...q, sourceLang, byLang };
}

                                                                                          
                                                                                                
                                                                                              
                                                                                                 
                                                                                                      
                                                                                                       
                                                                                                   
async function curateQuoteWithAI(quote: Quote, briefing: Briefing, lang: Lang): Promise<Quote> {
  try {
    if (typeof window === "undefined") return quote;
                                                                                       
                                                                                              
    const servicos = (quote.phases || []).map((p) => ({
      key: p.id,
      label: p.numero,
      desc: abilServiceDesc((p.id || "").replace(/^svc-/, "")),
                                                                                        
      etapas: (p.linhas || []).map((l, i) => ({ n: i + 1, titulo: l.titulo })),
      conteudo: ABIL_CONTENT_SERVICES.has((p.id || "").replace(/^svc-/, "")),
    }));
    if (servicos.length === 0) return quote;
    const persona = getAIPersonaContext();
    const res = await fetch(PRES_GEN_API_BASE + "/api/generate-quote", {
      method: "POST",
      headers: getAIHeaders(),
      body: JSON.stringify({
        briefing,
        servicos,
        lang,
        brandPersona: persona.brandPersona,
        buyerPersona: persona.buyerPersona,
        knowledge: persona.knowledge,
                                                                                            
        globalTextPrompt: persona.globalTextPrompt,
        referenceNotes: persona.referenceNotes,
        safeguards: persona.safeguards,
      }),
    });
    if (!res.ok) { if (typeof window !== "undefined") console.warn("[curateQuoteWithAI] endpoint", res.status); return quote; }
    const data = await res.json().catch(() => null);
    const c = data?.curated;
    if (!c || !Array.isArray(c.servicos)) return quote;
                                                                                              
                                                                                                 
                                                                                                     
                                                                                                 
    const byKey = new Map<string, any>(c.servicos.map((s: any) => [s.key, s]));
    const phases = (quote.phases || []).map((p) => {
      const sv = byKey.get(p.id);
      if (!sv) return p;
      let linhas = p.linhas;
      if (Array.isArray(sv.etapas) && sv.etapas.length) {
        const byN = new Map<number, string>(
          sv.etapas
            .filter((e: any) => e && typeof e.texto === "string")
            .map((e: any) => [Number(e.n), String(e.texto)])
        );
        linhas = p.linhas.map((l, i) => {
          const t = byN.get(i + 1);
          return t && t.trim() ? { ...l, descricao: t.trim() } : l;
        });
      }
      return {
        ...p,
        subtitulo: p.subtitulo,
        linhas,
        diagnostico: (typeof sv.diagnostico === "string" && sv.diagnostico.trim()) ? sv.diagnostico.trim() : p.diagnostico,
        ideiasConteudo: (sv.ideiasConteudo && sv.ideiasConteudo.trim()) || p.ideiasConteudo,
      };
    });
    const bienvenueIntro = (typeof c.bemVindo === "string" && c.bemVindo.trim().length > 20)
      ? c.bemVindo.trim()
      : quote.bienvenueIntro;
    return { ...quote, phases, bienvenueIntro, aiGenerated: true };
  } catch (err) {
    if (typeof window !== "undefined") console.warn("[curateQuoteWithAI] failed:", err);
    return quote;
  }
}

