function tc(label: string | undefined, lang: Lang): string {
  if (!label) return "";
  if (lang === "es" && CHIP_ES[label]) return CHIP_ES[label];
  if (lang === "pt") return label;
  return CHIP_DICT[label]?.[lang] ?? CHIP_DICT[label]?.fr ?? label;
}

                                           
