function AnimatedIcon({ icon: Icon, className, hoverRef }: {
  icon: React.ComponentType<{ className?: string }>;
  className?: string;
  hoverRef?: React.RefObject<HTMLElement | null>;
}) {
  const controls = useMotionAnimation();
  useEffect(() => {
    const el = hoverRef?.current;
    if (!el) return;
    const onEnter = () => {
      controls.start({
        scale: [1, 1.18, 1],
        rotate: [0, -10, 8, 0],
        transition: { duration: 0.55, ease: [0.22, 1, 0.36, 1] },
      });
    };
    const onLeave = () => {
      controls.start({ scale: 1, rotate: 0, transition: { duration: 0.2 } });
    };
    el.addEventListener("mouseenter", onEnter);
    el.addEventListener("mouseleave", onLeave);
    return () => {
      el.removeEventListener("mouseenter", onEnter);
      el.removeEventListener("mouseleave", onLeave);
    };
  }, [hoverRef, controls]);
  return (
    <motion.div className={className} animate={controls} style={{ display: "flex", alignItems: "center", justifyContent: "center" }}>
      <Icon className="w-full h-full" />
    </motion.div>
  );
}

