function OtherInput({
  field, draft, setDraft, placeholder,
}: {
  field: keyof Briefing;
  draft: Partial<Briefing>;
  setDraft: (d: Partial<Briefing>) => void;
  placeholder?: string;
}) {
  const value = (draft as any)[field] as string | undefined;
  return (
    <div className="mt-3 pt-3 border-t border-dashed border-neutral-300">
      <div className="flex items-start gap-2">
        <span className="font-mono text-[10px] uppercase tracking-[0.18em] text-rouge font-semibold flex-shrink-0 pt-2">+ Outro:</span>
        <input
          type="text"
          value={value ?? ""}
          onChange={(e) => setDraft({ ...draft, [field]: e.target.value } as any)}
          placeholder={placeholder ?? "Descreva uma alternativa que não esteja na lista…"}
          className="flex-1 border-b border-neutral-300 px-0 py-1.5 text-sm focus:outline-none focus:border-rouge bg-transparent"
        />
      </div>
    </div>
  );
}

