function BlogArticlePage() {
  const { t, lang, selectedPost, setSelectedPost } = useApp();
  const [drafts] = useLocalStorageState<BlogDraft[]>("abil_blog_drafts", []);
  const authors = useMemo(() => AUTHORS_BY_LANG[lang] || AUTHORS_BY_LANG.fr, [lang]);
  const selectedPostToken = String(selectedPost || "").trim();
  const postStatus = useCanonicalPostStatus();                                                      

                                                                                                   
                                                                                            
  const fromDraft = drafts.find((d) => d.status === "published" && blogMatchesRouteToken(d, selectedPostToken, lang));
  const basePost: BlogPost | undefined = fromDraft
    ? draftToBlogPost(fromDraft, authors)
    : BLOG_POSTS.find((p) => !postStatus[p.id] && blogStaticPostMatchesRouteToken(p, selectedPostToken, lang));

  const post: BlogPost | null = (() => {
    if (!basePost) return null;
    if (fromDraft) {
      const tr = fromDraft.byLang?.[lang];
      if (tr) {
        const base = draftToBlogPost({ ...fromDraft, title: tr.title, subtitle: tr.subtitle, excerpt: tr.excerpt, body: tr.body }, authors);
        return base;
      }
      return basePost!;
    }
    return localizePost(basePost!, lang);
  })();

  const articlePath = post ? canonicalBlogPostRoute(post, lang) : "";
  const articleId = post?.id ?? "";

  useEffect(() => {
    if (typeof window === "undefined") return;
    if (!articleId) return;
    if (articlePath && window.location.pathname !== articlePath) {
      window.history.replaceState({ view: "blog", selectedPost: articleId }, "", articlePath);
    }
  }, [articleId, articlePath]);

  if (!post) {
    return (
      <main data-header-theme="light" className="bg-white pt-16 md:pt-20 min-h-screen">
        <section className="px-6 lg:px-10 py-16 md:py-24">
          <div className="mx-auto max-w-[900px]">
            <button
              onClick={() => setSelectedPost(null)}
              className="group inline-flex items-center gap-2 font-mono text-[11px] uppercase tracking-[0.2em] text-neutral-500 hover:text-neutral-900 transition-colors mb-10"
            >
              <ArrowLeft className="w-3.5 h-3.5 group-hover:-translate-x-1 transition-transform" />
              <EditableText path="blog.back" defaultText={t.blog.back} maxLength={40} />
            </button>
            <h1 className="font-semibold tracking-normal leading-[1] text-4xl md:text-6xl text-neutral-950">
              Article not found
            </h1>
            <p className="mt-5 text-lg text-neutral-600 max-w-xl">
              This article is no longer available.
            </p>
          </div>
        </section>
        <Footer />
      </main>
    );
  }

                                                                       
  const allPosts = (() => {
    const fromDrafts = drafts.filter((d) => d.status === "published" && d.id !== post.id).map((d) => draftToBlogPost(d, authors));
    const fromStatic = BLOG_POSTS.filter((p) => p.id !== post.id && !drafts.some((d) => d.id === p.id) && !postStatus[p.id]);
    return [...fromDrafts, ...fromStatic];
  })();
  const others = allPosts.slice(0, 3).map((p) => localizePost(p, lang));

  return (
    <main data-header-theme="light" className="bg-white pt-16 md:pt-20">
      {          }
      <section
        className={`relative overflow-hidden ${BLOG_BG_CLASSES[post.bg]} px-6 lg:px-10 pt-12 md:pt-20 pb-16 md:pb-24`}
      >
        <img
          src={post.heroImg}
          alt=""
          className="absolute inset-0 w-full h-full object-cover opacity-50"
        />
        <div className="absolute inset-0 bg-gradient-to-t from-black/85 via-black/55 to-black/35" />
        <Asterisque
          className="absolute -right-20 -top-20 w-[600px] opacity-10 pointer-events-none z-10"
          color="currentColor"
        />
        <div className="mx-auto max-w-[1100px] relative z-20">
          <button
            onClick={() => setSelectedPost(null)}
            className="group inline-flex items-center gap-2 eyebrow eyebrow-sm opacity-80 hover:opacity-100 transition-opacity mb-12"
          >
            <ArrowLeft className="w-3.5 h-3.5 group-hover:-translate-x-1 transition-transform" />
            <EditableText path="blog.back" defaultText={t.blog.back} maxLength={40} />
          </button>

          <div className="flex flex-wrap items-center gap-3 font-mono text-[10px] uppercase tracking-[0.25em] mb-6 opacity-85">
            <span>{t.blog.categories[post.cat]}</span>
            <span className="opacity-60">·</span>
            <span>{post.date}</span>
            <span className="opacity-60">·</span>
            <span>{t.blog.readTime(post.readMin)}</span>
            <span className="opacity-60">·</span>
            <span>
              {t.blog.by} {post.author}
            </span>
          </div>

          <h1 className="font-semibold tracking-[-0.035em] leading-[1] text-4xl md:text-6xl lg:text-7xl mb-6 max-w-4xl">
            {post.title}
          </h1>
          <p className="text-lg md:text-xl opacity-90 max-w-3xl leading-relaxed">
            {post.subtitle}
          </p>
        </div>
      </section>

      {           }
      <section className="px-6 lg:px-10 py-10 md:py-14 border-b border-neutral-200 bg-neutral-50">
        <div className="mx-auto max-w-[900px] grid grid-cols-12 gap-x-6">
          <div className="col-span-12 md:col-span-3 mb-4 md:mb-0">
            <div className="font-mono text-[10px] uppercase tracking-[0.3em] text-rouge">
              <EditableText path="blog.tldrLabel" defaultText={t.blog.tldrLabel} maxLength={30} />
            </div>
            <div className="eyebrow text-neutral-400 mt-2">
              <EditableText path="blog.tldrSub" defaultText={t.blog.tldrSub} maxLength={30} />
            </div>
          </div>
          <ul className="col-span-12 md:col-span-9 space-y-2 text-base md:text-lg text-noir leading-snug">
            {post.tldr.map((line, i) => (
              <li key={i} className="flex gap-3">
                <span className="text-rouge font-bold">, </span>
                <span>{line}</span>
              </li>
            ))}
          </ul>
        </div>
      </section>

      {          }
      <article className="px-6 lg:px-10 py-12 md:py-16">
        <div className="mx-auto max-w-[760px] space-y-7">
          {post.body.map((block, i) => {
            if (block.kind === "h2") {
              return (
                <h2
                  key={i}
                  className="font-semibold tracking-[-0.025em] text-2xl md:text-3xl leading-tight pt-6 mt-6 border-t border-neutral-200"
                >
                  {block.text}
                </h2>
              );
            }
            if (block.kind === "p") {
              return (
                <p
                  key={i}
                  className="text-lg leading-relaxed text-noir/85"
                >
                  {block.text}
                </p>
              );
            }
            if (block.kind === "img") {
              return (
                <figure key={i} className="my-10 -mx-2 md:-mx-12">
                  <BlogVisual
                    bg={block.bg}
                    src={block.src}
                    className="w-full aspect-[16/9]"
                    asteriskSize={300}
                  />
                  <figcaption className="eyebrow text-neutral-400 mt-3 px-2 md:px-12">
                    {block.caption}
                  </figcaption>
                </figure>
              );
            }
            if (block.kind === "quote") {
              return (
                <blockquote
                  key={i}
                  className="border-l-4 border-rouge pl-6 py-3 my-8 text-2xl md:text-3xl font-semibold tracking-[-0.02em] leading-tight text-noir italic"
                >
                  « {block.text} »
                </blockquote>
              );
            }
            return null;
          })}
        </div>
      </article>

      {                         }
      <section className="px-6 lg:px-10 py-10 border-t border-b border-neutral-200 bg-neutral-50">
        <div className="mx-auto max-w-[760px] flex items-center gap-4">
          <div className="w-14 h-14 bg-noir text-white flex items-center justify-center font-semibold text-lg">
            {post.author.slice(0, 2).toUpperCase()}
          </div>
          <div>
            <div className="font-medium text-noir">{post.author}</div>
            <div className="eyebrow text-neutral-500 mt-1">
              <EditableText path="blog.signatureLocation" defaultText={t.blog.signatureLocation} maxLength={60} />
            </div>
          </div>
        </div>
      </section>

      {                   }
      <section className="px-6 lg:px-10 py-16 md:py-20">
        <div className="mx-auto max-w-[1480px]">
          <div className="font-mono text-[10px] uppercase tracking-[0.3em] text-rouge mb-3">
            <EditableText path="blog.relatedEyebrow" defaultText={t.blog.relatedEyebrow} maxLength={40} />
          </div>
          <h2 className="font-semibold tracking-[-0.025em] text-3xl md:text-4xl mb-10">
            <EditableText path="blog.relatedTitle" defaultText={t.blog.relatedTitle} maxLength={80} />
          </h2>
          <div className="grid grid-cols-12 gap-6">
            {others.map((p) => (
              <article
                key={p.id}
                onClick={() => {
                  setSelectedPost(blogRouteSlug(p, lang));
                  window.scrollTo({ top: 0 });
                }}
                className="group cursor-pointer col-span-12 md:col-span-4"
              >
                <BlogVisual
                  bg={p.bg}
                  src={p.heroImg}
                  className="w-full aspect-[4/3] mb-4"
                  asteriskSize={150}
                />
                <div className="eyebrow text-neutral-500 mb-2">
                  {t.blog.categories[p.cat]} · {p.date}
                </div>
                <h3 className="font-semibold tracking-[-0.02em] text-xl leading-tight group-hover:text-rouge transition-colors">
                  {p.title}
                </h3>
              </article>
            ))}
          </div>
        </div>
      </section>

      <Footer />
    </main>
  );
}

                                                                                                                                          
                                       
                                                                            
                                  
                                                                                                                                             
