function LangSwitcher({ tone = "dark" }: { tone?: "dark" | "light" }) {
  const { lang, setLang } = useApp();
  const { enabled: enabledLangs } = useEnabledLanguages();
  const container =
    tone === "light"
      ? "text-white/70"
      : "text-neutral-500";
  const active =
    tone === "light" ? "text-white" : "text-noir";
  return (
    <div
      className={`flex items-center gap-2 font-mono text-[11px] uppercase tracking-[0.18em] ${container}`}
    >
      {(["fr", "de", "en", "pt", "it"] as const).filter((l) => enabledLangs.includes(l)).map((l, i) => (
        <span key={l} className="flex items-center gap-2">
          {i > 0 && <span className="opacity-40">/</span>}
          <button
            onClick={() => setLang(l)}
            className={
              lang === l
                ? active
                : "hover:opacity-100 opacity-60 transition-opacity"
            }
            aria-label={`Switch to ${l.toUpperCase()}`}
          >
            {l}
          </button>
        </span>
      ))}
    </div>
  );
}

                                                               
                                                                       
                                                                      
                                                                           
                                                                   
