function getInitials(name: string): string {
  return name
    .split(/\s+/)
    .map((s) => s[0]?.toUpperCase())
    .filter(Boolean)
    .slice(0, 2)
    .join("");
}

                                                                                                                                          
                                         
                                               
                                         
                                           
                                                  
                                                       
                                                                                                                                             
type Notification = {
  id: string;
  kind: "briefing" | "project" | "post";
  title: string;
  desc: string;
  ts: number;            
  moduleTarget?: string;                                  
};

                                                                                             
                                                                                            
                                                                                                 
let notifReadServerSyncFeita = false;

function useNotifications(): {
  list: Notification[];
  unreadCount: number;
  unreadByModule: Record<string, number>;                      
  markAllRead: () => void;
  markRead: (id: string) => void;
  markModuleRead: (moduleId: string) => void;                                            
} {
  const { lang } = useApp();
  const [briefings] = useLocalStorageState<Briefing[]>("abil_briefings", []);
  const [quotes] = useLocalStorageState<Quote[]>("abil_quotes", []);
  const [projects] = useDashProjectsIDB([]);
  const [posts] = useLocalStorageState<{ id: string; title: string; status?: string; publishedAt?: string }[]>("abil_blog_posts_v1", []);
  const [readIds, setReadIds] = useLocalStorageState<string[]>("abil_notifications_read", []);

                                                                                                  
                                                                                                   
                                                                                                    
                                                                                             
                                                                                                
                                                                                                    
                                                                                                  
                                                                                                  
  const readIdsRef = useRef<string[]>(readIds);
  readIdsRef.current = readIds;
  useEffect(() => {
    let cancelado = false;
                                                                                                         
                                                                                                       
                                                                                                       
                                                                                                    
                                                                                                            
    const tentar = () => {
      const tok = pendingDecisionToken();
      if (!tok || notifReadServerSyncFeita) return;
      notifReadServerSyncFeita = true;
      void (async () => {
        try {
          const r = await fetch("/api/private-store?col=notifications_read", { headers: { "x-abil-admin": tok }, cache: "no-store" });
          if (!r.ok || cancelado) return;
          const j = await r.json();
          const remoto: string[] = Array.isArray(j?.value) ? j.value.filter((x: unknown) => typeof x === "string") : [];
          const uniao = Array.from(new Set([...remoto, ...readIdsRef.current]));
          if (uniao.length !== readIdsRef.current.length) setReadIds(uniao);
                                                                                             
                                                     
          if (uniao.length !== remoto.length) {
            await fetch("/api/private-store?col=notifications_read", {
              method: "POST",
              headers: { "Content-Type": "application/json", "x-abil-admin": tok },
              body: JSON.stringify({ value: uniao }),
            });
          }
        } catch { notifReadServerSyncFeita = false;                                                                   }
      })();
    };
    tentar();
    window.addEventListener("abil:vault", tentar);
    return () => { cancelado = true; window.removeEventListener("abil:vault", tentar); };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const persistTimer = useRef<number | null>(null);
  const persistReadIds = (calc: (prev: string[]) => string[]) => {
    setReadIds((prev) => {
      const next = calc(prev);
      const tok = pendingDecisionToken();
      if (tok && typeof window !== "undefined") {
        if (persistTimer.current) window.clearTimeout(persistTimer.current);
        persistTimer.current = window.setTimeout(() => {
          void fetch("/api/private-store?col=notifications_read", {
            method: "POST",
            headers: { "Content-Type": "application/json", "x-abil-admin": tok },
            body: JSON.stringify({ value: next }),
          }).catch(() => { /* Offline: local cache holds the value and startup merge restores it. */ });
        }, 1200);
      }
      return next;
    });
  };

                                                              
  const i18n = {
    fr: { briefingTitle: "Nouveau briefing", briefingNoName: "Nouveau briefing reçu", briefingService: "Service", briefingDefault: "Briefing à analyser", quoteTitle: "Devis généré", quoteClient: "Client", quoteDefault: "Devis à valider", projectTitle: "Projet publié", projectDefault: "Visible dans la page Projets", postTitle: "Article publié", postDefault: "Article visible sur le blog" },
    de: { briefingTitle: "Neues Briefing", briefingNoName: "Neues Briefing erhalten", briefingService: "Dienst", briefingDefault: "Briefing zu analysieren", quoteTitle: "Angebot erstellt", quoteClient: "Kunde", quoteDefault: "Angebot zu prüfen", projectTitle: "Projekt veröffentlicht", projectDefault: "Auf der Projektseite sichtbar", postTitle: "Artikel veröffentlicht", postDefault: "Artikel im Blog sichtbar" },
    en: { briefingTitle: "New briefing", briefingNoName: "New briefing received", briefingService: "Service", briefingDefault: "Briefing to analyze", quoteTitle: "Quote generated", quoteClient: "Client", quoteDefault: "Quote to validate", projectTitle: "Project published", projectDefault: "Visible on the projects page", postTitle: "Article published", postDefault: "Article visible on the blog" },
    pt: { briefingTitle: "Novo briefing", briefingNoName: "Novo briefing recebido", briefingService: "Serviço", briefingDefault: "Briefing a analisar", quoteTitle: "Orçamento gerado", quoteClient: "Cliente", quoteDefault: "Orçamento a validar", projectTitle: "Projecto publicado", projectDefault: "Visível na página Projectos", postTitle: "Artigo publicado", postDefault: "Artigo visível no blog" },
    it: { briefingTitle: "Nuovo briefing", briefingNoName: "Nuovo briefing ricevuto", briefingService: "Servizio", briefingDefault: "Briefing da analizzare", quoteTitle: "Preventivo generato", quoteClient: "Cliente", quoteDefault: "Preventivo da validare", projectTitle: "Progetto pubblicato", projectDefault: "Visibile nella pagina Progetti", postTitle: "Articolo pubblicato", postDefault: "Articolo visibile sul blog" },
  }[lang === "es" ? "fr" : lang];

  const list = useMemo<Notification[]>(() => {
    const items: Notification[] = [];
    briefings.forEach((b) => {
      items.push({
        id: `briefing-${b.id}`,
        kind: "briefing",
        title: b.contactName ? `${i18n.briefingTitle}, ${b.contactName}` : i18n.briefingNoName,
        desc: b.service ? `${i18n.briefingService} : ${b.service}${b.brandName ? " · " + b.brandName : ""}` : i18n.briefingDefault,
        ts: new Date(b.createdAt).getTime(),
        moduleTarget: "briefings",
      });
    });
    quotes.forEach((q) => {
      items.push({
        id: `quote-${q.id}`,
        kind: "project",                         
        title: `${i18n.quoteTitle}, ${q.projetoTitulo}`,
        desc: q.clientName ? `${i18n.quoteClient} : ${q.clientName}${q.ref ? " · " + q.ref : ""}` : i18n.quoteDefault,
        ts: new Date(q.createdAt).getTime(),
        moduleTarget: "quotes",
      });
    });
    projects.forEach((p) => {
      items.push({
        id: `project-${p.id}`,
        kind: "project",
        title: `${i18n.projectTitle}, ${p.title}`,
        desc: p.description?.slice(0, 80) ?? i18n.projectDefault,
        ts: new Date(p.publishedAt).getTime(),
        moduleTarget: "projets",
      });
    });
    posts.forEach((p) => {
      if (p.status !== "published" || !p.publishedAt) return;
      items.push({
        id: `post-${p.id}`,
        kind: "post",
        title: `${i18n.postTitle}, ${p.title}`,
        desc: i18n.postDefault,
        ts: new Date(p.publishedAt).getTime(),
        moduleTarget: "blog",
      });
    });
    return items.sort((a, b) => b.ts - a.ts);
  }, [briefings, quotes, projects, posts, i18n]);

  const unreadCount = useMemo(() => {
    const readSet = new Set(readIds);
    return list.filter((n) => !readSet.has(n.id)).length;
  }, [list, readIds]);

                                                                      
  const unreadByModule = useMemo<Record<string, number>>(() => {
    const readSet = new Set(readIds);
    const acc: Record<string, number> = {};
    list.forEach((n) => {
      if (!n.moduleTarget || readSet.has(n.id)) return;
      acc[n.moduleTarget] = (acc[n.moduleTarget] ?? 0) + 1;
    });
    return acc;
  }, [list, readIds]);

                                                                                              
                                                                                              
                                                            
  const markAllRead = () => persistReadIds((prev) => Array.from(new Set([...prev, ...list.map((n) => n.id)])));
  const markRead = (id: string) => persistReadIds((prev) => Array.from(new Set([...prev, id])));
  const markModuleRead = (moduleId: string) => {
    const ids = list.filter((n) => n.moduleTarget === moduleId).map((n) => n.id);
    persistReadIds((prev) => Array.from(new Set([...prev, ...ids])));
  };

  return { list, unreadCount, unreadByModule, markAllRead, markRead, markModuleRead };
}

function NotificationCenter({ onOpenModule }: { onOpenModule: (moduleId: string) => void }) {
  const { lang } = useApp();
  const { list, unreadCount, markAllRead, markRead } = useNotifications();
  const [open, setOpen] = useState(false);
  const [readIds] = useLocalStorageState<string[]>("abil_notifications_read", []);
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open) return;
    const onClick = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener("mousedown", onClick);
    return () => document.removeEventListener("mousedown", onClick);
  }, [open]);

                                                             
                                                                               
                                                                               
                                      
  const [openedUnreadIds, setOpenedUnreadIds] = useState<Set<string> | null>(null);
  const wasOpenRef = useRef(false);
  useEffect(() => {
    if (open && !wasOpenRef.current) {
                                                          
      const set = new Set(list.filter((n) => !readIds.includes(n.id)).map((n) => n.id));
      setOpenedUnreadIds(set);
      wasOpenRef.current = true;
    } else if (!open && wasOpenRef.current) {
                                                
      if (unreadCount > 0) markAllRead();
      setOpenedUnreadIds(null);
      wasOpenRef.current = false;
    }
  }, [open, list, readIds, unreadCount, markAllRead]);

                                                      
  const ui = {
    fr: { header: "Notifications", unread: "non lues", markAll: "Tout marquer lu", emptyTitle: "Aucune notification pour l'instant", emptyHint: "Briefings, devis, projets et posts publiés apparaîtront ici", justNow: "à l'instant", min: "min", hour: "h", day: "j" },
    de: { header: "Benachrichtigungen", unread: "ungelesen", markAll: "Alle als gelesen", emptyTitle: "Keine Benachrichtigungen", emptyHint: "Briefings, Angebote, Projekte und Posts erscheinen hier", justNow: "gerade eben", min: "Min", hour: "Std", day: "T" },
    en: { header: "Notifications", unread: "unread", markAll: "Mark all read", emptyTitle: "No notifications yet", emptyHint: "Briefings, quotes, projects and posts will appear here", justNow: "just now", min: "min", hour: "h", day: "d" },
    pt: { header: "Notificações", unread: "não lidas", markAll: "Marcar todas lidas", emptyTitle: "Sem notificações por agora", emptyHint: "Briefings, orçamentos, projectos e posts publicados aparecerão aqui", justNow: "agora mesmo", min: "min", hour: "h", day: "d" },
    it: { header: "Notifiche", unread: "non lette", markAll: "Segna tutte lette", emptyTitle: "Nessuna notifica al momento", emptyHint: "Briefing, preventivi, progetti e post appariranno qui", justNow: "adesso", min: "min", hour: "h", day: "g" },
  }[lang === "es" ? "fr" : lang];
  const localeMap: Record<Lang, string> = { fr: "fr-CH", de: "de-CH", en: "en-GB", pt: "pt-PT", it: "it-CH" };
  (localeMap as any).es ??= localeMap.fr;

  const nowMs = useNowMs();
  const readSet = new Set(readIds);
  const fmtRelative = (ts: number): string => {
    const diff = nowMs - ts;
    const min = Math.floor(diff / 60000);
    if (min < 1) return ui.justNow;
    if (min < 60) return `${min} ${ui.min}`;
    const hrs = Math.floor(min / 60);
    if (hrs < 24) return `${hrs} ${ui.hour}`;
    const days = Math.floor(hrs / 24);
    if (days < 7) return `${days} ${ui.day}`;
    return new Date(ts).toLocaleDateString(localeMap[lang]);
  };

  return (
    <div className="relative" ref={ref}>
      <button
        onClick={() => setOpen((v) => !v)}
        className="relative p-2 hover:bg-neutral-100 transition-colors"
        aria-label="Notifications"
      >
        <IconBell className="w-5 h-5 text-noir" />
        {unreadCount > 0 && (
          <span className="absolute top-0.5 right-0.5 min-w-[16px] h-4 bg-rouge text-white text-[9px] font-mono font-bold flex items-center justify-center px-1 rounded-full">
            {unreadCount > 9 ? "9+" : unreadCount}
          </span>
        )}
      </button>
      {open && (
        <div className="absolute right-0 mt-2 w-[380px] max-h-[480px] bg-white border border-neutral-200 shadow-xl z-50 flex flex-col">
          <div className="px-4 py-3 border-b border-neutral-100 flex items-center justify-between">
            <div className="eyebrow text-noir">
              {ui.header} {unreadCount > 0 && <span className="text-rouge">· {unreadCount} {ui.unread}</span>}
            </div>
            {unreadCount > 0 && (
              <button
                onClick={markAllRead}
                className="font-mono text-[10px] uppercase tracking-[0.18em] text-neutral-500 hover:text-rouge"
              >
                {ui.markAll}
              </button>
            )}
          </div>
          <div className="flex-1 overflow-y-auto">
            {list.length === 0 ? (
              <div className="px-4 py-12 text-center">
                <IconBell className="w-8 h-8 text-neutral-300 mx-auto mb-3" />
                <div className="text-sm text-neutral-500">{ui.emptyTitle}</div>
                <div className="text-xs text-neutral-400 mt-1">{ui.emptyHint}</div>
              </div>
            ) : (
                                                                                        
                                                                                       
              (() => {
                const visibleList = openedUnreadIds
                  ? list.filter((n) => openedUnreadIds.has(n.id))
                  : list.filter((n) => !readSet.has(n.id));
                if (visibleList.length === 0) {
                  return (
                    <div className="px-4 py-12 text-center">
                      <IconBell className="w-8 h-8 text-neutral-300 mx-auto mb-3" />
                      <div className="text-sm text-neutral-500">{ui.emptyTitle}</div>
                      <div className="text-xs text-neutral-400 mt-1">{ui.emptyHint}</div>
                    </div>
                  );
                }
                return visibleList.slice(0, 30).map((n) => {
                const isUnread = !readSet.has(n.id);
                const dotColor =
                  n.kind === "briefing" ? "bg-rouge" :
                  n.kind === "project" ? "bg-emerald-500" :
                  "bg-violet";
                return (
                  <button
                    key={n.id}
                    onClick={() => {
                      markRead(n.id);
                      if (n.moduleTarget) onOpenModule(n.moduleTarget);
                      setOpen(false);
                    }}
                    className={`w-full text-left px-4 py-3 border-b border-neutral-100 hover:bg-neutral-50 transition-colors flex gap-3 ${isUnread ? "bg-rouge/5" : ""}`}
                  >
                    <div className={`flex-shrink-0 w-2 h-2 rounded-full mt-2 ${isUnread ? dotColor : "bg-neutral-300"}`} />
                    <div className="flex-1 min-w-0">
                      <div className="font-semibold text-sm text-noir leading-tight truncate">{n.title}</div>
                      <div className="text-xs text-neutral-500 mt-0.5 line-clamp-2 leading-snug">{n.desc}</div>
                      <div className="font-mono text-[10px] uppercase tracking-[0.18em] text-neutral-400 mt-1">{fmtRelative(n.ts)}</div>
                    </div>
                  </button>
                );
                });
              })()
            )}
          </div>
        </div>
      )}
    </div>
  );
}

                                                                                                                                                                                                                                       
                                                                                      
                                                                                          
                                                                                                        
                                                                                                                                                                                                                                       
type AgentMsg = { from: "user" | "agent"; text: string; ts: number; imageUrl?: string; persona?: string };
type AgentAction = { type: string; params?: Record<string, any>; confirm?: string } | null;
const HIGH_RISK_AGENT_ACTIONS = new Set([
  "edit_site_text",
  "approve_blog_draft",
  "approve_social_post",
  "approve_email_template",
  "send_email",
  "publish_email",
  "send_newsletter",
  "generate_quote",
  "schedule_meeting",
  "create_calendar_event",
  "generate_image",
]);
const HIGH_RISK_AGENT_ACTION_PATTERNS = [
  /^(approve|publish|send|delete|archive|hide|unhide|activate|deactivate)_/,
  /_(approve|publish|send|delete|archive)$/,
  /(^|_)meeting($|_)/,
  /(^|_)calendar($|_)/,
];
function isHighRiskAgentAction(actionType: string): boolean {
  const action = String(actionType || "").trim().toLowerCase();
  return HIGH_RISK_AGENT_ACTIONS.has(action) || HIGH_RISK_AGENT_ACTION_PATTERNS.some((pattern) => pattern.test(action));
}

                                                                                              
                                                                                              
                                                                                             
                                                                                      
                                                                                             
const PENDING_DECISIONS_LS_KEY = "abil_pending_decisions_v1";
type PendingDecision = {
  id: string;
  ts: string;
  updatedAt?: string;
  card: string;                                                                                 
  sourceId?: string;                                                                         
  previewImage?: string;                                                         
  action: AgentAction;                                                               
  title: string;
  body: string;
  status: "pending" | "approved" | "executing" | "rejected" | "executed" | "failed";
  result?: string;
};
const PENDING_DECISIONS_CLOUD_COL = "pending_decisions";
const PENDING_DECISIONS_SYNC_KEY = "abil_pending_decisions_sync_v1";
let pendingDecisionSeq = 0;
let pendingDecisionsCloudTimer: number | null = null;
type PendingDecisionSyncStatus = {
  state: "synced" | "syncing" | "local_only" | "error";
  at: string;
  count?: number;
  detail?: string;
};

function readPendingDecisionSyncStatus(): PendingDecisionSyncStatus {
  const fallback: PendingDecisionSyncStatus = { state: "local_only", at: new Date().toISOString(), detail: "not_synced_yet" };
  try {
    if (typeof localStorage === "undefined") return fallback;
    const raw = localStorage.getItem(PENDING_DECISIONS_SYNC_KEY);
    if (!raw) return fallback;
    const parsed = JSON.parse(raw) as Partial<PendingDecisionSyncStatus>;
    if (parsed?.state === "synced" || parsed?.state === "syncing" || parsed?.state === "local_only" || parsed?.state === "error") {
      return { state: parsed.state, at: parsed.at || fallback.at, count: parsed.count, detail: parsed.detail };
    }
  } catch {            }
  return fallback;
}
function writePendingDecisionSyncStatus(next: Omit<PendingDecisionSyncStatus, "at"> & { at?: string }): void {
  try {
    if (typeof localStorage === "undefined") return;
    const status: PendingDecisionSyncStatus = { ...next, at: next.at || new Date().toISOString() };
    localStorage.setItem(PENDING_DECISIONS_SYNC_KEY, JSON.stringify(status));
    if (typeof window !== "undefined") window.dispatchEvent(new CustomEvent("abil:pending-decisions-sync"));
  } catch {            }
}
function usePendingDecisionSyncStatus(): PendingDecisionSyncStatus {
  const [status, setStatus] = useState<PendingDecisionSyncStatus>(() => readPendingDecisionSyncStatus());
  useEffect(() => {
    if (typeof window === "undefined") return undefined;
    const refresh = () => setStatus(readPendingDecisionSyncStatus());
    window.addEventListener("abil:pending-decisions-sync", refresh);
    window.addEventListener("storage", refresh);
    window.addEventListener("focus", refresh);
    return () => {
      window.removeEventListener("abil:pending-decisions-sync", refresh);
      window.removeEventListener("storage", refresh);
      window.removeEventListener("focus", refresh);
    };
  }, []);
  return status;
}

function pendingDecisionToken(): string {
  try {
    if (!abilVaultUnlocked()) return "";
    return (typeof localStorage !== "undefined" && localStorage.getItem("abil_vault_token")) || "";
  } catch { return ""; }
}
function usePendingDecisionVaultStatus(): boolean {
  const [unlocked, setUnlocked] = useState<boolean>(() => !!pendingDecisionToken());
  useEffect(() => {
    if (typeof window === "undefined") return undefined;
    const refresh = () => setUnlocked(!!pendingDecisionToken());
    refresh();
    window.addEventListener("storage", refresh);
    window.addEventListener("abil:vault", refresh);
    window.addEventListener("focus", refresh);
    return () => {
      window.removeEventListener("storage", refresh);
      window.removeEventListener("abil:vault", refresh);
      window.removeEventListener("focus", refresh);
    };
  }, []);
  return unlocked;
}
function pendingDecisionId(): string {
  pendingDecisionSeq += 1;
  try {
    const uuid = globalThis.crypto?.randomUUID?.();
    if (uuid) return `pd-${uuid}`;
  } catch {            }
  return `pd-${Date.now()}-${pendingDecisionSeq}`;
}
                                                                                               
                                                                                                
                                                                                   
                                                                                              
                                                                                          
                                   
function capPendingDecisions(list: PendingDecision[]): PendingDecision[] {
  if (list.length <= 200) return list;
  const at = (x: PendingDecision) => new Date(x.updatedAt || x.ts || 0).getTime();
  const pending = list.filter((x) => x.status === "pending");
  const keepIds = new Set<string>(
    pending.length >= 200
      ? [...pending].sort((a, b) => at(b) - at(a)).slice(0, 200).map((x) => x.id)
      : [
          ...pending.map((x) => x.id),
          ...list.filter((x) => x.status !== "pending").sort((a, b) => at(b) - at(a)).slice(0, 200 - pending.length).map((x) => x.id),
        ],
  );
  return list.filter((x) => keepIds.has(x.id));
}
function normalizePendingDecisions(value: unknown): PendingDecision[] {
  if (!Array.isArray(value)) return [];
  return capPendingDecisions(value
    .filter((x): x is PendingDecision => !!x && typeof x === "object" && typeof (x as PendingDecision).id === "string")
                                                                                                   
                                                                                                    
                                                                                                        
    .filter((x) => { const s = String((x as PendingDecision).sourceId || ""); return !s.startsWith("auto-blog:") && !s.startsWith("auto-blog-email:"); })
    .map((x) => ({ ...x, updatedAt: x.updatedAt || x.ts || new Date().toISOString() })));
}
function mergePendingDecisionLists(remote: PendingDecision[], local: PendingDecision[]): PendingDecision[] {
  const byId = new Map<string, PendingDecision>();
  [...remote, ...local].forEach((item) => {
    const current = byId.get(item.id);
    if (!current) { byId.set(item.id, item); return; }
    const a = new Date(item.updatedAt || item.ts || 0).getTime();
    const b = new Date(current.updatedAt || current.ts || 0).getTime();
    if (a >= b) byId.set(item.id, item);
  });
                                                                                         
  return capPendingDecisions(Array.from(byId.values())
    .sort((a, b) => new Date(b.ts || b.updatedAt || 0).getTime() - new Date(a.ts || a.updatedAt || 0).getTime()));
}
async function savePendingDecisionsToCloud(list: PendingDecision[]): Promise<void> {
  const tok = pendingDecisionToken();
  if (!tok) {
    writePendingDecisionSyncStatus({ state: "local_only", count: list.length, detail: "vault_locked" });
    return;
  }
  try {
    writePendingDecisionSyncStatus({ state: "syncing", count: list.length });
    const res = await fetch(`/api/private-store?col=${PENDING_DECISIONS_CLOUD_COL}`, {
      method: "POST",
      headers: { "Content-Type": "application/json", "x-abil-admin": tok },
      body: JSON.stringify({ value: capPendingDecisions(list) }),                                                                
    });
    if (!res.ok) throw new Error(`http_${res.status}`);
    writePendingDecisionSyncStatus({ state: "synced", count: Math.min(list.length, 200) });
  } catch (err: any) {
    writePendingDecisionSyncStatus({ state: "error", count: list.length, detail: String(err?.message || err).slice(0, 120) });
  }
}
function schedulePendingDecisionsCloudSave(list: PendingDecision[]): void {
  if (typeof window === "undefined") return;
  if (!pendingDecisionToken()) {
    writePendingDecisionSyncStatus({ state: "local_only", count: list.length, detail: "vault_locked" });
    return;
  }
  if (pendingDecisionsCloudTimer) window.clearTimeout(pendingDecisionsCloudTimer);
  pendingDecisionsCloudTimer = window.setTimeout(() => { void savePendingDecisionsToCloud(list); }, 350);
}
function readPendingDecisions(): PendingDecision[] {
  try { const raw = typeof localStorage !== "undefined" ? localStorage.getItem(PENDING_DECISIONS_LS_KEY) : null; const a = raw ? JSON.parse(raw) : []; return normalizePendingDecisions(a); } catch { return []; }
}
function writePendingDecisions(list: PendingDecision[], opts?: { skipCloud?: boolean }): void {
  const normalized = normalizePendingDecisions(list);
  try { localStorage.setItem(PENDING_DECISIONS_LS_KEY, JSON.stringify(normalized)); if (typeof window !== "undefined") window.dispatchEvent(new CustomEvent("abil:pending-decisions")); } catch {            }
  if (!opts?.skipCloud) schedulePendingDecisionsCloudSave(normalized);
}
function enqueuePendingDecision(d: Omit<PendingDecision, "id" | "ts" | "status"> & { status?: PendingDecision["status"] }): PendingDecision {
  const now = new Date().toISOString();
  const dec: PendingDecision = { id: pendingDecisionId(), ts: now, updatedAt: now, status: d.status || "pending", card: d.card, sourceId: d.sourceId, previewImage: d.previewImage, action: d.action, title: d.title, body: d.body };
  const list = readPendingDecisions(); list.unshift(dec); writePendingDecisions(list); return dec;
}
function setPendingDecisionStatus(id: string, status: PendingDecision["status"], result?: string): void {
  writePendingDecisions(readPendingDecisions().map((x) => x.id === id ? { ...x, status, updatedAt: new Date().toISOString(), ...(result !== undefined ? { result } : {}) } : x));
}
async function claimPendingDecisionOnServer(id: string, from: PendingDecision["status"], to: PendingDecision["status"], extra?: { action?: AgentAction; result?: string; skipLocal?: boolean }): Promise<{ ok: boolean; decision?: PendingDecision; error?: string } | null> {
  const tok = pendingDecisionToken();
  if (!tok) return null;
                                                                                                    
                                                                                    
  const { skipLocal, ...claimBody } = extra || {};
  try {
    const res = await fetch("/api/pending-decisions?action=claim", {
      method: "POST",
      headers: { "Content-Type": "application/json", "x-abil-admin": tok },
      body: JSON.stringify({ id, from, to, ...claimBody }),
      cache: "no-store",
    });
    const data = await res.json().catch(() => null);
    if (!skipLocal && Array.isArray(data?.value)) writePendingDecisions(data.value, { skipCloud: true });
    if (!res.ok || !data?.ok) return { ok: false, decision: data?.decision, error: data?.error || `http_${res.status}` };
    return { ok: true, decision: data.decision as PendingDecision };
  } catch (err: any) {
    return { ok: false, error: String(err?.message || err) };
  }
}
async function approvePendingDecision(id: string, actionOverride?: AgentAction): Promise<PendingDecision | null> {
  if (!pendingDecisionToken()) return null;
  const remote = await claimPendingDecisionOnServer(id, "pending", "approved", actionOverride ? { action: actionOverride } : undefined);
  if (remote?.ok && remote.decision) return remote.decision;
  if (remote && import.meta.env.PROD) return null;
  const list = readPendingDecisions();
  const idx = list.findIndex((item) => item.id === id);
  if (idx < 0 || list[idx].status !== "pending") return null;
  const now = new Date().toISOString();
  const next = [...list];
  next[idx] = { ...next[idx], action: actionOverride ?? next[idx].action, status: "approved", updatedAt: now };
  writePendingDecisions(next);
  return next[idx];
}
async function claimPendingDecisionExecution(id: string): Promise<PendingDecision | null> {
  if (!pendingDecisionToken()) return null;
  const remote = await claimPendingDecisionOnServer(id, "approved", "executing");
  if (remote?.ok && remote.decision) return remote.decision;
  if (remote && import.meta.env.PROD) return null;
  const list = readPendingDecisions();
  const idx = list.findIndex((item) => item.id === id);
  if (idx < 0 || list[idx].status !== "approved") return null;
  const now = new Date().toISOString();
  const next = [...list];
  next[idx] = { ...next[idx], status: "executing", updatedAt: now };
  writePendingDecisions(next);
  return next[idx];
}
async function finishPendingDecisionExecution(id: string, status: "executed" | "failed", result: string): Promise<void> {
  if (!pendingDecisionToken()) {
    setPendingDecisionStatus(id, "failed", "vault locked: server claim required");
    return;
  }
  const remote = await claimPendingDecisionOnServer(id, "executing", status, { result });
  if (remote?.ok) return;
  setPendingDecisionStatus(id, status, result);
}
async function rejectPendingDecision(id: string, result = "pending decision rejected by superadmin"): Promise<PendingDecision | null> {
                                                                                        
                                                                                       
                                                                                       
                                                                                    
                                                                                            
                                                                                         
  const list = readPendingDecisions();
  const idx = list.findIndex((item) => item.id === id);
  if (idx < 0) return null;
  if (list[idx].status !== "pending") return list[idx];                
  const now = new Date().toISOString();
  const next = [...list];
  next[idx] = { ...next[idx], status: "rejected", updatedAt: now, result };
  writePendingDecisions(next);                                                               
  reconcileRejectedGeneratedOutputs();                                                                                                    
  void claimPendingDecisionOnServer(id, "pending", "rejected", { result, skipLocal: true }).catch(() => {});
  return next[idx];
}
                                                                                                    
                                                                                               
                                                                                                
                                                                                                
                                                                                                     
                                                                                                         
                                                                                                
function reconcileRejectedSocialCards(): number {
  try {
    if (typeof window === "undefined") return 0;
    const pd = readPendingDecisions();
    const rejectedPids = new Set<string>();
                                                                                                     
                                                                                                    
                                                                                            
    const rejectedIds = new Set<string>();
    for (const d of pd) {
      if (d.card !== "social" || d.status !== "rejected" || typeof d.sourceId !== "string") continue;
      if (d.sourceId.startsWith("auto-social:")) rejectedPids.add(d.sourceId.slice("auto-social:".length));
      else rejectedIds.add(d.sourceId);
    }
    if (!rejectedPids.size && !rejectedIds.size) return 0;
    const cards = cloudGet<any[]>("abil_social_cards_v2", []);
    if (!Array.isArray(cards)) return 0;
    let changed = 0;
    const next = cards.map((c) => {
      if (!c || c.status === "deleted") return c;
      const sid = String(c.sourceId || "");
      if (sid.startsWith("project-")) {
        const pid = sid.slice("project-".length).replace(/-(li|fb)$/, "");
        if (rejectedPids.has(pid)) { changed++; return { ...c, status: "deleted" }; }
        return c;
      }
                                                                                                       
                                                                                                
      if (c.status === "draft" && (rejectedIds.has(String(c.id || "")) || rejectedIds.has(sid))) {
        changed++; return { ...c, status: "deleted" };
      }
      return c;
    });
    if (changed > 0) {
      cloudSet("abil_social_cards_v2", next);
      try { window.dispatchEvent(new CustomEvent("abil:social-cards-updated")); } catch {            }
    }
    return changed;
  } catch { return 0; }
}
                                                                                                     
                                                                                                      
                                                                                                  
                                                                                                 
                                                                                                     
                                                                                                       
                                                                                                 
function reconcileRejectedEmailTemplates(): number {
  try {
    if (typeof window === "undefined") return 0;
    const pd = readPendingDecisions();
    const rejPids = new Set<string>();
    const rejIds = new Set<string>();
    for (const d of pd) {
      if (d.card !== "email" || d.status !== "rejected" || typeof d.sourceId !== "string") continue;
      if (d.sourceId.startsWith("auto-email:")) rejPids.add(d.sourceId.slice("auto-email:".length));
      else if (!d.sourceId.startsWith("auto-blog-email:")) rejIds.add(d.sourceId);
    }
    if (!rejPids.size && !rejIds.size) return 0;
    const tpls = cloudGet<any[]>("abil_email_template_extras_v2", []);
    if (!Array.isArray(tpls)) return 0;
    let changed = 0;
    const next = tpls.map((t) => {
      if (!t || t.status !== "draft") return t;
      const id = String(t.id || "");
                                                                                                   
                                                                                                
      const hit = rejIds.has(id)
        || (id.startsWith("email-auto-") && rejPids.has(id.slice("email-auto-".length)))
        || (!id.startsWith("email-blog-auto-") && t.linkedProjectId && rejPids.has(String(t.linkedProjectId)));
      if (hit) { changed++; return { ...t, status: "deleted" }; }
      return t;
    });
    if (changed > 0) cloudSet("abil_email_template_extras_v2", next);
    return changed;
  } catch { return 0; }
}
                                                                                           
                                                                                      
function reconcileRejectedBlogDrafts(): number {
  try {
    if (typeof window === "undefined") return 0;
    const pd = readPendingDecisions();
    const rejIds = new Set<string>();
    for (const d of pd) {
      if (d.card === "blog" && d.status === "rejected" && typeof d.sourceId === "string" && !d.sourceId.startsWith("auto-blog:")) rejIds.add(d.sourceId);
    }
    if (!rejIds.size) return 0;
    const drafts = cloudGet<any[]>("abil_blog_drafts", []);
    if (!Array.isArray(drafts)) return 0;
    let changed = 0;
    const next = drafts.map((b) => {
      if (!b || b.status !== "draft") return b;
      if (rejIds.has(String(b.id || ""))) { changed++; return { ...b, status: "deleted" }; }
      return b;
    });
    if (changed > 0) cloudSet("abil_blog_drafts", next);
    return changed;
  } catch { return 0; }
}
                                                                                                
                                                                                                    
function reconcileRejectedGeneratedOutputs(): void {
  reconcileRejectedSocialCards();
  reconcileRejectedEmailTemplates();
  reconcileRejectedBlogDrafts();
}
async function syncPendingDecisionsFromCloud(): Promise<void> {
  const tok = pendingDecisionToken();
  if (!tok) {
    writePendingDecisionSyncStatus({ state: "local_only", count: readPendingDecisions().length, detail: "vault_locked" });
    return;
  }
  try {
    writePendingDecisionSyncStatus({ state: "syncing", count: readPendingDecisions().length });
    const r = await fetch(`/api/private-store?col=${PENDING_DECISIONS_CLOUD_COL}`, { headers: { "x-abil-admin": tok }, cache: "no-store" });
    if (!r.ok) throw new Error(`http_${r.status}`);
    const j = await r.json();
    const local = readPendingDecisions();
    const remote = normalizePendingDecisions(j?.value);
    const merged = mergePendingDecisionLists(remote, local);
    writePendingDecisions(merged, { skipCloud: true });
    writePendingDecisionSyncStatus({ state: "synced", count: merged.length });
    if (JSON.stringify(merged) !== JSON.stringify(remote)) void savePendingDecisionsToCloud(merged);
  } catch (err: any) {
    writePendingDecisionSyncStatus({ state: "error", count: readPendingDecisions().length, detail: String(err?.message || err).slice(0, 120) });
  }
}
                                                                                                        
function usePendingDecisions(filterCard?: string): PendingDecision[] {
  const [list, setList] = useState<PendingDecision[]>(() => readPendingDecisions());
  useEffect(() => {
    if (typeof window === "undefined") return undefined;
    const refresh = () => setList(readPendingDecisions());
    const refreshFromCloud = () => { void syncPendingDecisionsFromCloud(); refresh(); };
    void syncPendingDecisionsFromCloud();
    window.addEventListener("abil:pending-decisions", refresh);
    window.addEventListener("storage", refresh);
    window.addEventListener("abil:vault", refreshFromCloud);
    return () => { window.removeEventListener("abil:pending-decisions", refresh); window.removeEventListener("storage", refresh); window.removeEventListener("abil:vault", refreshFromCloud); };
  }, []);
  return filterCard ? list.filter((d) => d.card === filterCard) : list;
}

                                                                                            
                                                                                
                                                                                  
                                                                            
function cardForAction(t: string): string {
  const s = String(t || "").toLowerCase();
  if (/(reply|conversation|helpdesk|inbox|chat|message)/.test(s)) return "conversations";
  if (/(email|mail|newsletter)/.test(s)) return "email";
  if (/(blog|article|post_blog|create_blog|publish_blog)/.test(s)) return "blog";
  if (/(social|instagram|linkedin|facebook|tiktok|publish_social|create_social|create_post|publish_post)/.test(s)) return "social";
  return "agent";
}

type AgentActionGovernancePlan = { risk: "baixo" | "medio" | "alto"; target: string; effect: string; guardrail: string };
function agentActionGovernancePlan(action: NonNullable<AgentAction>, highRisk: boolean, currentModule?: string): AgentActionGovernancePlan {
  const p = action.params || {};
  const target = String(p.key || p.module || p.topic || p.to || p.projectId || p.draftId || p.postId || p.templateId || p.summary || p.sourceId || currentModule || "dashboard").slice(0, 140);
  const baseRisk: AgentActionGovernancePlan["risk"] = highRisk ? "alto" : "medio";
  switch (action.type) {
    case "read_dashboard":
      return { risk: "baixo", target, effect: "Leitura do snapshot do dashboard; nao altera dados.", guardrail: "Sem escrita. Pode ser executado como leitura." };
    case "open_module":
      return { risk: "baixo", target, effect: `Abre o modulo "${target}" no dashboard.`, guardrail: "Sem escrita e sem chamada externa." };
    case "list_pending_drafts":
      return { risk: "baixo", target, effect: "Lista rascunhos pendentes na caixa conectada.", guardrail: "Leitura autenticada; nao envia emails." };
    case "check_availability":
      return { risk: "baixo", target, effect: "Consulta disponibilidade no calendario conectado.", guardrail: "Leitura free/busy; nao cria evento." };
    case "remember":
      return { risk: "medio", target, effect: "Grava uma memoria long-term cifrada para o copiloto.", guardrail: "Exige cofre destrancado e fica auditavel." };
    case "edit_site_text":
      return { risk: "alto", target, effect: `Altera texto publico/localizado do site na chave "${target}".`, guardrail: "Confirmacao humana obrigatoria; registrar antes/depois e rollback ainda precisam fase propria." };
    case "create_blog_post":
      return { risk: "medio", target, effect: "Cria artigo de blog em rascunho, sem publicar automaticamente.", guardrail: "Fica em draft e deve passar por aprovacao." };
    case "approve_blog_draft":
      return { risk: "alto", target, effect: "Publica/aprova artigo gerado pela IA.", guardrail: "Aprovacao humana e log persistente." };
    case "create_social_post":
      return { risk: "medio", target, effect: "Cria post social em rascunho/calendario.", guardrail: "Nao publica externamente sem aprovacao/fila." };
    case "approve_social_post":
      return { risk: "alto", target, effect: "Aprova post social e tenta enfileirar publicacao externa.", guardrail: "Fila real depende de OAuth/envs; status fica registrado." };
    case "approve_email_template":
      return { risk: "alto", target, effect: "Ativa email marketing e tenta enfileirar envio para audiencia opt-in.", guardrail: "Fila real depende de Resend/envs; status fica registrado." };
    case "draft_email":
      return { risk: "medio", target, effect: `Cria rascunho de email para "${target}".`, guardrail: "Nao envia; humano revisa no Gmail." };
    case "send_email":
      return { risk: "alto", target, effect: `Envia email imediatamente para "${target}".`, guardrail: "So deve rodar com pedido explicito e confirmacao humana." };
    case "generate_quote":
      return { risk: "alto", target, effect: "Gera proposta/orcamento e grava no modulo de orcamentos.", guardrail: "Confirmacao humana; valores devem ser revisados." };
    case "schedule_meeting":
      return { risk: "alto", target, effect: "Cria evento no Google Calendar conectado.", guardrail: "Confirmacao humana e disponibilidade recomendada." };
    case "generate_image":
      return { risk: highRisk ? "alto" : "medio", target, effect: "Gera imagem com IA e pode consumir credito do provedor.", guardrail: "Usa prompt da marca; custos/fornecedor dependem de envs." };
    case "analyze_image":
      return { risk: "baixo", target, effect: "Analisa imagem anexada e responde sem alterar dados.", guardrail: "Leitura/analise; nao publica." };
    default:
      return { risk: baseRisk, target, effect: `Executa a acao "${action.type}" no contexto do dashboard.`, guardrail: "Confirmacao humana e log persistente; revisar parametros antes de aprovar." };
  }
}
function formatAgentActionGovernance(plan: AgentActionGovernancePlan): string {
  return `\n\nGovernanca da acao:\n- Risco: ${plan.risk}\n- Alvo: ${plan.target}\n- Efeito esperado: ${plan.effect}\n- Controle: ${plan.guardrail}\n- Auditoria: ao executar/rejeitar, o evento e registrado em /api/agent-action-log.`;
}

function agentActionStateSnapshot(action: NonNullable<AgentAction>, lang: Lang, currentModule?: string): Record<string, unknown> {
  const params = action.params || {};
  const pick = (item: any) => item ? {
    id: item.id,
    title: item.title || item.subject || item.caption,
    status: item.status,
    approvedAt: item.approvedAt,
    publishedAt: item.publishedAt,
    outboundQueueStatus: item.outboundQueueStatus,
    outboundQueued: item.outboundQueued,
    outboundQueueSkipped: item.outboundQueueSkipped,
    outboundQueueError: item.outboundQueueError,
  } : null;
  const byProject = (item: any) => params.projectId && (item?.projectId === params.projectId || item?.linkedProjectId === params.projectId || item?.sourceProjectId === params.projectId);
  try {
    if (action.type === "edit_site_text") {
      const key = String(params.key || "");
      const raw = typeof localStorage !== "undefined" ? localStorage.getItem("abil_site_edits_inline") : null;
      const edits = raw ? JSON.parse(raw) : {};
      const candidates = [`${key}__${lang}`, `${key}__fr`, key];
      const found = candidates.find((candidate) => typeof edits?.[candidate] === "string");
      return { kind: "site_text", key, currentModule, storageKey: found || candidates[0], value: found ? edits[found] : "", existed: Boolean(found) };
    }
    if (action.type === "create_blog_post" || action.type === "approve_blog_draft") {
      const drafts = cloudGet<BlogDraft[]>("abil_blog_drafts", []);
      const item = drafts.find((d: any) => d.id === params.draftId || byProject(d));
      return { kind: "blog_drafts", count: Array.isArray(drafts) ? drafts.length : 0, target: pick(item), recentIds: drafts.slice(0, 5).map((d) => d.id) };
    }
    if (action.type === "create_social_post" || action.type === "approve_social_post") {
      const posts = cloudGet<SocialPost[]>("abil_social_calendar", []);
      const item = posts.find((p: any) => p.id === params.postId || byProject(p));
      return { kind: "social_calendar", count: Array.isArray(posts) ? posts.length : 0, target: pick(item), recentIds: posts.slice(0, 5).map((p) => p.id) };
    }
    if (action.type === "approve_email_template") {
      const templates = cloudGet<EmailTemplate[]>("abil_email_template_extras_v2", []);
      const item = templates.find((tpl: any) => tpl.id === params.templateId || byProject(tpl));
      return { kind: "email_templates", count: Array.isArray(templates) ? templates.length : 0, target: pick(item), recentIds: templates.slice(0, 5).map((tpl) => tpl.id) };
    }
    if (action.type === "generate_quote") {
      const quotes = cloudGet<Quote[]>("abil_quotes", []);
      const briefings = cloudGet<Briefing[]>("abil_briefings", []);
      return { kind: "quote_generation", quotesCount: Array.isArray(quotes) ? quotes.length : 0, briefingsCount: Array.isArray(briefings) ? briefings.length : 0, currentModule };
    }
  } catch (err: any) {
    return { kind: "snapshot_error", action: action.type, error: String(err?.message || err).slice(0, 120) };
  }
  return { kind: "generic_action", action: action.type, currentModule };
}

function agentRollbackPlan(action: NonNullable<AgentAction>, before: Record<string, unknown>): Record<string, unknown> | undefined {
  if (action.type === "edit_site_text") return { safe: "manual_or_next_phase", action: "edit_site_text", restore: { key: action.params?.key, value: before.value ?? "" } };
  if (action.type === "approve_blog_draft") return { safe: "manual_or_next_phase", action: "restore_blog_draft", previous: before.target ?? null };
  if (action.type === "approve_social_post") return { safe: "manual_or_next_phase", action: "restore_social_post", previous: before.target ?? null };
  if (action.type === "approve_email_template") return { safe: "manual_or_next_phase", action: "restore_email_template", previous: before.target ?? null };
  return undefined;
}

function applyAgentRollback(entry: AgentActionLogEntry): { ok: boolean; message: string; before?: unknown; after?: unknown } {
  const rollback = entry.rollback as any;
  const before = entry.before as any;
  const action = String(rollback?.action || "");
  const target = before?.target as any;
  const normalizeValue = (value: unknown) => value === "" || value === null || value === undefined ? undefined : value;
  const pick = (item: any) => item ? {
    id: item.id,
    title: item.title || item.subject || item.caption,
    status: item.status,
    approvedAt: item.approvedAt,
    publishedAt: item.publishedAt,
    outboundQueueStatus: item.outboundQueueStatus,
    outboundQueued: item.outboundQueued,
    outboundQueueSkipped: item.outboundQueueSkipped,
    outboundQueueError: item.outboundQueueError,
  } : null;
  const restoreFields = (current: any, previous: any) => {
    const next = { ...current };
    ["status", "approvedAt", "publishedAt", "outboundQueueStatus", "outboundQueued", "outboundQueueSkipped", "outboundQueueError", "outboundQueuedAt"].forEach((key) => {
      const value = normalizeValue(previous?.[key]);
      if (value === undefined) delete next[key];
      else next[key] = value;
    });
    return next;
  };
  const restoreListItem = <T extends { id?: string }>(storageKey: string, label: string): { ok: boolean; message: string; before?: unknown; after?: unknown } => {
    const id = String(target?.id || "");
    if (!id) return { ok: false, message: `Rollback sem id para ${label}.` };
    const list = cloudGet<T[]>(storageKey, []);
    const idx = Array.isArray(list) ? list.findIndex((item: any) => item?.id === id) : -1;
    if (idx < 0) return { ok: false, message: `${label} nao encontrado para rollback.` };
    const next = [...list];
    const beforeItem = pick(next[idx]);
    next[idx] = restoreFields(next[idx], target) as T;
    cloudSet(storageKey, next);
    return { ok: true, message: `Rollback aplicado em ${label}.`, before: beforeItem, after: pick(next[idx]) };
  };
  if (action === "edit_site_text") {
    const storageKey = String(before?.storageKey || "");
    if (!storageKey) return { ok: false, message: "Rollback de texto sem storageKey." };
    const edits = (() => { try { const raw = localStorage.getItem("abil_site_edits_inline"); return raw ? JSON.parse(raw) : {}; } catch { return {}; } })() as Record<string, string>;
    const beforeValue = Object.prototype.hasOwnProperty.call(edits, storageKey) ? edits[storageKey] : undefined;
    if (before?.existed === false) delete edits[storageKey];
    else edits[storageKey] = String(before?.value || "");
    try { localStorage.setItem("abil_site_edits_inline", JSON.stringify(edits)); } catch {            }
    cloudSet("abil_site_edits_inline", edits);
    return { ok: true, message: `Rollback aplicado no texto ${String(before?.key || storageKey)}.`, before: { storageKey, value: beforeValue }, after: { storageKey, value: edits[storageKey] ?? null } };
  }
  if (action === "restore_blog_draft") return restoreListItem<BlogDraft>("abil_blog_drafts", "blog");
  if (action === "restore_social_post") return restoreListItem<SocialPost>("abil_social_calendar", "social");
  if (action === "restore_email_template") return restoreListItem<EmailTemplate>("abil_email_template_extras_v2", "email");
  return { ok: false, message: "Rollback nao disponivel para esta acao." };
}

                                                                                               
