function applyJourneyTranslation(tpl: EmailTemplate, lang: Lang): EmailTemplate {
  if (!tpl.phase || lang === "pt") return tpl;                
  const trans = EMAIL_JOURNEY_TRANSLATIONS[tpl.phase]?.[lang];
  if (!trans) return tpl;
  return { ...tpl, name: trans.name, subject: trans.subject, preheader: trans.preheader, body: trans.body, tag: trans.tag };
}

                                                                   
const EMAIL_JOURNEY_TEMPLATES_FR = EMAIL_JOURNEY_TEMPLATES_PT.map((t) => applyJourneyTranslation(t, "fr"));
const EMAIL_JOURNEY_TEMPLATES_EN = EMAIL_JOURNEY_TEMPLATES_PT.map((t) => applyJourneyTranslation(t, "en"));
const EMAIL_JOURNEY_TEMPLATES_DE = EMAIL_JOURNEY_TEMPLATES_PT.map((t) => applyJourneyTranslation(t, "de"));
const EMAIL_JOURNEY_TEMPLATES_IT = EMAIL_JOURNEY_TEMPLATES_PT.map((t) => applyJourneyTranslation(t, "it"));

                                                                                                   
                                                                                                   
                                                                                                      
const JRN_AUTOTRANS_KEY = "abil_email_jrn_autotrans_v1";
function jrnSrcHash(tpl: { subject?: string; preheader?: string; body?: string; blocks?: Array<{ titulo?: string; descricao?: string }> }): string {
  const s = `${tpl.subject || ""}|${tpl.preheader || ""}|${tpl.body || ""}|${(tpl.blocks || []).map((b) => `${b.titulo || ""}~${b.descricao || ""}`).join("|")}`;
  let h = 0; for (let i = 0; i < s.length; i++) { h = ((h << 5) - h + s.charCodeAt(i)) | 0; }
  return String(h >>> 0);
}
function readJrnAutoTrans(): Record<string, { h: string; byLang: Record<string, Partial<EmailTemplate>> }> {
  if (typeof window === "undefined") return {};
  try { return JSON.parse(localStorage.getItem(JRN_AUTOTRANS_KEY) || "{}"); } catch { return {}; }
}
function getJrnAutoTrans(tplId: string, lang: Lang, srcHash: string): Partial<EmailTemplate> | null {
  const e = readJrnAutoTrans()[tplId];
  return (e && e.h === srcHash && e.byLang[lang]) ? e.byLang[lang] : null;
}
async function ensureJrnAutoTrans(ptTpl: EmailTemplate, lang: Lang): Promise<Partial<EmailTemplate> | null> {
  if (lang === "pt" || !ptTpl.phase) return null;
  const srcHash = jrnSrcHash(ptTpl);
  const cached = getJrnAutoTrans(ptTpl.id, lang, srcHash);
  if (cached) return cached;
  try {
    const [subject, preheader, body] = await Promise.all([
      translateTextCached(ptTpl.subject || "", "pt", lang),
      translateTextCached(ptTpl.preheader || "", "pt", lang),
      translateTextCached(ptTpl.body || "", "pt", lang),
    ]);
    const blocks = await Promise.all((ptTpl.blocks || []).map(async (b) => ({
      ...b,
      titulo: await translateTextCached(b.titulo || "", "pt", lang),
      descricao: await translateTextCached(b.descricao || "", "pt", lang),
    })));
    const result: Partial<EmailTemplate> = { subject, preheader, body, blocks };
    const store = readJrnAutoTrans();
    const prevByLang = (store[ptTpl.id] && store[ptTpl.id].h === srcHash) ? store[ptTpl.id].byLang : {};
    store[ptTpl.id] = { h: srcHash, byLang: { ...prevByLang, [lang]: result } };
    try { localStorage.setItem(JRN_AUTOTRANS_KEY, JSON.stringify(store)); } catch {             }
    return result;
  } catch { return null; }
}

                                                              
                                                                           
async function autoTranslateEmailTemplate(tpl: EmailTemplate, sourceLangHint?: Lang): Promise<EmailTemplate> {
  const sourceLang: Lang = sourceLangHint || tpl.sourceLang || "fr";
  const targets = ALL_LANGS_AUTO_TRANSLATE.filter((l) => l !== sourceLang);
  const byLang: NonNullable<EmailTemplate["byLang"]> = { ...(tpl.byLang || {}) };
  byLang[sourceLang] = { name: tpl.name, subject: tpl.subject, preheader: tpl.preheader, body: tpl.body, tag: tpl.tag };
  await Promise.all(
    targets.map(async (target) => {
      try {
        const [tName, tSubject, tPre, tBody] = await Promise.all([
          translateTextCached(tpl.name, sourceLang, target),
          translateTextCached(tpl.subject, sourceLang, target),
          translateTextCached(tpl.preheader, sourceLang, target),
          translateTextCached(tpl.body, sourceLang, target),
        ]);
                                                                                                                 
        byLang[target] = { name: tName, subject: tSubject, preheader: tPre, body: tBody, tag: tpl.tag };
      } catch (err) {
        if (typeof window !== "undefined") console.warn(`[autoTranslateEmailTemplate] failed ${target}:`, err);
      }
    })
  );
  return { ...tpl, sourceLang, byLang };
}

                                                                                                 
                                                                                             
                                                                                       
                                                                                             
                                                                                              
                                                                           
                                                                                                
  
                      
                                                                                            
                                                                                                                  
                                                                                                            
                                                                                                  
