function escapeHtml(s: string): string {
  return String(s || "")
    .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
}
function buildProposalEmailHtml(opts: { lang: Lang; prenom: string; presentationUrl: string }): { subject: string; html: string } {
  const tpl = EMAIL_PROPOSTA_VIDEO_BY_LANG[opts.lang] || EMAIL_PROPOSTA_VIDEO_BY_LANG.en;
  const merge = (s: string) =>
    String(s || "")
      .replace(/\{\{\s*prenom\s*\}\}/g, opts.prenom || "")
      .replace(/\{\{\s*presentationUrl\s*\}\}/g, opts.presentationUrl || "");
  const subject = merge(tpl.subject);
  const bodyHtml = escapeHtml(merge(tpl.body)).replace(/\n/g, "<br/>");
  const ctaLabel = escapeHtml(merge(tpl.ctaLabel || "Ver"));
  const ctaUrl = escapeHtml(opts.presentationUrl);
  const tag = escapeHtml(tpl.tag || "PROPOSTA");
  const blocksHtml = (tpl.blocks || [])
    .map(
      (b) => `
      <tr><td style="padding:10px 0;border-top:1px solid #2a2a2a;">
        <div style="font:600 14px/1.3 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#f4efe6;">${escapeHtml(b.titulo)}</div>
        <div style="font:400 13px/1.5 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#b9b3a6;margin-top:3px;">${escapeHtml(b.descricao)}</div>
      </td></tr>`,
    )
    .join("");
                                                                               
  const preheader = escapeHtml(merge(tpl.preheader || ""));
  const html = `<!DOCTYPE html><html><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/></head>
<body style="margin:0;padding:0;background:#141414;">
  <div style="display:none;max-height:0;overflow:hidden;opacity:0;">${preheader}</div>
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#efefef;padding:28px 0;">
    <tr><td align="center">
      <table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background:#0a0a0b;">
        <tr><td style="padding:32px 36px 8px 36px;">
          <div style="font:400 10px/1 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;letter-spacing:0.08em;text-transform:uppercase;color:#d2ff01;">${tag}</div>
          <h1 style="margin:18px 0 0 0;font:300 26px/1.05 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#ffffff;letter-spacing:-0.03em;text-transform:uppercase;">${escapeHtml(subject)}</h1>
          <div style="width:56px;height:1px;background:rgba(255,255,255,0.24);margin:18px 0 0 0;"></div>
        </td></tr>
        <tr><td style="padding:22px 36px 8px 36px;font:300 15px/1.6 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:rgba(255,255,255,0.82);">${bodyHtml}</td></tr>
        <tr><td style="padding:18px 36px 8px 36px;">
          <table role="presentation" cellpadding="0" cellspacing="0"><tr><td style="background:#d2ff01;border-radius:999px;">
            <a href="${ctaUrl}" style="display:inline-block;padding:14px 30px;font:400 12px/1 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;letter-spacing:0.06em;text-transform:uppercase;color:#0a0a0b;text-decoration:none;">${ctaLabel}</a>
          </td></tr></table>
        </td></tr>
        <tr><td style="padding:8px 36px 28px 36px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0">${blocksHtml}</table></td></tr>
        <tr><td style="padding:18px 36px 28px 36px;border-top:1px solid rgba(255,255,255,0.14);font:400 11px/1.5 -apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:rgba(255,255,255,0.6);">
          ABiL MEDiAS · abil.ch
        </td></tr>
      </table>
    </td></tr>
  </table>
</body></html>`;
  return { subject, html };
}

                                               
                                                                     
                                                                   
                                                       
