function SendLangSelector({
  lang,
  sendLang,
  setSendLang,
  i18nKey = "email",
}: {
  lang: Lang;
  sendLang: Lang;
  setSendLang: (l: Lang) => void;
                                                                         
                                                                         
  i18nKey?: "email" | "social" | "blog" | "quote";
}) {
                                                                       
  const baseLabels = EMAIL_DASHBOARD_LABELS[lang] || EMAIL_DASHBOARD_LABELS.fr;
  const contextualTitle: Record<Lang, Record<"email" | "social" | "blog" | "quote", string>> = {
    pt: {
      email: "Em que idioma este email será entregue ao cliente?",
      social: "Em que idioma este conteúdo será publicado?",
      blog: "Em que idioma este artigo será publicado?",
      quote: "Em que idioma este orçamento será entregue ao cliente?",
    },
    fr: {
      email: "Dans quelle langue cet email sera-t-il livré au client ?",
      social: "Dans quelle langue ce contenu sera-t-il publié ?",
      blog: "Dans quelle langue cet article sera-t-il publié ?",
      quote: "Dans quelle langue ce devis sera-t-il livré au client ?",
    },
    en: {
      email: "In which language will this email be delivered to the client?",
      social: "In which language will this content be published?",
      blog: "In which language will this article be published?",
      quote: "In which language will this quote be delivered to the client?",
    },
    de: {
      email: "In welcher Sprache wird diese E-Mail an den Kunden geliefert?",
      social: "In welcher Sprache wird dieser Inhalt veröffentlicht?",
      blog: "In welcher Sprache wird dieser Artikel veröffentlicht?",
      quote: "In welcher Sprache wird dieses Angebot an den Kunden geliefert?",
    },
    it: {
      email: "In quale lingua questa email sarà consegnata al cliente?",
      social: "In quale lingua questo contenuto sarà pubblicato?",
      blog: "In quale lingua questo articolo sarà pubblicato?",
      quote: "In quale lingua questo preventivo sarà consegnato al cliente?",
    },
  };
  (contextualTitle as any).es ??= contextualTitle.fr;
  const eyebrowSuffix: Record<Lang, Record<"email" | "social" | "blog" | "quote", string>> = {
    pt: { email: "envio", social: "publicação", blog: "publicação", quote: "entrega" },
    fr: { email: "envoi", social: "publication", blog: "publication", quote: "envoi du devis" },
    en: { email: "send", social: "publishing", blog: "publishing", quote: "delivery" },
    de: { email: "Versand", social: "Veröffentlichung", blog: "Veröffentlichung", quote: "Liefer" },
    it: { email: "invio", social: "pubblicazione", blog: "pubblicazione", quote: "consegna" },
  };
  (eyebrowSuffix as any).es ??= eyebrowSuffix.fr;
                                                                                                                  
  const quoteExplain2: Record<Lang, string> = {
    pt: ") afecta SÓ a navegação do dashboard. O orçamento é entregue ao cliente no idioma dele, selecciona abaixo qual.",
    fr: ") n'affecte QUE la navigation du tableau de bord. Le devis est livré au client dans sa langue, sélectionnez-la ci-dessous.",
    en: ") only affects the dashboard navigation. The quote is delivered to the client in their language, select it below.",
    de: ") betrifft NUR die Navigation des Dashboards. Das Angebot wird dem Kunden in seiner Sprache geliefert, wählen Sie sie unten aus.",
    it: ") riguarda SOLO la navigazione della dashboard. Il preventivo è consegnato al cliente nella sua lingua, selezionala qui sotto.",
  };
  (quoteExplain2 as any).es ??= quoteExplain2.fr;
  const explain2 = i18nKey === "quote" ? (quoteExplain2[lang] || quoteExplain2.fr) : baseLabels.sendLangExplain2;
  const title = contextualTitle[lang]?.[i18nKey] || baseLabels.sendLangTitle;
  const eyebrowText = baseLabels.sendLangEyebrow.replace(
    /envio|envoi|send|Versand|invio/i,
    eyebrowSuffix[lang]?.[i18nKey] || "envio",
  );
  return (
    <div className="bg-noir text-white px-6 py-5 border border-rouge/30">
      <div className="mb-4">
        <div className="font-mono text-[10px] uppercase tracking-[0.28em] text-rouge mb-2 flex items-center gap-2">
          <Asterisque className="w-3 h-3" color="#d2ff01" />
          {eyebrowText}
        </div>
        <h3 className="font-semibold text-base leading-tight tracking-[-0.02em] mb-2">
          {title}
        </h3>
        <p className="text-xs text-white/65 leading-relaxed">
          {baseLabels.sendLangExplain1}
          <span className="font-mono uppercase text-rouge font-semibold">{lang}</span>
          {explain2}
        </p>
      </div>
      <div className="flex flex-wrap gap-x-6 gap-y-3 pt-3 border-t border-white/10">
        {(["fr", "pt", "en", "de", "it"] as Lang[]).map((l) => {
          const isActive = sendLang === l;
          const labels: Record<Lang, string> = { fr: "Français", pt: "Português", en: "English", de: "Deutsch", it: "Italiano" };
          (labels as any).es ??= labels.fr;
          return (
            <button
              key={l}
              onClick={() => setSendLang(l)}
              className="group inline-flex items-center gap-3 transition-all"
              title={`${l.toUpperCase()} · ${labels[l]}`}
              type="button"
            >
              <div className="flex flex-col items-start leading-tight">
                <span className={`eyebrow eyebrow-sm font-semibold transition-colors ${isActive ? "text-white" : "text-white/50 group-hover:text-white/80"}`}>
                  {l.toUpperCase()}
                </span>
                <span className={`font-mono text-[10px] tracking-[0.18em] uppercase transition-colors ${isActive ? "text-white/70" : "text-white/30 group-hover:text-white/50"}`}>
                  {labels[l]}
                </span>
              </div>
              <div className={`relative w-10 h-5 transition-colors duration-200 ${isActive ? "bg-rouge" : "bg-white/15 group-hover:bg-white/25"}`} style={{ borderRadius: "10px" }}>
                <div
                  className="absolute top-0.5 w-4 h-4 bg-white transition-transform duration-200 shadow-sm"
                  style={{
                    borderRadius: "50%",
                    left: "2px",
                    transform: isActive ? "translateX(20px)" : "translateX(0)",
                  }}
                />
              </div>
            </button>
          );
        })}
      </div>
    </div>
  );
}

                                                                  
                                                                             
                                                                                 
                                                                            
                                                                                   
                                                   
function getHeroImageForPhase(phase?: EmailJourneyPhase): string | null {
                                                                                 
                                                          
                                                                                 
                                                                       
                                                                               
                                                               
                                                          
                                                                       
                                                                         
  if (phase && phase in ABIL_MAIL_BANNER) {
    return ABIL_MAIL_BANNER[phase as keyof typeof ABIL_MAIL_BANNER];
  }
  return "/brand/kv-logo-black-2.jpg";
}

                                                                                   
                                                                                 
                                                                                     
function cleanProjetoSubject(subject: string, lang: Lang = "fr"): string {
  const prefixes: Record<Lang, RegExp> = {
    pt: /^(Novo\s+projecto|Novo\s+projeto)\s*[·:•, -]\s*/i,
    fr: /^(Nouveau\s+projet)\s*[·:•, -]\s*/i,
    en: /^(New\s+project)\s*[·:•, -]\s*/i,
    de: /^(Neues\s+Projekt)\s*[·:•, -]\s*/i,
    it: /^(Nuovo\s+progetto)\s*[·:•, -]\s*/i,
  };
  (prefixes as any).es ??= prefixes.fr;
  const pattern = prefixes[lang] || prefixes.fr;
  return subject.replace(pattern, "").trim();
}

                                                                               
                                                                             
                                                                          
function resolveHeroImage(template: EmailTemplate): string | null {
  if (template.aiImageUrl) return template.aiImageUrl;
  if (template.heroImage) return template.heroImage;
  return getHeroImageForPhase(template.phase) || "/brand/mock-website-2.jpg";
}

                                                                               
                                                                           
                                                                               
                                                                              
                                                   
                                                                                                         
type EmailTextEdit = {
  onText: (key: string, value: string) => void;
  onStyle: (key: string, patch: { fontScale?: number; color?: string }) => void;
};
function EmailEditableText({ value, fieldKey, edit, elStyle, className, style, as = "span", multiline = true }: {
  value: string;
  fieldKey: string;
  edit?: EmailTextEdit;
  elStyle?: { fontScale?: number; color?: string };
  className?: string;
  style?: React.CSSProperties;
  as?: "p" | "h1" | "h3" | "span" | "div";
  multiline?: boolean;
}) {
  const ref = useRef<HTMLElement | null>(null);
  const [editing, setEditing] = useState(false);
  const [baseColor, setBaseColor] = useState("");
  const scale = elStyle?.fontScale;
  const color = elStyle?.color;
  useLayoutEffect(() => {
    const el = ref.current; if (!el) return;
    if (color) el.style.setProperty("color", color, "important"); else el.style.removeProperty("color");
    if (scale && scale !== 1) {
      if (!el.dataset.emBaseFs) el.dataset.emBaseFs = window.getComputedStyle(el).fontSize;
      const base = parseFloat(el.dataset.emBaseFs || "0");
      if (base) el.style.setProperty("font-size", base * scale + "px", "important");
    } else if (el.dataset.emBaseFs) {
      el.style.fontSize = el.dataset.emBaseFs;
    }
  }, [color, scale, value]);
  const Tag = as as React.ElementType;
  if (!edit) {
    return <Tag ref={ref as React.Ref<never>} className={className} style={style}>{value}</Tag>;
  }
  return (
    <span style={{ position: "relative", display: as === "span" ? "inline-block" : "block", width: as === "span" ? undefined : "100%" }}>
      {editing && (
        <span
          contentEditable={false}
          onMouseDown={(e) => e.preventDefault()}
          style={{ position: "absolute", top: -38, left: 0, zIndex: 80, display: "inline-flex", alignItems: "center", gap: 3, background: "#0a0a0b", border: "1px solid rgba(245,34,50,0.55)", padding: "3px 5px", boxShadow: "0 8px 22px rgba(0,0,0,.55)", whiteSpace: "nowrap", borderRadius: 3 }}
        >
          <button type="button" title="Diminuir fonte" onMouseDown={(e) => { e.preventDefault(); const c = scale || 1; edit.onStyle(fieldKey, { fontScale: Math.max(0.5, Math.round((c - 0.1) * 10) / 10) }); }} style={{ color: "#f4efe6", fontFamily: "monospace", fontSize: 11, lineHeight: 1, padding: "4px 7px", cursor: "pointer" }}>A-</button>
          <button type="button" title="Aumentar fonte" onMouseDown={(e) => { e.preventDefault(); const c = scale || 1; edit.onStyle(fieldKey, { fontScale: Math.min(3, Math.round((c + 0.1) * 10) / 10) }); }} style={{ color: "#f4efe6", fontFamily: "monospace", fontSize: 15, lineHeight: 1, padding: "4px 7px", cursor: "pointer" }}>A+</button>
          <span style={{ width: 1, height: 16, background: "rgba(244,239,230,0.22)", margin: "0 3px" }} />
          <label title="Cor do texto" onMouseDown={(e) => e.stopPropagation()} style={{ display: "inline-flex", alignItems: "center", cursor: "pointer" }}>
            <input type="color" value={rgbToHex(color || baseColor || "#f4efe6")} onChange={(e) => edit.onStyle(fieldKey, { color: e.target.value })} style={{ width: 22, height: 22, padding: 0, border: 0, background: "transparent", cursor: "pointer" }} />
          </label>
        </span>
      )}
      <Tag
        ref={ref as React.Ref<never>}
        className={className}
        style={{ ...style, outline: editing ? "1px dashed rgba(245,34,50,0.75)" : undefined, outlineOffset: 2, cursor: "text" }}
        contentEditable
        suppressContentEditableWarning
        onFocus={() => { const el = ref.current; if (el) setBaseColor(window.getComputedStyle(el).color); setEditing(true); }}
        onBlur={(e) => {
          setEditing(false);
          const raw = (e.currentTarget as HTMLElement).innerText.replace(/ /g, " ");
          const clean = multiline ? raw.replace(/\n{3,}/g, "\n\n").replace(/[ \t]+$/gm, "") : raw.replace(/\s*\n\s*/g, " ").trim();
          if (clean !== value) edit.onText(fieldKey, clean);
        }}
        onKeyDown={(e) => { if (!multiline && e.key === "Enter") { e.preventDefault(); (e.currentTarget as HTMLElement).blur(); } }}
      >{value}</Tag>
    </span>
  );
}

                                                                         
                                                                             
                                                                                 
                                                                          
                                                                               
function EmailJourneyRenderer({
  template,
  editControls,
  lang,
}: {
  template: EmailTemplate;
  editControls?: { onEditImage?: () => void; onAiImage?: () => void; aiLoading?: boolean; text?: EmailTextEdit };
  lang?: Lang;
}) {
                                                                      
                                                                              
                                                                                
                                                                            
                                                                              
                                      
    
                                                                           
                                                                           
                                                                               
                                           
  const effectiveLang: Lang = lang || "fr";
  const hl = HERO_LABELS_BY_LANG[effectiveLang] || HERO_LABELS_BY_LANG.fr;
  const edit = editControls?.text;
  const styles = template.textStyles;
  const spec = buildEmailSpec({
                                                                      
    subject: template.phase === "projeto_publicado"
      ? cleanProjetoSubject(template.subject, effectiveLang)
      : template.subject,
    phase: template.phase,
    preheader: template.preheader,
    body: template.body,
    ctaLabel: template.ctaLabel,
    ctaUrl: template.ctaUrl,
    heroImage: resolveHeroImage(template) || undefined,
    projectGallery: template.projectGallery,
    blocks: template.blocks,
  });

  return (
    <AbilEmailPreview
      className="mx-auto shadow-2xl"
      spec={spec}
      unsubscribeLabel={hl.footerUnsubscribe}
      galleryLabel={hl.gallerySectionHeader}
      bannerOverlay={
        <>
          {editControls?.aiLoading && <AiImageLoadingOverlay />}
          {editControls && !editControls.aiLoading && (
            <ImageEditControls onEditImage={editControls.onEditImage} onAiImage={editControls.onAiImage} size="md" />
          )}
        </>
      }
      campo={({ value, fieldKey, as, multiline, style }) => (
        <EmailEditableText
          as={as}
          value={value}
          fieldKey={fieldKey}
          edit={edit}
          elStyle={styles?.[fieldKey]}
          multiline={multiline}
          style={style}
        />
      )}
    />
  );
}

                                                                           
                                                                           
                                                                   
function suggestPromptForPhase(phase?: EmailJourneyPhase, subject?: string): string {
  const map: Record<EmailJourneyPhase, string> = {
    atracao: "Wide editorial shot of a Swiss creative atelier in Genève, designers at work, natural daylight through large windows, wooden floors, restrained palette of black and warm grey.",
    boasvindas: "Minimalist editorial still-life, a single hand-printed letterpress card on a textured paper surface, generous negative space, soft side light, no text visible.",
    dor: "Editorial still-life of fragmented brand pieces, mismatched business cards, posters and packaging scattered across a wooden table, dramatic side light, sense of inconsistency.",
    repost_blog: "Editorial close-up of a hand turning the page of a hardcover journal on a wooden desk, natural side light, atmosphere of quiet reading and reflection, restrained palette of cream and warm black.",
    solucao: "Three brand pieces aligned in editorial composition, a poster, a packaging element and a printed manual, harmonious tonal palette, top-down view, natural light.",
    interesse: "Premium wine bottle close-up against a clean dark backdrop, refined label design implied, atmospheric side light, sense of craft and heritage.",
    prova: "Editorial flatlay of design awards and recognition, trophies, certificates, magazine covers arranged on a black surface, dramatic key light.",
    qualificacao: "Two designers in calm conversation at a wooden meeting table, sketches and prototypes scattered, focused atmosphere, natural light.",
    convite: "Empty wooden meeting table in Swiss atelier, two chairs facing each other, morning light through window, sense of anticipation and calm professionalism.",
    projeto_publicado: "Premium project showcase, final brand identity piece displayed on a clean studio surface, editorial photography, Swiss minimalism, no text or logo visible.",
  };
  return phase ? map[phase] : (subject ? `Editorial photographic interpretation of: ${subject}` : "Editorial scene for a Swiss creative atelier, calm, minimal, natural light, restrained palette.");
}

                                                                                
                                                                   
