function NewTemplatePickerModal({
  open,
  onClose,
  onPick,
}: {
  open: boolean;
  onClose: () => void;
  onPick: (phase: EmailJourneyPhase | null) => void;
}) {
  const { lang } = useApp();
  const dl = EMAIL_DASHBOARD_LABELS[lang] || EMAIL_DASHBOARD_LABELS.fr;
  const pl = EMAIL_JOURNEY_PHASE_LABELS[lang] || EMAIL_JOURNEY_PHASE_LABELS.fr;
  const pd = EMAIL_JOURNEY_PHASE_DESC[lang] || EMAIL_JOURNEY_PHASE_DESC.fr;
  if (!open) return null;
  return (
    <div className="fixed inset-0 z-[200] bg-noir/95 backdrop-blur-sm flex items-center justify-center p-6" onClick={onClose}>
      <div className="bg-white max-w-5xl w-full max-h-[90vh] overflow-y-auto shadow-2xl" onClick={(e) => e.stopPropagation()}>
        <header className="px-6 py-5 border-b border-neutral-200 flex items-center justify-between sticky top-0 bg-white z-10">
          <div>
            <div className="font-mono text-[10px] uppercase tracking-[0.28em] text-rouge mb-1.5 flex items-center gap-2">
              <Asterisque className="w-3 h-3" color="#d2ff01" />
              {dl.newTplPickerEyebrow}
            </div>
            <h2 className="font-semibold text-xl tracking-[-0.02em] mb-1">{dl.newTplPickerTitle}</h2>
            <p className="text-xs text-neutral-500 max-w-[600px]">{dl.newTplPickerSubtitle}</p>
          </div>
          <button onClick={onClose} className="text-noir/60 hover:text-rouge w-9 h-9 flex items-center justify-center" title={dl.closeBtn}>
            <IconX className="w-5 h-5" />
          </button>
        </header>
        <div className="p-6">
          {                      }
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
            {PHASE_ORDER.map((phase, idx) => {
              const accentCls = PHASE_NUMBER_CLASS[phase];
              const num = String(idx + 1).padStart(2, "0");
              return (
                <button
                  key={phase}
                  onClick={() => { onPick(phase); onClose(); }}
                  className="group text-left bg-white border border-neutral-200 hover:border-rouge transition-all hover:shadow-lg overflow-hidden"
                  type="button"
                >
                  {                                     }
                  <div className={`${accentCls} px-5 py-4 flex items-center gap-4`}>
                    <div className="flex flex-col items-start leading-none">
                      <span className="eyebrow opacity-70 mb-1">{dl.phaseLabel}</span>
                      <span className="font-semibold text-3xl tracking-tight">{num}</span>
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="font-semibold text-sm leading-tight tracking-[-0.01em]">{pl[phase]}</div>
                    </div>
                  </div>
                  {                                 }
                  <div className="px-5 py-4 border-t border-neutral-200">
                    <p className="text-xs text-neutral-600 leading-relaxed">{pd[phase]}</p>
                  </div>
                </button>
              );
            })}
          </div>
          {                                           }
          <div className="mt-6 pt-5 border-t border-neutral-200">
            <button
              onClick={() => { onPick(null); onClose(); }}
              className="w-full text-left bg-neutral-50 border border-dashed border-neutral-300 hover:border-rouge hover:bg-white transition-all px-5 py-4 flex items-center gap-4"
              type="button"
            >
              <div className="w-12 h-12 border-2 border-dashed border-neutral-400 flex items-center justify-center flex-shrink-0">
                <IconSparkles className="w-5 h-5 text-neutral-500" />
              </div>
              <div className="flex-1">
                <div className="font-semibold text-sm text-noir mb-0.5">{dl.newTplPickerGeneric}</div>
                <div className="text-xs text-neutral-500">Sem brand-voice pré-aplicado · ideal para emails fora da jornada (newsletter ad-hoc, anúncio, etc.).</div>
              </div>
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

function ImagePickerModal({
  open, onClose, onPick, currentSrc,
}: {
  open: boolean;
  onClose: () => void;
  onPick: (src: string) => void;
  currentSrc?: string;
}) {
  const { lang } = useApp();
  const dl = EMAIL_DASHBOARD_LABELS[lang] || EMAIL_DASHBOARD_LABELS.fr;
                                                                                                  
                                                                                                      
                                                                                                        
  const [dashProjects] = useDashProjectsIDB([]);
  if (!open) return null;
  const realPool: { src: string; label: string; project: string }[] = (dashProjects || [])
    .flatMap((p) => projectGalleryImageUrls(p, 12).map((src, i) => ({ src, label: i === 0 ? (p.title || "Projeto") : `${p.title || "Projeto"} · ${i + 1}`, project: p.title || "Projeto" })));
  const pool = realPool.length ? realPool : PROJECT_IMAGE_POOL;
  const groups = pool.reduce<Record<string, typeof PROJECT_IMAGE_POOL>>((acc, img) => {
    if (!acc[img.project]) acc[img.project] = [];
    acc[img.project].push(img);
    return acc;
  }, {});
  return (
    <div className="fixed inset-0 z-[200] bg-noir/95 backdrop-blur-sm flex items-center justify-center p-6" onClick={onClose}>
      <div className="bg-white max-w-5xl w-full max-h-[85vh] overflow-y-auto shadow-2xl" onClick={(e) => e.stopPropagation()}>
        <header className="px-6 py-4 border-b border-neutral-200 flex items-center justify-between sticky top-0 bg-white z-10">
          <div>
            <div className="font-mono text-[10px] uppercase tracking-[0.28em] text-rouge flex items-center gap-2 mb-1">
              <IconEdit className="w-3 h-3" /> {dl.pickerEyebrow}
            </div>
            <h3 className="font-semibold text-lg tracking-[-0.02em]">{dl.pickerTitle}</h3>
            <p className="text-xs text-neutral-500 mt-1">{dl.pickerSubtitle}</p>
          </div>
          <button onClick={onClose} className="text-noir/60 hover:text-rouge w-9 h-9 flex items-center justify-center" title={dl.closeBtn}>
            <IconX className="w-5 h-5" />
          </button>
        </header>
        <div className="p-6 space-y-6">
          {                                                                                         
                                                                       }
          {(() => {
            const server = collectReusableSiteImages(120);
            if (!server.length) return null;
            return (
              <div>
                <div className="eyebrow text-rouge mb-3">Do servidor · {server.length} imagens</div>
                <div className="grid grid-cols-3 md:grid-cols-4 gap-3">
                  {server.map((u, i) => {
                    const isCurrent = u === currentSrc;
                    return (
                      <button
                        key={`srv-${i}`}
                        onClick={() => { onPick(u); onClose(); }}
                        className={`group relative aspect-[3/2] overflow-hidden border-2 transition-all ${isCurrent ? "border-rouge ring-2 ring-rouge/30" : "border-transparent hover:border-rouge"}`}
                        title="Reutilizar esta imagem"
                        type="button"
                      >
                        <img src={u} alt="" loading="lazy" decoding="async" className="w-full h-full object-cover transition-transform group-hover:scale-105" onError={(e) => { const b = (e.currentTarget as HTMLImageElement).closest('button'); if (b) (b as HTMLElement).style.display = 'none'; }} />
                      </button>
                    );
                  })}
                </div>
              </div>
            );
          })()}
          {Object.entries(groups).map(([project, imgs]) => (
            <div key={project}>
              <div className="eyebrow text-noir/60 mb-3">
                {project}{dl.groupSeparator}{dl.pickerImageCount(imgs.length)}
              </div>
              <div className="grid grid-cols-3 md:grid-cols-4 gap-3">
                {imgs.map((img) => {
                  const isCurrent = img.src === currentSrc;
                  return (
                    <button
                      key={img.src}
                      onClick={() => { onPick(img.src); onClose(); }}
                      className={`group relative aspect-[3/2] overflow-hidden border-2 transition-all ${
                        isCurrent ? "border-rouge ring-2 ring-rouge/30" : "border-transparent hover:border-rouge"
                      }`}
                      title={img.label}
                      type="button"
                    >
                      <img src={img.src} alt={img.label} className="w-full h-full object-cover transition-transform group-hover:scale-105" onError={(e) => { const b = (e.currentTarget as HTMLImageElement).closest('button'); if (b) (b as HTMLElement).style.display = 'none'; }} />
                      <div className="absolute inset-0 bg-noir/0 group-hover:bg-noir/30 transition-colors flex items-end p-2">
                        <div className="text-white font-mono text-[9px] uppercase tracking-[0.18em] opacity-0 group-hover:opacity-100 transition-opacity">
                          {img.label}
                        </div>
                      </div>
                      {isCurrent && (
                        <div className="absolute top-1.5 left-1.5 bg-rouge text-white font-mono text-[10px] uppercase tracking-[0.18em] px-1.5 py-0.5">
                          {dl.pickerCurrent}
                        </div>
                      )}
                    </button>
                  );
                })}
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

                                                                         
                                                                             
                                                                        
function FieldWithAiWand({
  label, value, onChange, type = "input", rows = 4, placeholder = "",
  fieldName, maxLength = 500, monoFont = false,
}: {
  label: string;
  value: string;
  onChange: (v: string) => void;
  type?: "input" | "textarea";
  rows?: number;
  placeholder?: string;
  fieldName: string;
  maxLength?: number;
  monoFont?: boolean;
}) {
  const { lang } = useApp();
  const dl = EMAIL_DASHBOARD_LABELS[lang] || EMAIL_DASHBOARD_LABELS.fr;
  const [wandOpen, setWandOpen] = useState(false);
  const [prompt, setPrompt] = useState("");
  const [generated, setGenerated] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const generate = async () => {
    setLoading(true); setError(null); setGenerated(null);
    try {
                                                                                                 
      const txt = await aiGenerateText({
        currentText: value,
        userPrompt: prompt || "Reescreve mantendo o sentido, com melhor ritmo e mais brand-voice ABiL.",
        maxLength,
        path: `email.${fieldName}`,
        lang,
      });
      if (!txt) throw new Error(dl.aiTextErrorGeneric);
      setGenerated(txt);
    } catch (err: any) {
      setError(err.message || dl.aiTextErrorGeneric);
    } finally {
      setLoading(false);
    }
  };

  const apply = () => {
    if (generated) onChange(generated);
    setWandOpen(false); setGenerated(null); setPrompt(""); setError(null);
  };

  const cancel = () => { setWandOpen(false); setGenerated(null); setPrompt(""); setError(null); };

  const inputCls = `w-full bg-white/5 border border-white/15 px-3 py-2 text-sm text-white placeholder:text-white/30 focus:outline-none focus:border-violet ${monoFont ? "font-mono text-xs" : ""}`;

  return (
    <div className="space-y-2 relative">
      <div className="flex items-center justify-between">
        <label className="block eyebrow eyebrow-xs text-white/50">{label}</label>
        <button
          onClick={() => setWandOpen(!wandOpen)}
          className={`p-1 transition-colors ${wandOpen ? "text-rouge" : "text-white/40 hover:text-rouge"}`}
          title={dl.aiTextRewrite}
          type="button"
        >
          <IconWand className="w-3.5 h-3.5" strokeWidth={1.8} />
        </button>
      </div>
      {type === "input" ? (
        <input
          type="text"
          value={value}
          onChange={(e) => onChange(e.target.value)}
          placeholder={placeholder}
          className={inputCls}
        />
      ) : (
        <textarea
          value={value}
          onChange={(e) => onChange(e.target.value)}
          rows={rows}
          placeholder={placeholder}
          className={`${inputCls} resize-y leading-relaxed`}
        />
      )}
      {wandOpen && (
        <div className="absolute right-0 top-8 z-50 w-[320px] bg-noir border-2 border-rouge p-3 space-y-2.5 shadow-2xl">
          <div className="eyebrow eyebrow-xs text-rouge flex items-center gap-1.5">
            <IconWand className="w-3 h-3" /> {dl.aiTextRewrite} · {label}
          </div>
          <div className="bg-white/5 border-l-2 border-white/20 p-2 text-[10px] text-white/70 italic leading-snug max-h-16 overflow-y-auto">
            {value ? `"${value.slice(0, 140)}${value.length > 140 ? "…" : ""}"` : <span className="text-white/40 not-italic">{dl.aiTextEmpty}</span>}
          </div>
          <textarea
            value={prompt}
            onChange={(e) => setPrompt(e.target.value)}
            placeholder={dl.aiTextPromptPlaceholder}
            rows={2}
            className="w-full bg-white/5 border border-white/15 px-2 py-1.5 text-xs text-white placeholder:text-white/30 focus:outline-none focus:border-rouge resize-none"
          />
          {generated !== null && (
            <div className="bg-rouge/10 border-l-2 border-rouge p-2 text-xs text-white leading-relaxed max-h-32 overflow-y-auto">
              {generated || <span className="text-white/40 italic">{dl.aiTextEmptyResult}</span>}
            </div>
          )}
          {error && (
            <div className="bg-rouge/20 border border-rouge/40 px-2 py-1.5 text-[9px] text-rouge font-mono leading-snug">
              {error}
            </div>
          )}
          <div className="flex items-center gap-1.5 pt-1">
            <button
              onClick={cancel}
              disabled={loading}
              className="px-2 py-1 font-mono text-[9px] uppercase tracking-[0.18em] text-white/60 hover:text-white disabled:opacity-50"
              type="button"
            >
              {dl.aiTextCancel}
            </button>
            <button
              onClick={generate}
              disabled={loading}
              className="ml-auto bg-rouge text-white px-3 py-1.5 font-mono text-[9px] uppercase tracking-[0.18em] hover:bg-white hover:text-rouge transition-colors disabled:opacity-50 flex items-center gap-1.5"
              type="button"
            >
              <IconWand className={`w-3 h-3 ${loading ? "animate-spin" : ""}`} />
              {loading ? dl.aiTextLoading : (generated !== null ? dl.aiTextGenerateAgain : dl.aiTextGenerate)}
            </button>
            {generated !== null && generated && (
              <button
                onClick={apply}
                className="bg-violet text-noir px-3 py-1.5 font-mono text-[9px] uppercase tracking-[0.18em] hover:bg-white transition-colors"
                type="button"
              >
                {dl.aiTextApply}
              </button>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

                                                                      
                                                                           
                                                                             
                                                              
function EmailTemplatePreviewModal({
  template,
  sendLang,
  navLang,
  getTplInLang,
  onClose,
  onSave,
  onAutoGenerate,
  autoGenLoading,
}: {
  template: EmailTemplate;
  sendLang?: Lang;
  navLang?: Lang;
  getTplInLang?: (l: Lang) => EmailTemplate;
  onClose: () => void;
  onSave: (patch: Partial<EmailTemplate>) => void;
  onAutoGenerate: () => void;
  autoGenLoading: boolean;
}) {
                                                                                    
  const { lang: appLang } = useApp();
  const effectiveNavLang: Lang = navLang || appLang;
  const effectiveSendLang: Lang = sendLang || effectiveNavLang;
                                                                            
                                                                                  
                                                  
  const [viewLang, setViewLang] = useState<Lang>(effectiveNavLang);
  const dl = EMAIL_DASHBOARD_LABELS[viewLang] || EMAIL_DASHBOARD_LABELS.fr;
                                                                                  
  const activeTpl: EmailTemplate = getTplInLang ? getTplInLang(viewLang) : template;
  const viewingOriginal = viewLang === effectiveSendLang;
                                                                                  
                                                                               
                                                                                 
                                                                                  
  const showingSend = viewLang !== effectiveNavLang;
                                                                    
                                                       
                                                                 
  const [draft, setDraft] = useState({
    subject: activeTpl.subject,
    preheader: activeTpl.preheader,
    body: activeTpl.body,
    ctaLabel: activeTpl.ctaLabel ?? "",
    ctaUrl: activeTpl.ctaUrl ?? "",
                                                                                                      
    blocks: (activeTpl.blocks || []).map((b) => ({ ...b })),
    textStyles: activeTpl.textStyles || {},
  });
                                                                          
  useEffect(() => {
    const id = window.setTimeout(() => setDraft({
      subject: activeTpl.subject,
      preheader: activeTpl.preheader,
      body: activeTpl.body,
      ctaLabel: activeTpl.ctaLabel ?? "",
      ctaUrl: activeTpl.ctaUrl ?? "",
      blocks: (activeTpl.blocks || []).map((b) => ({ ...b })),
      textStyles: activeTpl.textStyles || {},
    }), 0);
    return () => window.clearTimeout(id);
  }, [activeTpl.id, viewLang, activeTpl.subject, activeTpl.preheader, activeTpl.body, activeTpl.ctaLabel, activeTpl.ctaUrl]);

  const isDirty =
    draft.subject !== activeTpl.subject ||
    draft.preheader !== activeTpl.preheader ||
    draft.body !== activeTpl.body ||
    draft.ctaLabel !== (activeTpl.ctaLabel ?? "") ||
    draft.ctaUrl !== (activeTpl.ctaUrl ?? "") ||
                                                                                           
    JSON.stringify(draft.blocks || []) !== JSON.stringify(activeTpl.blocks || []) ||
    JSON.stringify(draft.textStyles || {}) !== JSON.stringify(activeTpl.textStyles || {});

                                                                              
                                                                         
                                                                            
  const [aiImages, setAiImages] = useLocalStorageState<AiImageStore>("abil_email_ai_images_v1", {});
                                                                         
                                                                                    
                                                                                                
  const [imgPromptOpen, setImgPromptOpen] = useState(false);
                                                                   
  const [imagePickerOpen, setImagePickerOpen] = useState(false);

  const currentAiImage = aiImages[template.id] || null;

                                                                                 
  const applyAiImage = (src: string) => {
    try {
      setAiImages({ ...aiImages, [template.id]: src });
    } catch (storageErr: any) {
      if (String(storageErr?.name || "").includes("Quota")) setAiImages({ [template.id]: src });
    }
                                                                                               
                                                                                                
                                                                                    
    if (src && src.startsWith("data:")) {
      void (async () => {
        try {
          if (!abilVaultUnlocked()) return;
          const { cloudUploadFile, dataUrlToFile } = await import("@/lib/cloudProjects");
          const f = dataUrlToFile(src, `email-${template.id}-${(globalThis.crypto?.randomUUID?.() || "img")}.jpg`);
          if (!f) return;
          const r = await cloudUploadFile(f, { prefix: "email" });
          if (r.ok && r.url) {
            const merged = { ...aiImages, [template.id]: r.url };
            setAiImages(merged);
            try { cloudSet("abil_email_ai_images_v1", merged); } catch {            }
          }
        } catch {                           }
      })();
    }
  };

  const handleRemoveAiImage = () => {
    const next = { ...aiImages };
    delete next[template.id];
    setAiImages(next);
  };

                                                                            
                                                                            
  const previewTemplate: EmailTemplate = {
    ...activeTpl,
    subject: draft.subject,
    preheader: draft.preheader,
    body: draft.body,
                                                                                              
    blocks: draft.blocks,
    textStyles: draft.textStyles,
    ctaLabel: draft.ctaLabel,
    ctaUrl: draft.ctaUrl,
    aiImageUrl: currentAiImage || undefined,
  };

  const handleSave = () => {
    if (!isDirty) { onClose(); return; }
    onSave({
      subject: draft.subject,
      preheader: draft.preheader,
      body: draft.body,
                                                                                         
      blocks: draft.blocks,
      textStyles: draft.textStyles,
      ctaLabel: draft.ctaLabel,
      ctaUrl: draft.ctaUrl,
      lastEdit: new Date().toLocaleDateString("fr-CH"),
    });
  };

  return (
    <div className="fixed inset-0 z-[100] bg-noir/95 backdrop-blur-sm flex">
      {                                                           }
      <aside className="w-full lg:w-[380px] bg-noir text-white flex-shrink-0 flex flex-col border-r border-white/10">
        <header className="flex items-center justify-between px-5 py-4 border-b border-white/10">
          <h2 className="eyebrow text-white/80">
            {dl.editTemplate}
          </h2>
          <button
            onClick={handleSave}
            disabled={!isDirty}
            className="bg-violet text-noir px-3 py-1.5 eyebrow eyebrow-xs hover:bg-white transition-colors flex items-center gap-1.5 disabled:opacity-40 disabled:cursor-not-allowed"
            title={dl.saveChanges}
          >
            <IconSparkles className="w-3 h-3" /> {dl.save}
          </button>
        </header>
        <div className="flex-1 overflow-y-auto p-5 space-y-5">
          <FieldWithAiWand
            label={dl.fldSubject}
            value={draft.subject}
            onChange={(v) => setDraft({ ...draft, subject: v })}
            fieldName="subject"
            maxLength={120}
          />
          <FieldWithAiWand
            label={dl.fldPreheader}
            value={draft.preheader}
            onChange={(v) => setDraft({ ...draft, preheader: v })}
            fieldName="preheader"
            maxLength={140}
          />
          <FieldWithAiWand
            label={dl.fldBody}
            value={draft.body}
            onChange={(v) => setDraft({ ...draft, body: v })}
            fieldName="body"
            type="textarea"
            rows={10}
            maxLength={2000}
          />
          <FieldWithAiWand
            label={dl.fldCtaLabel}
            value={draft.ctaLabel}
            onChange={(v) => setDraft({ ...draft, ctaLabel: v })}
            placeholder={dl.fldCtaLabelPlaceholder}
            fieldName="ctaLabel"
            maxLength={60}
          />
          <FieldWithAiWand
            label={dl.fldCtaUrl}
            value={draft.ctaUrl}
            onChange={(v) => setDraft({ ...draft, ctaUrl: v })}
            placeholder={dl.fldCtaUrlPlaceholder}
            fieldName="ctaUrl"
            maxLength={200}
            monoFont
          />
          {                                                                          
                                                                                     
                                                                  }
          <div className="pt-4 border-t border-white/10 space-y-3">
            <label className="block eyebrow eyebrow-xs text-rouge">
              * {dl.aiImageBlockTitle}
            </label>
            {currentAiImage && (
              <div className="relative group">
                <img src={currentAiImage} alt="" className="w-full aspect-[3/2] object-cover border border-white/15" />
                <button
                  onClick={handleRemoveAiImage}
                  className="absolute top-1.5 right-1.5 bg-noir/80 text-white w-6 h-6 flex items-center justify-center font-mono text-[10px] opacity-0 group-hover:opacity-100 transition-opacity"
                  title={dl.aiImageRemoveTitle}
                >
                  <IconX className="w-3 h-3" />
                </button>
                <div className="absolute bottom-1.5 left-1.5 bg-noir/80 text-white px-2 py-0.5 font-mono text-[10px] uppercase tracking-[0.18em]">
                  * {dl.aiImageCached}
                </div>
              </div>
            )}
            <div className="font-mono text-[10px] text-white/40 leading-relaxed">
              ⓘ {dl.aiImageHint}
            </div>
            <button
              onClick={() => setImgPromptOpen(true)}
              className="w-full bg-rouge text-white px-4 py-2.5 eyebrow hover:bg-white hover:text-rouge transition-colors flex items-center justify-center gap-2"
            >
              <IconSparkles className="w-3.5 h-3.5" />
              {currentAiImage ? dl.aiImageRegenerate : dl.aiImageGenerate}
            </button>
          </div>

          {                          }
          <div className="pt-4 border-t border-white/10 space-y-2">
            <button
              onClick={handleSave}
              disabled={!isDirty}
              className="w-full bg-violet text-noir px-4 py-2.5 eyebrow hover:bg-white transition-colors flex items-center justify-center gap-2 disabled:opacity-40 disabled:cursor-not-allowed"
            >
              <IconSparkles className="w-3.5 h-3.5" /> {dl.saveChanges}
            </button>
            <button
              onClick={onAutoGenerate}
              disabled={autoGenLoading}
              className="w-full bg-white/10 text-white px-4 py-2.5 eyebrow hover:bg-rouge transition-colors flex items-center justify-center gap-2 disabled:opacity-40"
            >
              <IconSparkles className="w-3.5 h-3.5" /> {autoGenLoading ? dl.aiTextLoading : dl.generateText}
            </button>
          </div>
        </div>
      </aside>
      {                     }
      <main className="flex-1 flex flex-col min-w-0">
        {                                                                            }
        <header className="border-b border-white/10 bg-noir flex-shrink-0">
          <div className="flex items-center justify-between px-6 py-3">
            <div className="flex-1 min-w-0 flex items-center gap-4 flex-wrap">
              <div className="eyebrow text-white/60 truncate">
                {dl.preview} · {activeTpl.name}
              </div>
              {                                                                    
                                                                                    }
            </div>
            <button
              onClick={onClose}
              className="text-white/60 hover:text-white w-9 h-9 flex items-center justify-center transition-colors flex-shrink-0"
              aria-label={dl.closeBtn}
              title={dl.closeBtn}
            >
              <IconX className="w-5 h-5" />
            </button>
          </div>
        </header>
        <div className="flex-1 overflow-y-auto py-10 px-4 bg-noir/50">
          {                                                                       
                                                                                   
                                                                                }
          <div className="max-w-[640px] mx-auto mb-4 text-center">
            <button
              type="button"
              onClick={() => setViewLang(showingSend ? effectiveNavLang : effectiveSendLang)}
              aria-pressed={showingSend}
              title="Idioma do site vs idioma de envio ao cliente"
              className={`w-full sm:w-auto inline-flex items-center justify-center gap-2 eyebrow px-4 py-2.5 transition-colors ${showingSend ? "bg-white/10 text-white/60 hover:bg-white/20" : "bg-rouge text-white hover:bg-noir"}`}
            >
              <IconLanguages className="w-3.5 h-3.5 shrink-0" />
              {showingSend
                ? `Idioma de envio · ${String(effectiveSendLang).toUpperCase()}`
                : "Ver idioma de envio"}
            </button>
            <p className="mt-1.5 text-[10px] leading-snug text-white/40">
              {showingSend
                ? `Vês como vai ser enviado ao cliente (${String(effectiveSendLang).toUpperCase()}). Clica para voltar ao idioma do site (${String(effectiveNavLang).toUpperCase()}).`
                : `Vês no idioma do site (${String(effectiveNavLang).toUpperCase()}). Clica para ver como vai ser enviado ao cliente.`}
            </p>
          </div>
          <EmailJourneyRenderer
            template={previewTemplate}
            lang={viewLang}
            editControls={{
              aiLoading: false,
              onEditImage: () => setImagePickerOpen(true),
                                                                                    
                                                                                     
              onAiImage: () => setImgPromptOpen(true),
                                                                                              
                                                                                                
                                                                
              text: {
                onText: (key, v) => {
                  if (key === "subject") { setDraft((d) => ({ ...d, subject: v })); return; }
                  if (key === "body") { setDraft((d) => ({ ...d, body: v })); return; }
                  const m = /^block-(\d+)-(titulo|descricao)$/.exec(key);
                  if (m) {
                    const idx = Number(m[1]); const f = m[2];
                    setDraft((d) => {
                      const bs = (d.blocks || []).map((b) => ({ ...b }));
                      if (bs[idx]) (bs[idx] as Record<string, string>)[f] = v;
                      return { ...d, blocks: bs };
                    });
                  }
                },
                onStyle: (key, patch) => {
                  setDraft((d) => {
                    const ts = { ...((d.textStyles || {}) as Record<string, { fontScale?: number; color?: string }>) };
                    ts[key] = { ...(ts[key] || {}), ...patch };
                    return { ...d, textStyles: ts };
                  });
                },
              },
            }}
          />
        </div>
      </main>
      {                                                                      
                                                                     }
      <ImagePickerModal
        open={imagePickerOpen}
        onClose={() => setImagePickerOpen(false)}
        currentSrc={currentAiImage || getHeroImageForPhase(template.phase) || undefined}
        onPick={(src) => applyAiImage(src)}
      />
      {                                                                                      
                                                                                           }
      <AIImagePromptModal
        open={imgPromptOpen}
        onClose={() => setImgPromptOpen(false)}
        lang={viewLang}
        contextLabel={`Email hero for "${template.name}", phase: ${template.phase || "generic"}`}
        initialPrompt={suggestPromptForPhase(template.phase, template.subject)}
        onApply={(url) => applyAiImage(url)}
      />
    </div>
  );
}

                                                                        
                                                                              
                                                                           
