function getPhaseNumber(phase?: EmailJourneyPhase): string | null {
  if (!phase) return null;
  const idx = PHASE_ORDER.indexOf(phase);
  return idx === -1 ? null : String(idx + 1).padStart(2, "0");
}

                                                                         
                                                                          
                                                                              
