              const phaseNum = getPhaseNumber(tpl.phase) || (tpl.phase ? "NL" : null);
              const phaseColorClass = tpl.phase ? (PHASE_NUMBER_CLASS[tpl.phase] || "bg-rouge text-white") : "bg-neutral-100 text-noir";
                                                                                       
