function layoutToTag(layout: SocialCard["layout"]): TemplateTag {
  switch (layout) {
    case "hero-image":      return "frases-criativas";
    case "portrait-photo":  return "diferenciais";
    case "product-shot":    return "servicos";
    case "triptych":        return "curiosidades";
    case "hero-quote":      return "frases-criativas";
    case "stat":            return "frases-criativas";
    case "manifesto":       return "frases-criativas";
    case "carousel-cover":  return "repost-projeto";
    case "repost-blog":     return "repost-blog";
    case "repost-project":  return "repost-projeto";
    default:                return "frases-criativas";
  }
}

                                                                       
                                                                             
                                                               
                                                                                               
                                                                                              
                                                     
function localizedCardContent(card: SocialCard, lang: Lang): SocialCard & { titleRich?: string; supportRich?: string } {
  const t = card.translations?.[lang];
  if (!t) return card;
  return {
    ...card,
    title: t.title ?? card.title,
    subtitle: t.subtitle ?? card.subtitle,
    supportText: t.supportText ?? card.supportText,
    disruptivePhrase: t.disruptivePhrase ?? card.disruptivePhrase,
    caption: t.caption ?? card.caption,
    ...(t.titleRich ? { titleRich: t.titleRich } : {}),
    ...(t.supportRich ? { supportRich: t.supportRich } : {}),
  };
}

                                                                                                
                                                                                                  
                                                                                                         
                                                                                                              
async function ensureCardLang(card: SocialCard, toLang: Lang): Promise<SocialCard> {
  if (!card) return card;
  const FLAT = ["title", "subtitle", "supportText", "disruptivePhrase", "caption"] as const;
  const existing = { ...((card.translations?.[toLang] || {}) as Record<string, string>) };
  const src = (card.sourceLang || "auto") as Lang | "auto";
  for (const k of FLAT) {
    if (existing[k] && existing[k].trim()) continue;                                
    const val = String((card as Record<string, unknown>)[k] ?? "");
    if (!val.trim()) continue;
    try {
      const tr = await translateText(val, src, toLang);
      if (tr && tr.trim()) existing[k] = tr;
    } catch {                                                 }
  }
  return { ...card, translations: { ...(card.translations || {}), [toLang]: existing } } as SocialCard;
}

                                                                                                  
                                                                                                 
                                                                                               
                                                                                              
                                                                        
                                                                      
function socialPlainTextPatch(card: SocialCard, elName: string, value: string, editLang: Lang): Partial<SocialCard> {
                                                                                               
                                                                                               
                                                                                               
  if (elName !== "title" && elName !== "support") {
                                                                              
                                                                                  
    const trPrev = { ...(card.translations?.[editLang] || {}) };
    const cur = { ...(trPrev.textOverrides || {}) };
    if (value === "") delete cur[elName]; else cur[elName] = value;
    trPrev.textOverrides = cur;
    return { translations: { ...(card.translations || {}), [editLang]: trPrev } };
  }
  const field: "title" | "supportText" = elName === "title" ? "title" : "supportText";
  const hasTr = !!card.translations?.[editLang];
  const foreign = !!card.sourceLang && card.sourceLang !== editLang;
  if (hasTr || foreign) {
    const cur = { ...(card.translations?.[editLang] || {}), [field]: value };
    return { translations: { ...(card.translations || {}), [editLang]: cur } };
  }
  return field === "title" ? { title: value } : { supportText: value };
}

function SocialCardPreview({ card: rawCard, scale = 1, pubLangOverride, slideIndex, imageTools }: { card: SocialCard; scale?: number; pubLangOverride?: PubLang; slideIndex?: number; imageTools?: boolean }) {
                                                              
                                                      
                                                                                        
  const card = localizedCardContent(rawCard, (pubLangOverride || "fr") as Lang);
  const tag = (card as { tag?: TemplateTag }).tag || layoutToTag(card.layout);
  const pubLang: PubLang = pubLangOverride || "fr";
                                                                                    
                                                                                 
                                                                                       
  const isCarousel = Array.isArray(card.carouselSlides) && card.carouselSlides.length > 1;
  const effectiveSlideIndex = slideIndex ?? (isCarousel ? 0 : undefined);
  return renderSocialTemplate(tag, {
    title: card.title,
    supportText: (card as { supportText?: string }).supportText || card.subtitle,
    disruptivePhrase: (card as { disruptivePhrase?: string }).disruptivePhrase,
    imageSrc: card.imageSrc,
                                                                                            
                                                                                             
                                                                                             
                                                                                           
                                                                       
    carouselImages: isCarousel ? card.carouselSlides : undefined,
    bgColor: card.bg,
    format: card.format,
    pubLang,
    scale,
    slideIndex: effectiveSlideIndex,
                                                                                          
    imageTools,
    slotPositions: card.slotPositions,
                                                                                     
    asteriskImageSrc: card.asteriskImageSrc,
                                                                  
                                                                                                  
                                                                                              
                                                                                       
    elementOffsets: (typeof effectiveSlideIndex === "number" && effectiveSlideIndex > 0) ? undefined : card.elementOffsets,
                                                                                            
    textElementStyles: (typeof effectiveSlideIndex === "number" && effectiveSlideIndex > 0) ? undefined : (card as { textElementStyles?: Record<string, ElStyle> }).textElementStyles,
                                                                                                   
                                                                                              
                                                                                          
                                                                                          
    elementRich: (card.titleRich || card.supportRich)
      ? { ...(card.titleRich ? { title: card.titleRich } : {}), ...(card.supportRich ? { support: card.supportRich } : {}) }
      : undefined,
                                                                                               
                                                                                                   
                                                                                                     
    textOverrides: (typeof effectiveSlideIndex === "number" && effectiveSlideIndex > 0) ? undefined : rawCard.translations?.[(pubLangOverride || "fr") as Lang]?.textOverrides,
  });
}

                                                                                      
                                                                                     
                                                                               
function ImageRepositionOverlay({
  active,
  objectPosition,
  onChange,
  onDone,
  onCancel,
}: {
  active: boolean;
  objectPosition: string;
  onChange: (pos: string) => void;
  onDone: () => void;
  onCancel: () => void;
}) {
  const [isDragging, setIsDragging] = useState(false);
  const dragRef = useRef<{ startX: number; startY: number; startPosX: number; startPosY: number } | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const onChangeRef = useRef(onChange);
  useEffect(() => { onChangeRef.current = onChange; }, [onChange]);

  const parsePos = (pos: string): [number, number] => {
    const m = (pos || "50% 50%").match(/([\d.]+)%\s*([\d.]+)%/);
    return m ? [parseFloat(m[1]), parseFloat(m[2])] : [50, 50];
  };
  const [posX, posY] = parsePos(objectPosition);

                                                                  
  useEffect(() => {
    if (!isDragging) return;
    const onMove = (e: MouseEvent) => {
      if (!dragRef.current || !containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      const dx = e.clientX - dragRef.current.startX;
      const dy = e.clientY - dragRef.current.startY;
      const newX = Math.max(0, Math.min(100, dragRef.current.startPosX - (dx / rect.width) * 100));
      const newY = Math.max(0, Math.min(100, dragRef.current.startPosY - (dy / rect.height) * 100));
      onChangeRef.current(`${Math.round(newX)}% ${Math.round(newY)}%`);
    };
    const onUp = () => { dragRef.current = null; setIsDragging(false); };
    window.addEventListener("mousemove", onMove);
    window.addEventListener("mouseup", onUp);
    return () => {
      window.removeEventListener("mousemove", onMove);
      window.removeEventListener("mouseup", onUp);
    };
  }, [isDragging]);

  const handleMouseDown = (e: React.MouseEvent) => {
    e.preventDefault(); e.stopPropagation();
    dragRef.current = { startX: e.clientX, startY: e.clientY, startPosX: posX, startPosY: posY };
    setIsDragging(true);
  };
  const nudge = (dx: number, dy: number) => (e: React.MouseEvent) => {
    e.stopPropagation();
    onChange(`${Math.max(0, Math.min(100, Math.round(posX + dx)))}% ${Math.max(0, Math.min(100, Math.round(posY + dy)))}%`);
  };

  if (!active) return null;
  return (
    <div
      ref={containerRef}
      className="absolute inset-0 z-30 select-none"
      style={{ cursor: isDragging ? "grabbing" : "grab" }}
      onMouseDown={handleMouseDown}
    >
      {                       }
      <div className="absolute inset-0 pointer-events-none" style={{
        backgroundImage: "linear-gradient(rgba(255,255,255,0.1) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,0.1) 1px, transparent 1px)",
        backgroundSize: "33.33% 33.33%",
      }} />
      {                             }
      <div className="absolute pointer-events-none transition-all duration-75" style={{
        left: `${posX}%`, top: `${posY}%`, transform: "translate(-50%, -50%)",
        width: 20, height: 20, border: "2px solid #d2ff01", borderRadius: "50%",
        boxShadow: "0 0 0 1px rgba(0,0,0,0.6), 0 0 6px rgba(240,43,54,0.5)",
      }} />
      {                          }
      <div className="absolute top-2 left-2 bg-noir/75 text-rouge text-[10px] font-mono tracking-wide px-2 py-1 pointer-events-none">
        {Math.round(posX)}% · {Math.round(posY)}%
      </div>
      {                 }
      <div className="absolute top-2 right-2 bg-noir/75 text-white/50 text-[9px] font-mono tracking-wide px-2 py-1 pointer-events-none">
        Arrastar · ajustar
      </div>
      {                        }
      <div
        className="absolute bottom-2 left-1/2 -translate-x-1/2 flex items-center gap-1"
        onMouseDown={(e) => e.stopPropagation()}
      >
        {([["←", -10, 0, "Esquerda"], ["↑", 0, -10, "Cima"], ["↓", 0, 10, "Baixo"], ["→", 10, 0, "Direita"]] as [string, number, number, string][]).map(([lbl, dx, dy, title]) => (
          <button key={lbl} type="button" title={title} onClick={nudge(dx, dy)}
            className="w-7 h-7 bg-noir/80 text-white text-sm flex items-center justify-center hover:bg-rouge transition-colors backdrop-blur-sm">
            {lbl}
          </button>
        ))}
        <div className="w-px h-5 bg-white/20 mx-0.5" />
        <button type="button" title="Confirmar posição"
          onClick={(e) => { e.stopPropagation(); onDone(); }}
          className="h-7 px-3 bg-rouge text-white text-[10px] font-mono font-bold uppercase tracking-wider flex items-center gap-1 hover:bg-noir transition-colors">
          <IconCheck className="w-3 h-3" /> OK
        </button>
        <button type="button" title="Cancelar"
          onClick={(e) => { e.stopPropagation(); onCancel(); }}
          className="w-7 h-7 bg-noir/80 text-white/60 text-sm flex items-center justify-center hover:text-white transition-colors backdrop-blur-sm">
          </button>
      </div>
    </div>
  );
}

                                                                                         
                                                                                          
                                                                                          
                                                                                         
                                                                                             
                                                               
                                                                                                                   
function rgbToHex(c?: string): string {
  if (!c) return "#ffffff";
  const s = String(c).trim();
  if (s[0] === "#") return s.length === 7 ? s : "#ffffff";
  const m = s.match(/\d+/g);
  if (!m || m.length < 3) return "#ffffff";
  return "#" + m.slice(0, 3).map((n) => Math.max(0, Math.min(255, parseInt(n, 10))).toString(16).padStart(2, "0")).join("");
}
                                                                                                    
                                                                                                       
                                                                                                        
                                                                                                          
                                                                                                       
         
function sanitizeRichField(html: string): string | null {
  try {
    const doc = new DOMParser().parseFromString(`<div id="r">${html}</div>`, "text/html");
    const root = doc.getElementById("r");
    if (!root) return null;
    const walk = (el: Element) => {
      for (const child of Array.from(el.children)) {
        const tag = child.tagName.toLowerCase();
                                                                                           
                                                                                
        if (tag === "br") { child.replaceWith(doc.createElement("br")); continue; }
        if (tag === "b" || tag === "strong" || tag === "i" || tag === "em" || tag === "span" || tag === "font" || tag === "div" || tag === "p") {
          walk(child);
          if (tag === "div" || tag === "p") {
                                                                                            
            const brk = doc.createElement("br");
            if (child.previousSibling) child.parentNode?.insertBefore(brk, child);
            while (child.firstChild) child.parentNode?.insertBefore(child.firstChild, child);
            child.remove();
            continue;
          }
          const keep = doc.createElement(tag === "font" ? "span" : tag);
          const styleAttr = (child.getAttribute("style") || "");
          const colorM = /(?:^|;)\s*color\s*:\s*([^;]+)/i.exec(styleAttr);
          const legacyColor = (child as HTMLElement).getAttribute("color");
                                                                                                 
                                                                                                
          const weightM = /font-weight\s*:\s*(bold(?:er)?|[1-9]00|normal|lighter)/i.exec(styleAttr);
          const styleM = /font-style\s*:\s*(italic|normal)/i.exec(styleAttr);
          const parts: string[] = [];
          const cor = (colorM && colorM[1].trim()) || (legacyColor ? legacyColor.trim() : "");
          if (cor) { parts.push(`color:${cor}`); keep.setAttribute("data-abil-richcolor", "1"); }
          if (weightM) { const w = weightM[1].toLowerCase(); const heavy = w.startsWith("bold") || /^[6-9]00$/.test(w); parts.push(`font-weight:${heavy ? 800 : 400}`); }
          if (styleM) parts.push(`font-style:${styleM[1].toLowerCase()}`);
          if (parts.length) keep.setAttribute("style", parts.join(";"));
          while (child.firstChild) keep.appendChild(child.firstChild);
          child.replaceWith(keep);
          continue;
        }
                                                               
        walk(child);
        while (child.firstChild) child.parentNode?.insertBefore(child.firstChild, child);
        child.remove();
      }
    };
    walk(root);
    const out = root.innerHTML.trim();
                                                                               
    if (!/<(b|strong|i|em|span)\b/i.test(out)) return null;
    return out;
  } catch { return null; }
}
                                                                                                     
                                                                                                   
                                                                                               
                                                                                                      
                                                                                           
                                                                                                  
                                                                  
