      const els = Array.from(h.querySelectorAll<HTMLElement>("[data-abil-photo]"));
      const next = els
        .map((el) => {
          const r = el.getBoundingClientRect();
                                                                                                 
                                                                                                          
          return { idx: el.getAttribute("data-abil-photo") || "", left: r.left - wrap.left, top: r.top - wrap.top, width: r.width, height: r.height, ow: el.offsetWidth, oh: el.offsetHeight };
        })
        .filter((r) => r.width > 28 && r.height > 28);
      setSlots((prev) => (prev.length === next.length && prev.every((p, i) => p.idx === next[i].idx && p.left === next[i].left && p.top === next[i].top && p.width === next[i].width && p.height === next[i].height) ? prev : next));
                                                                                                            
      const elNodes = Array.from(h.querySelectorAll<HTMLElement>("[data-abil-el]"));
      const elNext = elNodes
