      if (!moved && (Math.abs(ev.clientX - d.startX) > 4 || Math.abs(ev.clientY - d.startY) > 4)) moved = true;
      if (!moved) return;
      const dx = d.startDx + ((ev.clientX - d.startX) / d.hostW) * 100;
      const dy = d.startDy + ((ev.clientY - d.startY) / d.hostW) * 100;
