function SocialConnectBar({ lang }: { lang: Lang }) {
  const [data, setData] = useState<IntegrationStatusPayload | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const ct = SOCIAL_CONNECT_I18N[lang] || SOCIAL_CONNECT_I18N.fr;
  const loadStatus = useCallback(async () => {
    setLoading(true);
    setError("");
    try {
      const res = await fetch("/api/integration-status", { headers: getAIHeaders(), cache: "no-store" });
      const payload = await res.json().catch(() => null);
      if (!res.ok) {
        const code = payload?.error || `http_${res.status}`;
        throw new Error(code === "unauthorized" ? "vault_locked" : code);
      }
      setData(payload as IntegrationStatusPayload);
    } catch (err: any) {
      setData(null);
      setError(String(err?.message || err || "status_unavailable"));
    } finally {
      setLoading(false);
    }
  }, []);
  useEffect(() => {
    const timer = window.setTimeout(() => { void loadStatus(); }, 0);
    return () => window.clearTimeout(timer);
  }, [loadStatus]);

                                                                                    
                                                   
  const start = () => { window.open(window.location.origin + "/admin", "_blank", "noopener,noreferrer"); };
  const groups = (data?.groups || []).filter((group) => group.id === "meta" || group.id === "linkedin");
  const statusClass = (status: IntegrationStatusKind) => (
    status === "ready"
      ? "border-emerald-300 text-emerald-700 bg-emerald-50"
      : status === "partial"
        ? "border-amber-300 text-amber-700 bg-amber-50"
        : "border-rouge/40 text-rouge bg-white"
  );
  return (
    <div className="border border-neutral-200 bg-neutral-50/70 p-3 mb-4">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div className="flex items-center gap-2 flex-wrap">
          <span className="eyebrow eyebrow-xs text-neutral-500">{ct.networksLabel}</span>
          {loading ? (
            <span className="text-xs text-neutral-400">...</span>
          ) : error ? (
            <span className="text-xs text-rouge inline-flex items-center gap-2">
              {error === "vault_locked" ? ct.vaultLocked : `${ct.statusUnavailable}: ${error}`}
              {/* Keep the unlock action next to the warning because saving and restoring
                  models requires an unlocked vault. */}
              {error === "vault_locked" && (
                <button
                  type="button"
                  onClick={async () => {
                    const pw = window.prompt(ct.unlockPrompt || "Senha do cofre de superadmin:");
                    if (!pw) return;
                    const r = await abilVaultLogin(pw);
                    if (r.ok) { window.dispatchEvent(new Event("abil:vault")); window.location.reload(); }
                    else window.alert(ct.unlockFail || "Senha incorreta.");
                  }}
                  className="border border-rouge/50 text-rouge px-2 py-0.5 font-mono text-[9px] uppercase tracking-[0.14em] hover:bg-rouge hover:text-white transition-colors"
                >
                  {ct.unlockBtn || "Destrancar"}
                </button>
              )}
            </span>
          ) : groups.length === 0 ? (
            <span className="text-xs text-neutral-400">{ct.noneYet}</span>
          ) : groups.map((group) => (
            <span key={group.id} title={group.action} className={`inline-flex items-center gap-1.5 text-xs border px-2 py-1 ${statusClass(group.status)}`}>
              {group.status === "ready" ? <IconCheck className="w-3.5 h-3.5" /> : <IconAlertTriangle className="w-3.5 h-3.5" />}
              <span className="font-semibold">{group.label}</span>
              <span className="font-mono uppercase tracking-[0.14em] text-[9px]">{ct[group.status] || group.status}</span>
            </span>
          ))}
        </div>
        <div className="flex items-center gap-2">
          <button onClick={() => void loadStatus()} type="button" className="border border-neutral-300 px-3 py-2 eyebrow text-neutral-500 hover:border-rouge hover:text-rouge transition-colors">
            {ct.refresh}
          </button>
          <button onClick={start} type="button" className="bg-rouge text-white px-4 py-2.5 eyebrow hover:bg-noir transition-colors flex items-center gap-2">
            <IconLink className="w-4 h-4" /> {ct.connectBtn}
          </button>
        </div>
      </div>
      <p className="text-[10px] text-neutral-400 mt-2 leading-snug">{ct.hubHint}</p>
    </div>
  );
}

                                                                              
