  type TemplateOverride = { byLang?: Record<string, { title?: string; support?: string; disruptive?: string }>; imageSrc?: string; carouselSlides?: string[]; bg?: SocialCard["bg"]; slotPositions?: Record<number, string>; asteriskImageSrc?: string; elementOffsets?: Record<string, { dx: number; dy: number }>; textElementStyles?: Record<string, ElStyle> };
  const [templateOverrides, setTemplateOverrides] = useCloudState<Record<string, TemplateOverride>>("abil_social_template_overrides_v1", {});
  const [editingTemplateTag, setEditingTemplateTag] = useState<TemplateTag | null>(null);
                                                                                         
                                                                                           
                                                                                                   
