  const setAsteriskImageFromFile = async (cardId: string, f: File) => {
    const reader = new FileReader();
    const base64 = await new Promise<string>((res) => { reader.onload = () => res(String(reader.result || "")); reader.readAsDataURL(f); });
    if (!base64) return;
    let url = base64;
    try { if (abilVaultUnlocked()) { const { cloudUploadFile } = await import("@/lib/cloudProjects"); const up = await cloudUploadFile(f, { prefix: "social" }); if (up.ok && up.url) url = up.url; } } catch {                     }
    updateCard(cardId, { asteriskImageSrc: url });
    if (editingCard?.id === cardId) setEditingCard((prev) => (prev ? { ...prev, asteriskImageSrc: url } : prev));
    showToast("" + LS("asteriskSwapped"));
  };

  const handleSetSlotImageUrl = (cardId: string, targetIdx: number, url: string) => {
    if (!url) return;
    const card = cardInEdit(cardId);
    if (!card) return;
                                                                                          
    if (targetIdx === -2) {
      updateCard(cardId, { asteriskImageSrc: url });
      if (editingCard?.id === cardId) setEditingCard((prev) => (prev ? { ...prev, asteriskImageSrc: url } : prev));
      showToast("" + LS("asteriskSwapped"));
      return;
    }
    let patch: Partial<SocialCard>;
    if (targetIdx >= 0 && Array.isArray(card.carouselSlides) && card.carouselSlides.length > 0) {
      const slides = [...card.carouselSlides];
      if (targetIdx >= slides.length) return;
      slides[targetIdx] = url;
      patch = { carouselSlides: slides, imageSrc: slides[0] };
    } else {
      patch = { imageSrc: url, isAIGenerated: false, isManualUpload: true };
      if (!url.startsWith("data:") && !url.startsWith("blob:") && !card.sourceId) patch.sourceId = `manual-${cardId}`;
    }
    updateCard(cardId, patch);
    if (editingCard?.id === cardId) setEditingCard({ ...editingCard, ...patch });
    showToast(targetIdx >= 0 ? `${LS("slideSwapped").replace("{n}", String(targetIdx + 1))}` : "" + LS("photoSwapped"));
  };

                                                            
