  const [translatingCard, setTranslatingCard] = useState(false);
  const handleTranslateCard = async () => {
    if (!editingCard) return;
    setTranslatingCard(true);
    try {
      const src = (editingCard.sourceLang || lang) as Lang;
      const fields = ["title", "subtitle", "supportText", "disruptivePhrase", "caption"] as const;
      const translations: Partial<Record<Lang, Record<string, string>>> = {};
      for (const f of fields) {
        const val = (editingCard as Record<string, unknown>)[f];
        if (!val || !String(val).trim()) continue;
        const all = await autoTranslateAllLangs(String(val), src);
        (Object.keys(all) as Lang[]).forEach((L) => {
          if (!translations[L]) translations[L] = {};
          translations[L]![f] = all[L];
        });
      }
                                                                                                 
                                                                                                 
                                                                                     
      const withRich = { ...translations } as NonNullable<SocialCard["translations"]>;
      (Object.keys(editingCard.translations || {}) as Lang[]).forEach((L) => {
        const prev = editingCard.translations?.[L];
        if (!prev) return;
        const keep: { titleRich?: string; supportRich?: string } = {};
        if (prev.titleRich) keep.titleRich = prev.titleRich;
        if (prev.supportRich) keep.supportRich = prev.supportRich;
        if (Object.keys(keep).length) withRich[L] = { ...(withRich[L] || {}), ...keep };
      });
      const patch: Partial<SocialCard> = { sourceLang: src, translations: withRich };
      updateCard(editingCard.id, patch);
      setEditingCard({ ...editingCard, ...patch });
      showToast(TRANSLATE_CARD_I18N[lang].done);
    } catch (e) {
      showToast("" + String((e as Error).message).slice(0, 80));
    } finally {
      setTranslatingCard(false);
    }
  };

  const handleGenerateAIImage = async (cardId: string, userPrompt?: string) => {
    const card = cardInEdit(cardId);
    if (!card) return;
    setAiGenLoadingId(cardId);
    try {
      const prompt = (userPrompt && userPrompt.trim())
        ? userPrompt.trim()
        : [
            `Editorial photography for a creative agency social media post.`,
            `Topic: ${card.title}`,
            card.supportText ? `Context: ${card.supportText}` : "",
            `Style: modern, sophisticated, minimalist, brand-aligned with ABiL (Swiss creative atelier).`,
            `Composition: editorial, clean, elegant, COLORFUL (never grayscale).`,
            `Square 1:1 format, no text overlay, professional photography aesthetic.`,
          ].filter(Boolean).join(" ");
      const resp = await fetch("/api/generate-image", {
        method: "POST",
        headers: getAIHeaders(),
        body: JSON.stringify({ prompt, size: "1024x1024", context: `Social ${card.platform} post, ${card.title}. ${personaImageContext()}` }),
      });
      const data = await resp.json();
      let img = data.url || data.dataUrl;
      if (!resp.ok || !img) {
        throw new Error(data.error || `HTTP ${resp.status}`);
      }
                                                                                 
                                                                                  
                                                                                      
      img = await compressDataUrl(img);
      const patch: Partial<SocialCard> = {
        imageSrc: img,
        isAIGenerated: true,
      };
      updateCard(cardId, patch);
      if (editingCard?.id === cardId) setEditingCard({ ...editingCard, ...patch });
      showToast(tn("imageIAGenerated"));
    } catch (e) {
      console.error("[AI image gen] failed:", e);
      showToast(`${LS("iaFailed")}: ${String((e as Error).message).slice(0, 80)}`);
    } finally {
      setAiGenLoadingId(null);
    }
  };

                                                                      
