  const addDaysISO = (iso: string, days: number) => { const d = new Date(iso + "T12:00:00"); d.setDate(d.getDate() + days); return d.toISOString().slice(0, 10); };
                                                                                         
                                                                                          
  const computeNextBatchDate = (tag: TemplateTag): string => {
    const today = new Date().toISOString().slice(0, 10);
    const dated = allCards.filter((c) => c.date && c.status !== "draft");
    if (!dated.length) return today;
    const maxDate = dated.reduce((m, c) => (c.date > m ? c.date : m), dated[0].date);
    let candidate = maxDate >= today ? addDaysISO(maxDate, 1) : today;
    if (dated.some((c) => c.date === maxDate && c.tag === tag)) candidate = addDaysISO(candidate, 1);
    return candidate;
  };
                                                                                            
