const TEAM_AUTHOR_PREFIX = "tm-auth-";
const normAuthorName = (v: string) =>
  (v || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-z]/g, "");
   
                                          
  
                                                                      
                                                                               
                                                                              
                                                                            
                                                                        
                                                                            
                                    
  
                                                          
                                                                   
                                                                           
                                                             
  
                                                                                
                                                                              
                  
   
function teamAsAuthors(team: DashTeamMember[], base: Author[]): Author[] {
  const naBase = new Set(base.map((a) => normAuthorName(a.name)));
  const vistos = new Set<string>();
  const out: Author[] = [];
  (team || []).forEach((mb) => {
    const key = normAuthorName(mb.name);
    if (!key || vistos.has(key)) return;
    vistos.add(key);
                                                                          
    if (naBase.has(key)) return;
    out.push({ id: TEAM_AUTHOR_PREFIX + mb.id, name: mb.name, email: "", bio: "",
               role: mb.role || "", avatar: mb.photo || "", active: true });
  });
  return out;
}

                                                                         
                                                                 
function fundirEquipaNosAutores(base: Author[], team: DashTeamMember[]): Author[] {
  const porNome = new Map((team || []).map((mb) => [normAuthorName(mb.name), mb]));
  return base.map((a) => {
    const mb = porNome.get(normAuthorName(a.name));
    if (!mb) return a;
    return { ...a, avatar: a.avatar || mb.photo || "", role: a.role || mb.role || "" };
  });
}

const BLOG_EDITORIAL_PROMPT_LS_KEY = "abil_blog_editorial_prompt_v1";
                                                                             
                                                                                  
const LEGACY_BLOG_EDITORIAL_PROMPT_1000 = `Todo texto gerado deve ter no minimo 1000 palavras sobre o tema indicado, com foco em marketing 360, publicidade, branding, social media e producao de conteudo audiovisual, incluindo formatos verticais e horizontais.

O texto deve ser claro, estrategico e compreensivel tanto para profissionais iniciantes quanto para perfis mais experientes, como gestores de marketing e CMOs.

Requisitos principais:
SEO: usar palavras-chave de cauda longa de forma natural.
AEO: incluir respostas diretas para perguntas comuns do publico.
GEO: usar vocabulario rico, referencias a autores, marcas, tendencias e contextos historicos do marketing.
Estrutura: titulo com no maximo 65 caracteres, subtitulos em sentence case, palavra-chave principal no primeiro paragrafo, em um H2 e repetida naturalmente.
Incluir FAQ final e bloco tecnico com Main keyword, 5 tags, Title tag, AEO summary, Meta description e URL slug sem acentos.
Evitar travessoes, cliches, frases genericas com cara de IA, promessas exageradas e linguagem comercial demais.`;
const DEFAULT_BLOG_EDITORIAL_PROMPT = `Todo texto gerado deve ter no minimo 2200 palavras sobre o tema indicado, com foco em marketing 360, publicidade, branding, social media e producao de conteudo audiovisual, incluindo formatos verticais e horizontais.

O texto deve ser claro, estrategico e compreensivel tanto para profissionais iniciantes quanto para perfis mais experientes, como gestores de marketing e CMOs.

Requisitos principais:
SEO: usar palavras-chave de cauda longa de forma natural.
AEO: incluir respostas diretas para perguntas comuns do publico.
GEO: usar vocabulario rico, referencias a autores, marcas, tendencias e contextos historicos do marketing.
Estrutura: titulo com no maximo 65 caracteres, subtitulos em sentence case, palavra-chave principal no primeiro paragrafo, em um H2 e repetida naturalmente.
Incluir FAQ final e bloco tecnico com Main keyword, 5 tags, Title tag, AEO summary, Meta description e URL slug sem acentos.
Imagens: as 4 imagens do corpo sao FOTOGRAFIAS REAIS (Pexels), nao ilustracoes; escreve pensando em fotos editoriais plausiveis.
Evitar travessoes, cliches, frases genericas com cara de IA, promessas exageradas e linguagem comercial demais.`;

function getBlogEditorialPrompt(): string {
  try {
    const saved = typeof localStorage !== "undefined" ? localStorage.getItem(BLOG_EDITORIAL_PROMPT_LS_KEY) : null;
    if (!saved || !saved.trim()) return DEFAULT_BLOG_EDITORIAL_PROMPT;
                                                                                                         
                                                                                                        
    let v = saved;
    if (v.startsWith('"')) { try { const p = JSON.parse(v); if (typeof p === "string") v = p; } catch {                                } }
    if (v.trim() === LEGACY_BLOG_EDITORIAL_PROMPT_1000.trim()) return DEFAULT_BLOG_EDITORIAL_PROMPT;                              
    return v.trim().length > 0 ? v : DEFAULT_BLOG_EDITORIAL_PROMPT;
  } catch {
    return DEFAULT_BLOG_EDITORIAL_PROMPT;
  }
}

function blogImageSlug(theme: string): string {
  return (theme || "blog").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 60) || "blog";
}

function blogAIUnavailableMessage(error?: unknown): string {
  const detail = error instanceof Error && error.message ? ` (${error.message.slice(0, 90)})` : "";
  return `IA indisponivel: nada foi publicado com fallback local. Verifica chave/credito e tenta de novo.${detail}`;
}

function stockImageUnavailableMessage(error?: unknown): string {
  const detail = error instanceof Error && error.message ? ` (${error.message.slice(0, 90)})` : "";
  return `Imagem real indisponivel: nenhum fallback local foi usado. Configura Pexels/Unsplash e tenta de novo.${detail}`;
}

                                                                                          
                                                                                         
                                                                                          
                                                                                        
                                                                                      
                                                                                      
                                                                
const techBlockLabelRe = (names: string) =>
  new RegExp(`^\\s*(?:[-*\\u2022]\\s*)?(?:\\*\\*|#{1,6}\\s+)?\\s*(?:${names})\\s*\\**\\s*[:\\uFF1A]\\s*(.*?)\\s*$`, "i");
const TECH_BLOCK_LABELS: { key: string; re: RegExp }[] = [
  { key: "mainKeyword", re: techBlockLabelRe("main\\s+keyword|palavra[\\s-]chave\\s+principal|mot[\\s-]cl[e\\u00e9]\\s+principal|haupt[\\s-]?keyword|parola\\s+chiave\\s+principale") },
  { key: "tags", re: techBlockLabelRe("(?:5\\s+)?tags?(?:\\s*\\(5\\))?|etiquetas|mots[\\s-]cl[e\\u00e9]s") },
  { key: "titleTag", re: techBlockLabelRe("title\\s*[\\s-]?tag|balise\\s+title|tag\\s+de\\s+t[i\\u00ed]tulo|titolo\\s+seo|seo[\\s-]titel") },
  { key: "aeoSummary", re: techBlockLabelRe("aeo\\s+summary|resumo\\s+aeo|sum[a\\u00e1]rio\\s+aeo|r[e\\u00e9]sum[e\\u00e9]\\s+aeo|aeo[\\s-]zusammenfassung|riassunto\\s+aeo") },
  { key: "metaDescription", re: techBlockLabelRe("m[e\\u00e9]ta[\\s-]?descri(?:ption|[c\\u00e7][a\\u00e3]o|zione)|meta[\\s-]?beschreibung") },
  { key: "urlSlug", re: techBlockLabelRe("url[\\s-]?slug|slug\\s+(?:de\\s+|d['e]\\s*)?url|slug") },
];
const TECH_BLOCK_HEADING_RE = /^\s*(?:#{1,6}\s+|\*\*)?\s*(?:bloco\s+t[eé]cnico|bloc\s+technique|technical\s+block|blocco\s+tecnico|technische[rs]?\s+block|seo\s*[/·-]?\s*aeo(?:\s*[/·-]?\s*geo)?)\s*\**\s*:?\s*$/i;
const TECH_BLOCK_RULE_RE = /^\s*[-_*]{3,}\s*$/;
function parseTechnicalSeoBlock(body: string): { seoTitle?: string; seoDescription?: string; cleanedBody?: string } | null {
  const lines = body.split("\n");
  type Hit = { line: number; key: string; value: string };
  const hits: Hit[] = [];
  for (let i = 0; i < lines.length; i++) {
    for (const { key, re } of TECH_BLOCK_LABELS) {
      const m = lines[i].match(re);
      if (m) { hits.push({ line: i, key, value: (m[1] || "").replace(/^\*+\s*/, "").replace(/\s*\*+$/, "").trim() }); break; }
    }
  }
  if (new Set(hits.map((h) => h.key)).size < 2) return null;
  const valueOf = (key: string) => hits.find((h) => h.key === key && h.value)?.value;
  const out: { seoTitle?: string; seoDescription?: string; cleanedBody?: string } = {
    seoTitle: valueOf("titleTag"),
    seoDescription: valueOf("metaDescription"),
  };
                                                                                           
                                                                                       
  const hitLines = new Set(hits.map((h) => h.line));
  for (const start of hits.map((h) => h.line)) {
    let ok = true;
    const regionKeys = new Set<string>();
    for (let i = start; i < lines.length; i++) {
      const ln = lines[i];
      if (hitLines.has(i)) { regionKeys.add(hits.find((h) => h.line === i)!.key); continue; }
      if (!ln.trim()) continue;
      if (TECH_BLOCK_HEADING_RE.test(ln) || TECH_BLOCK_RULE_RE.test(ln)) continue;
                                                                                                 
      if (/^\s*[-*•]\s+\S/.test(ln) && i > start) continue;
      ok = false; break;
    }
    if (!ok || regionKeys.size < 2) continue;
                                                                                        
    let cut = start;
    while (cut > 0 && (!lines[cut - 1].trim() || TECH_BLOCK_RULE_RE.test(lines[cut - 1]) || TECH_BLOCK_HEADING_RE.test(lines[cut - 1]))) cut--;
    const cleaned = lines.slice(0, cut).join("\n").replace(/\s+$/, "");
    if (cut > 0 && cleaned.trim()) { out.cleanedBody = cleaned; break; }
  }
  if (!out.seoTitle && !out.seoDescription && out.cleanedBody == null) return null;
  return out;
}
function applyTechnicalSeoBlock(draft: BlogDraft): BlogDraft {
  const parsed = parseTechnicalSeoBlock(draft.body || "");
  if (!parsed) return draft;
  const next: BlogDraft = { ...draft };
  if (parsed.seoTitle && !(next.seoTitle || "").trim()) next.seoTitle = parsed.seoTitle;
  if (parsed.seoDescription && !(next.seoDescription || "").trim()) next.seoDescription = parsed.seoDescription;
  if (parsed.cleanedBody != null) next.body = parsed.cleanedBody;
  return next;
}

async function persistBlogGeneratedImage(dataUrl: string, filename: string): Promise<string | null> {
  if (!dataUrl.startsWith("data:image")) return dataUrl;
  try {
    const { cloudUploadFile, dataUrlToFile } = await import("@/lib/cloudProjects");
    const file = dataUrlToFile(dataUrl, filename);
    if (!file) return null;
    const upload = await cloudUploadFile(file, { prefix: "assets", filename });
    return upload.ok && upload.url ? upload.url : null;
  } catch {
    return null;
  }
}

async function aiGenerateBlogIllustrations(theme: string): Promise<{ cover: string; gallery: string[] }> {
  if (typeof fetch === "undefined") throw new Error("fetch indisponivel para gerar imagens");
  const topic = theme.trim().slice(0, 320) || "creative strategy";
  const slug = blogImageSlug(topic);
  const personaCtx = getAIPersonaContext();
  const results = await Promise.all([0, 1, 2, 3].map(async (i) => {
    try {
      const prompt = [
        `Editorial illustrative image ${i + 1} of 4 for a long-form ABiL blog article.`,
        `Article topic: ${topic}.`,
        `Create a premium 16:9 landscape image aligned with the dashboard design system, photography direction and site image prompt.`,
        `The image must support the article visually without text, logos, UI, watermarks or generic stock-photo cliches.`,
      ].join(" ");
      const resp = await fetch("/api/generate-image", {
        method: "POST",
        headers: getAIHeaders(),
        body: JSON.stringify({
          prompt,
          size: "1536x1024",
          quality: "medium",
          context: `Blog article illustration ${i + 1}/4 - ${topic}`,
          ...personaCtx,
        }),
      });
      const data = await resp.json().catch(() => ({})) as { dataUrl?: string; url?: string };
      const image = data.url || data.dataUrl || "";
      if (!resp.ok || !image) return null;
      const persisted = await persistBlogGeneratedImage(image, `${slug}-blog-illustration-${i + 1}.png`);
      return persisted;
    } catch {
                                                                                                      
      return null;
    }
  }));
  const generated = results.filter((url): url is string => !!url).filter((url, idx, arr) => arr.indexOf(url) === idx);
  if (generated.length < 4) throw new Error("4 imagens IA obrigatorias nao foram geradas");
  return { cover: generated[0], gallery: generated.slice(0, 4) };
}

                                                                                  
                                                                               
                                                                                     
async function aiBlogContentRich(theme: string, tone: string, keywords: string[], lang: Lang): Promise<{ title: string; excerpt: string; body: string; cover: string; images: string[]; imageCredits?: { credit?: string; creditUrl?: string; source?: string }[] }> {
  const kwLine = keywords.length > 0 ? ` Palavras-chave a integrar: ${keywords.join(", ")}.` : "";
  const editorialPrompt = getBlogEditorialPrompt();
  const raw = await aiGenerateText({
    userPrompt: `Escreve um artigo de blog completo e original para o atelier criativo ABiL sobre o tema: "${theme}". Tom editorial: ${tone}.${kwLine}

Este prompt e complementar. Usa obrigatoriamente tambem a brand persona, buyer personas, tom de voz, agente de IA, design system, direcao de fotografia e prompt de imagem do site enviados no contexto do dashboard.

Prompt editorial complementar configurado pelo superadmin:
${editorialPrompt}

O artigo precisa prever 4 imagens ilustrativas alinhadas ao design system e direcao de fotografia do site. No CORPO, posiciona obrigatoriamente os marcadores [[IMG:0]], [[IMG:1]], [[IMG:2]] e [[IMG:3]] em quatro pontos naturais do texto.

Devolve EXACTAMENTE neste formato:
TÍTULO: <título com no máximo 65 caracteres>
RESUMO: <2 frases de resumo>
CORPO:
<artigo completo com no minimo 2200 palavras, FAQ final e bloco tecnico final>`,
    maxLength: 32000,
    path: "blog.article",
    lang,
  });
  if (!raw) throw new Error("texto IA indisponivel");
                                                                                 
                                                                             
                                                                               
  const fotosReais: { url: string; credit?: string; creditUrl?: string; source?: string }[] = [];
  for (let slot = 0; slot < 4; slot += 1) {
    const foto = await fetchStockPhoto(blogStockQuery(theme, "", slot));
    if (foto) fotosReais.push(foto);
  }
  const blogImages = fotosReais.length >= 2
    ? { cover: fotosReais[0].url, gallery: fotosReais.slice(1).map((p) => p.url) }
    : { cover: "", gallery: [] };
  const imageCredits = fotosReais.length >= 2 ? fotosReais.map((p) => ({ credit: p.credit, creditUrl: p.creditUrl, source: p.source })) : undefined;
  const tMatch = raw.match(/T[ÍI]TULO:\s*(.+?)(?:\n|$)/i);
  const rMatch = raw.match(/RESUMO:\s*(.+?)(?:\n|$)/i);
  const bMatch = raw.match(/CORPO:?\s*\n?([\s\S]*)/i);
  return {
    title: (tMatch ? tMatch[1].trim() : theme.trim()).slice(0, 65),
    excerpt: rMatch ? rMatch[1].trim() : "",
    body: bMatch ? bMatch[1].trim() : raw,
    cover: blogImages.cover,
    images: blogImages.gallery,
    imageCredits,
  };
}

   
                                          
                                                                  
                                                                      
                                                                
   
function RichBodyRenderer({ body, images, className = "" }: { body: string; images?: string[]; className?: string }) {
  if (!body) return null;

                                                        
  const parts: { type: "text" | "image"; content: string; imgIdx?: number }[] = [];
  const regex = /\[\[IMG:(\d+)\]\]/g;
  let lastIndex = 0;
  let match;
  while ((match = regex.exec(body)) !== null) {
    if (match.index > lastIndex) {
      parts.push({ type: "text", content: body.slice(lastIndex, match.index) });
    }
    parts.push({ type: "image", content: "", imgIdx: Number(match[1]) });
    lastIndex = regex.lastIndex;
  }
  if (lastIndex < body.length) {
    parts.push({ type: "text", content: body.slice(lastIndex) });
  }

                                                                                    
  const hasMarkers = parts.some(p => p.type === "image");

  return (
    <div className={className}>
      {parts.map((p, i) => {
        if (p.type === "text") {
          const trimmed = p.content.replace(/^\n+|\n+$/g, "");
          if (!trimmed) return null;
          return (
            <pre key={i} className="whitespace-pre-wrap font-sans text-inherit leading-relaxed mb-4 last:mb-0">
              {trimmed}
            </pre>
          );
        }
                       
        const url = images?.[p.imgIdx!];
        if (!url) return null;
        return (
          <figure key={i} className="my-8 -mx-1">
            <img
              src={url}
              alt={`Illustration ${(p.imgIdx ?? 0) + 1}`}
              className="w-full aspect-[16/9] object-cover"
            />
          </figure>
        );
      })}
      {                                                                                                       }
      {!hasMarkers && images && images.length > 0 && (
        <div className="grid grid-cols-4 gap-2 my-4">
          {images.map((url, i) => (
            <img key={i} src={url} alt={`Illustration ${i+1}`} className="aspect-[3/2] object-cover w-full" />
          ))}
        </div>
      )}
    </div>
  );
}

                                                                                                     
                                                                                                       
                                                                                                       
                                                                                                   
