function IntegrationReadinessPanel() {
  const { lang } = useApp();
  const copy = (o: Record<string, string>) => _trO(o, lang);
  const [data, setData] = useState<IntegrationStatusPayload | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  const loadStatus = useCallback(async () => {
    setLoading(true);
    setError("");
    try {
      const res = await fetch("/api/integration-status", { headers: getAIHeaders(), cache: "no-store" });
      const payload = await res.json().catch(() => null);
      if (!res.ok) {
        const code = payload?.error || `http_${res.status}`;
        throw new Error(code === "unauthorized" ? "vault_locked" : code);
      }
      setData(payload as IntegrationStatusPayload);
    } catch (err: any) {
      setData(null);
      setError(String(err?.message || err || "status_unavailable"));
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    const timer = window.setTimeout(() => { void loadStatus(); }, 0);
    return () => window.clearTimeout(timer);
  }, [loadStatus]);

  const statusLabel = (status: IntegrationStatusKind) => (
    status === "ready"
      ? copy({ pt: "pronto", en: "ready", fr: "pret", de: "bereit", it: "pronto" })
      : status === "partial"
        ? copy({ pt: "parcial", en: "partial", fr: "partiel", de: "teilweise", it: "parziale" })
        : copy({ pt: "bloqueado", en: "blocked", fr: "bloque", de: "blockiert", it: "bloccato" })
  );
  const statusClass = (status: IntegrationStatusKind) => (
    status === "ready"
      ? "border-emerald-500 bg-emerald-50 text-emerald-700"
      : status === "partial"
        ? "border-amber-400 bg-amber-50 text-amber-700"
        : "border-rouge bg-rouge/5 text-rouge"
  );

  return (
    <div className="bg-white border border-neutral-200">
      <div className="px-6 py-4 border-b border-neutral-200 flex items-start justify-between gap-4">
        <div>
          <div className="eyebrow text-rouge mb-1">// {copy({ pt: "Integrações e chaves de API", en: "Integrations and API keys", fr: "Intégrations et clés API", de: "Integrationen und API-Schlüssel", it: "Integrazioni e chiavi API" })}</div>
          <h3 className="font-semibold text-xl mt-0.5 text-noir">
            {data ? `${data.summary.ready}/${data.summary.total}` : loading ? "..." : "0/0"} <span className="text-sm font-normal text-neutral-400">{copy({ pt: "grupos prontos para operacao externa", en: "groups ready for external operation", fr: "groupes prets pour operation externe", de: "Gruppen bereit fuer externe Ausfuehrung", it: "gruppi pronti per operazioni esterne" })}</span>
          </h3>
          <p className="mt-2 text-sm text-neutral-500 max-w-3xl">{copy({ pt: "Cada integração do sistema num lugar só. As chaves vivem nas variáveis de ambiente do Vercel (no servidor, seguras), não no navegador. O selo mostra o que já está configurado.", en: "Every system integration in one place. Keys live in the Vercel environment variables (on the server, secure), not in the browser. The chip shows what is configured.", fr: "Chaque intégration au même endroit. Les clés vivent dans les variables d'environnement Vercel (serveur, sécurisées), pas dans le navigateur. Le badge montre ce qui est configuré.", de: "Jede Integration an einem Ort. Die Schlüssel leben in den Vercel-Umgebungsvariablen (Server, sicher), nicht im Browser. Das Abzeichen zeigt, was konfiguriert ist.", it: "Ogni integrazione in un posto solo. Le chiavi vivono nelle variabili d'ambiente Vercel (server, sicure), non nel browser. Il chip mostra cosa è configurato." })}</p>
        </div>
        <button onClick={() => void loadStatus()} className="shrink-0 border border-neutral-300 px-3 py-1.5 eyebrow text-neutral-500 hover:border-rouge hover:text-rouge transition-colors">{copy({ pt: "Atualizar", en: "Refresh", fr: "Actualiser", de: "Aktualisieren", it: "Aggiorna" })}</button>
      </div>
      {loading ? (
        <div className="px-6 py-5 text-sm text-neutral-400">{copy({ pt: "A verificar ambiente seguro...", en: "Checking secure environment...", fr: "Verification de l'environnement...", de: "Sichere Umgebung wird geprueft...", it: "Verifica ambiente sicuro..." })}</div>
      ) : error ? (
        <div className="px-6 py-5 text-sm text-rouge">
          {error === "vault_locked"
            ? copy({ pt: "Destranca o cofre de superadmin para ver o estado real das integracoes.", en: "Unlock the superadmin vault to see real integration status.", fr: "Deverrouille le coffre superadmin pour voir l'etat reel.", de: "Entsperre den Superadmin-Tresor fuer den echten Status.", it: "Sblocca il vault superadmin per vedere lo stato reale." })
            : copy({ pt: `Estado indisponivel: ${error}`, en: `Status unavailable: ${error}`, fr: `Etat indisponible: ${error}`, de: `Status nicht verfuegbar: ${error}`, it: `Stato non disponibile: ${error}` })}
        </div>
      ) : (
        <div className="grid grid-cols-1 xl:grid-cols-2 gap-4 p-4">
          {(data?.groups || []).map((group) => {
            const missing = group.checks.filter((checkItem) => checkItem.required && !checkItem.configured);
            const cfg = INTEGRATION_BOX[group.id];
            const boxLabel = cfg ? copy(cfg.label) : group.label;
            const boxDesc = cfg ? copy(cfg.desc) : group.action;
            return (
              <div key={group.id} className="border border-neutral-200 bg-neutral-50/60 p-4 flex flex-col">
                <div className="flex items-start justify-between gap-3">
                  <div>
                    <div className="font-semibold text-noir">{boxLabel}</div>
                    <div className="mt-1 text-xs text-neutral-500">{missing.length ? `${copy({ pt: "Falta", en: "Missing", fr: "Manque", de: "Fehlt", it: "Manca" })}: ${missing.map((item) => item.key).join(", ")}` : copy({ pt: "Variaveis obrigatorias presentes.", en: "Required variables present.", fr: "Variables requises presentes.", de: "Pflichtvariablen vorhanden.", it: "Variabili richieste presenti." })}</div>
                  </div>
                  <span className={`shrink-0 border px-2 py-1 font-mono text-[9px] uppercase tracking-[0.16em] ${statusClass(group.status)}`}>{statusLabel(group.status)}</span>
                </div>
                <div className="mt-4 flex flex-wrap gap-1.5">
                  {group.checks.map((checkItem) => (
                    <span key={`${group.id}-${checkItem.key}`} className={`border px-2 py-1 font-mono text-[9px] uppercase tracking-[0.14em] ${checkItem.configured ? "border-emerald-300 text-emerald-700 bg-emerald-50" : checkItem.required ? "border-rouge/40 text-rouge bg-white" : "border-neutral-200 text-neutral-400 bg-white"}`}>
                      {checkItem.configured ? "ok" : checkItem.required ? "missing" : "optional"} · {checkItem.key}
                    </span>
                  ))}
                </div>
                <p className="mt-3 text-xs leading-relaxed text-neutral-500">{boxDesc}</p>
                {                                                                                     
                                                                                                 }
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

                                                                                             
