  pending_decision_created: { pt: "Decisão pendente", en: "Decision created", fr: "Décision créée", de: "Entscheidung erstellt", it: "Decisione creata" },
  pending_decision: { pt: "Decisão pendente", en: "Pending decision", fr: "Décision en attente", de: "Ausstehende Entscheidung", it: "Decisione in attesa" },
