type ClientPresentationAccess = { login: string; password?: string; passwordHash?: string };

function localPasswordHash(raw: string): string {
  let h = 2166136261;
  for (let i = 0; i < raw.length; i += 1) {
    h ^= raw.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return `fnv1a:${(h >>> 0).toString(16).padStart(8, "0")}`;
}

async function hashClientPresentationPassword(raw: string): Promise<string> {
  const value = raw.trim();
  if (!value) return "";
  try {
    const data = new TextEncoder().encode(value);
    const digest = await crypto.subtle.digest("SHA-256", data);
    return "sha256:" + Array.from(new Uint8Array(digest)).map((b) => b.toString(16).padStart(2, "0")).join("");
  } catch {
    return localPasswordHash(value);
  }
}

function hasClientPresentationAccess(access?: ClientPresentationAccess): boolean {
  return !!(access?.login && (access.passwordHash || access.password));
}

async function verifyClientPresentationPassword(access: ClientPresentationAccess | undefined, raw: string): Promise<boolean> {
  const value = raw.trim();
  if (!access || !value) return false;
  if (access.passwordHash) return (await hashClientPresentationPassword(value)) === access.passwordHash;
  return value === (access.password || "").trim();
}

