function useDashTeam(): [DashTeamMember[], (v: DashTeamMember[] | ((p: DashTeamMember[]) => DashTeamMember[])) => void] {
  const [team, setTeam] = useLocalStorageState<DashTeamMember[]>("abil_dash_team", INITIAL_DASH_TEAM);
                                                                   
  useEffect(() => {
    if (typeof window === "undefined") return;
    const storedVer = window.localStorage.getItem("abil_dash_team_version");
    if (storedVer !== DASH_TEAM_VERSION) {
      setTeam(INITIAL_DASH_TEAM);
      window.localStorage.setItem("abil_dash_team_version", DASH_TEAM_VERSION);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  return [team, setTeam];
}

                                                                       
                                                                             
                                               
