function isRenderableImageUrl(u?: string): boolean {
  const raw = String(u || "").trim();
  if (!raw) return false;
  if (/^data:(?!image\/)/i.test(raw)) return false;
  if (/\.(pdf|mp4|webm|mov|m4v)(?:$|[?#])/i.test(raw)) return false;
  if (/(^|[?&;])(format|fm|mime|content_type)=video/i.test(raw)) return false;
  return raw.startsWith("data:image") || /^https?:/i.test(raw) || (raw.startsWith("/") && !raw.startsWith("data:"));
}

function projectAssetImageUrl(asset?: Partial<ProjectAsset> | null): string {
  if (!asset) return "";
  const poster = typeof asset.posterSrc === "string" ? asset.posterSrc : "";
  const preview = typeof asset.previewSrc === "string" ? asset.previewSrc : "";
  const src = typeof asset.src === "string" ? asset.src : "";
  if (poster && poster !== src && poster !== preview && isRenderableImageUrl(poster)) return poster;
  if (asset.type !== "video" && isRenderableImageUrl(src)) return src;
  return "";
}

function projectCoverImageUrl(project: Pick<DashboardProject, "cover" | "assets">): string {
  const cover = projectAssetImageUrl(project.cover);
  if (cover) return cover;
  for (const asset of project.assets || []) {
    const url = projectAssetImageUrl(asset);
    if (url) return url;
  }
  return "";
}

function projectGalleryImageUrls(project: Pick<DashboardProject, "cover" | "assets">, max = 4): string[] {
  const urls: string[] = [];
  const push = (url: string) => { if (url && !urls.includes(url)) urls.push(url); };
  push(projectAssetImageUrl(project.cover));
  (project.assets || []).forEach((asset) => push(projectAssetImageUrl(asset)));
  return urls.slice(0, max);
}

                                                                                                 
                                                                                            
                                                                                                   
function collectReusableSiteImages(cap = 200): string[] {
  const seen = new Set<string>();
  const out: string[] = [];
  const push = (u?: unknown) => {
    const url = typeof u === "string" ? u.trim() : "";
    if (!url || seen.has(url) || !isRenderableImageUrl(url) || url.startsWith("blob:")) return;
    seen.add(url);
    out.push(url);
  };
  const arr = <T,>(k: string): T[] => { try { const x = cloudGet<unknown>(k, []); return Array.isArray(x) ? (x as T[]) : []; } catch { return []; } };
  try {
                                                                       
    for (const p of arr<any>("abil_projects_v3")) {
      if (!p) continue;
      try { projectGalleryImageUrls(p, 99).forEach(push); } catch {       }
      push(p.coverImage);
      (Array.isArray(p.images) ? p.images : []).forEach(push);
    }
                                                                             
    for (const t of arr<any>("abil_email_template_extras_v2")) {
      if (!t) continue;
      push(t.heroImage);
      (Array.isArray(t.projectGallery) ? t.projectGallery : []).forEach(push);
    }
                                                                        
    for (const j of EMAIL_JOURNEY_BASE_PT) push(j.heroImage);
                                                                                                         
    for (const c of arr<any>("abil_social_cards_v2")) {
      if (!c) continue;
      push(c.imageSrc);
      (Array.isArray(c.carouselSlides) ? c.carouselSlides : []).forEach(push);
    }
    for (const c of arr<any>("abil_social_calendar")) {
      if (!c) continue;
      push(c.imageSrc);
      (Array.isArray(c.carouselSlides) ? c.carouselSlides : []).forEach(push);
      (Array.isArray(c.slides) ? c.slides : []).forEach((s: any) => push(s && s.src));
    }
                                                  
    for (const d of arr<any>("abil_blog_drafts")) {
      if (!d) continue;
      push(d.cover);
      (Array.isArray(d.images) ? d.images : []).forEach(push);
    }
                                                                             
    try {
      const ai = cloudGet<Record<string, string>>("abil_email_ai_images_v1", {}) || {};
      Object.values(ai).forEach(push);
    } catch {       }
  } catch {       }
  return out.slice(0, cap);
}

                                                                                      
                                                                                                 
                                                                                                     
                                                                                                  
function ServerImagePicker({ open, onClose, onSelect }: { open: boolean; onClose: () => void; onSelect: (url: string) => void }) {
  if (!open) return null;
  const imgs = collectReusableSiteImages(300);
  return (
    <Modal open={open} onClose={onClose} size="lg">
      <div className="p-6 text-noir">
        <div className="eyebrow text-rouge mb-3">Do servidor · {imgs.length} imagens</div>
        {imgs.length === 0 ? (
          <div className="text-sm text-neutral-400">Sem imagens guardadas ainda.</div>
        ) : (
          <div className="grid grid-cols-4 md:grid-cols-6 gap-2 max-h-[70vh] overflow-y-auto">
            {imgs.map((u, i) => (
              <button
                key={i}
                type="button"
                title="Reutilizar esta imagem"
                onClick={() => { onSelect(u); onClose(); }}
                className="aspect-square bg-neutral-100 border border-neutral-200 hover:border-rouge overflow-hidden transition-colors"
              >
                <img src={u} alt="" loading="lazy" decoding="async" onError={(e) => { const b = (e.currentTarget as HTMLImageElement).closest('button'); if (b) (b as HTMLElement).style.display = 'none'; }} className="w-full h-full object-cover" />
              </button>
            ))}
          </div>
        )}
      </div>
    </Modal>
  );
}

function generatedOutputApprovalAction(card: "blog" | "email" | "social", sourceId: string): NonNullable<AgentAction> {
  const projectId = sourceId.split(":").pop() || sourceId;
  if (card === "blog") {
    return {
      type: "approve_blog_draft",
      params: { draftId: `auto-${projectId}`, projectId, sourceId },
      confirm: "Publicar o artigo de blog gerado pela IA?",
    };
  }
  if (card === "social") {
    return {
      type: "approve_social_post",
      params: { postId: `social-auto-${projectId}`, projectId, sourceId },
      confirm: "Publicar o post social gerado pela IA?",
    };
  }
  return {
    type: "approve_email_template",
    params: { templateId: `email-auto-${projectId}`, projectId, sourceId },
    confirm: "Ativar o email marketing gerado pela IA?",
  };
}

function enqueueGeneratedOutputPreview(args: { card: "blog" | "email" | "social"; sourceId: string; title: string; body: string; previewImage?: string }) {
  try {
    const action = generatedOutputApprovalAction(args.card, args.sourceId);
    const previewImage = isRenderableImageUrl(args.previewImage) ? args.previewImage : undefined;
    const list = readPendingDecisions();
                                                                                            
                                                                                                   
                                                                                                    
                                                                                            
    const existing = list.find((d) => d.sourceId === args.sourceId && d.card === args.card);
    if (existing) {
      if (existing.status === "pending") {
        const next = list.map((d) => d.id === existing.id ? { ...d, action, title: args.title, body: args.body, previewImage, updatedAt: new Date().toISOString() } : d);
        writePendingDecisions(next);
      }
      return;                                                      
    }
    const queued = enqueuePendingDecision({ card: args.card, sourceId: args.sourceId, previewImage, action, title: args.title, body: args.body });
    void recordAgentActionLog({ action: action.type, params: action.params, before: agentActionStateSnapshot(action, "pt", args.card), result: args.title, status: "queued", auto: true, decisionId: queued.id, card: args.card, source: "generated_output_preview" });
  } catch {            }
}

type OutboundQueueResult = { ok: boolean; status: "queued" | "skipped" | "failed"; queued: number; skipped?: string; error?: string; details?: unknown };
                                                                             
                                                                                
                                                                
const OUTBOUND_TENANT_ID = "abil";
                                                                                  
                                                                                   
                                                                             
                                                                                 
                                                                                     
                                                                         
const OUTBOUND_SITE_BASE = "https://abil-site.vercel.app";
const OUTBOUND_FROM_NAME = "ABiL";
const OUTBOUND_FROM_EMAIL = "sam@abil.ch";

function emailAddressOk(value: string): boolean {
  return /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(value);
}

function htmlEscape(value: string): string {
  return String(value || "").replace(/[&<>"']/g, (ch) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", "\"": "&quot;", "'": "&#39;" }[ch] || ch));
}

function absoluteOutboundUrl(value?: string): string {
  const raw = String(value || "").trim();
  if (/^https?:\/\//i.test(raw)) return raw;
  if (raw.startsWith("/")) return `${OUTBOUND_SITE_BASE}${raw}`;
  return "";
}

function emailNameFromAddress(email: string): string {
  const base = email.split("@")[0]?.split(/[+._-]/)[0] || "";
  return base ? base.charAt(0).toUpperCase() + base.slice(1) : "there";
}

function readMarketingRecipients(): string[] {
  const recipients: string[] = [];
  const push = (value: unknown) => {
    const email = String(value || "").trim().toLowerCase();
    if (emailAddressOk(email) && !recipients.includes(email)) recipients.push(email);
  };
  try {
    const subscribers = cloudGet<Array<string | { email?: string; active?: boolean; unsubscribed?: boolean }>>("abil_newsletter_subscribers", []);
    (Array.isArray(subscribers) ? subscribers : []).forEach((item) => {
      if (typeof item === "string") push(item);
      else if (item && item.active !== false && item.unsubscribed !== true) push(item.email);
    });
  } catch {            }
  try {
                                                                                                      
    const leads = getLeadsMem() as unknown as Array<Record<string, unknown>>;
    (Array.isArray(leads) ? leads : []).forEach((lead) => {
      if (lead?.newsletterOptIn === true || lead?.marketingOptIn === true || lead?.optIn === true) push(lead.email);
    });
  } catch {            }
  return recipients.slice(0, 500);
}

async function ensureOutboundPublicImageUrl(src: string | undefined, prefix: "covers" | "assets" | "social" | "email" | "airefs" | "catalog" | "autovideo" | "equipa", seed: string): Promise<string> {
  const raw = String(src || "").trim();
  if (/^https?:\/\//i.test(raw)) return raw;
                                                                                
                                                                                 
                                                                                 
                                                                                 
  if (raw.startsWith("/")) return absoluteOutboundUrl(raw);
  if (!raw.startsWith("data:image/")) return "";
  try {
    const { cloudUploadFile, dataUrlToFile } = await import("@/lib/cloudProjects");
    const mime = raw.match(/^data:(image\/[^;]+);base64,/)?.[1] || "image/jpeg";
    const ext = mime.includes("png") ? "png" : mime.includes("webp") ? "webp" : "jpg";
    const file = dataUrlToFile(raw, `${seed.replace(/[^a-z0-9_-]/gi, "-").slice(0, 64) || "asset"}.${ext}`);
    if (!file) return "";
    const out = await cloudUploadFile(file, { prefix, filename: file.name });
    return out.ok && out.url ? out.url : "";
  } catch {
    return "";
  }
}

function renderQueuedEmailHtml(template: EmailTemplate, to: string, heroUrl: string): string {
                                                                                
                                                                             
                                                                                
                                                                          
  return renderAbilEmailHtml(
    {
      phase: template.phase,
      subject: template.subject,
      preheader: template.preheader,
      body: template.body,
      ctaLabel: template.ctaLabel,
      ctaUrl: absoluteOutboundUrl(template.ctaUrl),
                                                                              
                                              
      heroImage: heroUrl || template.heroImage,
      projectGallery: template.projectGallery,
      blocks: template.blocks,
    },
    {
      absolute: absoluteOutboundUrl,
      mergeName: emailNameFromAddress(to),
      preheader: template.preheader,
    },
  );
}

async function enqueueApprovedEmailTemplate(template: EmailTemplate): Promise<OutboundQueueResult> {
  const recipients = readMarketingRecipients();
  if (recipients.length === 0) return { ok: false, status: "skipped", queued: 0, skipped: "awaiting_audience" };
                                                                                                        
                                                                                                 
  let tpl = template;
  try {
    const navLang = (((typeof localStorage !== "undefined" && localStorage.getItem("abil_lang")) || "pt").replace(/[^a-z]/gi, "").slice(0, 2) || "pt") as Lang;
    const sendLang = (cloudGet<Lang>("abil_email_send_lang_v1", navLang) || navLang) as Lang;
    if (sendLang && sendLang !== navLang) {
      const tr = async (s?: string): Promise<string> => { const v = String(s || ""); if (!v.trim()) return v; try { const o = await translateText(v, "auto", sendLang); return (o && o.trim()) ? o : v; } catch { return v; } };
      const [subject, body, preheader, ctaLabel] = await Promise.all([tr(template.subject), tr(template.body), tr(template.preheader), tr(template.ctaLabel)]);
      const blocks = template.blocks ? await Promise.all(template.blocks.map(async (b) => ({ ...b, titulo: await tr(b.titulo), descricao: await tr(b.descricao) }))) : template.blocks;
      tpl = { ...template, subject, body, preheader, ctaLabel, blocks };
    }
  } catch {                                }
  const heroUrl = await ensureOutboundPublicImageUrl(tpl.heroImage || tpl.projectGallery?.[0], "email", tpl.id);
  const items = recipients.map((to) => ({
    id: `${tpl.id}-${to.replace(/[^a-z0-9]+/gi, "-").slice(0, 80)}`,
    to,
    subject: tpl.subject,
    html: renderQueuedEmailHtml(tpl, to, heroUrl),
    fromName: OUTBOUND_FROM_NAME,
    fromEmail: OUTBOUND_FROM_EMAIL,
    scheduledAt: new Date().toISOString(),
  }));
                                                                              
                                                                                
                                                                             
                                                                           
                                                                               
                                                                       
  const LOTE = 100;
  let entraram = 0;
  try {
    for (let i = 0; i < items.length; i += LOTE) {
      const lote = items.slice(i, i + LOTE);
      const res = await fetch("/api/email-queue", { method: "POST", headers: getAIHeaders(), body: JSON.stringify({ tenantId: OUTBOUND_TENANT_ID, items: lote }) });
      const data = await res.json().catch(() => ({}));
      if (!res.ok || !data?.ok) {
        return { ok: false, status: "failed", queued: entraram, error: data?.error || `http_${res.status}`, details: data };
      }
      entraram += Array.isArray(data.added) ? data.added.length : lote.length;
    }
    return { ok: true, status: "queued", queued: entraram };
  } catch (err) {
    return { ok: false, status: "failed", queued: entraram, error: String(err) };
  }
}

async function enqueueApprovedSocialPost(post: SocialPost): Promise<OutboundQueueResult> {
  const platforms = Array.from(new Set((post.platforms || []).filter((p) => ["instagram", "facebook", "linkedin"].includes(p)))) as Array<"instagram" | "facebook" | "linkedin">;
  if (platforms.length === 0) return { ok: false, status: "skipped", queued: 0, skipped: "no_supported_platform" };
  const imageUrl = await ensureOutboundPublicImageUrl(post.slides?.[0]?.src, "social", post.id);
  const skippedPlatforms: string[] = [];
  const items = platforms.flatMap((platform) => {
    if (platform === "instagram" && !imageUrl) {
      skippedPlatforms.push("instagram_requires_public_image");
      return [];
    }
    return [{
      id: `${post.id}-${platform}`,
      platform,
      caption: post.caption,
      message: post.caption,
      imageUrl: imageUrl || undefined,
      scheduledAt: post.scheduledAt || new Date().toISOString(),
    }];
  });
  if (items.length === 0) return { ok: false, status: "skipped", queued: 0, skipped: skippedPlatforms.join(",") || "no_queueable_platform" };
  try {
    const res = await fetch("/api/social-queue", { method: "POST", headers: getAIHeaders(), body: JSON.stringify({ tenantId: OUTBOUND_TENANT_ID, items }) });
    const data = await res.json().catch(() => ({}));
    if (!res.ok || !data?.ok) return { ok: false, status: "failed", queued: 0, error: data?.error || `http_${res.status}`, details: data };
    return { ok: true, status: "queued", queued: Array.isArray(data.added) ? data.added.length : items.length, skipped: skippedPlatforms.join(",") || undefined, details: data };
  } catch (err) {
    return { ok: false, status: "failed", queued: 0, error: String(err) };
  }
}

type SlideAICuration = { captions: string[]; titles: string[]; coverTitle: string };
async function generateSlideCaptions(images: string[], opts?: { title?: string; lang?: string }): Promise<SlideAICuration> {
  const EMPTY: SlideAICuration = { captions: [], titles: [], coverTitle: "" };
  if (typeof fetch === "undefined") return EMPTY;
  const origin = typeof location !== "undefined" ? location.origin : "";
  const imgs = (images || [])
    .map((u) => (typeof u === "string" && u.startsWith("/") ? origin + u : u))
    .filter((u) => typeof u === "string" && /^(https?:|data:image\/)/i.test(u))
    .slice(0, 10);
  if (!imgs.length) return EMPTY;
  try {
    const res = await fetch("/api/analyze-project", {
      method: "POST",
      headers: getAIHeaders(),
      body: JSON.stringify({
        filename: `${(opts?.title || "projeto").slice(0, 60)}.carrossel`,
        text: opts?.title ? `Projeto "${opts.title}". Carrossel de ${imgs.length} slides para Instagram/LinkedIn.` : "",
        pageCount: imgs.length,
        images: imgs,
        captionLang: opts?.lang || "",
        ...getAIPersonaContext(),
      }),
    });
    if (!res.ok) return EMPTY;
    const data = await res.json();
    return {
      captions: Array.isArray(data.slideCaptions) ? data.slideCaptions.map((c: any) => String(c || "").trim()).filter(Boolean) : [],
      titles: Array.isArray(data.slideTitles) ? data.slideTitles.map((c: any) => String(c || "").trim()).filter(Boolean) : [],
      coverTitle: typeof data.coverTitle === "string" ? data.coverTitle.trim() : "",
    };
  } catch { return EMPTY; }
}

                                                                               
                                                                           
