function projectDisciplineLabel(catKey: ProjectCatKey | undefined, lang: Lang): string {
  const map: Partial<Record<ProjectCatKey, Record<Lang, string>>> = {
    branding: { pt: "branding e identidade visual", fr: "branding et identité visuelle", en: "branding and visual identity", de: "Branding und visuelle Identität", it: "branding e identità visiva" },
    campagne: { pt: "campanha e direção criativa", fr: "campagne et direction créative", en: "campaign and creative direction", de: "Kampagne und Kreativdirektion", it: "campagna e direzione creativa" },
    film: { pt: "direção de arte para filme", fr: "direction artistique pour le film", en: "art direction for film", de: "Art Direction für Film", it: "direzione artistica per film" },
    digital: { pt: "produto digital", fr: "produit numérique", en: "digital product", de: "digitales Produkt", it: "prodotto digitale" },
    editorial: { pt: "design editorial", fr: "design éditorial", en: "editorial design", de: "Editorial Design", it: "design editoriale" },
    social: { pt: "conteúdo para redes sociais", fr: "contenu pour réseaux sociaux", en: "social media content", de: "Social-Media-Inhalte", it: "contenuto per i social" },
  };
  const entry = catKey ? map[catKey] : undefined;
  const fallback: Record<Lang, string> = { pt: "direção criativa", fr: "direction créative", en: "creative direction", de: "Kreativdirektion", it: "direzione creativa" };
  (fallback as any).es ??= fallback.fr;
  return (entry && entry[lang]) || fallback[lang] || fallback.en;
}

