const EMAIL_LIMIT_PHASES = ["atracao", "boasvindas", "dor", "repost_blog", "solucao", "interesse", "prova", "qualificacao", "convite", "projeto_publicado"];
function emailCharLimit(phase: string | undefined, kind: "subject" | "body" | "cta"): number {
  const fb = kind === "subject" ? 90 : kind === "body" ? 600 : 24;
  try {
    const i = EMAIL_LIMIT_PHASES.indexOf(String(phase || ""));
    if (i < 0) return fb;                                                                  
    const key = `em-${i * 3 + (kind === "subject" ? 0 : kind === "body" ? 1 : 2)}`;
    const lim = JSON.parse(localStorage.getItem("abil_ai_char_limits_v1") || "{}") as Record<string, number>;
    const v = Number(lim[key]);
    return Number.isFinite(v) && v > 0 ? v : fb;
  } catch { return fb; }
}
