type AbilExpPillar = { t: string; c: string };
type AbilExpSig =
  | { kind: "4p" }
  | { kind: "engine"; title: string; lead: string; beats: AbilExpPillar[] }
  | { kind: "pillars"; label: string; title: string; items: AbilExpPillar[] };
type AbilExpDetail = {
  eyebrow: string; title: string; lead: string;
  tension: string; approachLabel: string; approach: string;
  methodLabel: string; steps: AbilExpStep[];
  sig: AbilExpSig;
  deliverLabel: string; deliverables: string[];
  outcome: string;
};
                                                                                                         
                                                                                               
