const pickQuoteSection = (svc: string, lang: Lang): AbilQuoteSection => {
                                                                                                
  const l: "pt" | "en" | "fr" = lang === "pt" ? "pt" : lang === "fr" ? "fr" : "en";
  const fam = abilQuoteFamily(svc);
  const famOver = (ABIL_QUOTE_SECTION_FAMILY[fam] && ABIL_QUOTE_SECTION_FAMILY[fam]![l]) || {};
  return { ...ABIL_QUOTE_SECTION_BASE[l], ...famOver };
};

const SERVICE_TO_JOURNEY: Record<string, string> = {
  branding: "01", naming: "01", label: "01", signage: "01", consulting: "01", talk_team: "01", editorial: "01",
  campaigns: "02", marketing_360: "02",
  webdesign: "03", app_design: "03",
  video: "04", motion_graphic: "04", cgi_3d: "04", ai_music: "04",
  social_media: "05", marketing_digital: "05", photo: "05",
  activation: "06",
};

                                                                                        
                                                                                               
                                                                                     
const ABIL_CONTENT_SERVICES = new Set<string>([
  "social_media", "marketing_digital", "marketing_360", "video", "motion_graphic",
  "campaigns", "photo", "cgi_3d", "ai_music", "activation",
]);

function buildAbilQuotePhases(b: Briefing, lang: Lang = "pt"): QuotePhase[] {
  const c = loadAbilCentral();
                                                                                     
                                                                                    
                                                                                       
  const fmt = (n: number) => Math.round(n).toLocaleString("en-US").replace(/,/g, "'") + ".00";
  const catMap: Record<string, string[]> = {
    branding: ["Branding"], naming: ["Naming"], social_media: ["Social media"],
    marketing_digital: ["Marketing digital", "Tráfego pago"], marketing_360: ["Marketing digital", "Social media", "Publicidade"],
    campaigns: ["Publicidade"], video: ["Audiovisual"], webdesign: ["Web"], app_design: ["App"],
    label: ["Rótulos"], motion_graphic: ["Motion graphics"], photo: ["Fotografia"], cgi_3d: ["Audiovisual", "Motion graphics"],
    ai_music: ["Música"], editorial: ["Editorial"], consulting: ["Consultoria"], signage: ["Sinalética"], activation: ["Ativação"], talk_team: ["Consultoria"],
  };
  const svc = b.service || "branding";
  const namingRequested = svc === "naming" || b.brandNeedsNaming === true;
  const cats = (svc === "branding" && namingRequested) ? ["Branding", "Naming"] : (catMap[svc] || ["Branding"]);
  const exclude = ["BR-12", "AD-01", "AD-02", "AD-03", "AD-04"];
                                                                                
  const tier: AbilTier = b.companySize || "bronze";
  const offer = ABIL_SERVICE_OFFERS.find((o) => o.service === svc);
  const pkg = c.pkgs.find((p) => p.service === svc && p.tier === tier);
  const offerTier = offer?.tiers.find((t) => t.tier === tier);
  let total = pkg?.priceFinal ?? offerTier?.price ?? 0;
                                                                                    
  if (total === 0) {
    let micros = c.micros.filter((m) => m.status === "ativo" && cats.includes(m.cat) && !exclude.includes(m.code) && m.billing !== "percent_verba");
    if (micros.length === 0) micros = c.micros.filter((m) => m.status === "ativo").slice(0, 6);
    total = micros.reduce((s, m) => s + m.priceRec, 0);
  }
                                        
  if (svc === "branding" && namingRequested) total += ABIL_NAMING_ADDON[tier];
                                                                      
  const journeyKey = SERVICE_TO_JOURNEY[svc] || "01";
  const entry = ABIL_EXP_DETAIL[journeyKey] || ABIL_EXP_DETAIL["01"];
                                                                                                 
  const det: AbilExpDetail | null = entry ? ((((entry as any)[lang] as AbilExpDetail) ?? entry.en)) : null;
  const svcLabelPt = SERVICE_OPTIONS.find((s) => s.id === svc)?.label ?? "Projeto";
  const svcLabel = abilServiceLabelForLang(svcLabelPt, lang);
  const steps = det?.steps ?? [];
  const sec = pickQuoteSection(svc, lang);
  const diagDefault = lang === "pt"
    ? "A partir do teu briefing, desenhámos esta proposta à volta do que realmente importa para o teu negócio. Abaixo, desdobramos o serviço passo a passo."
    : lang === "fr"
    ? "À partir de votre briefing, nous avons construit cette proposition autour de ce qui compte vraiment pour votre activité. Ci-dessous, nous déroulons le service étape par étape."
    : "From your briefing, we shaped this proposal around what truly matters for your business. Below, we unfold the service step by step.";
  return [{
    id: `svc-${svc}`,
    numero: svcLabel,
    titulo: svcLabel,
                                                                                                
                                                                                                
    subtitulo: lang === "pt"
      ? (abilServiceDesc(svc) || (det?.lead ? det.lead.replace(/\*/g, "") : undefined))
      : (det?.lead ? det.lead.replace(/\*/g, "") : undefined),
    linhas: steps
      .filter((s) => namingRequested || !/naming/i.test(s.t))
      .map((s, j) => {
        const num = String(j + 1).padStart(2, "0");
        const parts = (s.t || "").split(" · ");
        const namePart = parts.length >= 2 ? parts[1] : (parts[0] || "").replace(/^\s*\d+\s*·\s*/, "");
        if (j === 0) {
                                                                                        
                                                                                              
          const c1 = lang === "pt"
            ? "Mergulhamos no briefing que entregaste, cruzando cada resposta para garantir que nada passa batido. É daqui que nasce toda a proposta abaixo."
            : lang === "fr"
            ? s.c
            : "We dive into the brief you've submitted, cross-reading every answer so nothing slips through. Everything below is born from it.";
          return { id: `j${j}`, titulo: `${num} · ${namePart}`, descricao: c1, bullets: [], preco: "" };
        }
        return { id: `j${j}`, titulo: `${num} · ${namePart}`, descricao: s.c, bullets: [], preco: "" };
      }),
    totalHT: fmt(total),
    diagnostico: diagDefault,
    especificacoes: sec.especificacoes,
    cronograma: sec.cronograma,
    politicaAlteracoes: sec.politica,
    escopo: sec.escopo,
    autonomia: sec.autonomia,
    ideiasConteudo: sec.ideiasConteudo,
    observacoes: sec.observacoes,
  }];
}

                                                                                
const ABIL_VAT_OPTIONS: { rate: number; label: string }[] = [
  { rate: 0.081, label: "TVA 8.1% (CH)" },
];
const abilVatRate = (quote: Quote): number => (typeof quote.vatRate === "number" ? quote.vatRate : 0.081);
const abilVatLabel = (rate: number): string => ABIL_VAT_OPTIONS.find((o) => o.rate === rate)?.label ?? `TVA ${Math.round(rate * 1000) / 10}%`;
const abilParseEuro = (s: string): number => {
  const cleaned = String(s).replace(/[^\d.,]/g, "").replace(/\.(?=\d{3}(?:[.,]|$))/g, "").replace(",", ".");
  const n = parseFloat(cleaned);
  return isNaN(n) ? NaN : n;
};

                                                                          
                                                                    
                                                                        
                                                                                                
                                                                                                 
                                                                                                   
                                                                                                                            
function buildAbilQuotePhasesMulti(b: Briefing, lang: Lang = "pt"): QuotePhase[] {
  const picks: { service: ServiceType; companySize: AbilTier }[] = [];
  const seen = new Set<string>();
  const add = (svc?: ServiceType, tier?: AbilTier) => {
    if (!svc || seen.has(svc)) return;
    seen.add(svc);
    picks.push({ service: svc, companySize: (tier || b.companySize || "bronze") as AbilTier });
  };
  add(b.service, b.companySize);
  for (const s of (b.services || [])) add(s.service, s.companySize);
  if (picks.length === 0) return buildAbilQuotePhases(b, lang);
  return picks.flatMap((p) => buildAbilQuotePhases({ ...b, service: p.service, companySize: p.companySize, services: undefined }, lang));
}

                                                                                   
                                                                             
if (typeof window !== "undefined") {
  (window as unknown as Record<string, unknown>).__abilQuoteTest = (primary: ServiceType, extras: ServiceType[] = [], tier: AbilTier = "ouro", lang: Lang = "pt") => {
    const b = { id: "test", service: primary, companySize: tier, services: (extras || []).map((s) => ({ service: s })), contactName: "Teste", contactCompany: "Teste Lda" } as unknown as Briefing;
    const q = createQuoteFromBriefing(b, 1, lang);
                                                                                                                                    
    return {
      fases: q.phases.length,
      servicos: q.phases.map((p) => p.titulo),
      total: calcQuoteTotal(q),
      texto: q.phases.map((p) => ({ titulo: p.titulo, subtitulo: p.subtitulo, diagnostico: p.diagnostico, especificacoes: p.especificacoes, cronograma: p.cronograma, politica: p.politicaAlteracoes, escopo: p.escopo, linhas: p.linhas.map((l) => `${l.titulo} :: ${l.descricao}`) })),
      intro: q.bienvenueIntro,
      etapas: q.processoEtapas.map((e) => e.texto),
    };
  };
}

                                                                                                         
                                                                                                           
                                                                                                       
                                                                                                    
                                                                                                         
                                                                                                         
function quoteRefSeq(ref: string): number { const m = /(\d{4})-(\d+)\s*$/.exec(String(ref || "")); return m ? parseInt(m[2], 10) : 0; }
function quoteRefBase(createdAt: string | undefined): string { const d = new Date(createdAt || Date.now()); const yy = isNaN(d.getTime()) ? new Date() : d; return `${yy.getFullYear().toString().slice(-2)}${String(yy.getMonth() + 1).padStart(2, "0")}`; }
function reconcileQuoteRefs(quotes: Quote[]): Quote[] {
  if (!Array.isArray(quotes) || quotes.length === 0) return quotes;
  const tsOf = (q: Quote) => { const t = new Date(q.createdAt || 0).getTime(); return isNaN(t) ? 0 : t; };
  const sorted = [...quotes].sort((a, b) => (tsOf(a) - tsOf(b)) || String(a.id).localeCompare(String(b.id)));
  const lockedSeqs = new Set<number>();
  for (const q of sorted) if (q.status !== "draft") { const s = quoteRefSeq(q.ref); if (s > 0) lockedSeqs.add(s); }
  let next = 1;
  const byId = new Map<string, Quote>();
  for (const q of sorted) {
    if (q.status !== "draft") { byId.set(q.id, q); continue; }                          
    while (lockedSeqs.has(next)) next++;
    const seq = next++;
    const core = `${quoteRefBase(q.createdAt)}-${String(seq).padStart(3, "0")}`;
    const newRef = /(\d{4})-(\d+)\s*$/.test(q.ref || "") ? q.ref.replace(/(\d{4})-(\d+)(\s*)$/, core + "$3") : q.ref;
    byId.set(q.id, newRef !== q.ref ? { ...q, ref: newRef } : q);
  }
  return quotes.map((q) => byId.get(q.id) || q);
}

                                                                                             
                                                                                                 
                                                                  
function quoteLangFromBriefing(b: { sourceLang?: Lang; detectedLang?: string } | null | undefined): Lang {
  const ok = (v: unknown): v is Lang => typeof v === "string" && ["pt", "fr", "en", "it", "de"].includes(v);
  if (b) {
    if (ok(b.sourceLang)) return b.sourceLang;
    if (ok((b as { detectedLang?: string }).detectedLang)) return (b as { detectedLang?: string }).detectedLang as Lang;
  }
  return "fr";
}

function createQuoteFromBriefing(b: Briefing, refSeq: number, lang: Lang = "fr"): Quote {
  const today = new Date();
  const ref = `${today.getFullYear().toString().slice(-2)}${String(today.getMonth() + 1).padStart(2, "0")}-${String(refSeq).padStart(3, "0")}`;
  const localeMap: Record<Lang, string> = { fr: "fr-CH", de: "de-CH", en: "en-GB", pt: "pt-PT", it: "it-CH" };
  (localeMap as any).es ??= localeMap.fr;
  const cityPrefix: Record<Lang, string> = { fr: "Genève, le", de: "Genève, den", en: "Genève,", pt: "Genève,", it: "Genève," };
  (cityPrefix as any).es ??= cityPrefix.fr;
  const dataStr = `${cityPrefix[lang]} ${today.toLocaleDateString(localeMap[lang], { day: "numeric", month: "long", year: "numeric" })}`;
  const projetTitleWord: Record<Lang, string> = { fr: "PROJET", de: "PROJEKT", en: "PROJECT", pt: "PROJETO", it: "PROGETTO" };
  (projetTitleWord as any).es ??= projetTitleWord.fr;
  const projetoTitulo = `${projetTitleWord[lang]} ${(b.brandName ?? b.contactCompany ?? "CLIENT").toUpperCase()}`;

                                                                                           
                                                                                            
                                                                                   
  const phases: QuotePhase[] = [];
  for (const ph of buildAbilQuotePhasesMulti(b, lang)) phases.push(ph);
                                                                                       
  if (phases.length === 0) {
                                                                                                 
    const svcLabelFb = abilServiceLabelForLang(SERVICE_OPTIONS.find((s) => s.id === b.service)?.label ?? "Projeto", lang);
    phases.push({
      id: "p1",
      numero: "PHASE 1",
      titulo: svcLabelFb,
      linhas: [
        {
          id: "l1",
          titulo: svcLabelFb,
          descricao: "",
          bullets: [],
          preco: "à définir",
        },
      ],
    });
  }

                                   
  const refLabel: Record<Lang, string> = { fr: "Réf.", de: "Ref.", en: "Ref.", pt: "Ref.", it: "Rif." };
  (refLabel as any).es ??= refLabel.fr;
  const greetings: Record<Lang, string> = { fr: "M. / Mme", de: "Herr/Frau", en: "Mr/Ms", pt: "Sr./Sra.", it: "Sig./Sig.ra" };
  (greetings as any).es ??= greetings.fr;
  const intros: Record<Lang, string> = {
    fr: "Cher client,\n\nNous vous remercions pour votre demande d'offre, dont vous trouverez le détail ci-après. Avant d'en prendre connaissance, nous souhaitons vous présenter les principales étapes du processus de création de votre projet au sein de notre atelier.\n\nNous sommes très attachés à la co-création. Cela veut dire que vous faites partie intégrante du projet et que, pour nous, vous devez être pleinement satisfait et convaincu du résultat final de votre mandat.\n\nÀ noter qu'il se peut que, dans certains cas spécifiques de projet, nous fassions appel à vos ressources pour alimenter certains contenus.",
    de: "Sehr geehrte Kundschaft,\n\nWir danken Ihnen für Ihre Angebotsanfrage, deren Details Sie nachstehend finden. Bevor Sie diese durchlesen, möchten wir Ihnen die wichtigsten Schritte des Entstehungsprozesses Ihres Projekts in unserem Atelier vorstellen.\n\nWir legen grossen Wert auf Ko-Kreation. Das bedeutet, dass Sie ein integraler Bestandteil des Projekts sind und für uns vollkommen zufrieden und vom Endergebnis Ihres Auftrags überzeugt sein müssen.\n\nIn bestimmten spezifischen Projektfällen kann es vorkommen, dass wir auf Ihre Ressourcen zurückgreifen, um bestimmte Inhalte zu speisen.",
    en: "Dear client,\n\nThank you for your quote request, the details of which you will find below. Before reviewing them, we would like to present the main stages of the creative process for your project at our atelier.\n\nWe are deeply attached to co-creation. This means that you are an integral part of the project and that, for us, you must be fully satisfied and convinced by the final result of your mandate.\n\nPlease note that, in certain specific project cases, we may call upon your resources to feed certain content.",
    pt: "Caro cliente,\n\nAgradecemos pelo seu pedido de proposta, cujo detalhe encontrará a seguir. Antes de a consultar, gostaríamos de lhe apresentar as principais etapas do processo de criação do seu projecto no nosso atelier.\n\nEstamos profundamente comprometidos com a co-criação. Isto significa que faz parte integrante do projecto e que, para nós, deve estar plenamente satisfeito e convicto do resultado final do seu mandato.\n\nA notar que, em certos casos específicos de projecto, poderemos recorrer aos seus recursos para alimentar certos conteúdos.",
    it: "Caro cliente,\n\nLa ringraziamo per la sua richiesta d'offerta, i cui dettagli troverà di seguito. Prima di prenderne visione, desideriamo presentarle le principali tappe del processo di creazione del suo progetto presso il nostro atelier.\n\nSiamo molto legati alla co-creazione. Ciò significa che lei fa parte integrante del progetto e che, per noi, deve essere pienamente soddisfatto e convinto del risultato finale del suo mandato.\n\nDa notare che, in alcuni casi specifici di progetto, potremmo fare appello alle sue risorse per alimentare determinati contenuti.",
  };
  (intros as any).es ??= intros.fr;
  const etapas: Record<Lang, { numero: string; texto: string }[]> = {
    fr: [
      { numero: "01", texto: "Analyse de la situation et recherche de solutions adaptées" },
      { numero: "02", texto: "Création du concept et de plusieurs propositions graphiques" },
      { numero: "03", texto: "Présentation des maquettes au client" },
      { numero: "04", texto: "Discussion pour adaptations et approbation finale" },
      { numero: "05", texto: "Réalisation du BAT de validation avec signature du client" },
      { numero: "06", texto: "Mise au net du fichier pour utilisation/production" },
      { numero: "07", texto: "Remise du matériel au client" },
    ],
    de: [
      { numero: "01", texto: "Analyse der Situation und Suche nach geeigneten Lösungen" },
      { numero: "02", texto: "Konzepterstellung und mehrere grafische Vorschläge" },
      { numero: "03", texto: "Präsentation der Entwürfe beim Kunden" },
      { numero: "04", texto: "Besprechung für Anpassungen und endgültige Freigabe" },
      { numero: "05", texto: "Erstellung des BAT zur Validierung mit Kundenunterschrift" },
      { numero: "06", texto: "Reinzeichnung der Datei für Nutzung/Produktion" },
      { numero: "07", texto: "Übergabe des Materials an den Kunden" },
    ],
    en: [
      { numero: "01", texto: "Situation analysis and search for adapted solutions" },
      { numero: "02", texto: "Concept creation and several graphic proposals" },
      { numero: "03", texto: "Presentation of mockups to the client" },
      { numero: "04", texto: "Discussion for adjustments and final approval" },
      { numero: "05", texto: "Production of validation BAT with client signature" },
      { numero: "06", texto: "Cleaning up the file for use/production" },
      { numero: "07", texto: "Delivery of materials to the client" },
    ],
    pt: [
      { numero: "01", texto: "Análise da situação e pesquisa de soluções adaptadas" },
      { numero: "02", texto: "Criação do conceito e várias propostas gráficas" },
      { numero: "03", texto: "Apresentação das maquetes ao cliente" },
      { numero: "04", texto: "Discussão para adaptações e aprovação final" },
      { numero: "05", texto: "Realização do BAT de validação com assinatura do cliente" },
      { numero: "06", texto: "Finalização do ficheiro para uso/produção" },
      { numero: "07", texto: "Entrega do material ao cliente" },
    ],
    it: [
      { numero: "01", texto: "Analisi della situazione e ricerca di soluzioni adatte" },
      { numero: "02", texto: "Creazione del concetto e diverse proposte grafiche" },
      { numero: "03", texto: "Presentazione dei mockup al cliente" },
      { numero: "04", texto: "Discussione per adattamenti e approvazione finale" },
      { numero: "05", texto: "Realizzazione del BAT di validazione con firma del cliente" },
      { numero: "06", texto: "Finalizzazione del file per uso/produzione" },
      { numero: "07", texto: "Consegna del materiale al cliente" },
    ],
  };
  (etapas as any).es ??= etapas.fr;
  const conditions: Record<Lang, string> = {
    fr: "Tarifs hors TVA. Acompte de 30% à la commande, solde à la livraison.\nDroits d'auteur cédés au client après paiement intégral.\nFichiers sources livrés sur demande après réception du paiement final.",
    de: "Preise exkl. MwSt. Anzahlung von 30% bei Bestellung, Restbetrag bei Lieferung.\nUrheberrechte nach vollständiger Bezahlung an den Kunden übertragen.\nQuelldateien auf Anfrage nach Erhalt der Schlusszahlung geliefert.",
    en: "Prices excl. VAT. 30% deposit on order, balance on delivery.\nCopyrights transferred to client upon full payment.\nSource files delivered upon request after receipt of final payment.",
    pt: "Preços sem IVA. Sinal de 30% na encomenda, saldo na entrega.\nDireitos de autor cedidos ao cliente após pagamento integral.\nFicheiros-fonte entregues a pedido após recepção do pagamento final.",
    it: "Prezzi IVA esclusa. Acconto del 30% all'ordine, saldo alla consegna.\nDiritti d'autore ceduti al cliente dopo pagamento integrale.\nFile sorgente consegnati su richiesta dopo ricezione del pagamento finale.",
  };
  (conditions as any).es ??= conditions.fr;
  const validity: Record<Lang, string> = {
    fr: "Offre valable 30 jours à compter de la date d'émission.",
    de: "Angebot gültig 30 Tage ab Ausstellungsdatum.",
    en: "Offer valid for 30 days from date of issue.",
    pt: "Proposta válida 30 dias a partir da data de emissão.",
    it: "Offerta valida 30 giorni dalla data di emissione.",
  };
  (validity as any).es ??= validity.fr;

                                                                       
                                                                         
                                                               
                                                                              
                                                                             
  const attachments = b.briefingAttachments ?? [];
  const attachmentsSummary: Record<Lang, string> = {
    fr: attachments.length > 0
      ? `\n\n, Le client a transmis ${attachments.length} pièce${attachments.length > 1 ? "s" : ""} jointe${attachments.length > 1 ? "s" : ""} (${attachments.map(a => a.name).slice(0, 4).join(", ")}${attachments.length > 4 ? "…" : ""}) qui seront analysées par notre équipe avant la phase de création.`
      : "",
    de: attachments.length > 0
      ? `\n\n, Der Kunde hat ${attachments.length} Anhang/Anhänge übermittelt (${attachments.map(a => a.name).slice(0, 4).join(", ")}${attachments.length > 4 ? "…" : ""}), die von unserem Team vor der Kreativphase analysiert werden.`
      : "",
    en: attachments.length > 0
      ? `\n\n, The client provided ${attachments.length} attachment${attachments.length > 1 ? "s" : ""} (${attachments.map(a => a.name).slice(0, 4).join(", ")}${attachments.length > 4 ? "…" : ""}) which will be reviewed by our team before the creative phase.`
      : "",
    pt: attachments.length > 0
      ? `\n\n, O cliente enviou ${attachments.length} anexo${attachments.length > 1 ? "s" : ""} (${attachments.map(a => a.name).slice(0, 4).join(", ")}${attachments.length > 4 ? "…" : ""}) que serão analisados pela nossa equipa antes da fase de criação.`
      : "",
    it: attachments.length > 0
      ? `\n\n, Il cliente ha inviato ${attachments.length} allegato/i (${attachments.map(a => a.name).slice(0, 4).join(", ")}${attachments.length > 4 ? "…" : ""}) che verranno analizzati dal nostro team prima della fase creativa.`
      : "",
  };
  (attachmentsSummary as any).es ??= attachmentsSummary.fr;

  return {
    id: `quote_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`,
    ref: `${refLabel[lang]} ${ref}`,
    status: "draft",
    createdAt: new Date().toISOString(),
    briefingId: b.id,
    clientName: b.contactName ?? greetings[lang],
    clientCompany: b.contactCompany ?? "",
    clientAddress: "",
    clientEmail: b.contactEmail,
    clientPhone: b.contactPhone,
    projetoTitulo,
    data: dataStr,
    bienvenueIntro: intros[lang] + attachmentsSummary[lang],
    processoEtapas: etapas[lang],
    phases,
    condicoesGerais: conditions[lang],
    validade: validity[lang],
    tva: "TVA 8.1% (Suisse)",
  };
}

                          
function calcQuoteTotal(quote: Quote): { ht: number; tva: number; ttc: number } {
  let ht = 0;
                                                                                   
                                                                                    
                                                                                   
                                                                               
  (quote.phases || []).forEach((ph) => {
    if (ph.totalHT) {
      const v = parseFloat(ph.totalHT.replace(/['\s]/g, "").replace(",", "."));
      if (!isNaN(v)) ht += v;
    } else {
      (ph.linhas || []).forEach((l) => {
        const v = parseFloat(l.preco.replace(/['\s]/g, "").replace(",", "."));
        if (!isNaN(v)) ht += v;
      });
    }
  });
  const tva = ht * 0.081;
  return { ht, tva, ttc: ht + tva };
}
function fmtCHF(n: number): string {
  return n.toLocaleString("fr-CH", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

                                                                                                                                                                                                                                       
                                                                            
                                                                                   
                                                                                   
                                                                             
                                                              
type CopilotDraft = {
  lang: Lang;
  service: ServiceType;
  serviceRationale: string;
  companySize: AbilTier;
  companySizeRationale: string;
  contactName: string;
  contactCompany: string;
  contactEmail: string;
  contactPhone: string;
  sector: string;
  summary: string;
  scope: string;
  deliverables: string[];
  deadline: string;
  budget: string;
  openQuestions: string[];
};

                                                                                       
                                                           
function copilotDeterministicOpener(lang: Lang, firstName: string, company: string, serviceLabel: string, sector: string): string {
  const hello: Record<Lang, string> = {
    fr: firstName ? `Bonjour ${firstName},` : "Bonjour,",
    en: firstName ? `Hello ${firstName},` : "Hello,",
    pt: firstName ? `Olá ${firstName},` : "Olá,",
    de: firstName ? `Hallo ${firstName},` : "Hallo,",
    it: firstName ? `Buongiorno ${firstName},` : "Buongiorno,",
  };
  (hello as any).es ??= hello.fr;
  const co = company ? ` (${company})` : "";
  const body: Record<Lang, string> = {
    fr: `Merci pour votre message. Nous avons lu votre demande${sector ? ` dans le domaine ${sector}` : ""} et préparé une proposition pour ${serviceLabel}${co}. Les détails figurent dans le document ci-dessous. Nous restons à votre disposition pour ajuster ce qu'il faut ou en discuter.`,
    en: `Thank you for your message. We have read your request${sector ? ` in ${sector}` : ""} and prepared a proposal for ${serviceLabel}${co}. The details are in the document below. We remain at your disposal to adjust anything or to talk it through.`,
    pt: `Obrigado pela sua mensagem. Lemos o seu pedido${sector ? ` na área de ${sector}` : ""} e preparámos uma proposta para ${serviceLabel}${co}. Os detalhes estão no documento abaixo. Ficamos à sua disposição para ajustar o que for preciso ou conversarmos.`,
    de: `Vielen Dank für Ihre Nachricht. Wir haben Ihre Anfrage${sector ? ` im Bereich ${sector}` : ""} gelesen und einen Vorschlag für ${serviceLabel}${co} vorbereitet. Die Details finden Sie im Dokument unten. Wir stehen Ihnen gerne zur Verfügung, um etwas anzupassen oder zu sprechen.`,
    it: `Grazie per il suo messaggio. Abbiamo letto la sua richiesta${sector ? ` nel settore ${sector}` : ""} e preparato una proposta per ${serviceLabel}${co}. I dettagli sono nel documento qui sotto. Restiamo a sua disposizione per modificare quanto serve o per sentirci.`,
  };
  (body as any).es ??= body.fr;
  return `${hello[lang]}\n\n${body[lang]}`;
}

                                                                                                
function copilotReplyText(lang: Lang, opener: string, totalTTC: string, totalHT: string): string {
  const price: Record<Lang, string> = {
    fr: `Investissement : ${totalTTC} TVA incluse (${totalHT} hors TVA). Offre valable 30 jours.`,
    en: `Investment: ${totalTTC} incl. VAT (${totalHT} excl. VAT). Offer valid for 30 days.`,
    pt: `Investimento: ${totalTTC} com IVA (${totalHT} sem IVA). Proposta válida 30 dias.`,
    de: `Investition: ${totalTTC} inkl. MwSt. (${totalHT} exkl. MwSt.). Angebot 30 Tage gültig.`,
    it: `Investimento: ${totalTTC} IVA inclusa (${totalHT} IVA esclusa). Offerta valida 30 giorni.`,
  };
  (price as any).es ??= price.fr;
  const sign: Record<Lang, string> = {
    fr: "Bien à vous,\nABiL",
    en: "Best regards,\nABiL",
    pt: "Com os melhores cumprimentos,\nABiL",
    de: "Beste Grüße,\nABiL",
    it: "Cordiali saluti,\nABiL",
  };
  (sign as any).es ??= sign.fr;
  return `${opener.trim()}\n\n${price[lang]}\n\n${sign[lang]}`;
}

                                                                                         
                                                                                        
                                                                                             
