function DocSection({ label, children }: { label: string; children: React.ReactNode }) {
  return (
    <div className="grid grid-cols-12 gap-6 mb-8 break-inside-avoid">
      <div className="col-span-3">
        <div className="eyebrow text-noir font-bold border-b-2 border-rouge pb-1 inline-block">
          {label}
        </div>
      </div>
      <div className="col-span-9">{children}</div>
    </div>
  );
}
function DocField({ label, value, multiline = false }: { label: string; value: string; multiline?: boolean }) {
  return (
    <div>
      <div className="eyebrow eyebrow-xs text-neutral-500 mb-0.5">{label}</div>
      <div className={`text-sm text-noir ${multiline ? "whitespace-pre-wrap leading-relaxed" : ""}`}>{value}</div>
    </div>
  );
}
function DocChips({ label, values, highlighted = false }: { label: string; values: string[]; highlighted?: boolean }) {
  return (
    <div>
      <div className="eyebrow eyebrow-xs text-neutral-500 mb-1.5">{label}</div>
      <div className="flex flex-wrap gap-1.5">
        {values.map((v, i) => (
          <span key={i} className={`px-2 py-1 font-mono text-[9px] uppercase tracking-[0.18em] ${highlighted ? "bg-rouge text-white" : "bg-neutral-100 text-neutral-700 border border-neutral-300"}`}>{v}</span>
        ))}
      </div>
    </div>
  );
}

                                                                                                                                          
                                                     
                                                                    
                                                                                                                                             

                                                                     
                                                  
function EditableInline({
  value,
  onChange,
  className = "",
  multiline = false,
  placeholder = "",
  as = "span",
}: {
  value: string;
  onChange: (v: string) => void;
  className?: string;
  multiline?: boolean;
  placeholder?: string;
  as?: "span" | "div" | "h1" | "h2" | "h3" | "p";
}) {
  const [editing, setEditing] = useState(false);

                                                                              
                                                                                     
                                                                                          
                                                                                        
                                                                                                
                                                                                                  
                                                                                            
                                                                                              
                                                                                              

  const Component = as as any;
  return (
    <Component
      contentEditable
      suppressContentEditableWarning
      onFocus={() => setEditing(true)}
      onBlur={(e: React.FocusEvent<HTMLElement>) => {
        setEditing(false);
        const newVal = (e.currentTarget.innerText ?? "").trim();
        if (newVal !== value) onChange(newVal);
      }}
      onKeyDown={(e: React.KeyboardEvent) => {
        if (!multiline && e.key === "Enter") {
          e.preventDefault();
          (e.target as HTMLElement).blur();
        }
      }}
      data-placeholder={placeholder}
      className={`outline-none transition-all ${editing ? "ring-2 ring-rouge ring-offset-2 bg-rouge/5" : "hover:bg-rouge/5 hover:ring-1 hover:ring-rouge/30 hover:ring-offset-2"} ${!value ? "before:content-[attr(data-placeholder)] before:text-neutral-300" : ""} ${className}`}
    >{value}</Component>
  );
}

                                                                                 
                                                                           
type AIQuoteInput = {
  clientCompany: string;
  clientName: string;
  clientEmail?: string;
  services: { titulo: string; preco: string }[];
  description: string;
  attachments: { name: string; size: number; mime?: string }[];
};

function createBriefingFromAIInput(input: AIQuoteInput): Briefing {
  const now = new Date().toISOString();
  return {
    id: `ai_${Date.now()}`,
    service: "branding",
    contactName: input.clientName,
    contactEmail: input.clientEmail ?? "",
    contactCompany: input.clientCompany,
    brandName: input.clientCompany,
    additionalInfo: input.description,
    briefingAttachments: input.attachments.map((a) => ({
      name: a.name,
      size: a.size,
      mime: a.mime || "application/octet-stream",
      uploadedAt: now,
    })),
    status: "in_quote",
    createdAt: now,
  };
}

function aiQuoteAttachmentNote(input: AIQuoteInput, lang: Lang): string {
  if (input.attachments.length === 0) return "";
  const names = input.attachments.map((a) => a.name).join(", ");
  const note = ({
    fr: `${input.attachments.length} fichier(s) reçu(s) pour contexte. Le contenu des fichiers n'a pas été lu automatiquement dans ce flux`,
    de: `${input.attachments.length} Datei(en) als Kontext erhalten. Der Dateiinhalt wurde in diesem Ablauf nicht automatisch gelesen`,
    en: `${input.attachments.length} file(s) received for context. File contents were not read automatically in this flow`,
    pt: `${input.attachments.length} ficheiro(s) recebidos como contexto. O conteúdo dos ficheiros não foi lido automaticamente neste fluxo`,
    it: `${input.attachments.length} file ricevuti come contesto. Il contenuto dei file non è stato letto automaticamente in questo flusso`,
    es: `${input.attachments.length} archivo(s) recibidos como contexto. El contenido no fue leído automáticamente en este flujo`,
  } as Record<string, string>)[lang] ?? `${input.attachments.length} file(s) received for context. File contents were not read automatically in this flow`;
  return `\n\n[${note}: ${names}]`;
}

function createQuoteFromAIInput(input: AIQuoteInput, refSeq: number, lang: Lang = "fr", briefing: Briefing = createBriefingFromAIInput(input)): Quote {
  const baseQuote = createQuoteFromBriefing(briefing, refSeq, lang);

                                                                                  
  const phases = input.services
    .filter((s) => s.titulo.trim().length > 0)
    .map((s, i) => ({
      id: `phase_${Date.now()}_${i}`,
      numero: `0${i + 1}`,
      titulo: s.titulo.toUpperCase(),
      subtitulo: "",
      linhas: [
        {
          id: `line_${Date.now()}_${i}`,
          titulo: s.titulo.toUpperCase(),
          bullets: input.description ? [input.description.slice(0, 200)] : ["À définir avec le client"],
          preco: s.preco,
        },
      ],
      totalHT: s.preco,
    }));

                                                                   
  const aiNote: Record<Lang, string> = {
    fr: "Devis généré automatiquement à partir des informations fournies.",
    de: "Angebot automatisch aus den bereitgestellten Informationen erstellt.",
    en: "Quote automatically generated from the provided information.",
    pt: "Orçamento gerado automaticamente a partir das informações fornecidas.",
    it: "Preventivo generato automaticamente dalle informazioni fornite.",
  };
  (aiNote as any).es ??= aiNote.fr;
  const bienvenue = `${aiNote[lang]}\n\n${input.description}${aiQuoteAttachmentNote(input, lang)}`;

  return {
    ...baseQuote,
    phases: phases.length > 0 ? phases : baseQuote.phases,
    bienvenueIntro: bienvenue,
  };
}

