const ABIL_TIER_PORTE: Record<AbilTier, string> = { bronze: "Empresa pequena", prata: "Empresa média", ouro: "Empresa grande", platina: "Líder de mercado" };
const ABIL_TIER_ORDER: AbilTier[] = ["bronze", "prata", "ouro", "platina"];
                                                                                               
                                                                                     
const ABIL_NAMING_ADDON: Record<AbilTier, number> = { bronze: Math.round(290 * CHF_FACTOR), prata: Math.round(450 * CHF_FACTOR), ouro: Math.round(700 * CHF_FACTOR), platina: Math.round(1100 * CHF_FACTOR) };

                                                                                        
                                                                                        
                                                                          
