function abilServiceDesc(svc: string): string {
  try {
                                                                                                 
                                                                                                             
    const o = cloudGet<Record<string, string>>("abil_service_desc", {});
    if (o && typeof o[svc] === "string" && o[svc].trim()) return o[svc].trim();
  } catch {            }
  return ABIL_SERVICE_PROCESS[svc] || "";
}
