function toCHF(seed: AbilCentral): AbilCentral {
  return {
    ...seed,
    equip: seed.equip.map((e) => ({ ...e, cost: Math.round(e.cost * CHF_FACTOR), price: Math.round(e.price * CHF_FACTOR) })),
    opcosts: seed.opcosts.map((o) => ({ ...o, monthly: Math.round(o.monthly * CHF_FACTOR) })),
    countries: seed.countries.map((c) => ({ ...c, minRec: Math.round(c.minRec * CHF_FACTOR) })),
  };
}

                                                                                        
                                                                                         
                                                                                           
