function migratePresentationTemplate(raw: unknown, service: string): PresentationTemplate {
  const def = PRESENTATION_TEMPLATE_DEFAULTS[service] || emptyPresentationTemplate();
  if (raw && typeof raw === "object" && !Array.isArray(raw)) {
    const o = raw as Partial<PresentationTemplate>;
    return {
      introLine: typeof o.introLine === "string" ? o.introLine : def.introLine,
      closingLine: typeof o.closingLine === "string" ? o.closingLine : def.closingLine,
      scenes: Array.isArray(o.scenes)
        ? o.scenes.map((s) => ({
            role: (s && s.role) || "understanding",
            title: (s && typeof s.title === "string") ? s.title : "",
            onScreen: Array.isArray(s && s.onScreen) ? s!.onScreen.filter((x) => typeof x === "string") : [],
            voiceover: (s && typeof s.voiceover === "string") ? s.voiceover : "",
          }))
        : def.scenes.map((s) => ({ ...s, onScreen: [...s.onScreen] })),
      legacyOutline: typeof o.legacyOutline === "string" ? o.legacyOutline : undefined,
    };
  }
  if (typeof raw === "string" && raw.trim()) {
    return {
      introLine: def.introLine,
      closingLine: def.closingLine,
      scenes: def.scenes.map((s) => ({ ...s, onScreen: [...s.onScreen] })),
      legacyOutline: raw.trim(),
    };
  }
  return {
    introLine: def.introLine,
    closingLine: def.closingLine,
    scenes: def.scenes.map((s) => ({ ...s, onScreen: [...s.onScreen] })),
  };
}

                                                                                    
                                                                                     
                                                                      
                                                                                
