  errorAddingGif: { fr: "Erreur lors de l'ajout de « {name} »", pt: "Erro ao adicionar « {name} »", en: "Error adding « {name} »", de: "Fehler beim Hinzufügen von « {name} »", it: "Errore durante l'aggiunta di « {name} »" },
  preparingCompression: { fr: "Préparation de la compression…", pt: "A preparar compressão…", en: "Preparing compression…", de: "Komprimierung wird vorbereitet…", it: "Preparazione della compressione…" },
  videoCompressedLoaded: { fr: "« {name} » compressé ({mb}MB) et chargé.", pt: "« {name} » comprimido ({mb}MB) e carregado.", en: "« {name} » compressed ({mb}MB) and loaded.", de: "« {name} » komprimiert ({mb}MB) und geladen.", it: "« {name} » compresso ({mb}MB) e caricato." },
  fileExceeds2gb: { fr: "{name} ignoré : dépasse la limite de 2GB (les vidéos sont compressées avant l'envoi).", pt: "{name} ignorado: excede o teto de 2GB (os vídeos são comprimidos antes de subir).", en: "{name} skipped: exceeds the 2GB cap (videos are compressed before upload).", de: "{name} übersprungen: überschreitet die 2GB-Grenze (Videos werden vor dem Hochladen komprimiert).", it: "{name} ignorato: supera il limite di 2GB (i video sono compressi prima del caricamento)." },
  fileUploadedToBlob: { fr: "« {name} » envoyé vers Blob ({mb}MB)", pt: "« {name} » uploaded para Blob ({mb}MB)", en: "« {name} » uploaded to Blob ({mb}MB)", de: "« {name} » zu Blob hochgeladen ({mb}MB)", it: "« {name} » caricato su Blob ({mb}MB)" },
  fileTooBigNotUploaded: { fr: "« {name} » ({mb} MB) n'a pas été envoyé : l'upload vers le cloud a échoué. Vérifiez la connexion et réessayez.", pt: "« {name} » ({mb} MB) não subiu: o upload para a nuvem falhou. Verifica a ligação e tenta de novo.", en: "« {name} » ({mb} MB) did not upload: the cloud upload failed. Check the connection and try again.", de: "« {name} » ({mb} MB) wurde nicht hochgeladen: der Cloud-Upload ist fehlgeschlagen. Verbindung prüfen und erneut versuchen.", it: "« {name} » ({mb} MB) non è stato caricato: l'upload sul cloud è fallito. Controlla la connessione e riprova." },
  pdfHeavyWarning: { fr: "Le PDF \"{name}\" pèse {mb} MB. Pensez à le pré-compresser (smallpdf.com, ilovepdf.com) pour de meilleures performances sur le site public. Le système préserve les vecteurs mais n'optimise pas les images raster internes.", pt: "PDF \"{name}\" pesa {mb} MB. Considera pre-comprimir (smallpdf.com, ilovepdf.com) para melhor performance no site público. O sistema preserva vetores mas não optimiza imagens raster internas.", en: "PDF \"{name}\" weighs {mb} MB. Consider pre-compressing it (smallpdf.com, ilovepdf.com) for better performance on the public site. The system preserves vectors but does not optimize internal raster images.", de: "Das PDF \"{name}\" wiegt {mb} MB. Erwägen Sie eine Vorkomprimierung (smallpdf.com, ilovepdf.com) für bessere Leistung auf der öffentlichen Website. Das System bewahrt Vektoren, optimiert aber keine internen Rasterbilder.", it: "Il PDF \"{name}\" pesa {mb} MB. Valuta di pre-comprimerlo (smallpdf.com, ilovepdf.com) per prestazioni migliori sul sito pubblico. Il sistema preserva i vettori ma non ottimizza le immagini raster interne." },
  videoLoadedGeneratingPreviewBg: { fr: "« {name} » chargé. Génération de l'aperçu léger en arrière-plan…", pt: "« {name} » carregado. A gerar preview leve em background…", en: "« {name} » loaded. Generating light preview in the background…", de: "« {name} » geladen. Leichte Vorschau wird im Hintergrund erstellt…", it: "« {name} » caricato. Generazione dell'anteprima leggera in background…" },
  errorLoadingFile: { fr: "Erreur lors du chargement de « {name} » : {err}", pt: "Erro ao carregar « {name} »: {err}", en: "Error loading « {name} »: {err}", de: "Fehler beim Laden von « {name} »: {err}", it: "Errore durante il caricamento di « {name} »: {err}" },
  errorReadingFile: { fr: "Erreur de lecture de « {name} » : {err}", pt: "Erro a ler « {name} »: {err}", en: "Error reading « {name} »: {err}", de: "Fehler beim Lesen von « {name} »: {err}", it: "Errore nella lettura di « {name} »: {err}" },
  videoLoadedGeneratingPreview: { fr: "« {name} » chargé. Génération de l'aperçu léger…", pt: "« {name} » carregado. A gerar preview leve…", en: "« {name} » loaded. Generating light preview…", de: "« {name} » geladen. Leichte Vorschau wird erstellt…", it: "« {name} » caricato. Generazione dell'anteprima leggera…" },
