function FieldWithIcon({
  icon: Icon,
  label,
  children,
  accentColor = "text-noir/70",
}: {
  icon: React.ComponentType<{ className?: string; strokeWidth?: number }>;
  label: string;
  children: React.ReactNode;
  accentColor?: string;
}) {
  return (
    <div>
      <div className={`flex items-center gap-2 mb-1.5 font-mono text-[10px] uppercase tracking-[0.22em] ${accentColor}`}>
        <Icon className="w-3.5 h-3.5" strokeWidth={1.5} />
        {label}
      </div>
      {children}
    </div>
  );
}

                                                                           
                                                                                    
function PersonaAvatar({ src, seed, size = 80, className = "" }: { src?: string; seed?: string; size?: number; className?: string }) {
  const rawSrc = (src || "").trim();
  const generatedAvatar = /^(https?:)?\/\/(?:randomuser\.me|i\.pravatar\.cc)\b/i.test(rawSrc);
  const url = rawSrc && !generatedAvatar ? rawSrc : siteFallbackImage(`persona-${seed || "default"}`);
  return (
    <img
      src={url}
      alt=""
      width={size}
      height={size}
      loading="lazy"
      className={`block bg-neutral-200 ${className}`}
      style={{
        width: size,
        height: size,
        filter: "grayscale(1) contrast(1.05)",
        objectFit: "cover",
      }}
    />
  );
}

                                                                                 
                                                                             
                                                                     
type KBFile = { name: string; content: string; size: number };
function KnowledgeBaseUploader({
  files,
  setFiles,
  label,
  hint,
  variant = "light",
}: {
  files: KBFile[];
  setFiles: (f: KBFile[]) => void;
  label?: string;
  hint?: string;
  variant?: "light" | "dark";
}) {
  const { showToast, lang } = useApp();
  const tn = (k: I18nNewKey) => tNew(lang, k);
  const isDark = variant === "dark";
                                              
  const effectiveLabel = label || tn("kbBaseLabel");
  const effectiveHint = hint || tn("kbAttachHint");

  const handleUpload = async (fileList: FileList | null) => {
    if (!fileList || fileList.length === 0) return;
    const newFiles: KBFile[] = [];
    for (const f of Array.from(fileList)) {
                                                                                                               
                                                                                                                
                                                                                                                 
                                                                                                           
      const isPdf = /\.pdf$/i.test(f.name);
      if (!isPdf && !/\.(txt|md|markdown|json|csv|tsv|html|xml|yml|yaml)$/i.test(f.name)) {
        showToast(`${f.name}: PDF, .txt, .md, .json ou .csv`);
        continue;
      }
      if (isPdf) {
        try {
          const texto = (await extractPdfTextForAgent(f)).trim();
          if (texto.length < 40) { showToast(`${f.name}: sem texto (PDF só com imagens?)`); continue; }
          newFiles.push({ name: f.name, content: texto, size: texto.length });
        } catch { showToast(`${f.name}: não consegui ler o PDF`); }
        continue;
      }
      if (f.size > 100_000) {
        showToast(`${f.name}: > 100KB (${(f.size / 1024).toFixed(0)}KB)`);
        continue;
      }
      const content = await f.text();
      newFiles.push({ name: f.name, content, size: f.size });
    }
    if (newFiles.length === 0) return;
    setFiles([...files, ...newFiles]);
    showToast(`${newFiles.length} ${newFiles.length === 1 ? "file" : "files"}`);
  };
  const removeFile = (name: string) => setFiles(files.filter((f) => f.name !== name));

  const labelColor = isDark ? "text-white/60" : "text-neutral-500";
  const dropBg = isDark
    ? "bg-white/5 border-white/20 hover:border-rouge text-white/70"
    : "bg-neutral-50 border-neutral-300 hover:border-rouge text-neutral-600";
  const hintColor = isDark ? "text-white/40" : "text-neutral-400";
  const itemBg = isDark ? "bg-white/5 text-white/80" : "bg-neutral-50 text-neutral-700";
  const itemMeta = isDark ? "text-white/40" : "text-neutral-400";

  return (
    <div>
      <label className={`eyebrow mb-2 block ${labelColor}`}>{effectiveLabel}</label>
      <label className={`block border-2 border-dashed px-4 py-6 text-center cursor-pointer transition-colors ${dropBg}`}>
        <input
          type="file"
          multiple
          accept=".pdf,.txt,.md,.markdown,.json,.csv,.tsv,.html,.xml,.yml,.yaml"
          onChange={(e) => handleUpload(e.target.files)}
          className="hidden"
        />
        <div className="text-sm">{tn("kbAttachFiles")}</div>
        <div className={`text-[11px] mt-1 ${hintColor}`}>{effectiveHint}</div>
      </label>
      {files.length > 0 && (
        <ul className="mt-2 space-y-1">
          {files.map((f) => (
            <li key={f.name} className={`flex items-center justify-between px-3 py-1.5 text-xs ${itemBg}`}>
              <span className="font-mono truncate">{f.name}</span>
              <span className={`text-xs ${itemMeta} ml-2`}>{(f.size / 1024).toFixed(1)}KB</span>
              <button
                onClick={() => removeFile(f.name)}
                className="text-rouge hover:text-noir text-xs ml-2 flex-shrink-0"
                type="button"
              >
                </button>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

                                                                                
