type AbilTestimonial = { id: string; cliente: string; empresa: string; texto: string; idioma: string; autorizadoEm: string; fonte: "email" | "manual"; aprovado: boolean; criadoEm: string; leadId?: string; msgId?: string };
                                                                                                             
function vaultTextValue(v: unknown): string {
  return typeof v === "string" ? v : (typeof (v as { texto?: unknown })?.texto === "string" ? String((v as { texto: string }).texto) : "");
}

                                                                                                                
                                                                                                               
                                                                                                                      
                                                                                                                 
                                                                     
