function AiChannelPromptField({ label, persisted, fallback, hint, placeholder, rows = 4, onSave, lang }: { label: string; persisted?: string; fallback?: string; hint?: string; placeholder?: string; rows?: number; onSave: (v: string) => void; lang: Lang }) {
  const L = (k: keyof typeof CHATBOT_TXT) => _trO(CHATBOT_TXT[k], lang);
  const base = (persisted !== undefined && persisted !== null && String(persisted).length > 0) ? String(persisted) : String(fallback || "");
  const [draft, setDraft] = React.useState(base);
  React.useEffect(() => { setDraft(base);                                                       // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [base]);
  const dirty = draft !== base;
  return (
    <div>
      <div className="flex items-center justify-between gap-2 mb-1">
        <span className="font-mono text-[10px] uppercase tracking-[0.14em] text-neutral-500">{label}</span>
        {dirty && <button type="button" onClick={() => onSave(draft)} className="eyebrow eyebrow-xs text-white bg-rouge px-2.5 py-1 hover:bg-noir transition-colors">{L("saveBtn")}</button>}
      </div>
      <textarea rows={rows} value={draft} placeholder={placeholder} onChange={(e) => setDraft(e.target.value)} className="w-full bg-neutral-50 border border-neutral-200 px-3 py-2.5 text-xs text-noir placeholder:text-neutral-300 focus:outline-none focus:border-rouge font-mono resize-y leading-relaxed" />
      {hint && <p className="mt-1 text-[10px] text-neutral-400 leading-relaxed">{hint}</p>}
    </div>
  );
}
                                                                                                 
                                                                                           
                                                                                                       
                                                                             
type AiImageRef = { url: string; name: string; desc: string; kind: "image" | "doc" };
function AiImageRefsBlock() {
  const { lang, showToast } = useApp();
  const L = (k: keyof typeof CHATBOT_TXT) => _trO(CHATBOT_TXT[k], lang);
  const [refs, setRefs] = useLocalStorageState<AiImageRef[]>("abil_ai_image_refs_v1", []);
  const [busy, setBusy] = useState(false);
  const inputRef = useRef<HTMLInputElement | null>(null);
  const addFiles = async (files: FileList | null) => {
    if (!files || !files.length || busy) return;
    if (!abilVaultUnlocked()) { showToast(L("refsVaultLocked")); return; }
    setBusy(true);
    try {
      const { cloudUploadFile } = await import("@/lib/cloudProjects");
      const added: AiImageRef[] = [];
      let lastErr = "";
      for (const f of Array.from(files).slice(0, 10)) {
        try {
          if (f.type.startsWith("image/")) {
            const up = await cloudUploadFile(f, { prefix: "airefs" });
            if (!up.ok || !up.url) { lastErr = up.error || L("refsUploadFail"); continue; }
            let desc = "";
            try {
              const r = await fetch("/api/regenerate-text", { method: "POST", headers: getAIHeaders(), body: JSON.stringify({ currentText: "", userPrompt: "Descreve em UMA frase (máx 140 caracteres) o ESTILO fotográfico desta imagem: luz, paleta, lente, atmosfera. Só a frase, sem aspas.", maxLength: 150, path: "ai/image-ref", lang, imageUrl: up.url }) });
              const d = await r.json().catch(() => null); desc = String(d?.text || "").trim().slice(0, 150);
            } catch { /* Without image analysis, keep the file name. */ }
            added.push({ url: up.url, name: f.name, desc: desc || f.name, kind: "image" });
          } else if (f.type === "application/pdf") {
            let txt = ""; try { txt = (await extractPdfTextForAgent(f)).replace(/\s+/g, " ").slice(0, 220); } catch {       }
            added.push({ url: "", name: f.name, desc: txt || f.name, kind: "doc" });
          } else if (f.type.startsWith("text/") || /\.(txt|md)$/i.test(f.name)) {
            const txt = (await f.text()).replace(/\s+/g, " ").slice(0, 220);
            added.push({ url: "", name: f.name, desc: txt || f.name, kind: "doc" });
          }
        } catch {                            }
      }
      if (added.length) { setRefs([...(Array.isArray(refs) ? refs : []), ...added].slice(0, 12)); showToast(`${added.length} ${L("refsAttached")}`); }
                                                                               
      else showToast(L("refsNoneAttached") + (lastErr ? ` (${lastErr.slice(0, 90)})` : ""));
    } finally { setBusy(false); if (inputRef.current) inputRef.current.value = ""; }
  };
  const list = Array.isArray(refs) ? refs : [];
  return (
    <div className="mt-3 border border-neutral-200 bg-neutral-50 p-3" id="ai-image-prompt">
      <div className="flex items-center justify-between gap-3 flex-wrap mb-2">
        <span className="font-mono text-[10px] uppercase tracking-[0.14em] text-neutral-500">{`${L("refsTitle")} · ${list.length}`}</span>
        <button type="button" disabled={busy} onClick={() => inputRef.current?.click()} className="eyebrow eyebrow-xs text-rouge hover:text-noir disabled:opacity-50">{busy ? L("refsAnalysing") : L("refsAttachBtn")}</button>
        <input ref={inputRef} type="file" accept="image/*,.pdf,.txt,.md,text/plain" multiple className="hidden" onChange={(e) => void addFiles(e.target.files)} />
      </div>
      {list.length === 0 ? (
        <p className="text-[11px] text-neutral-400 leading-relaxed">{L("refsEmptyHint")}</p>
      ) : (
        <ul className="space-y-1.5">
          {list.map((rf, ri) => (
            <li key={`${rf.name}-${ri}`} className="flex items-center gap-2.5">
              {rf.kind === "image" && rf.url ? <img src={rf.url} alt="" className="w-9 h-9 object-cover shrink-0 border border-neutral-200" loading="lazy" /> : <span className="w-9 h-9 shrink-0 border border-neutral-200 flex items-center justify-center font-mono text-[9px] text-neutral-400">DOC</span>}
              <span className="flex-1 min-w-0">
                <span className="block text-[11px] text-neutral-700 truncate">{rf.name}</span>
                <span className="block text-[10px] text-neutral-400 truncate">{rf.desc}</span>
              </span>
              <button type="button" title={L("refsRemove")} onClick={() => setRefs(list.filter((_, j) => j !== ri))} className="text-neutral-400 hover:text-rouge text-xs shrink-0"></button>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

                                                                                         
                                                                                                  
