function useEditValue(path: string, defaultText: string): [string, (v: string) => void] {
  const { edits, setEdit, lang } = useApp();
  const langKey = `${path}__${lang}`;
  const value = edits[langKey] ?? edits[path] ?? defaultText;
  return [value, (v: string) => setEdit(path, v)];
}

                                                                                   
                                                                             
                                                                            
                                                                             
                                       
function useCombinedTextLines(combinedPath: string, defaults: string[], separator: "\n" | "\n\n" = "\n"): string[] {
  const { edits, lang } = useApp();
  const langKey = `${combinedPath}__${lang}`;
  const raw = edits[langKey] ?? edits[combinedPath];
  if (typeof raw === "string" && raw.trim() !== "") {
    return raw.split(separator);
  }
  return defaults;
}

                                                                   
function TitleLines({ combinedPath, defaults, className }: { combinedPath: string; defaults: string[]; className?: string }) {
  const lines = useCombinedTextLines(combinedPath, defaults, "\n");
  return (
    <span className={className}>
      {lines.map((l, i) => (
        <React.Fragment key={i}>
          {l}
          {i < lines.length - 1 && <br />}
        </React.Fragment>
      ))}
    </span>
  );
}

                                                                           
function ParagraphsBlock({ combinedPath, defaults, paragraphClassName, lastClassName, container }: {
  combinedPath: string;
  defaults: string[];
  paragraphClassName?: string;
  lastClassName?: string;
  container?: string;
}) {
  const paras = useCombinedTextLines(combinedPath, defaults, "\n\n");
  return (
    <div className={container || "space-y-7"}>
      {paras.map((p, i) => (
        <p key={i} className={`${paragraphClassName || ""} ${i === paras.length - 1 ? (lastClassName || "") : ""}`.trim()}>{p}</p>
      ))}
    </div>
  );
}

                                                                  
function EditableUnifiedField({ combinedPath, defaults, separator, label, rows, max, placeholder, hint }: {
  combinedPath: string;
  defaults: string[];
  separator: "\n" | "\n\n";
  label: string;
  rows?: number;
  max?: number;
  placeholder?: string;
  hint?: string;
}) {
  const { lang } = useApp();
  const L = (k: keyof typeof TEXTES_TXT) => _trO(TEXTES_TXT[k], lang);
  const defaultJoined = defaults.join(separator);
  const [value, setValue] = useEditValue(combinedPath, defaultJoined);
  const isEdited = value !== defaultJoined;
  return (
    <div>
      <label className="block eyebrow text-neutral-500 mb-2">
        {label} {isEdited && <span className="text-rouge">● {L("modified")}</span>}
      </label>
      <textarea
        value={value}
        onChange={(e) => setValue(e.target.value)}
        rows={rows || 5}
        maxLength={max}
        placeholder={placeholder}
        className="w-full border border-neutral-300 px-3 py-2 text-sm focus:outline-none focus:border-rouge resize-y font-mono"
      />
      {hint && <div className="font-mono text-[9px] text-neutral-400 mt-1">{hint}</div>}
      {max && <div className="font-mono text-[9px] text-neutral-400 mt-1 text-right">{value.length}/{max}</div>}
      <FieldActions path={combinedPath} defaultText={defaultJoined} currentValue={value} maxLength={max} />
    </div>
  );
}

                                                                                    
                                                                                
                                                                        
                                                                       
                                                                     
                                                           
                                                        
type ArrayOverride<T> = { extras: T[]; removed: number[] };
                                                                             
                                                                           
                                                                           
                                                   
const LEGACY_ARRAY_BRIDGE: Record<string, { extrasKey: string; removedKey?: string; removedPrefix?: string }> = {
  "atelierPage.team": { extrasKey: "abil_atelier_team_extras", removedKey: "abil_atelier_team_removed", removedPrefix: "base-" },
  "atelierPage.timeline": { extrasKey: "abil_atelier_timeline_extras" },
                                                                             
                                                                             
                                                              
};
function getArrayOverride<T>(key: string): ArrayOverride<T> {
  if (typeof window === "undefined") return { extras: [], removed: [] };
  const legacy = LEGACY_ARRAY_BRIDGE[key];
  try {
    if (legacy) {
      const rawExtras = localStorage.getItem(legacy.extrasKey);
      const extras = rawExtras ? JSON.parse(rawExtras) : [];
      let removed: number[] = [];
      if (legacy.removedKey) {
        const rawRemoved = localStorage.getItem(legacy.removedKey);
        const arr: string[] = rawRemoved ? JSON.parse(rawRemoved) : [];
        removed = arr
          .map((s) => (legacy.removedPrefix ? s.replace(legacy.removedPrefix, "") : s))
          .map((s) => Number(s))
          .filter((n) => !Number.isNaN(n));
      }
      return { extras: Array.isArray(extras) ? extras : [], removed };
    }
                                                                                                   
                                                                                             
    const obj = cloudGet<{ extras?: unknown; removed?: unknown }>(`abil_array_${key}`, { extras: [], removed: [] });
    if (!obj) return { extras: [], removed: [] };
    return { extras: Array.isArray(obj.extras) ? (obj.extras as T[]) : [], removed: Array.isArray(obj.removed) ? (obj.removed as number[]) : [] };
  } catch { return { extras: [], removed: [] }; }
}
function setArrayOverride<T>(key: string, ov: ArrayOverride<T>): void {
  if (typeof window === "undefined") return;
  const legacy = LEGACY_ARRAY_BRIDGE[key];
  try {
    if (legacy) {
      localStorage.setItem(legacy.extrasKey, JSON.stringify(ov.extras));
      if (legacy.removedKey) {
        const arr = ov.removed.map((n) => `${legacy.removedPrefix || ""}${n}`);
        localStorage.setItem(legacy.removedKey, JSON.stringify(arr));
      }
                                               
      window.dispatchEvent(new StorageEvent("storage", { key: legacy.extrasKey }));
      if (legacy.removedKey) window.dispatchEvent(new StorageEvent("storage", { key: legacy.removedKey }));
    } else {
                                                                                                      
                                                                                                   
      cloudSet(`abil_array_${key}`, ov);
      window.dispatchEvent(new StorageEvent("storage", { key: `abil_array_${key}` }));
    }
  } catch { /* noop */ }
}
function useExtensibleArray<T>(key: string, defaults: T[]): {
  items: T[];
  defaultsActive: { item: T; defaultIndex: number }[];                           
  extras: T[];
  addItem: (item: T) => void;
  removeDefault: (defaultIndex: number) => void;
  removeExtra: (extraIndex: number) => void;
  updateExtra: (extraIndex: number, item: T) => void;
} {
  const [override, setOverride] = useState<ArrayOverride<T>>(() => getArrayOverride<T>(key));
                                                  
  useEffect(() => {
    const onStorage = (e: StorageEvent) => {
      if (e.key === `abil_array_${key}` || e.key === null) setOverride(getArrayOverride<T>(key));
    };
    window.addEventListener("storage", onStorage);
                                                                                            
                                                                              
    const unsubCloud = LEGACY_ARRAY_BRIDGE[key] ? () => {} : subscribeCloud(`abil_array_${key}`, () => setOverride(getArrayOverride<T>(key)));
    return () => { window.removeEventListener("storage", onStorage); unsubCloud(); };
  }, [key]);
  const persist = (next: ArrayOverride<T>) => { setOverride(next); setArrayOverride<T>(key, next); };
  const removedSet = new Set(override.removed);
  const defaultsActive = defaults
    .map((item, defaultIndex) => ({ item, defaultIndex }))
    .filter((x) => !removedSet.has(x.defaultIndex));
  const items = [...defaultsActive.map((x) => x.item), ...override.extras];
  return {
    items,
    defaultsActive,
    extras: override.extras,
    addItem: (item) => persist({ ...override, extras: [...override.extras, item] }),
    removeDefault: (defaultIndex) => persist({ ...override, removed: [...override.removed, defaultIndex] }),
    removeExtra: (extraIndex) => persist({ ...override, extras: override.extras.filter((_, i) => i !== extraIndex) }),
    updateExtra: (extraIndex, item) => persist({ ...override, extras: override.extras.map((x, i) => (i === extraIndex ? item : x)) }),
  };
}

                                                                                        
