function EditableStringArrayPanel({ legacyKey, basePath, defaults, label, placeholder, textarea, rows, max, addLabel }: {
  legacyKey: string;
  basePath: string;                                                                   
  defaults: string[];
  label: string;
  placeholder?: string;
  textarea?: boolean;
  rows?: number;
  max?: number;
  addLabel?: string;
}) {
  const { lang } = useApp();
  const L = (k: keyof typeof TEXTES_TXT) => _trO(TEXTES_TXT[k], lang);
  const arr = useExtensibleArray<string>(legacyKey, defaults);
  return (
    <div className="space-y-2">
      <div className="eyebrow text-rouge">{label} ({arr.items.length})</div>
      {arr.defaultsActive.map(({ item: s, defaultIndex }) => (
        <div key={`def-${defaultIndex}`} className="flex items-start gap-2">
          <div className="flex-1">
            <EditableField label={`#${defaultIndex + 1}`} path={`${basePath}.${defaultIndex}`} defaultText={s} textarea={textarea} rows={rows} max={max} placeholder={placeholder} />
          </div>
          <button
            type="button"
            onClick={() => { if (window.confirm(L("confirmRemoveItem"))) arr.removeDefault(defaultIndex); }}
            className="mt-7 font-mono text-[10px] uppercase tracking-[0.18em] text-neutral-400 hover:text-rouge px-2"
          >
            </button>
        </div>
      ))}
      {arr.extras.map((s, extraIdx) => (
        <div key={`x-${extraIdx}`} className="flex items-start gap-2 bg-emerald-50/40 p-2">
          <div className="flex-1">
            <label className="block eyebrow text-emerald-600 mb-1">{L("newHashLabel")}{arr.defaultsActive.length + extraIdx + 1}</label>
            {textarea ? (
              <textarea value={s} onChange={(e) => arr.updateExtra(extraIdx, e.target.value)} rows={rows || 2} maxLength={max} placeholder={placeholder} className="w-full border border-neutral-300 px-3 py-2 text-sm focus:outline-none focus:border-rouge resize-y" />
            ) : (
              <input value={s} onChange={(e) => arr.updateExtra(extraIdx, e.target.value)} maxLength={max} placeholder={placeholder} className="w-full border border-neutral-300 px-3 py-2 text-sm focus:outline-none focus:border-rouge" />
            )}
          </div>
          <button type="button" onClick={() => arr.removeExtra(extraIdx)} className="mt-7 font-mono text-[10px] uppercase tracking-[0.18em] text-neutral-400 hover:text-rouge px-2"></button>
        </div>
      ))}
      <button
        type="button"
        onClick={() => arr.addItem("")}
        className="w-full border border-dashed border-neutral-300 hover:border-rouge hover:bg-rouge/5 px-3 py-2 eyebrow text-neutral-500 hover:text-rouge transition-colors"
      >
        + {addLabel || L("addItemDefault")}
      </button>
    </div>
  );
}

                                                                      
                                                                              
                                                                       
type TeamMember = { nome: string; cargo: string; bio: string; foto: string; video?: string };
function AtelierTeamSection({ p }: { p: any }) {
  const { lang } = useApp();
  const L = (k: keyof typeof TEXTES_TXT) => _trO(TEXTES_TXT[k], lang);
  const team = useExtensibleArray<TeamMember>("atelierPage.team", (p.team || []) as TeamMember[]);
  return (
    <PageSectionShell
      eyebrow={L("teamEyebrow")}
      title={L("teamCount").replace("{n}", String(team.items.length))}
      preview={
        <div className="bg-transparent p-8">
          <div className="eyebrow text-rouge mb-2">{p.teamLabel}</div>
          <h3 className="h1-section mb-2">{p.teamTitle}</h3>
          <p className="text-sm text-neutral-600">{p.teamIntro}</p>
          <div className="grid grid-cols-3 gap-2 mt-4">
            {team.items.slice(0, 6).map((m, i) => (
              <div key={i} className="text-xs"><div className="font-semibold">{m.nome || L("noName")}</div><div className="text-neutral-500">{m.cargo}</div></div>
            ))}
          </div>
        </div>
      }
    >
      <EditableField label={L("fldTeamLabel")} path="atelierPage.teamLabel" defaultText={p.teamLabel || ""} max={40} />
      <EditableField label={L("fldTeamTitle")} path="atelierPage.teamTitle" defaultText={p.teamTitle || ""} max={60} />
      <EditableField label={L("fldTeamIntro")} path="atelierPage.teamIntro" defaultText={p.teamIntro || ""} textarea rows={3} max={300} />
      {team.defaultsActive.map(({ item: m, defaultIndex }) => (
        <div key={`def-${defaultIndex}`} className="border-l-2 border-rouge pl-4 space-y-2 relative">
          <div className="flex items-center justify-between">
            <div className="eyebrow text-rouge">{L("memberPrefix")} {m.nome || L("noName")}</div>
            <button
              type="button"
              onClick={() => { if (window.confirm(L("confirmRemoveMember").replace("{name}", String(m.nome)))) team.removeDefault(defaultIndex); }}
              className="font-mono text-[10px] uppercase tracking-[0.18em] text-neutral-400 hover:text-rouge"
            >
              {L("btnRemoveWord")}
            </button>
          </div>
          <EditableField label={L("fldName")} path={`atelierPage.team.${defaultIndex}.nome`} defaultText={m.nome || ""} max={60} />
          <EditableField label={L("fldRole")} path={`atelierPage.team.${defaultIndex}.cargo`} defaultText={m.cargo || ""} max={80} />
          <EditableField label={L("fldBio")} path={`atelierPage.team.${defaultIndex}.bio`} defaultText={m.bio || ""} textarea rows={2} max={200} />
          <EditableImageField label={L("fldPhoto")} path={`atelierPage.team.${defaultIndex}.foto`} defaultSrc={m.foto || ""} aspectClass="w-24 aspect-square" />
        </div>
      ))}
      {team.extras.map((m, extraIdx) => (
        <div key={`x-${extraIdx}`} className="border-l-2 border-emerald-500 pl-4 space-y-2 bg-emerald-50/40 p-3">
          <div className="flex items-center justify-between">
            <div className="eyebrow text-emerald-600">{L("newDotPrefix")} {m.nome || L("noName")}</div>
            <button
              type="button"
              onClick={() => { if (window.confirm(L("confirmRemoveAddedMember"))) team.removeExtra(extraIdx); }}
              className="font-mono text-[10px] uppercase tracking-[0.18em] text-neutral-400 hover:text-rouge"
            >
              {L("btnRemoveWord")}
            </button>
          </div>
          <div>
            <label className="block eyebrow text-neutral-500 mb-2">{L("fldName")}</label>
            <input value={m.nome} onChange={(e) => team.updateExtra(extraIdx, { ...m, nome: e.target.value })} className="w-full border border-neutral-300 px-3 py-2 text-sm" />
          </div>
          <div>
            <label className="block eyebrow text-neutral-500 mb-2">{L("fldRole")}</label>
            <input value={m.cargo} onChange={(e) => team.updateExtra(extraIdx, { ...m, cargo: e.target.value })} className="w-full border border-neutral-300 px-3 py-2 text-sm" />
          </div>
          <div>
            <label className="block eyebrow text-neutral-500 mb-2">{L("fldBio")}</label>
            <textarea value={m.bio} onChange={(e) => team.updateExtra(extraIdx, { ...m, bio: e.target.value })} rows={2} className="w-full border border-neutral-300 px-3 py-2 text-sm" />
          </div>
          <div>
            <label className="block eyebrow text-neutral-500 mb-2">{L("fldPhotoUrl")}</label>
            <input value={m.foto} onChange={(e) => team.updateExtra(extraIdx, { ...m, foto: e.target.value })} placeholder={L("phPhotoUrl")} className="w-full border border-neutral-300 px-3 py-2 text-sm font-mono" />
          </div>
        </div>
      ))}
      <button
        type="button"
        onClick={() => team.addItem({ nome: L("newMemberName"), cargo: L("fldRole"), bio: L("newMemberBio"), foto: "" })}
        className="w-full border-2 border-dashed border-neutral-300 hover:border-rouge hover:bg-rouge/5 px-3 py-3 eyebrow text-neutral-500 hover:text-rouge transition-colors"
      >
        {L("btnAddMember")}
      </button>
    </PageSectionShell>
  );
}

type TimelineEntry = { ano: string; titulo: string; desc: string };
function AtelierTimelineSection({ p }: { p: any }) {
  const { lang } = useApp();
  const L = (k: keyof typeof TEXTES_TXT) => _trO(TEXTES_TXT[k], lang);
  const tl = useExtensibleArray<TimelineEntry>("atelierPage.timeline", (p.timeline || []) as TimelineEntry[]);
  return (
    <PageSectionShell
      eyebrow={L("timelineEyebrow")}
      title={L("timelineCount").replace("{n}", String(tl.items.length))}
      preview={
        <div className="bg-transparent p-8">
          <div className="eyebrow text-rouge mb-2">{p.historyLabel}</div>
          <h3 className="h1-section mb-3">{p.historyTitle}</h3>
          <div className="space-y-2 max-h-48 overflow-y-auto">
            {tl.items.slice(0, 5).map((e, i) => (
              <div key={i} className="text-xs"><span className="font-bold">{e.ano}</span> · {e.titulo}</div>
            ))}
          </div>
        </div>
      }
    >
      <EditableField label={L("fldHistoryLabel")} path="atelierPage.historyLabel" defaultText={p.historyLabel || ""} max={40} />
      <EditableField label={L("fldHistoryTitle")} path="atelierPage.historyTitle" defaultText={p.historyTitle || ""} max={60} />
      {tl.defaultsActive.map(({ item: e, defaultIndex }) => (
        <div key={`def-${defaultIndex}`} className="border-l-2 border-rouge pl-4 space-y-2">
          <div className="flex items-center justify-between">
            <div className="eyebrow text-rouge">{L("milestonePrefix")} {e.ano}</div>
            <button
              type="button"
              onClick={() => { if (window.confirm(L("confirmRemoveMilestone").replace("{ano}", String(e.ano)))) tl.removeDefault(defaultIndex); }}
              className="font-mono text-[10px] uppercase tracking-[0.18em] text-neutral-400 hover:text-rouge"
            >
              {L("btnRemoveWord")}
            </button>
          </div>
          <div className="grid grid-cols-3 gap-2">
            <EditableField label={L("fldYear")} path={`atelierPage.timeline.${defaultIndex}.ano`} defaultText={e.ano || ""} max={6} />
            <div className="col-span-2"><EditableField label={L("fldTitle")} path={`atelierPage.timeline.${defaultIndex}.titulo`} defaultText={e.titulo || ""} max={80} /></div>
          </div>
          <EditableField label={L("fldDesc")} path={`atelierPage.timeline.${defaultIndex}.desc`} defaultText={e.desc || ""} textarea rows={2} max={400} />
        </div>
      ))}
      {tl.extras.map((e, extraIdx) => (
        <div key={`x-${extraIdx}`} className="border-l-2 border-emerald-500 pl-4 space-y-2 bg-emerald-50/40 p-3">
          <div className="flex items-center justify-between">
            <div className="eyebrow text-emerald-600">{L("newDotPrefix")} {e.ano}</div>
            <button type="button" onClick={() => { if (window.confirm(L("confirmRemoveAddedMilestone"))) tl.removeExtra(extraIdx); }} className="font-mono text-[10px] uppercase tracking-[0.18em] text-neutral-400 hover:text-rouge">{L("btnRemoveWord")}</button>
          </div>
          <div className="grid grid-cols-3 gap-2">
            <input value={e.ano} onChange={(ev) => tl.updateExtra(extraIdx, { ...e, ano: ev.target.value })} placeholder={L("fldYear")} className="border border-neutral-300 px-3 py-2 text-sm" />
            <input value={e.titulo} onChange={(ev) => tl.updateExtra(extraIdx, { ...e, titulo: ev.target.value })} placeholder={L("fldTitle")} className="col-span-2 border border-neutral-300 px-3 py-2 text-sm" />
          </div>
          <textarea value={e.desc} onChange={(ev) => tl.updateExtra(extraIdx, { ...e, desc: ev.target.value })} placeholder={L("fldDesc")} rows={2} className="w-full border border-neutral-300 px-3 py-2 text-sm" />
        </div>
      ))}
      <button
        type="button"
        onClick={() => tl.addItem({ ano: String(new Date().getFullYear()), titulo: L("newMilestoneTitle"), desc: L("newMilestoneDesc") })}
        className="w-full border-2 border-dashed border-neutral-300 hover:border-rouge hover:bg-rouge/5 px-3 py-3 eyebrow text-neutral-500 hover:text-rouge transition-colors"
      >
        {L("btnAddMilestone")}
      </button>
    </PageSectionShell>
  );
}

