type SiteV3RegItem = { def: string; max: number; tipo: "txt" | "img" | "href" };

function lerRegistoV3(): Record<string, SiteV3RegItem> | null {
  try {
    const raw = localStorage.getItem("abil_v3_registo_v1");
    const j = raw ? JSON.parse(raw) : null;
    if (j && typeof j === "object" && !Array.isArray(j) && Object.keys(j).length > 0) {
      return j as Record<string, SiteV3RegItem>;
    }
  } catch { /* Treat blocked localStorage or invalid JSON as empty. */ }
  return null;
}

