function DashboardEquipaModule() {
  const { showToast } = useApp();
  const [team, setTeam] = useDashTeam();
  const [aSubir, setASubir] = useState<string | null>(null);

  const mudar = (id: string, campo: "name" | "role", v: string) =>
    setTeam((prev) => prev.map((m) => (m.id === id ? { ...m, [campo]: v } : m)));

  const trocarFoto = async (id: string, f: File) => {
    setASubir(id);
    try {
      const { cloudUploadFile } = await import("@/lib/cloudProjects");
      const up = await cloudUploadFile(f, { prefix: "equipa" });
      if (up.ok && up.url) {
        setTeam((prev) => prev.map((m) => (m.id === id ? { ...m, photo: up.url } : m)));
        showToast("Foto atualizada");
      } else showToast("Não consegui subir a foto");
    } catch { showToast("Não consegui subir a foto"); }
    setASubir(null);
  };

  const adicionar = () =>
    setTeam((prev) => [...prev, { id: `tm-${Date.now()}`, name: "", role: "" }]);
  const remover = (id: string) => {
    if (!window.confirm("Remover este membro da equipa?")) return;
    setTeam((prev) => prev.filter((m) => m.id !== id));
  };
  const mover = (id: string, d: number) =>
    setTeam((prev) => {
      const i = prev.findIndex((m) => m.id === id);
      const j = i + d;
      if (i < 0 || j < 0 || j >= prev.length) return prev;
      const n = prev.slice();
      n.splice(j, 0, n.splice(i, 1)[0]);
      return n;
    });

                                                                                                                                                            
                                                                               
                                                                                  
                                                                                
                                                                              
                                                                      
                                                   
                                                                                 
                                                                                 
                                      
  const [aPublicar, setAPublicar] = useState(false);
  const LINGUAS = ["fr", "en", "pt", "de", "it"] as const;
  const slugDoMembro = (nome: string, usados: Set<string>) => {
    const base = (nome.trim().split(/\s+/)[0] || "membro")
      .toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-z0-9]/g, "") || "membro";
    let s2 = base, n = 2;
    while (usados.has(s2)) { s2 = `${base}${n}`; n += 1; }
    usados.add(s2);
    return s2;
  };
  const publicarNoSite = async () => {
    const tok = (() => { try { return window.localStorage.getItem("abil_vault_token") || ""; } catch { return ""; } })();
    if (!tok) { showToast("Entra primeiro no cofre: o site só aceita alterações autenticadas."); return; }
    const membros = team.filter((m) => (m.name || "").trim());
    if (!membros.length) { showToast("Não há ninguém para publicar."); return; }
    setAPublicar(true);
    try {
      const CHAVE = "abil_site_edits_inline";
      const doc = await fetch(`/api/store?key=${CHAVE}`, { cache: "no-store" }).then((r) => (r.ok ? r.json() : null)).catch(() => null);
      const mapa: Record<string, string> = (doc && doc.value && typeof doc.value === "object" && !Array.isArray(doc.value)) ? { ...doc.value } : {};
      const usados = new Set<string>();
      const lista = membros.map((m) => {
        const partes = m.name.trim().split(/\s+/);
        const slug = slugDoMembro(m.name, usados);
        const first = partes[0];
        const last = partes.slice(1).join(" ");
        mapa[`v3.agence.team.${slug}.first`] = first;
        mapa[`v3.agence.team.${slug}.last`] = last;
        mapa[`v3.agence.team.${slug}.role`] = m.role || "";
        if (m.photo) mapa[`v3.agence.team.${slug}.img`] = m.photo;
        return { slug, first, last, photo: m.photo || "", role: m.role || "" };
      });
      mapa["v3.agence.team.lista"] = JSON.stringify(lista);
                                                                
      let traduzidos = 0;
      await Promise.all(lista.flatMap((m) => (m.role ? LINGUAS.filter((l) => l !== "fr").map(async (alvo) => {
        try {
          const r = await fetch("/api/translate", {
            method: "POST",
            headers: { "Content-Type": "application/json", "x-abil-admin": tok },
            body: JSON.stringify({ text: m.role, from: "fr", to: alvo }),
          });
          if (!r.ok) return;
          const j = await r.json().catch(() => null);
          const t = String(j?.translated || "").trim();
          if (t) { mapa[`v3.agence.team.${m.slug}.role__${alvo}`] = t; traduzidos += 1; }
        } catch {                                       }
      }) : [])));
      const r = await fetch("/api/store", {
        method: "POST",
        headers: { "Content-Type": "application/json", "x-abil-admin": tok },
        body: JSON.stringify({ updates: [{ key: CHAVE, value: mapa }] }),
      });
      if (!r.ok) { showToast(`O site não aceitou a publicação (HTTP ${r.status}).`); return; }
      showToast(`Publicado: ${lista.length} pessoas na página do site${traduzidos ? `, ${traduzidos} cargos traduzidos` : ""}.`);
    } catch (e) {
      showToast(`Não consegui publicar: ${String((e as Error)?.message || e).slice(0, 80)}`);
    } finally { setAPublicar(false); }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-end justify-between gap-4 flex-wrap">
        <div>
          <h2 className="text-2xl font-semibold tracking-[-0.02em]">Equipa</h2>
          <p className="text-sm text-neutral-500 mt-1 max-w-2xl">
            Nome, cargo e fotografia de cada pessoa. Alimenta de imediato a assinatura
            dos artigos do blog e as etiquetas de equipa nas fichas de projeto. Para
            a página “A Equipa” do site mudar, carrega em <strong>Publicar no site</strong>:
            é aí que a lista, as fotos e os cargos (traduzidos para as cinco línguas)
            vão para o ar.
          </p>
        </div>
        <div className="flex items-center gap-2">
          <button type="button" onClick={adicionar}
            className="bg-white border-2 border-noir text-noir px-4 py-2.5 eyebrow inline-flex items-center gap-2 hover:bg-neutral-50">
            <IconPlus className="w-3.5 h-3.5" /> Adicionar membro
          </button>
          <button type="button" onClick={() => void publicarNoSite()} disabled={aPublicar}
            className="bg-noir text-white px-4 py-2.5 eyebrow inline-flex items-center gap-2 disabled:opacity-50">
            {aPublicar ? "A publicar…" : "Publicar no site"}
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-4">
        {team.map((m, i) => (
          <div key={m.id} className="border border-neutral-200 bg-white p-3 flex flex-col gap-3">
            <div className="relative bg-neutral-100" style={{ aspectRatio: "241 / 362" }}>
              {m.photo ? (
                <img src={m.photo} alt={m.name} className="w-full h-full object-cover" />
              ) : (
                <div className="w-full h-full flex items-center justify-center text-neutral-400 text-xs">
                  sem foto
                </div>
              )}
              <label className="absolute bottom-2 left-2 bg-noir text-white px-2.5 py-1.5 eyebrow text-[9px] cursor-pointer">
                {aSubir === m.id ? "A subir…" : "Trocar foto"}
                <input type="file" accept="image/*" className="hidden"
                  onChange={(e) => { const f = e.target.files?.[0]; if (f) void trocarFoto(m.id, f); e.target.value = ""; }} />
              </label>
            </div>
            <input value={m.name} onChange={(e) => mudar(m.id, "name", e.target.value)}
              placeholder="Nome" className="border border-neutral-200 px-3 py-2 text-sm" />
            <input value={m.role} onChange={(e) => mudar(m.id, "role", e.target.value)}
              placeholder="Cargo" className="border border-neutral-200 px-3 py-2 text-sm" />
            <div className="flex items-center gap-1">
              <button type="button" onClick={() => mover(m.id, -1)} disabled={i === 0}
                className="w-8 h-8 border border-neutral-200 disabled:opacity-30" title="Subir">↑</button>
              <button type="button" onClick={() => mover(m.id, 1)} disabled={i === team.length - 1}
                className="w-8 h-8 border border-neutral-200 disabled:opacity-30" title="Descer">↓</button>
              <span className="flex-1" />
              <button type="button" onClick={() => remover(m.id)}
                className="w-8 h-8 border border-neutral-200 text-rouge" title="Remover">×</button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

function DashboardPagesModule() {
  const { lang, edits, setEdit, removeEdit, saveEdits, showToast } = useApp();
  const L = (k: keyof typeof PAGESV3_TXT) => _trO(PAGESV3_TXT[k], lang);
                                                                                  
  const [pageEdits] = useCloudState<Record<string, string>>(PAGE_LAST_EDIT_KEY, {});
  const fmtEdit = (iso?: string) => { if (!iso) return null; const d = new Date(iso); return Number.isNaN(d.getTime()) ? null : d.toLocaleDateString("fr-CH"); };
  const hideKey = (id: string) => `v3.cfg.nav.hide.${id}`;
  const isHidden = (id: string) => edits[hideKey(id)] === "1";
  const hideable = PAGESV3_ROWS.filter((p) => p.hideable);
  const hiddenCount = hideable.filter((p) => isHidden(p.id)).length;
  const lastIso = PAGESV3_ROWS.map((p) => pageEdits[`v3-${p.id}`]).filter(Boolean).sort().pop() || "";
  const toggle = (id: string) => {
                                                                                 
    if (isHidden(id)) removeEdit(hideKey(id));
    else setEdit(hideKey(id), "1");
    showToast(`* ${L("toastPending")}`);
  };

  return (
    <div className="space-y-4">
      <div className="grid grid-cols-12 gap-4">
        <div className="col-span-4"><DashboardCard title={L("kpiPages")} value={String(PAGESV3_ROWS.length)} delta={L("kpiPagesHint")} neutral /></div>
        <div className="col-span-4"><DashboardCard title={L("kpiHidden")} value={`${hiddenCount}/${hideable.length}`} delta={L("kpiHiddenHint")} neutral /></div>
        <div className="col-span-4"><DashboardCard title={L("kpiLastEdit")} value={fmtEdit(lastIso) ?? L("neverEdited")} neutral /></div>
      </div>

      {                                                                       }
      <div className="bg-neutral-50 border border-neutral-200 px-6 py-3 flex items-center gap-3 flex-wrap">
        <span className="eyebrow text-rouge flex-shrink-0">*</span>
        <p className="text-xs text-neutral-600 m-0 flex-1 min-w-[240px]">{L("noteHide")}</p>
        <button
          onClick={() => saveEdits()}
          className="bg-rouge text-white px-4 py-2 eyebrow hover:bg-noir transition-colors flex-shrink-0"
        >
          {L("btnSave")}
        </button>
      </div>

      <div className="bg-white border border-neutral-200">
        <table className="w-full">
          <thead>
            <tr className="border-b border-neutral-200 bg-neutral-50">
              <th className="text-left px-6 py-3 eyebrow text-neutral-500">{L("colPage")}</th>
              <th className="text-left px-6 py-3 eyebrow text-neutral-500">{L("colUrl")}</th>
              <th className="text-left px-6 py-3 eyebrow text-neutral-500">{L("colLastEdit")}</th>
              <th className="text-right px-6 py-3 eyebrow text-neutral-500">{L("colNav")}</th>
            </tr>
          </thead>
          <tbody>
            {PAGESV3_ROWS.map((p) => {
              const hidden = isHidden(p.id);
              const when = fmtEdit(pageEdits[`v3-${p.id}`]);
              return (
                <tr key={p.id} className="border-b border-neutral-100 hover:bg-neutral-50">
                  <td className="px-6 py-4">
                    <div className="font-medium text-noir">
                      {_trO(p.label, lang)} {hidden && <span className="ml-2 eyebrow text-rouge">* {L("badgeHidden")}</span>}
                    </div>
                    {p.sub && <div className="font-mono text-[10px] text-neutral-400 mt-0.5">{L(p.sub)}</div>}
                  </td>
                  <td className="px-6 py-4 font-mono text-[11px]">
                    <a href={p.url} target="_blank" rel="noopener noreferrer" className="text-neutral-500 hover:text-rouge hover:underline">{p.url} ↗</a>
                  </td>
                  <td className="px-6 py-4 font-mono text-[11px] text-neutral-500">{when ?? L("neverEdited")}</td>
                  <td className="px-6 py-4 text-right">
                    {p.hideable ? (
                                                                                   
                                                                                
                      <span style={{ display: "inline-flex", alignItems: "center", gap: 10 }}>
                        <span className="font-mono text-[10px] uppercase tracking-[0.14em] text-neutral-500">
                          {hidden ? L("notInNav") : L("inNav")}
                        </span>
                        <button
                          type="button"
                          role="switch"
                          aria-checked={!hidden}
                          aria-label={hidden ? L("btnShow") : L("btnHide")}
                          onClick={() => toggle(p.id)}
                          style={{ width: 44, height: 24, borderRadius: 999, border: "1px solid var(--ad-noir, #0a0a0b)", background: hidden ? "transparent" : "var(--ad-acao, #d2ff01)", position: "relative", cursor: "pointer", padding: 0, transition: "background .18s" }}
                        >
                          <span style={{ position: "absolute", top: 2, left: hidden ? 2 : 22, width: 18, height: 18, borderRadius: 999, background: "var(--ad-noir, #0a0a0b)", transition: "left .18s" }} />
                        </button>
                      </span>
                    ) : (
                      <span className="font-mono text-[10px] text-neutral-400">{p.id === "home" ? L("alwaysNav") : L("notInNav")}</span>
                    )}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
        <div className="px-6 py-3 border-t border-neutral-100 font-mono text-[10px] text-neutral-400">{L("noteDates")}</div>
      </div>
    </div>
  );
}

                                                                                                                                          
                                                            
                            
                                                                               
                                                                           
                                                                         
                              
                                                                                
                                                                             
                                                                               
                                        
                                                                                
                                                         
                                                                               
                                                                          
                                                          
                                                                                                                                             

const LANGSV3_TXT = {
  kpiTotal: { fr: "Langues du site", pt: "Línguas do site", en: "Site languages", de: "Sprachen der Website", it: "Lingue del sito" },
  kpiTotalHint: { fr: "FR EN PT DE IT", pt: "FR EN PT DE IT", en: "FR EN PT DE IT", de: "FR EN PT DE IT", it: "FR EN PT DE IT" },
  kpiOff: { fr: "Désactivées", pt: "Desligadas", en: "Switched off", de: "Abgeschaltet", it: "Disattivate" },
  kpiOffHint: { fr: "hors sélecteur du site", pt: "fora do seletor do site", en: "out of the site selector", de: "aus dem Sprachwähler der Website", it: "fuori dal selettore del sito" },
  kpiEdited: { fr: "Textes édités", pt: "Textos editados", en: "Edited texts", de: "Bearbeitete Texte", it: "Testi modificati" },
  kpiEditedHint: { fr: "base de la couverture", pt: "base da cobertura", en: "coverage base", de: "Basis der Abdeckung", it: "base della copertura" },
  secTitle: { fr: "Langues du site (V3)", pt: "Línguas do site (V3)", en: "Site languages (V3)", de: "Sprachen der Website (V3)", it: "Lingue del sito (V3)" },
  secSub: { fr: "Désactiver une langue la retire du sélecteur et de l'overlay des 3 surfaces; un visiteur dont la langue active est désactivée bascule en FR. Sauver pour publier.", pt: "Desligar uma língua tira-a do seletor e do overlay das 3 superfícies; um visitante com essa língua ativa cai para FR. Guardar para publicar.", en: "Switching a language off removes it from the selector and the overlay of the 3 surfaces; a visitor using that language falls back to FR. Save to publish.", de: "Wird eine Sprache abgeschaltet, verschwindet sie aus dem Sprachwähler und dem Overlay der 3 Flächen; Besucher mit dieser Sprache fallen auf FR zurück. Speichern zum Veröffentlichen.", it: "Disattivare una lingua la toglie dal selettore e dall'overlay delle 3 superfici; un visitatore con quella lingua attiva passa al FR. Salva per pubblicare." },
  frLocked: { fr: "langue socle: repli du site, jamais désactivable", pt: "língua de rede: fallback do site, nunca se desliga", en: "base language: site fallback, never switched off", de: "Basissprache: Rückfallebene der Website, nie abschaltbar", it: "lingua base: ripiego del sito, mai disattivabile" },
  coverageOf: { fr: "textes édités avec version enregistrée dans cette langue", pt: "textos editados com versão gravada nesta língua", en: "edited texts with a saved version in this language", de: "bearbeitete Texte mit gespeicherter Fassung in dieser Sprache", it: "testi modificati con versione salvata in questa lingua" },
  coverageNote: { fr: "La couverture compte les versions enregistrées dans le tiroir d'édition (suffixe de langue). Les versions semées automatiquement (dictionnaire, puis IA) comptent aussi: relisez chaque langue avant de la considérer publiée.", pt: "A cobertura conta as versões gravadas na gaveta de edição (sufixo de língua). As versões semeadas automaticamente (dicionário, depois IA) também contam: convém rever cada língua antes de a dar por publicada.", en: "Coverage counts the versions saved in the edits drawer (language suffix). Automatically seeded versions (dictionary, then AI) also count: review each language before considering it published.", de: "Die Abdeckung zählt die im Bearbeitungsspeicher gespeicherten Fassungen (Sprachsuffix). Automatisch gefüllte Fassungen (Wörterbuch, dann KI) zählen mit: jede Sprache vor der Veröffentlichung prüfen.", it: "La copertura conta le versioni salvate nel cassetto delle modifiche (suffisso di lingua). Le versioni seminate automaticamente (dizionario, poi IA) contano anch'esse: rileggere ogni lingua prima di considerarla pubblicata." },
  emptyReg: { fr: "Inventaire vide: ouvrez le site une fois dans ce navigateur pour que la V3 publie la liste de ses textes; la couverture réelle apparaîtra ici. Rien n'est estimé.", pt: "Inventário vazio: abra o site uma vez neste browser para a V3 publicar a lista dos seus textos; a cobertura real aparece aqui. Nada é estimado.", en: "Empty inventory: open the site once in this browser so the V3 publishes the list of its texts; the real coverage will appear here. Nothing is estimated.", de: "Leeres Inventar: Website einmal in diesem Browser öffnen, damit die V3 die Liste ihrer Texte veröffentlicht; die echte Abdeckung erscheint hier. Nichts wird geschätzt.", it: "Inventario vuoto: aprire il sito una volta in questo browser perché la V3 pubblichi l'elenco dei suoi testi; la copertura reale apparirà qui. Nulla è stimato." },
  btnOff: { fr: "Désactiver", pt: "Desligar", en: "Switch off", de: "Abschalten", it: "Disattiva" },
  btnOn: { fr: "Réactiver", pt: "Religar", en: "Switch on", de: "Einschalten", it: "Riattiva" },
  badgeOff: { fr: "désactivée", pt: "desligada", en: "off", de: "abgeschaltet", it: "disattivata" },
  btnSave: { fr: "Sauver", pt: "Guardar", en: "Save", de: "Speichern", it: "Salva" },
  toastPending: { fr: "Sauver pour publier.", pt: "Guardar para publicar.", en: "Save to publish.", de: "Speichern zum Veröffentlichen.", it: "Salva per pubblicare." },
  panelTitle: { fr: "Sélecteur du panneau /admin (moteur)", pt: "Seletor do painel /admin (motor)", en: "/admin panel selector (engine)", de: "Sprachwähler des /admin-Panels (Motor)", it: "Selettore del pannello /admin (motore)" },
                                                                                 
                                                                               
  panelSub: { fr: "Ces interrupteurs choisissent les langues visibles dans ce panneau, pour vous. Les langues du site public se règlent avec les interrupteurs ci-dessus.", pt: "Estes interruptores escolhem as línguas visíveis neste painel, para si. As línguas do site público regulam-se com os interruptores acima.", en: "These switches choose the languages visible in this panel, for you. The public site languages are set with the switches above.", de: "Diese Schalter wählen die Sprachen, die in diesem Panel für Sie sichtbar sind. Die Sprachen der öffentlichen Website stellen Sie mit den Schaltern oben ein.", it: "Questi interruttori scelgono le lingue visibili in questo pannello, per lei. Le lingue del sito pubblico si regolano con gli interruttori qui sopra." },
};

                                                                               
const LANGSV3_ROWS: { code: Lang; label: string; flag: string }[] = [
  { code: "fr" as Lang, label: "Français", flag: "" },
  { code: "en" as Lang, label: "English", flag: "" },
  { code: "pt" as Lang, label: "Português", flag: "" },
  { code: "de" as Lang, label: "Deutsch", flag: "" },
  { code: "it" as Lang, label: "Italiano", flag: "" },
];

function DashboardLanguagesModule() {
  const { lang: uiLang, edits, setEdit, removeEdit, saveEdits, showToast } = useApp();
  const L = (k: keyof typeof LANGSV3_TXT) => _trO(LANGSV3_TXT[k], uiLang);
                                                                                                              
  const langsSaveFail = _trO({ pt: "Não guardei no servidor: sessão expirada ou sem rede. O idioma voltou ao estado anterior; faz login e tenta de novo.", fr: "Non enregistré sur le serveur : session expirée ou hors ligne. La langue est revenue à l'état précédent ; reconnectez-vous et réessayez.", en: "Not saved on the server: session expired or offline. The language was reverted; log in again and retry.", de: "Nicht auf dem Server gespeichert: Sitzung abgelaufen oder offline. Die Sprache wurde zurückgesetzt; erneut anmelden und noch einmal versuchen.", it: "Non salvato sul server: sessione scaduta o offline. La lingua è tornata allo stato precedente; rifai il login e riprova." }, uiLang);
  const { isEnabled, toggle: toggleEnabled } = useEnabledLanguages();

                                                                                
                                                                                  
                                                                              
                                                  
  const registo = useMemo(() => lerRegistoV3(), []);
  const [cloudRaw] = useCloudState<Record<string, string>>("abil_site_edits_inline", {});
  const raw = useMemo<Record<string, string>>(() => {
    let local: Record<string, string> = {};
    try {
      const b = localStorage.getItem("abil_site_edits_inline");
      const j = b ? JSON.parse(b) : null;
      if (j && typeof j === "object" && !Array.isArray(j)) local = j as Record<string, string>;
    } catch { /* If local storage is unreadable, count only cloud values. */ }
    return { ...local, ...(cloudRaw && typeof cloudRaw === "object" ? cloudRaw : {}) };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [cloudRaw, edits]);
  const paths = useMemo(() => (registo ? Object.keys(registo) : []), [registo]);
  const editedBase = useMemo(
    () => paths.filter((p) => typeof raw[p] === "string" || LANGSV3_ROWS.some((l) => typeof raw[`${p}__${l.code}`] === "string")).length,
    [paths, raw]
  );
  const coverage = (code: Lang) => paths.filter((p) => typeof raw[`${p}__${code}`] === "string").length;

                                                                
  const offKey = (code: Lang) => `v3.cfg.langs.off.${code}`;
  const isOff = (code: Lang) => code !== "fr" && edits[offKey(code)] === "1";
  const offCount = LANGSV3_ROWS.filter((l) => isOff(l.code)).length;
  const toggleSite = (code: Lang) => {
    if (code === "fr") return;
    if (isOff(code)) removeEdit(offKey(code));
    else setEdit(offKey(code), "1");
    showToast(`* ${L("toastPending")}`);
  };

  return (
    <div className="space-y-4">
      <div className="grid grid-cols-12 gap-4">
        <div className="col-span-4"><DashboardCard title={L("kpiTotal")} value={String(LANGSV3_ROWS.length)} delta={L("kpiTotalHint")} neutral /></div>
        <div className="col-span-4"><DashboardCard title={L("kpiOff")} value={`${offCount}/4`} delta={L("kpiOffHint")} neutral /></div>
        <div className="col-span-4"><DashboardCard title={L("kpiEdited")} value={registo ? String(editedBase) : "N/D"} delta={L("kpiEditedHint")} neutral /></div>
      </div>

      <div className="bg-white border border-neutral-200">
        <div className="px-6 py-4 border-b border-neutral-200 flex items-start justify-between gap-3 flex-wrap">
          <div className="min-w-[240px] flex-1">
            <div className="eyebrow text-rouge">{L("secTitle")}</div>
            <p className="text-xs text-neutral-600 mt-1 m-0">{L("secSub")}</p>
          </div>
          <button
            onClick={() => saveEdits()}
            className="bg-rouge text-white px-4 py-2 eyebrow hover:bg-noir transition-colors flex-shrink-0"
          >
            {L("btnSave")}
          </button>
        </div>
        <ul className="divide-y divide-neutral-100">
          {LANGSV3_ROWS.map((l) => {
            const off = isOff(l.code);
            return (
              <li key={l.code} className="px-6 py-4 flex items-center gap-4">
                <div className="text-2xl">{l.flag}</div>
                <div className="flex-1 min-w-0">
                  <div className="font-medium text-sm">
                    {l.label} <span className="font-mono text-[10px] text-neutral-400 uppercase ml-1">{l.code}</span>
                    {off && <span className="ml-2 eyebrow text-rouge">* {L("badgeOff")}</span>}
                  </div>
                  <div className="font-mono text-[10px] text-neutral-500 mt-0.5">
                    {registo ? `${coverage(l.code)} / ${editedBase} ${L("coverageOf")}` : L("emptyReg")}
                  </div>
                </div>
                {l.code === "fr" ? (
                  <span className="font-mono text-[10px] text-neutral-400 text-right max-w-[220px]">{L("frLocked")}</span>
                ) : (
                  <button
                    onClick={() => toggleSite(l.code)}
                    className={`eyebrow px-3 py-1.5 border transition-colors flex-shrink-0 ${off ? "bg-noir text-white border-noir hover:bg-rouge hover:border-rouge" : "border-neutral-200 text-neutral-600 hover:border-rouge hover:text-rouge"}`}
                  >
                    {off ? L("btnOn") : L("btnOff")}
                  </button>
                )}
              </li>
            );
          })}
        </ul>
        <div className="px-6 py-3 border-t border-neutral-100 font-mono text-[10px] text-neutral-400">
          {L("coverageNote")}
        </div>
      </div>

      {                                                                           }
      <div className="bg-white border border-neutral-200">
        <div className="px-6 py-4 border-b border-neutral-200">
          <div className="eyebrow text-neutral-500">{L("panelTitle")}</div>
          <p className="text-xs text-neutral-600 mt-1 m-0">{L("panelSub")}</p>
        </div>
        <ul className="divide-y divide-neutral-100">
          {LANGSV3_ROWS.map((l) => {
            const on = isEnabled(l.code);
            const isFr = l.code === "fr";
            return (
              <li key={l.code} className="px-6 py-3 flex items-center gap-4">
                <div className="font-medium text-sm flex-1">{l.label} <span className="font-mono text-[10px] text-neutral-400 uppercase ml-1">{l.code}</span></div>
                <button
                  onClick={() => { if (!isFr) void toggleEnabled(l.code).then((ok) => { if (!ok) showToast(langsSaveFail); }); }}
                  className={`flex-shrink-0 w-10 h-5 rounded-full p-0.5 transition-colors ${on ? "bg-emerald-500" : "bg-neutral-300"} ${isFr ? "opacity-50 cursor-not-allowed" : ""}`}
                  aria-label={l.label}
                >
                  <div className={`w-4 h-4 rounded-full bg-white transition-transform ${on ? "translate-x-5" : ""}`} />
                </button>
              </li>
            );
          })}
        </ul>
      </div>
    </div>
  );
}

                                                                                        
                                                                                                   
                                                                                     
                                                                                                     
                                                                                         
                                                                                            
