  defaultLabel: { fr: "Texte du code (FR)", pt: "Texto do código (FR)", en: "Code text (FR)", de: "Text im Code (FR)", it: "Testo nel codice (FR)" },
  badgeEdited: { fr: "édité", pt: "editado", en: "edited", de: "bearbeitet", it: "modificato" },
  btnRevert: { fr: "Rétablir", pt: "Reverter", en: "Revert", de: "Zurücksetzen", it: "Ripristina" },
  btnRevertHint: { fr: "Revient au texte du code (toutes les langues). Sauver pour publier.", pt: "Volta ao texto do código (todas as línguas). Guardar para publicar.", en: "Returns to the code text (all languages). Save to publish.", de: "Zurück zum Text im Code (alle Sprachen). Speichern zum Veröffentlichen.", it: "Torna al testo nel codice (tutte le lingue). Salva per pubblicare." },
  toastReverted: { fr: "Rétabli. Sauver pour publier.", pt: "Revertido. Guardar para publicar.", en: "Reverted. Save to publish.", de: "Zurückgesetzt. Speichern zum Veröffentlichen.", it: "Ripristinato. Salva per pubblicare." },
  toastPending: { fr: "Sauver pour publier.", pt: "Guardar para publicar.", en: "Save to publish.", de: "Speichern zum Veröffentlichen.", it: "Salva per pubblicare." },
