  chars: { fr: "caractères", pt: "caracteres", en: "characters", de: "Zeichen", it: "caratteri" },
  titleGuide: { fr: "repère: Google coupe vers 60", pt: "referência: o Google corta perto de 60", en: "guide: Google cuts around 60", de: "Richtwert: Google schneidet bei etwa 60 ab", it: "riferimento: Google taglia verso 60" },
  descGuide: { fr: "fenêtre visée par le code: 110 à 160", pt: "janela usada pelo código: 110 a 160", en: "window used by the code: 110 to 160", de: "vom Code genutztes Fenster: 110 bis 160", it: "finestra usata dal codice: 110 a 160" },
