const ABIL_FREEMAIL_UI = new Set(["gmail.com", "googlemail.com", "hotmail.com", "hotmail.co.uk", "hotmail.fr", "hotmail.it", "outlook.com", "outlook.pt", "live.com", "live.co.uk", "msn.com", "yahoo.com", "yahoo.co.uk", "yahoo.fr", "yahoo.it", "ymail.com", "icloud.com", "me.com", "mac.com", "aol.com", "gmx.com", "gmx.net", "protonmail.com", "proton.me", "mail.com", "yandex.com", "sapo.pt", "orange.fr", "free.fr", "laposte.net", "bluewin.ch", "sunrise.ch", "libero.it", "virgilio.it"]);
function derivarTipoTitular(email: string, nome: string): "empresa" | "singular" {
  const dom = String(email || "").trim().toLowerCase().split("@")[1] || "";
  if (!dom || !ABIL_FREEMAIL_UI.has(dom)) return "empresa";
  const n = String(nome || "").trim().toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
  const TERMOS_EMPRESA = /(\b(lda|ltda|unipessoal|gmbh|sarl|sa|ag|inc|llc|ltd|limited|corp|studio|estudio|atelier|agency|agencia|agence|agentur|group|grupo|groupe|company|cia|clinica|clinic|restaurante|restaurant|hotel|shop|store|loja|salao|salon|barbearia|cafe|padaria|pastelaria|oficina|imobiliaria|servicos|services)\b|[&@\d])/;
  if (TERMOS_EMPRESA.test(n)) return "empresa";
  return "singular";
}

                                                                                                   
                                                                                             
                                                                                  
function normalizeLead(l: any): Lead {
  const raw = (l && typeof l === "object") ? l : {};
  const num = (...vs: any[]) => { for (const v of vs) { const n = Number(v); if (Number.isFinite(n)) return n; } return 0; };
  const web = String(raw.website || raw.site || "").trim();
  return {
    ...raw,
    id: String(raw.id || uid()),
    fase: (raw.fase || "lead") as LeadFase,
    score: num(raw.score, 50),
    nome: String(raw.nome || raw.nom || "").trim(),
    empresa: String(raw.empresa || raw.entreprise || "").trim(),
    email: String(raw.email || "").trim(),
    telefone: String(raw.telefone || raw.telephone || "").trim(),
    site: web,
    website: web,
    pais: String(raw.pais || "").trim(),
    valor: num(raw.valor, raw.valeur),
    notas: String(raw.notas ?? raw.notes ?? ""),
    createdAt: String(raw.createdAt || raw.dataMapeamento || ""),
                                                                                                    
                                                                                                           
    tipoTitular: (raw.tipoTitular === "empresa" || raw.tipoTitular === "singular") ? raw.tipoTitular : (String(raw.email || "").trim() ? derivarTipoTitular(String(raw.email || ""), String(raw.nome || raw.nom || raw.empresa || raw.entreprise || "")) : undefined),
  };
}

                                                                       
function leadTier(l: { tier?: Lead["tier"]; score: number }): "quente" | "morno" | "frio" {
  return l.tier || (l.score >= 70 ? "quente" : l.score >= 50 ? "morno" : "frio");
}
                                                                                   
