const FOLLOWUP_NEG_DIAS = 5;                                                                   
                                                                                                      
                                                                                                          
                                                                                         
type RaioXEtapa = { key: string; rotulo: string; ok: boolean | null; motivo?: string };
function raioXResumo(l: Lead): { estado: "completo" | "parcial" | "falhou" | "por_correr"; etapas: RaioXEtapa[]; motivo?: string } {
  const a: any = (l as any).audit; const ds: any = (l as any).deepStudy; const st: any = (l as any).study; const sd: any = (l as any).socialDeep;
  const etapas: RaioXEtapa[] = [];
  const tecnicoOk = !!(a && a.at);
  etapas.push({ key: "tecnico", rotulo: "Technique", ok: tecnicoOk ? true : null, motivo: tecnicoOk && a.partial ? `analyse partielle (couches desactivees: ${(a.layersSkipped || []).join(", ") || "n/d"})` : undefined });
  const profundoOk = !!(ds && ds.ok === true);
  const profundoFalhou = !!(ds && ds.ok === false);
  etapas.push({ key: "profundo", rotulo: "Profonde", ok: profundoOk ? true : (profundoFalhou ? false : null), motivo: profundoFalhou ? String(ds.mensagem || ds.erro || "echec") : undefined });
  etapas.push({ key: "estudo", rotulo: "Etude", ok: (st && st.estudo) ? true : null });
  etapas.push({ key: "redes", rotulo: "Reseaux", ok: sd ? true : null });
  let estado: "completo" | "parcial" | "falhou" | "por_correr";
  if (tecnicoOk && profundoOk) estado = "completo";
  else if (profundoFalhou && !tecnicoOk) estado = "falhou";
  else if (tecnicoOk || profundoOk || profundoFalhou || (st && st.estudo) || sd) estado = "parcial";
  else estado = "por_correr";
  const motivo = etapas.find((e) => e.ok === false)?.motivo || etapas.find((e) => e.motivo)?.motivo;
  return { estado, etapas, motivo };
}
const RAIOX_LABEL: Record<string, string> = { completo: "complete", parcial: "partielle", falhou: "echec", por_correr: "a lancer" };
const RAIOX_CHIP: Record<string, string> = { completo: "border-emerald-500/40 text-emerald-600", parcial: "border-amber-500/50 text-amber-600", falhou: "border-red-500/50 text-red-600", por_correr: "border-neutral-200 text-neutral-400" };

function unifiedStageOf(l: Lead): string {
  const rich = (l as any).agentMemory?.fase || (l as any).journeyPhase || "";
  if (l.fase === "delivered" || l.fase === "production") return "ganho";
  if ((l as any).outcome === "declinou" || (l as any).replyClass === "negativa") return "negativa";
  if (l.fase === "inactive") return "inativo";
  if ((l as any).proposalApprovedAt) return "aprovacao";
  const ps = (l as any).proposalSentAt;
  if (ps) {
    const respondeuDepois = (l as any).repliedAt && Date.parse(String((l as any).repliedAt)) > Date.parse(String(ps));
    const diasCalado = (Date.now() - Date.parse(String(ps))) / 86400000;
    if (!respondeuDepois && diasCalado >= FOLLOWUP_NEG_DIAS) return "followup_neg";
    return "negociacao";
  }
  if (rich === "negociacao" || l.fase === "negociation") return "negociacao";
  if (rich === "qualificado" || l.fase === "briefing") return "qualificado";
  if (rich === "em_conversa" || rich === "engajou") return "conversa";
  if (l.replied) return "conversa";
  if (l.lastEmailSentAt) return "contactado";
  return "novo";
}
                                                                                                                         
                                                                                                          
                                                                                                              
                                                                                                           
                                                                                                       
type SuppressList = { emails: string[]; domains: string[] };
function isSuppressedEmail(email: string, sup: SuppressList | null): boolean {
  if (!sup) return false;
  const e = String(email || "").trim().toLowerCase();
  if (!e || e.indexOf("@") < 0) return false;
  if ((sup.emails || []).some((x) => String(x).toLowerCase().trim() === e)) return true;
  const dom = e.split("@")[1] || "";
  return (sup.domains || []).some((d) => { const dd = String(d).toLowerCase().replace(/^@/, "").trim(); return !!dd && (dom === dd || dom.endsWith("." + dd)); });
}

                                                                                                          
                                                                                                             
                                                                                                                  
                                                                                                                 
                                                                                                                 
                                                     
function unifiedStagePatch(stage: string, l: Lead): Partial<Lead> {
  const am = (fase: string): Record<string, unknown> => ({ ...((l as any).agentMemory || {}), fase });
  switch (stage) {
    case "inativo": return { fase: "inactive", agentMemory: am(""), outcome: "", replyClass: "" } as Partial<Lead>;
    case "negativa": return { outcome: "declinou" } as Partial<Lead>;
    case "ganho": return { fase: "delivered", outcome: "", replyClass: "" } as Partial<Lead>;
                                                                                                              
    case "aprovacao": return { proposalApprovedAt: new Date().toISOString(), proposalApprovedVia: "manual", outcome: "", replyClass: "" } as Partial<Lead>;
                                                                                                                    
                                                                                                              
                                                        
    case "followup_neg":
    case "negociacao": return { fase: "negociation", replied: true, agentMemory: am("negociacao"), outcome: "", replyClass: "", proposalApprovedAt: undefined, proposalApprovedVia: undefined } as Partial<Lead>;
    case "qualificado": return { fase: "briefing", replied: true, agentMemory: am("qualificado"), outcome: "", replyClass: "", proposalApprovedAt: undefined, proposalApprovedVia: undefined, proposalSentAt: undefined } as Partial<Lead>;
    case "conversa": return { fase: "lead", replied: true, agentMemory: am("em_conversa"), outcome: "", replyClass: "", proposalApprovedAt: undefined, proposalApprovedVia: undefined, proposalSentAt: undefined } as Partial<Lead>;
    case "contactado": return { fase: "lead", replied: false, lastEmailSentAt: l.lastEmailSentAt || new Date().toISOString(), agentMemory: am(""), outcome: "", replyClass: "", proposalApprovedAt: undefined, proposalApprovedVia: undefined, proposalSentAt: undefined } as Partial<Lead>;
    case "novo": default: return { fase: "lead", replied: false, lastEmailSentAt: undefined, agentMemory: am(""), outcome: "", replyClass: "", proposalApprovedAt: undefined, proposalApprovedVia: undefined, proposalSentAt: undefined } as Partial<Lead>;
  }
}
                                                                                                                 
                                                                                                             
                                                                                                               
function unifiedStageServerPatch(stage: string, l: Lead): Record<string, unknown> {
  const base: Record<string, unknown> = { id: l.id };
  const am = (fase: string): Record<string, unknown> => ({ ...((l as any).agentMemory || {}), fase });
  switch (stage) {
    case "inativo": return { ...base, fase: "inactive", agentMemory: am(""), outcome: "", replyClass: "" };
    case "negativa": return { ...base, outcome: "declinou" };
    case "ganho": return { ...base, fase: "delivered", outcome: "", replyClass: "" };
                                                                                                
    case "aprovacao": return { ...base, proposalApprovedAt: new Date().toISOString(), proposalApprovedVia: "manual", outcome: "", replyClass: "" };
                                                                                                                        
    case "followup_neg":
    case "negociacao": return { ...base, fase: "negociation", replied: true, agentMemory: am("negociacao"), outcome: "", replyClass: "", proposalApprovedAt: "", proposalApprovedVia: "" };
    case "qualificado": return { ...base, fase: "briefing", replied: true, agentMemory: am("qualificado"), outcome: "", replyClass: "", proposalApprovedAt: "", proposalApprovedVia: "", proposalSentAt: "" };
    case "conversa": return { ...base, fase: "lead", replied: true, agentMemory: am("em_conversa"), outcome: "", replyClass: "", proposalApprovedAt: "", proposalApprovedVia: "", proposalSentAt: "" };
    case "contactado": return { ...base, fase: "lead", replied: false, repliedAt: "", lastEmailSentAt: l.lastEmailSentAt || new Date().toISOString(), agentMemory: am(""), outcome: "", replyClass: "", proposalApprovedAt: "", proposalApprovedVia: "", proposalSentAt: "" };
    case "novo": default: return { ...base, fase: "lead", replied: false, repliedAt: "", lastEmailSentAt: "", journeyPhase: "", followupCount: 0, lastFollowupAt: "", agentMemory: am(""), outcome: "", replyClass: "", proposalApprovedAt: "", proposalApprovedVia: "", proposalSentAt: "" };
  }
}

                                                                                                     
                                                                                                           
                                                                                                                       
                                                                                                    
                                                                                            
                                               
                                                                                            
