function ClientLogoOrText({ client, logoDataUrl, height = 14 }: { client: { name: string; tagline?: string }; logoDataUrl?: string; height?: number }) {
                                                                               
  if (logoDataUrl) {
    return <img src={logoDataUrl} alt={client.name} style={{ height: `${height}px`, width: "auto", display: "inline-block", verticalAlign: "middle", maxWidth: "200px", objectFit: "contain" }} />;
  }
  return <span style={{ fontFamily: "Inter, sans-serif", fontWeight: 700, fontSize: `${height - 1}px`, color: "#fff", letterSpacing: "-0.005em" }}>{client.name.replace(/ SA$/, "")}</span>;
}

                                                                        
                                                                      
                                                                       
                                                                      
                                                                       
                                            
                                                                        
