async function workReportDocToPdfBase64(lang?: Lang): Promise<string> {
  const pages = Array.from(document.querySelectorAll(".work-report-document .wr-page")) as HTMLElement[];
  if (!pages.length) throw new Error(_trO(WORK_REPORTS_TXT.pdfNoPages, lang || "pt"));
  const { PDFDocument } = await import("pdf-lib");
  const pdf = await PDFDocument.create();
  const A4W = 595.28;
  const A4H = 841.89;
  for (const page of pages) {
                                                                                             
                                                                                                   
    const svgUrl = await toSvg(page, {
      skipFonts: false,
      width: page.offsetWidth,
      height: page.offsetHeight,
      backgroundColor: "#0a0a0b",
    });
    const im = new Image();
    await new Promise<void>((res, rej) => { im.onload = () => res(); im.onerror = () => rej(new Error("PDF: falha a carregar o desenho da página")); im.src = svgUrl; });
    const cv = document.createElement("canvas");
    cv.width = Math.max(1, Math.round(page.offsetWidth * 1.6));
    cv.height = Math.max(1, Math.round(page.offsetHeight * 1.6));
    const cctx = cv.getContext("2d");
    if (!cctx) throw new Error("PDF: canvas indisponível");
    cctx.fillStyle = "#0a0a0b"; cctx.fillRect(0, 0, cv.width, cv.height);
    cctx.drawImage(im, 0, 0, cv.width, cv.height);
    const dataUrl = cv.toDataURL("image/jpeg", 0.94);
    const bytes = new Uint8Array(await (await fetch(dataUrl)).arrayBuffer());
    const jpg = await pdf.embedJpg(bytes);
    const ratio = jpg.width / jpg.height;
    let drawW = A4W;
    let drawH = drawW / ratio;
    if (drawH < A4H) {
      drawH = A4H;
      drawW = drawH * ratio;
    }
    const pg = pdf.addPage([A4W, A4H]);
    pg.drawImage(jpg, { x: (A4W - drawW) / 2, y: A4H - drawH, width: drawW, height: drawH });
  }
  const out = await pdf.save();
  let bin = "";
  for (let i = 0; i < out.length; i += 0x8000) bin += String.fromCharCode.apply(null, Array.from(out.subarray(i, i + 0x8000)));
  return btoa(bin);
}

                                                                                
function detectWorkReportOverflow(): number[] {
  const pages = Array.from(document.querySelectorAll(".work-report-document .wr-page")) as HTMLElement[];
  const overflowing: number[] = [];
  pages.forEach((p, i) => {
    if (p.scrollHeight > p.clientHeight + 4) overflowing.push(i + 1);
  });
  return overflowing;
}

function downloadWorkReportPdf(report: WorkReport, lang?: Lang) {
  return new Promise<void>(async (resolve, reject) => {
    try {
      await new Promise((r) => setTimeout(r, 60));
                                                                   
      const overflowing = detectWorkReportOverflow();
      if (overflowing.length > 0) {
                                                                                      
        const proceed = window.confirm(_trO({
          pt: "Atenção: {n} página(s) podem cortar conteúdo (págs {pages}). Gerar mesmo assim?",
          fr: "Attention : {n} page(s) risquent de couper du contenu (pages {pages}). Générer quand même ?",
          en: "Warning: {n} page(s) may crop content (pages {pages}). Generate anyway?",
          de: "Achtung: {n} Seite(n) könnten Inhalt abschneiden (Seiten {pages}). Trotzdem erstellen?",
          it: "Attenzione: {n} pagina/e potrebbero tagliare contenuto (pagg. {pages}). Generare comunque?",
        }, lang || "pt").replace("{n}", String(overflowing.length)).replace("{pages}", overflowing.join(", ")));
        if (!proceed) { resolve(); return; }
      }
      const base64 = await workReportDocToPdfBase64(lang);
      const bytes = Uint8Array.from(atob(base64), (c) => c.charCodeAt(0));
      const blob = new Blob([bytes], { type: "application/pdf" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `${report.ref}.pdf`;
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(url), 5000);
      resolve();
    } catch (e) { reject(e); }
  });
}

                                                                        
                                                        
                                                              
                                                                        
                                                                        
                                                                               
                                                                                            
                                                                        
                                                                        

                                                                  
                                                                                                 
