function WorkReportWizardModal({
  open, onClose, presentation, leads, onCreate,
  availablePresentations, onPickPresentation,
  existingReport,
}: {
  open: boolean;
  onClose: () => void;
  presentation: DashboardProject | null;
  leads: Lead[];
  onCreate: (wr: WorkReport) => void;
  availablePresentations?: DashboardProject[];
  onPickPresentation?: (id: string) => void;
  existingReport?: WorkReport | null;
}) {
  const { lang } = useApp();
  const Lq = (o: Record<string, string>) => _trO(o, lang);

                     
  const [serviceHours, setServiceHours] = useState<Record<string, number>>({});                                                                         
  const [universalHours, setUniversalHours] = useState<Record<string, number>>({});
  const [expandedExpertise, setExpandedExpertise] = useState<Record<string, boolean>>({});
  const [clientNameInput, setClientNameInput] = useState<string>("");
  const [projectInput, setProjectInput] = useState<string>("");
  const [clientLocation, setClientLocation] = useState<string>("");
  const [clientTagline, setClientTagline] = useState<string>("");
                                                                                                   
  const [clientLogosVault, setClientLogosVault] = useLocalStorageState<Record<string, string>>("abil_client_logos", {});
  const [clientLogoDataUrl, setClientLogoDataUrl] = useState<string>("");
                                                           
  const [overrideLead, setOverrideLead] = useState<string>("");
  const [overrideCommitment, setOverrideCommitment] = useState<string>("");
  const [overrideClosingOrg, setOverrideClosingOrg] = useState<string>("");
  const [overrideClosingBenefice, setOverrideClosingBenefice] = useState<string>("");
                                                                 
  const [reportTheme, setReportTheme] = useState<"noir" | "blanc" | "rouge">("noir");
  const [refOverride, setRefOverride] = useState<string>("");
  const [submitting, setSubmitting] = useState(false);

                                                        
  const clientLead = presentation?.clientId ? leads.find((l) => l.id === presentation.clientId) : null;
  const derivedClientName = clientLead?.nom || "";
  const derivedProject = presentation?.title || "";

                                                                              
  useEffect(() => {
    if (!open) return;
    if (existingReport) {
                                                                                                          
      const wi = existingReport.wizardInputs;
      setServiceHours(wi?.serviceHours ? { ...wi.serviceHours } : {});
      if (wi?.universalHours) {
        setUniversalHours({ ...wi.universalHours });
      } else {
        const u: Record<string, number> = {};
        WORK_REPORT_UNIVERSAL_STEPS.forEach((s) => { u[s.id] = s.defaultHours; });
        setUniversalHours(u);
      }
                                                        
      const expanded: Record<string, boolean> = {};
      if (wi?.serviceHours) {
        WORK_REPORT_SERVICE_CATALOG.forEach((exp) => {
          if (exp.services.some((s) => (wi.serviceHours![s.id] || 0) > 0)) {
            expanded[exp.expertiseId] = true;
          }
        });
      }
      setExpandedExpertise(expanded);
      setRefOverride(existingReport.ref || "");
      setClientNameInput(existingReport.client?.name || "");
      setProjectInput(existingReport.project?.replace(/\.$/, "") || "");
      setClientLocation(existingReport.client?.location || "");
      setClientTagline(existingReport.client?.tagline || "");
      setClientLogoDataUrl(existingReport.clientLogoDataUrl || "");
      setOverrideLead(wi?.overrideLead || "");
      setOverrideCommitment(wi?.overrideCommitment || "");
      setOverrideClosingOrg(wi?.overrideClosingOrg || "");
      setOverrideClosingBenefice(wi?.overrideClosingBenefice || "");
      setReportTheme(existingReport.theme || "noir");
    } else {
                          
      setServiceHours({});
      const u: Record<string, number> = {};
      WORK_REPORT_UNIVERSAL_STEPS.forEach((s) => { u[s.id] = s.defaultHours; });
      setUniversalHours(u);
      setExpandedExpertise({ "direction-artistique": true });
      setRefOverride("");
      setClientNameInput(derivedClientName);
      setProjectInput(derivedProject);
      setClientLocation("");
      setClientTagline("");
      const key = (derivedClientName || "").trim().toLowerCase();
      setClientLogoDataUrl(key && clientLogosVault[key] ? clientLogosVault[key] : "");
      setOverrideLead("");
      setOverrideCommitment("");
      setOverrideClosingOrg("");
      setOverrideClosingBenefice("");
      setReportTheme("noir");
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, presentation?.id, existingReport?.id]);

                                                                     
  useEffect(() => {
    if (presentation) {
      setClientNameInput(derivedClientName);
      setProjectInput(derivedProject);
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [presentation?.id]);

  const totalServicesHours = Object.values(serviceHours).reduce((s, h) => s + (Number.isFinite(h) && h > 0 ? h : 0), 0);
  const totalUniversalHours = Object.values(universalHours).reduce((s, h) => s + (Number.isFinite(h) && h > 0 ? h : 0), 0);
  const totalHours = totalServicesHours + totalUniversalHours;

  const effectiveClientName = (clientNameInput.trim() || derivedClientName || Lq({ fr: "Sans client", pt: "Sem cliente", en: "No client", de: "Ohne Kunde", it: "Senza cliente" }));
  const effectiveProject = (projectInput.trim() || derivedProject || Lq({ fr: "Projet sans titre", pt: "Projeto sem título", en: "Untitled project", de: "Projekt ohne Titel", it: "Progetto senza titolo" }));

  const autoRef = useMemo(() => {
    const d = new Date();
    const base = (effectiveClientName || "ABiL").split(/\s+/).filter(Boolean).map((w) => w[0]).join("").toUpperCase().slice(0, 4) || "ABiL";
    return `RAP-${base}-${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [effectiveClientName, open]);
  const effectiveRef = refOverride.trim() || autoRef;

  const labels = {
    header: existingReport
      ? Lq({ fr: "Éditer le rapport de travail", pt: "Editar relatório de trabalho", en: "Edit work report", de: "Arbeitsbericht bearbeiten", it: "Modifica rapporto di lavoro" })
      : Lq({ fr: "Générer un rapport de travail", pt: "Gerar relatório de trabalho", en: "Generate work report", de: "Arbeitsbericht erstellen", it: "Genera rapporto di lavoro" }),
    subtitle: Lq({ fr: "Choisis les services réalisés (avec leur temps), confirme les étapes universelles du projet et la fiche client. Le rapport est généré au format A4 noir validé.", pt: "Escolhe os serviços realizados (com o tempo de cada), confirma as etapas universais do projeto e a ficha do cliente. O relatório é gerado no formato A4 noir validado.", en: "Pick the services delivered (with their time), confirm the universal project steps and the client info. The report is generated in the validated A4 noir format.", de: "Wähle die geleisteten Services mit Stunden.", it: "Scegli i servizi con tempo." }),
    sectionServices: "* " + Lq({ fr: "Services réalisés", pt: "Serviços realizados", en: "Services delivered", de: "Geleistete Services", it: "Servizi realizzati" }),
    sectionUniversal: "* " + Lq({ fr: "Étapes universelles du projet", pt: "Etapas universais do projeto", en: "Universal project steps", de: "Universelle Schritte", it: "Fasi universali" }),
    sectionMeta: "* " + Lq({ fr: "Référence & client", pt: "Referência & cliente", en: "Reference & client", de: "Referenz & Kunde", it: "Riferimento & cliente" }),
    cancel: Lq({ fr: "Annuler", pt: "Cancelar", en: "Cancel", de: "Abbrechen", it: "Annulla" }),
    generate: "* " + (existingReport
      ? Lq({ fr: "Enregistrer les modifications", pt: "Salvar alterações", en: "Save changes", de: "Änderungen speichern", it: "Salva modifiche" })
      : Lq({ fr: "Générer le rapport", pt: "Gerar relatório", en: "Generate report", de: "Bericht generieren", it: "Genera rapporto" })),
    generating: Lq({ fr: "Génération…", pt: "A gerar…", en: "Generating…", de: "Erstellen…", it: "Generazione…" }),
    hoursUnit: "h",
    refLabel: Lq({ fr: "Référence (auto)", pt: "Referência (auto)", en: "Reference (auto)", de: "Referenz (auto)", it: "Riferimento (auto)" }),
    clientLabel: Lq({ fr: "Client", pt: "Cliente", en: "Client", de: "Kunde", it: "Cliente" }),
    projectLabel: Lq({ fr: "Projet", pt: "Projeto", en: "Project", de: "Projekt", it: "Progetto" }),
    locationLabel: Lq({ fr: "Localisation client (optionnel)", pt: "Localização cliente (opcional)", en: "Client location (optional)", de: "Standort (optional)", it: "Sede (opzionale)" }),
    taglineLabel: Lq({ fr: "Tagline client (optionnel)", pt: "Tagline cliente (opcional)", en: "Client tagline (optional)", de: "Slogan (optional)", it: "Tagline (opzionale)" }),
    logoLabel: Lq({ fr: "Logo du client (PNG/SVG, optionnel)", pt: "Logo do cliente (PNG/SVG, opcional)", en: "Client logo (PNG/SVG, optional)", de: "Kunden-Logo", it: "Logo cliente" }),
    logoHint: Lq({ fr: "Cliquez ou glissez. Apparaît en haut à droite de la couverture et dans la signature.", pt: "Clica ou arrasta. Aparece no topo direito da capa e na assinatura.", en: "Click or drop. Appears on cover top-right and signature.", de: "Klicken oder ziehen.", it: "Clicca o trascina." }),
    logoRemove: Lq({ fr: "Retirer le logo", pt: "Remover logo", en: "Remove logo", de: "Logo entfernen", it: "Rimuovi logo" }),
    totalServicesLabel: Lq({ fr: "Total services", pt: "Total serviços", en: "Total services", de: "Services-Total", it: "Totale servizi" }),
    totalUniversalLabel: Lq({ fr: "Total étapes", pt: "Total etapas", en: "Total steps", de: "Schritte-Total", it: "Totale fasi" }),
    totalAllLabel: Lq({ fr: "Total facturable", pt: "Total facturável", en: "Billable total", de: "Abrechenbar", it: "Totale fatturabile" }),
  };

  const setSvcHours = (sid: string, h: number) => setServiceHours((prev) => ({ ...prev, [sid]: Math.max(0, h) }));
  const toggleSvc = (sid: string, defaultH: number) => setServiceHours((prev) => ({ ...prev, [sid]: (prev[sid] || 0) > 0 ? 0 : defaultH }));
  const setUnivHours = (uid: string, h: number) => setUniversalHours((prev) => ({ ...prev, [uid]: Math.max(0, h) }));
  const toggleExpertise = (eid: string) => setExpandedExpertise((prev) => ({ ...prev, [eid]: !prev[eid] }));

  const handleGenerate = async () => {
    if (submitting) return;
    if (totalServicesHours === 0) { window.alert(Lq({ fr: "Sélectionne au moins un service réalisé.", pt: "Selecciona pelo menos um serviço realizado.", en: "Select at least one service delivered.", de: "Mindestens einen Service.", it: "Almeno un servizio." })); return; }
    setSubmitting(true);

                                                              
    const builtServicePhases: WorkReportPhase[] = [];
    let phaseIdx = 0;
    WORK_REPORT_SERVICE_CATALOG.forEach((expertise) => {
      expertise.services.forEach((svc) => {
        const h = serviceHours[svc.id];
        if (h && h > 0) {
          phaseIdx++;
          builtServicePhases.push({
            id: `ph${phaseIdx}`,
            num: String(phaseIdx).padStart(2, "0"),
            icon: expertise.icon,
            name: Lq(svc.label),
            description: Lq(svc.descLabel),
            hours: h,
          });
        }
      });
    });

                                           
    WORK_REPORT_UNIVERSAL_STEPS.forEach((step) => {
      const h = universalHours[step.id];
      if (h && h > 0) {
        phaseIdx++;
        builtServicePhases.push({
          id: `ph${phaseIdx}`,
          num: String(phaseIdx).padStart(2, "0"),
          icon: step.icon,
          name: Lq(step.label),
          description: Lq(step.descLabel),
          hours: h,
        });
      }
    });

                                                                                         
    const builtDeliverables: WorkReportDeliverable[] = [];
    WORK_REPORT_SERVICE_CATALOG.forEach((expertise) => {
      const selectedSvcs = expertise.services.filter((s) => (serviceHours[s.id] || 0) > 0);
      if (selectedSvcs.length === 0) return;
      const expertiseHours = selectedSvcs.reduce((sum, s) => sum + (serviceHours[s.id] || 0), 0);
      builtDeliverables.push({
        id: expertise.expertiseId,
        index: String(builtDeliverables.length + 1).padStart(2, "0"),
        icon: expertise.icon,
        title: Lq(expertise.expertiseLabel) + ".",
        subtitle: `${selectedSvcs.length} ${Lq({ fr: "service(s) livré(s)", pt: "serviço(s) entregue(s)", en: "service(s) delivered", de: "Service(s) geliefert", it: "servizio/i consegnato/i" })} · ${expertiseHours}h`,
        badge: Lq(expertise.badge),
        stats: [
          { num: String(selectedSvcs.length), label: Lq({ fr: "Services", pt: "Serviços", en: "Services", de: "Services", it: "Servizi" }) },
          { num: String(expertiseHours), unit: "h", label: Lq({ fr: "Temps consacré", pt: "Tempo dedicado", en: "Time spent", de: "Aufgewendete Zeit", it: "Tempo dedicato" }) },
          { num: String(Math.round((expertiseHours / Math.max(totalHours, 1)) * 100)), unit: "%", label: Lq({ fr: "Du total", pt: "Do total", en: "Of total", de: "Vom Total", it: "Del totale" }) },
        ],
        items: selectedSvcs.map((s, i) => ({
          id: `${expertise.expertiseId}-${s.id}`,
          index: String(i + 1).padStart(2, "0"),
          name: Lq(s.label),
          meta: Lq(s.descLabel),
          qty: `${serviceHours[s.id]}h`,
        })),
        techNote: Lq({
          fr: `Cette expertise a mobilisé ${selectedSvcs.length} service(s) pour un total de ${expertiseHours}h. Sources éditables et exports finaux remis au client dans le Drive partagé.`,
          pt: `Esta expertise mobilizou ${selectedSvcs.length} serviço(s) num total de ${expertiseHours}h. Fontes editáveis e exports finais entregues ao cliente no Drive partilhado.`,
          en: `This expertise covered ${selectedSvcs.length} service(s) totaling ${expertiseHours}h. Editable sources and final exports delivered in the shared Drive.`,
          de: `${selectedSvcs.length} Service(s) für ${expertiseHours}h.`,
          it: `${selectedSvcs.length} servizio/i per ${expertiseHours}h.`,
        }),
      });
    });

                                                                                                
    const langKey = ({ fr: "fr", pt: "pt", en: "en", de: "de", it: "it", es: "fr" } as Record<string, string>)[lang] || "fr";
    const teamRoles: WorkReportTeamRole[] = (WORK_REPORT_CANONICAL_TEAM_ROLES[langKey]?.roles || WORK_REPORT_CANONICAL_TEAM_ROLES.fr.roles).map((r, i) => ({
      id: `tr${i + 1}`, name: r.name, description: r.description,
    }));
    const beyondProduction: WorkReportTeamRole[] = (WORK_REPORT_CANONICAL_BEYOND[langKey]?.items || WORK_REPORT_CANONICAL_BEYOND.fr.items).map((r, i) => ({
      id: `bp${i + 1}`, name: r.name, description: r.description,
    }));

    const today = new Date();
    const monthName = today.toLocaleDateString(({ fr: "fr-FR", pt: "pt-PT", en: "en-GB", de: "de-DE", it: "it-IT", es: "es-ES" } as Record<string, string>)[lang] || "fr-FR", { month: "long", year: "numeric" });

    const wr: WorkReport = {
      id: `wr_${today.getTime().toString(36)}`,
      ref: effectiveRef,
      status: "rascunho",
      createdAt: today.toISOString(),
      date: monthName,
      presentationId: presentation?.id,
      client: {
        name: effectiveClientName,
        location: clientLocation.trim() || "Genève · Suisse",
        tagline: clientTagline.trim() || undefined,
      },
                                                                                                               
      clientLogoDataUrl: clientLogoDataUrl || undefined,
      prestataire: { name: "ABiL atelier créatif", url: "abil.ch" },
      project: effectiveProject.endsWith(".") ? effectiveProject : effectiveProject + ".",
      projectSubtitle: Lq({ fr: "Détail du temps consacré.", pt: "Detalhe do tempo dedicado.", en: "Time breakdown.", de: "Aufschlüsselung.", it: "Dettaglio del tempo." }),
      lead: overrideLead.trim() || Lq({
        fr: `Synthèse complète de la conception, de la production et de la livraison du projet « ${effectiveProject.replace(/\.$/, "")} » pour ${effectiveClientName}. Décomposition par expertise, services réalisés et étapes universelles.`,
        pt: `Síntese completa da conceção, produção e entrega do projeto « ${effectiveProject.replace(/\.$/, "")} » para ${effectiveClientName}. Decomposição por expertise, serviços realizados e etapas universais.`,
        en: `Complete summary of conception, production and delivery of « ${effectiveProject.replace(/\.$/, "")} » for ${effectiveClientName}.`,
        de: `Vollständige Zusammenfassung des Projekts.`,
        it: `Sintesi completa del progetto.`,
      }),
      totalHours,
      filesCount: builtDeliverables.reduce((s, d) => s + d.items.length, 0),
      familiesCount: builtDeliverables.length,
      phases: builtServicePhases,
      deliverables: builtDeliverables,
      teamRoles,
      beyondProduction,
      processSteps: [
        { id: "s1", num: "01", icon: "lens", title: Lq({ fr: "Compréhension de la marque", pt: "Compreensão da marca", en: "Brand understanding", de: "Markenverständnis", it: "Comprensione del brand" }), description: Lq({ fr: "Étude du brand book, des codes couleur, typographiques et de la mécanique visuelle.", pt: "Estudo do brand book, dos códigos cromáticos, tipográficos e da mecânica visual.", en: "Brand book, color, typography and visual mechanics study.", de: "Brand-Book-Studie.", it: "Studio del brand book." }) },
        { id: "s2", num: "02", icon: "layers", title: Lq({ fr: "Système graphique", pt: "Sistema gráfico", en: "Graphic system", de: "Grafiksystem", it: "Sistema grafico" }), description: Lq({ fr: "Grille, hiérarchie typographique, codes secondaires, signature visuelle commune.", pt: "Grelha, hierarquia tipográfica, códigos secundários, assinatura visual.", en: "Grid, typography, secondary codes, common visual signature.", de: "Raster, Typografie.", it: "Griglia, tipografia." }) },
        { id: "s3", num: "03", icon: "build", title: Lq({ fr: "Production", pt: "Produção", en: "Production", de: "Produktion", it: "Produzione" }), description: Lq({ fr: "Conception et exécution des templates, supports multi-formats, animations.", pt: "Conceção e execução dos templates, suportes multi-formato, animações.", en: "Templates, multi-format supports and animations.", de: "Templates und Animationen.", it: "Template e animazioni." }) },
        { id: "s4", num: "04", icon: "check", title: Lq({ fr: "Itérations & QC", pt: "Iterações & QC", en: "Iterations & QC", de: "Iterationen & QC", it: "Iterazioni & QC" }), description: Lq({ fr: "Validation visuelle, contrôle des contrastes, du sound design, ajustements après retours.", pt: "Validação visual, controlo dos contrastes, do sound design, ajustes após feedback.", en: "Visual validation, contrast and sound control, post-feedback adjustments.", de: "Visuelle Validierung.", it: "Validazione visiva." }) },
        { id: "s5", num: "05", icon: "package", title: Lq({ fr: "Livraison", pt: "Entrega", en: "Delivery", de: "Lieferung", it: "Consegna" }), description: Lq({ fr: "Préparation des fichiers sources et exports finaux, classés par usage.", pt: "Preparação dos ficheiros fonte e exports finais, classificados por uso.", en: "Source and export files, classified by usage.", de: "Quell- und Exportdateien.", it: "File sorgente ed export." }) },
      ],
      commitment: overrideCommitment.trim() || Lq({ fr: "Chaque heure facturée représente une combinaison d'expertises pensée pour garantir un livrable robuste, cohérent avec la marque et durable dans le temps.", pt: "Cada hora facturada representa uma combinação de competências para garantir um entregável robusto, coerente com a marca e duradouro.", en: "Each billed hour combines expertise to guarantee a robust, on-brand and durable deliverable.", de: "Jede Stunde kombiniert Expertise.", it: "Ogni ora combina competenze." }),
      closingOrgTitle: Lq({ fr: "Sources & exports", pt: "Fontes & exports", en: "Sources & exports", de: "Quellen & Exporte", it: "Sorgenti & export" }),
      closingOrg: overrideClosingOrg.trim() || Lq({ fr: `L'ensemble des fichiers est livré dans le Drive partagé, classés par expertise et par livrable.`, pt: `O conjunto dos ficheiros é entregue no Drive partilhado, classificados por expertise e por entregável.`, en: `All files are delivered in the shared Drive, classified by expertise.`, de: `Alle Dateien im geteilten Drive.`, it: `File nel Drive condiviso.` }),
      closingBeneficeTitle: Lq({ fr: "Autonomie de production", pt: "Autonomia de produção", en: "Production autonomy", de: "Produktionsautonomie", it: "Autonomia di produzione" }),
      closingBenefice: overrideClosingBenefice.trim() || Lq({ fr: `Le système mis en place permet à ${effectiveClientName} de produire de nouvelles communications par duplication des templates.`, pt: `O sistema implementado permite a ${effectiveClientName} produzir novas comunicações por duplicação dos templates.`, en: `The system allows ${effectiveClientName} to produce new communications by duplicating templates.`, de: `Neue Kommunikation durch Duplikation.`, it: `Nuove comunicazioni duplicando i template.` }),
      summaryLabel: Lq({ fr: `Temps total consacré au projet.\nLivré, documenté, prêt à l'emploi.`, pt: `Tempo total dedicado ao projeto.\nEntregue, documentado, pronto a usar.`, en: `Total time dedicated to the project.\nDelivered, documented, ready to use.`, de: `Gesamtzeit für das Projekt.`, it: `Tempo totale dedicato al progetto.` }),
      signatureLabel: "Genève · Suisse · abil.ch",
      theme: reportTheme,
      wizardInputs: {
        serviceHours: { ...serviceHours },
        universalHours: { ...universalHours },
        overrideLead: overrideLead || undefined,
        overrideCommitment: overrideCommitment || undefined,
        overrideClosingOrg: overrideClosingOrg || undefined,
        overrideClosingBenefice: overrideClosingBenefice || undefined,
      },
    };

                                                                                      
    if (existingReport) {
      wr.id = existingReport.id;
      wr.createdAt = existingReport.createdAt;
      wr.status = existingReport.status;
                                                           
      if (existingReport.ref === wr.ref) wr.ref = existingReport.ref;
    }
    onCreate(wr);
    setSubmitting(false);
  };

                                                                                      
  const canEditClient = !presentation;
  const canEditProject = !presentation;

  return (
    <Modal open={open} onClose={onClose} size="lg">
      <div className="p-8 space-y-6 max-h-[85vh] overflow-y-auto">
        {            }
        <div className="border-b border-neutral-200 pb-4">
          <div className="eyebrow text-rouge mb-2">* {Lq({ fr: "Rapport de travail", pt: "Relatório de trabalho", en: "Work report", de: "Arbeitsbericht", it: "Rapporto di lavoro" })}</div>
          <h2 className="font-semibold text-2xl tracking-tight">{labels.header}</h2>
          <p className="text-sm text-neutral-600 mt-2 leading-relaxed">{labels.subtitle}</p>
          {                                                                     }
          {availablePresentations && availablePresentations.length > 0 && onPickPresentation && (
            <div className="mt-3 space-y-2">
              <div className="font-mono text-[9px] uppercase tracking-[0.18em] text-noir">{Lq({ fr: "* Présentation source (optionnel)", pt: "* Apresentação de origem (opcional)", en: "* Source presentation (optional)", de: "* Quellpräsentation (optional)", it: "* Presentazione (opzionale)" })}</div>
              <select
                value={presentation?.id ?? ""}
                onChange={(e) => onPickPresentation(e.target.value)}
                className="w-full border-2 border-neutral-300 px-3 py-2.5 text-sm focus:outline-none focus:border-rouge bg-white"
              >
                <option value="">{Lq({ fr: ", sans présentation (saisie libre), ", pt: ", sem apresentação (preenchimento livre), ", en: ", no presentation (free input), ", de: ", ohne Präsentation, ", it: ", senza presentazione, " })}</option>
                {availablePresentations.map((p) => {
                  const ln = leads.find((l) => l.id === p.clientId)?.nom || Lq({ fr: "Sans client", pt: "Sem cliente", en: "No client", de: "Ohne Kunde", it: "Senza cliente" });
                  return <option key={p.id} value={p.id}>{p.title} · {ln}</option>;
                })}
              </select>
            </div>
          )}
          {presentation && (
            <div className="mt-3 flex items-center gap-2 flex-wrap">
              <span className="font-mono text-[9px] uppercase tracking-[0.18em] bg-noir text-white px-2 py-1">{presentation.title}</span>
              <span className="font-mono text-[9px] uppercase tracking-[0.18em] bg-white border border-neutral-300 text-neutral-600 px-2 py-1">{derivedClientName}</span>
            </div>
          )}
        </div>

        {                                                  }
        <div className="space-y-3">
          <div className="flex items-end justify-between">
            <div className="eyebrow text-noir">{labels.sectionServices}</div>
            <div className="font-mono text-[10px] uppercase tracking-[0.18em] text-rouge">
              {labels.totalServicesLabel}: <span className="text-noir font-bold">{totalServicesHours}{labels.hoursUnit}</span>
            </div>
          </div>
          <div className="space-y-2">
            {WORK_REPORT_SERVICE_CATALOG.map((expertise) => {
              const expanded = !!expandedExpertise[expertise.expertiseId];
              const selectedCount = expertise.services.filter((s) => (serviceHours[s.id] || 0) > 0).length;
              const expertiseHours = expertise.services.reduce((sum, s) => sum + (serviceHours[s.id] || 0), 0);
              return (
                <div key={expertise.expertiseId} className="border-2 border-neutral-200">
                  <button
                    type="button"
                    onClick={() => toggleExpertise(expertise.expertiseId)}
                    className={`w-full flex items-center justify-between gap-3 px-3 py-2.5 text-left transition-colors ${selectedCount > 0 ? "bg-rouge/5" : "bg-white hover:bg-neutral-50"}`}
                  >
                    <div className="flex items-center gap-3">
                      <div className={`flex-shrink-0 w-8 h-8 flex items-center justify-center ${selectedCount > 0 ? "bg-rouge text-white" : "bg-noir text-rouge"}`}>
                        <WorkReportIconSvg name={expertise.icon} className="w-4 h-4" />
                      </div>
                      <div>
                        <div className="font-semibold text-sm">{Lq(expertise.expertiseLabel)}</div>
                        <div className="font-mono text-[10px] uppercase tracking-[0.16em] text-neutral-500">
                          {selectedCount > 0 ? `${selectedCount} ${Lq({ fr: "sélectionné(s)", pt: "selecionado(s)", en: "selected", de: "ausgewählt", it: "selezionato/i" })} · ${expertiseHours}h` : `${expertise.services.length} ${Lq({ fr: "services disponibles", pt: "serviços disponíveis", en: "services available", de: "verfügbar", it: "disponibili" })}`}
                        </div>
                      </div>
                    </div>
                    <div className="font-mono text-[10px] uppercase tracking-[0.18em] text-rouge">
                      {expanded ? "−" : "+"}
                    </div>
                  </button>
                  {expanded && (
                    <div className="border-t border-neutral-200 bg-neutral-50/50 divide-y divide-neutral-200">
                      {expertise.services.map((svc) => {
                        const h = serviceHours[svc.id] || 0;
                        const selected = h > 0;
                        return (
                          <div key={svc.id} className={`flex items-start gap-3 px-3 py-2.5 ${selected ? "bg-white" : ""}`}>
                            <input
                              type="checkbox"
                              checked={selected}
                              onChange={() => toggleSvc(svc.id, svc.defaultHours)}
                              className="mt-1 accent-rouge flex-shrink-0"
                            />
                            <div className="flex-1 min-w-0">
                              <div className="font-semibold text-sm">{Lq(svc.label)}</div>
                              <div className="text-xs text-neutral-500 mt-0.5 leading-snug">{Lq(svc.descLabel)}</div>
                            </div>
                            <div className="flex-shrink-0 flex items-center gap-1">
                              <input
                                type="number"
                                min={0}
                                step={0.5}
                                value={selected ? h : ""}
                                placeholder={String(svc.defaultHours)}
                                onChange={(e) => setSvcHours(svc.id, parseFloat(e.target.value) || 0)}
                                disabled={!selected}
                                className="w-16 border-2 border-neutral-300 px-2 py-1 text-sm text-right focus:outline-none focus:border-rouge font-mono disabled:bg-neutral-100 disabled:text-neutral-400"
                              />
                              <span className="font-mono text-[10px] text-neutral-500">{labels.hoursUnit}</span>
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>

        {                                 }
        <div className="space-y-3">
          <div className="flex items-end justify-between">
            <div className="eyebrow text-noir">{labels.sectionUniversal}</div>
            <div className="font-mono text-[10px] uppercase tracking-[0.18em] text-rouge">
              {labels.totalUniversalLabel}: <span className="text-noir font-bold">{totalUniversalHours}{labels.hoursUnit}</span>
            </div>
          </div>
          <div className="space-y-2">
            {WORK_REPORT_UNIVERSAL_STEPS.map((step) => {
              const h = universalHours[step.id] || 0;
              return (
                <div key={step.id} className={`flex items-start gap-3 border-2 px-3 py-2.5 transition-colors ${h > 0 ? "border-neutral-300 bg-white" : "border-neutral-200 bg-neutral-50"}`}>
                  <div className="flex-shrink-0 w-9 h-9 bg-noir text-rouge flex items-center justify-center">
                    <WorkReportIconSvg name={step.icon} className="w-5 h-5" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="font-semibold text-sm">{Lq(step.label)}</div>
                    <div className="text-xs text-neutral-500 mt-0.5 leading-snug">{Lq(step.descLabel)}</div>
                  </div>
                  <div className="flex-shrink-0 flex items-center gap-1">
                    <input
                      type="number"
                      min={0}
                      step={0.5}
                      value={h}
                      onChange={(e) => setUnivHours(step.id, parseFloat(e.target.value) || 0)}
                      className="w-16 border-2 border-neutral-300 px-2 py-1 text-sm text-right focus:outline-none focus:border-rouge font-mono"
                    />
                    <span className="font-mono text-[10px] text-neutral-500">{labels.hoursUnit}</span>
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        {                      }
        <div className="flex items-center justify-between border-2 border-noir bg-noir text-white px-4 py-3">
          <div className="font-mono text-[10px] uppercase tracking-[0.18em] text-white/70">{labels.totalAllLabel}</div>
          <div className="font-bold text-2xl">{totalHours}<span className="font-mono text-sm text-white/60 ml-1">{labels.hoursUnit}</span></div>
        </div>

        {                    }
        <div className="space-y-3">
          <div className="eyebrow text-noir">{labels.sectionMeta}</div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
            <div>
              <div className="font-mono text-[9px] uppercase tracking-[0.18em] text-neutral-500 mb-1">{labels.refLabel}</div>
              <input value={refOverride || autoRef} onChange={(e) => setRefOverride(e.target.value)} className="w-full border-2 border-neutral-300 px-3 py-2.5 text-sm focus:outline-none focus:border-rouge font-mono" />
            </div>
            <div>
              <div className="font-mono text-[9px] uppercase tracking-[0.18em] text-neutral-500 mb-1">{labels.clientLabel}{canEditClient ? "" : " (auto)"}</div>
              <input
                value={canEditClient ? clientNameInput : derivedClientName}
                onChange={(e) => canEditClient && setClientNameInput(e.target.value)}
                placeholder={Lq({ fr: "Nom du client", pt: "Nome do cliente", en: "Client name", de: "Kundenname", it: "Nome cliente" })}
                readOnly={!canEditClient}
                className={`w-full border-2 px-3 py-2.5 text-sm focus:outline-none ${canEditClient ? "border-neutral-300 focus:border-rouge" : "border-neutral-200 bg-neutral-50 text-neutral-700"}`}
              />
            </div>
            <div>
              <div className="font-mono text-[9px] uppercase tracking-[0.18em] text-neutral-500 mb-1">{labels.projectLabel}{canEditProject ? "" : " (auto)"}</div>
              <input
                value={canEditProject ? projectInput : derivedProject}
                onChange={(e) => canEditProject && setProjectInput(e.target.value)}
                placeholder={Lq({ fr: "Titre du projet", pt: "Título do projeto", en: "Project title", de: "Projekttitel", it: "Titolo progetto" })}
                readOnly={!canEditProject}
                className={`w-full border-2 px-3 py-2.5 text-sm focus:outline-none ${canEditProject ? "border-neutral-300 focus:border-rouge" : "border-neutral-200 bg-neutral-50 text-neutral-700"}`}
              />
            </div>
            <div>
              <div className="font-mono text-[9px] uppercase tracking-[0.18em] text-neutral-500 mb-1">{labels.locationLabel}</div>
              <input value={clientLocation} onChange={(e) => setClientLocation(e.target.value)} placeholder="Genève · Suisse" className="w-full border-2 border-neutral-300 px-3 py-2.5 text-sm focus:outline-none focus:border-rouge" />
            </div>
            <div className="md:col-span-2">
              <div className="font-mono text-[9px] uppercase tracking-[0.18em] text-neutral-500 mb-1">{labels.taglineLabel}</div>
              <input value={clientTagline} onChange={(e) => setClientTagline(e.target.value)} placeholder={Lq({ fr: "Ex. : Le coffre-fort intelligent", pt: "Ex.: O cofre inteligente", en: "Ex.: The smart vault", de: "Beispiel", it: "Es." })} className="w-full border-2 border-neutral-300 px-3 py-2.5 text-sm focus:outline-none focus:border-rouge" />
            </div>
            {                                                                                                    }
            <div className="md:col-span-2">
              <div className="font-mono text-[9px] uppercase tracking-[0.18em] text-neutral-500 mb-1">{labels.logoLabel}</div>
              {clientLogoDataUrl ? (
                <div className="border-2 border-neutral-300 p-4 flex items-center justify-between gap-4 bg-neutral-50">
                  <img src={clientLogoDataUrl} alt="logo" style={{ height: "48px", width: "auto", maxWidth: "200px", objectFit: "contain" }} />
                  <button
                    type="button"
                    onClick={() => setClientLogoDataUrl("")}
                    className="px-3 py-1.5 font-mono text-[9px] uppercase tracking-[0.18em] border border-rouge text-rouge hover:bg-rouge hover:text-white transition-colors"
                  >
                    {labels.logoRemove}
                  </button>
                </div>
              ) : (
                <label className="block border-2 border-dashed border-neutral-300 hover:border-rouge transition-colors p-6 text-center cursor-pointer">
                  <input
                    type="file"
                    accept="image/png,image/jpeg,image/svg+xml,image/webp"
                    onChange={(e) => {
                      const f = e.target.files?.[0];
                      if (!f) return;
                      if (f.size > 1024 * 1024) { window.alert(Lq({ fr: "Logo trop grand (max 1 Mo)", pt: "Logo demasiado grande (máx 1 MB)", en: "Logo too large (max 1 MB)", de: "Logo zu groß", it: "Logo troppo grande" })); return; }
                      void (async () => {
                        const reader = new FileReader();
                        const base64 = await new Promise<string>((res) => { reader.onload = () => res(String(reader.result || "")); reader.readAsDataURL(f); });
                        if (!base64) return;
                                                                                                                  
                                                                                                                
                        let url = base64;
                        try {
                          const { cloudUploadFile } = await import("@/lib/cloudProjects");
                          const up = await cloudUploadFile(f, { prefix: "assets" });
                          if (up.ok && up.url) url = up.url;
                        } catch {                                         }
                        setClientLogoDataUrl(url);
                                                                                      
                        const key = (effectiveClientName || "").trim().toLowerCase();
                        if (key && url) setClientLogosVault((v) => ({ ...v, [key]: url }));
                      })();
                    }}
                    className="hidden"
                  />
                  <IconUpload className="w-6 h-6 text-neutral-400 mx-auto mb-2" />
                  <div className="font-mono text-[10px] uppercase tracking-[0.18em] text-neutral-500">{Lq({ fr: "Cliquez pour choisir", pt: "Clica para escolher", en: "Click to choose", de: "Klicken zum Auswählen", it: "Clicca per scegliere" })}</div>
                  <div className="text-xs text-neutral-500 mt-2 leading-snug">{labels.logoHint}</div>
                </label>
              )}
            </div>
          </div>
        </div>

        {                                                            }
        <div className="space-y-3">
          <div className="eyebrow text-noir">* {Lq({ fr: "Thème du rapport", pt: "Tema do relatório", en: "Report theme", de: "Berichts-Thema", it: "Tema rapporto" })}</div>
          <div className="flex gap-2">
            {(["noir", "blanc", "rouge"] as const).map((th) => {
              const isActive = reportTheme === th;
              const labelTh = th === "noir" ? Lq({ fr: "Noir (standard)", pt: "Noir (padrão)", en: "Noir (default)", de: "Schwarz", it: "Nero" }) : th === "blanc" ? Lq({ fr: "Blanc", pt: "Branco", en: "White", de: "Weiß", it: "Bianco" }) : "Rouge";
              const swatch = th === "noir" ? "#0a0a0b" : th === "blanc" ? "#fff" : "#d2ff01";
              const borderClass = isActive ? "border-rouge bg-rouge/5" : "border-neutral-300 hover:border-rouge";
              return (
                <button
                  key={th}
                  type="button"
                  onClick={() => setReportTheme(th)}
                  className={`flex-1 border-2 px-3 py-2.5 text-left transition-colors ${borderClass}`}
                >
                  <div className="flex items-center gap-2">
                    <span style={{ width: 18, height: 18, background: swatch, border: th === "blanc" ? "1px solid #ccc" : "none", display: "inline-block" }} />
                    <span className="font-mono text-[9px] uppercase tracking-[0.16em] text-noir">{labelTh}</span>
                  </div>
                </button>
              );
            })}
          </div>
        </div>

        {                                                                                             }
        <div className="space-y-3">
          <div className="eyebrow text-noir">* {Lq({ fr: "Textes personnalisés (optionnel)", pt: "Textos personalizados (opcional)", en: "Custom texts (optional)", de: "Eigene Texte", it: "Testi personalizzati" })}</div>
          <div className="space-y-2">
            <div>
              <div className="font-mono text-[9px] uppercase tracking-[0.18em] text-neutral-500 mb-1">{Lq({ fr: "Lead (résumé en haut de la couverture)", pt: "Lead (resumo no topo da capa)", en: "Lead (cover summary)", de: "Lead (Deckblatt)", it: "Lead (sommario)" })}</div>
              <textarea value={overrideLead} onChange={(e) => setOverrideLead(e.target.value)} rows={3} placeholder={Lq({ fr: "Laisser vide pour utiliser le texte généré automatiquement", pt: "Deixar vazio para usar o texto gerado automaticamente", en: "Leave empty to use auto-generated", de: "Leer für Auto-Text", it: "Vuoto per auto" })} className="w-full border-2 border-neutral-300 px-3 py-2 text-sm focus:outline-none focus:border-rouge resize-none" />
            </div>
            <div>
              <div className="font-mono text-[9px] uppercase tracking-[0.18em] text-neutral-500 mb-1">{Lq({ fr: "Engagement (P9, encadré rouge)", pt: "Compromisso (P9, caixa rouge)", en: "Commitment (P9, red block)", de: "Engagement", it: "Impegno" })}</div>
              <textarea value={overrideCommitment} onChange={(e) => setOverrideCommitment(e.target.value)} rows={2} placeholder={Lq({ fr: "Auto si vide", pt: "Auto se vazio", en: "Auto if empty", de: "Auto", it: "Auto" })} className="w-full border-2 border-neutral-300 px-3 py-2 text-sm focus:outline-none focus:border-rouge resize-none" />
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
              <div>
                <div className="font-mono text-[9px] uppercase tracking-[0.18em] text-neutral-500 mb-1">{Lq({ fr: "Clôture · Organisation", pt: "Encerramento · Organização", en: "Closing · Organization", de: "Abschluss · Org", it: "Chiusura · Org" })}</div>
                <textarea value={overrideClosingOrg} onChange={(e) => setOverrideClosingOrg(e.target.value)} rows={3} placeholder={Lq({ fr: "Auto si vide", pt: "Auto", en: "Auto", de: "Auto", it: "Auto" })} className="w-full border-2 border-neutral-300 px-3 py-2 text-sm focus:outline-none focus:border-rouge resize-none" />
              </div>
              <div>
                <div className="font-mono text-[9px] uppercase tracking-[0.18em] text-neutral-500 mb-1">{Lq({ fr: "Clôture · Bénéfice", pt: "Encerramento · Benefício", en: "Closing · Benefit", de: "Abschluss · Nutzen", it: "Chiusura · Beneficio" })}</div>
                <textarea value={overrideClosingBenefice} onChange={(e) => setOverrideClosingBenefice(e.target.value)} rows={3} placeholder={Lq({ fr: "Auto si vide", pt: "Auto", en: "Auto", de: "Auto", it: "Auto" })} className="w-full border-2 border-neutral-300 px-3 py-2 text-sm focus:outline-none focus:border-rouge resize-none" />
              </div>
            </div>
          </div>
        </div>

        {            }
        <div className="flex gap-3 pt-4 border-t border-neutral-200">
          <button
            onClick={() => { if (!submitting) onClose(); }}
            disabled={submitting}
            className="flex-1 px-4 py-3 eyebrow bg-white border-2 border-neutral-300 text-noir hover:border-rouge hover:text-rouge transition-colors"
            type="button"
          >
            {labels.cancel}
          </button>
          <button
            onClick={handleGenerate}
            disabled={submitting || totalServicesHours === 0}
            className="flex-[2] px-4 py-3 eyebrow bg-rouge text-white hover:bg-noir transition-colors disabled:opacity-40 disabled:cursor-not-allowed"
            type="button"
          >
            {submitting ? labels.generating : labels.generate}
          </button>
        </div>
      </div>
    </Modal>
  );
}



function DashboardWorkReportsModule() {
  const { showToast, lang } = useApp();
  const localeOf = (l: string) => ({ fr: "fr-CH", de: "de-CH", en: "en-GB", pt: "pt-PT", it: "it-CH", es: "es-ES" } as Record<string, string>)[l] || "fr-CH";
  const [reports, setReports] = useLocalStorageState<WorkReport[]>("abil_work_reports", []);
  const [filter, setFilter] = useState<WorkReport["status"] | "all">("all");
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [busy, setBusy] = useState<string | null>(null);
  const Lq = (o: Record<string, string>) => _trO(o, lang);

                                                                                  
                                                                            
                                                                                   
                                                                                  
                                                                                    
                                                                        

                                                                                        
                                                                                         
                                                                                            
  const [presentations] = useDashPresentationsIDB();
  const [leads] = useLocalStorageState<Lead[]>("abil_crm_leads", []);
  const [wizardOpen, setWizardOpen] = useState(false);
  const [wizardPresId, setWizardPresId] = useState<string | null>(null);
  const [editingReportId, setEditingReportId] = useState<string | null>(null);                                                                      
  const openWizard = () => { setWizardPresId(null); setWizardOpen(true); };
  const closeWizard = () => { setWizardOpen(false); setWizardPresId(null); };
  const duplicate = (wr: WorkReport) => {
    const copy: WorkReport = { ...wr, id: `wr_${Date.now().toString(36)}`, ref: wr.ref + "-COPY", createdAt: new Date().toISOString(), status: "rascunho" };
    setReports((prev) => [copy, ...prev]);
    setSelectedId(copy.id);
    showToast?.(Lq({ fr: "Rapport dupliqué", pt: "Relatório duplicado", en: "Report duplicated", de: "Bericht dupliziert", it: "Rapporto duplicato" }));
  };
  const remove = (id: string) => {
    if (!window.confirm(Lq({ fr: "Supprimer ce rapport ? Irréversible.", pt: "Apagar este relatório? Irreversível.", en: "Delete this report? Irreversible.", de: "Diesen Bericht löschen?", it: "Eliminare questo rapporto?" }))) return;
    setReports((prev) => prev.filter((r) => r.id !== id));
    if (selectedId === id) setSelectedId(null);
  };
  const setStatus = (id: string, status: WorkReport["status"]) => {
    setReports((prev) => prev.map((r) => r.id === id ? { ...r, status } : r));
  };
  const download = async (wr: WorkReport) => {
    setBusy(wr.id);
    setSelectedId(wr.id);
    await new Promise((r) => setTimeout(r, 200));
    try {
      await downloadWorkReportPdf(wr, lang);
      showToast?.(`PDF · ${wr.ref}.pdf`);
    } catch (e) {
      showToast?.(`${Lq({ fr: "Erreur PDF", pt: "Erro PDF", en: "PDF error", de: "PDF-Fehler", it: "Errore PDF" })}: ${(e as Error).message}`);
    } finally {
      setBusy(null);
    }
  };

                                                         
  const counts = {
    all: reports.length,
    rascunho: reports.filter((r) => r.status === "rascunho").length,
    em_revisao: reports.filter((r) => r.status === "em_revisao").length,
    aprovado: reports.filter((r) => r.status === "aprovado").length,
  };
  const filtered = filter === "all" ? reports : reports.filter((r) => r.status === filter);
  const selected = selectedId ? reports.find((r) => r.id === selectedId) || null : null;

  const statusLabel: Record<WorkReport["status"], string> = {
    rascunho: Lq({ fr: "Brouillon", pt: "Rascunho", en: "Draft", de: "Entwurf", it: "Bozza" }),
    em_revisao: Lq({ fr: "En révision", pt: "Em revisão", en: "In review", de: "In Prüfung", it: "In revisione" }),
    aprovado: Lq({ fr: "Approuvé", pt: "Aprovado", en: "Approved", de: "Genehmigt", it: "Approvato" }),
  };
  const filterLabel: Record<"all" | WorkReport["status"], string> = {
    all: Lq({ fr: "Tous", pt: "Todos", en: "All", de: "Alle", it: "Tutti" }),
    ...statusLabel,
  };
  const statusBadgeCls = (s: WorkReport["status"]) =>
    s === "rascunho" ? "bg-neutral-300 text-neutral-700" :
    s === "em_revisao" ? "bg-amber-500 text-white" :
    s === "aprovado" ? "bg-emerald-600 text-white" :
    "bg-neutral-300 text-neutral-700";
  const tabActiveCls = (key: "all" | WorkReport["status"]) =>
    key === "rascunho" ? "bg-neutral-300 text-neutral-700 border-neutral-300" :
    key === "em_revisao" ? "bg-amber-500 text-white border-amber-500" :
    key === "aprovado" ? "bg-emerald-600 text-white border-emerald-600" :
    "bg-noir text-white border-noir";

  return (
    <div className="space-y-6">
      <div>
        <h1 className="h1-section">{Lq({ fr: "Rapports de travail", pt: "Relatórios de trabalho", en: "Work reports", de: "Arbeitsberichte", it: "Rapporti di lavoro" })}</h1>
        <p className="text-sm text-neutral-500 mt-1 max-w-3xl leading-relaxed">
          {Lq({
            fr: "Documents A4 récapitulant le temps consacré, l'équipe mobilisée et les livrables produits. Générés à partir des Présentations livrées. Phase 1 : moteur + page. Phase 2 : assistant de sélection (équipe, étapes, services, heures).",
            pt: "Documentos A4 a sumariar tempo dedicado, equipa mobilizada e entregáveis. Gerados a partir das Apresentações entregues. Fase 1: motor + página. Fase 2: wizard de seleção (equipa, etapas, serviços, horas).",
            en: "A4 documents summing up time spent, team mobilised and deliverables. Generated from Presentations. Phase 1: engine + page. Phase 2: wizard (team, steps, services, hours).",
            de: "A4-Berichte mit Zeit, Team und Lieferobjekten. Aus Präsentationen erzeugt. Phase 1: Motor + Seite. Phase 2: Assistent.",
            it: "Documenti A4 con tempo, team e deliverable. Generati dalle Presentazioni. Fase 1: motore + pagina. Fase 2: wizard.",
          })}
        </p>
      </div>

      {                                                           }
      <div className="flex flex-wrap gap-2">
        {(["all", "rascunho", "em_revisao", "aprovado"] as const).map((key) => {
          const isActive = filter === key;
          const activeClass = tabActiveCls(key);
          const inactiveClass = "bg-white text-neutral-600 border-neutral-300 hover:border-rouge";
          return (
            <button
              key={key}
              onClick={() => setFilter(key)}
              className={`px-3 py-2 font-mono text-[10px] uppercase tracking-[0.18em] border-2 transition-colors ${isActive ? activeClass : inactiveClass}`}
            >
              {filterLabel[key]} · {counts[key]}
            </button>
          );
        })}
      </div>

      {filtered.length === 0 && reports.length === 0 ? (
        <div className="text-center py-20 border-2 border-dashed border-neutral-300">
          <IconFileText className="w-10 h-10 text-neutral-300 mx-auto mb-3" />
          <p className="text-neutral-500">{Lq({ fr: "Aucun rapport pour l'instant", pt: "Ainda sem relatórios", en: "No reports yet", de: "Noch keine Berichte", it: "Ancora nessun rapporto" })}</p>
          <p className="text-xs text-neutral-400 mt-2 max-w-md mx-auto leading-relaxed">{Lq({ fr: "Les rapports sont aussi accessibles depuis la page « Présentations privées » (bouton « Rapport » sur le card).", pt: "Os relatórios também são acessíveis a partir de « Apresentações privadas » (botão « Relatório » no card).", en: "Reports can also be created from « Private presentations » (« Report » button on the card).", de: "Berichte sind auch über « Private Präsentationen » erreichbar.", it: "I rapporti sono accessibili anche da « Presentazioni private »." })}</p>
          <button
            onClick={openWizard}
            className="mt-6 inline-flex items-center gap-2 px-3 py-2 font-mono text-[10px] uppercase tracking-[0.18em] border-2 border-noir bg-noir text-white hover:bg-rouge hover:border-rouge transition-colors"
          >
            <IconPlus className="w-3.5 h-3.5" />
            {Lq({ fr: "Nouveau rapport", pt: "Novo relatório", en: "New report", de: "Neuer Bericht", it: "Nuovo rapporto" })}
          </button>
        </div>
      ) : (
        <div className="grid grid-cols-12 gap-4">
          {                            }
          <div className="col-span-12 lg:col-span-4 space-y-2 max-h-[80vh] overflow-y-auto">
            {filtered.map((r) => (
              <div
                key={r.id}
                className={`border-2 transition-colors ${selectedId === r.id ? "border-rouge bg-rouge/5" : "border-neutral-200 hover:border-rouge bg-white"}`}
              >
                <button onClick={() => setSelectedId(r.id)} className="w-full text-left p-4">
                  <div className="flex items-start justify-between gap-2 mb-1">
                    <div className="eyebrow text-rouge">{r.ref}</div>
                    <span className={`font-mono text-[9px] uppercase tracking-[0.18em] px-2 py-1 ${statusBadgeCls(r.status)}`}>{statusLabel[r.status]}</span>
                  </div>
                  <div className="font-semibold text-base mb-1">{r.project.replace(/\.$/, "")}</div>
                  <div className="text-xs text-neutral-500 mb-2">{r.client.name}{r.client.location ? ` · ${r.client.location}` : ""}</div>
                  <div className="flex items-center justify-between mt-2 pt-2 border-t border-neutral-100">
                    <div className="font-mono text-[10px] text-neutral-400">{new Date(r.createdAt).toLocaleDateString(localeOf(lang))}</div>
                    <div className="font-semibold text-sm">{r.totalHours} h · {r.phases.length} {Lq({ fr: "phases", pt: "fases", en: "phases", de: "Phasen", it: "fasi" })}</div>
                  </div>
                </button>
              </div>
            ))}
            {                                                                                      }
            <button
              onClick={openWizard}
              className="w-full border-2 border-dashed border-neutral-300 hover:border-rouge p-6 text-center transition-colors bg-white"
            >
              <IconPlus className="w-5 h-5 mx-auto mb-2 text-neutral-400" />
              <div className="font-mono text-[10px] uppercase tracking-[0.18em] text-neutral-500">
                {Lq({ fr: "Nouveau rapport", pt: "Novo relatório", en: "New report", de: "Neuer Bericht", it: "Nuovo rapporto" })}
              </div>
              <div className="font-mono text-[9px] tracking-[0.14em] text-neutral-400 mt-1">
                {Lq({ fr: "* Ouvre l'assistant", pt: "* Abre o assistente", en: "* Opens the wizard", de: "* Öffnet den Assistenten", it: "* Apre l'assistente" })}
              </div>
            </button>
          </div>

          {                                             }
          <div className="col-span-12 lg:col-span-8">
            {selected ? (
              <div className="space-y-3">
                {                                                                 }
                <div className="flex flex-nowrap gap-1.5 bg-white border-2 border-neutral-200 p-2 sticky top-0 z-10 mx-auto overflow-x-auto" style={{ width: "210mm", maxWidth: "100%" }}>
                  {(() => {
                    const selectClass =
                      selected.status === "rascunho" ? "bg-neutral-300 text-neutral-700 border-neutral-300" :
                      selected.status === "em_revisao" ? "bg-amber-500 text-white border-amber-500" :
                      selected.status === "aprovado" ? "bg-emerald-600 text-white border-emerald-600" :
                      "bg-white text-noir border-neutral-300";
                    return (
                      <select
                        value={selected.status}
                        onChange={(e) => setStatus(selected.id, e.target.value as WorkReport["status"])}
                        className={`font-mono text-[9px] uppercase tracking-[0.16em] border-2 px-2 py-2 focus:outline-none flex-shrink-0 min-w-0 transition-colors ${selectClass}`}
                      >
                        <option value="rascunho" className="bg-white text-noir">{statusLabel.rascunho}</option>
                        <option value="em_revisao" className="bg-white text-noir">{statusLabel.em_revisao}</option>
                        <option value="aprovado" className="bg-white text-noir">{statusLabel.aprovado}</option>
                      </select>
                    );
                  })()}
                  <button
                    onClick={() => download(selected)}
                    disabled={busy === selected.id}
                    className="px-2.5 py-2 font-mono text-[9px] uppercase tracking-[0.16em] bg-white border-2 border-neutral-300 text-noir hover:border-rouge hover:text-rouge transition-colors flex items-center gap-1.5 flex-shrink-0 whitespace-nowrap disabled:opacity-50"
                  >
                    <IconPrinter className="w-3.5 h-3.5" /> {busy === selected.id ? "..." : Lq({ fr: "Télécharger PDF", pt: "Baixar PDF", en: "Download PDF", de: "PDF herunterladen", it: "Scarica PDF" })}
                  </button>
                  {                                                                                  }
                  <button
                    onClick={() => { setEditingReportId(selected.id); setWizardOpen(true); }}
                    className="px-2.5 py-2 font-mono text-[9px] uppercase tracking-[0.16em] bg-white border-2 border-neutral-300 text-noir hover:border-rouge hover:text-rouge transition-colors flex items-center gap-1.5 flex-shrink-0 whitespace-nowrap"
                    title={Lq({ fr: "Éditer dans l'assistant (pré-rempli)", pt: "Editar no assistente (pré-preenchido)", en: "Edit in wizard (pre-filled)", de: "Im Assistenten bearbeiten", it: "Modifica nell'assistente" })}
                  >
                    <IconEdit className="w-3.5 h-3.5" /> {Lq({ fr: "Éditer", pt: "Editar", en: "Edit", de: "Bearbeiten", it: "Modifica" })}
                  </button>
                  <button
                    onClick={() => duplicate(selected)}
                    className="px-2.5 py-2 font-mono text-[9px] uppercase tracking-[0.16em] bg-white border-2 border-neutral-300 text-noir hover:border-rouge hover:text-rouge transition-colors flex items-center gap-1.5 flex-shrink-0 whitespace-nowrap"
                  >
                    <IconLayers className="w-3.5 h-3.5" /> {Lq({ fr: "Dupliquer", pt: "Duplicar", en: "Duplicate", de: "Duplizieren", it: "Duplica" })}
                  </button>
                  <button
                    onClick={() => remove(selected.id)}
                    className="ml-auto w-9 h-9 bg-white border-2 border-neutral-300 text-noir flex items-center justify-center hover:bg-rouge hover:text-white hover:border-rouge transition-colors flex-shrink-0"
                    title={Lq({ fr: "Supprimer", pt: "Apagar", en: "Delete", de: "Löschen", it: "Elimina" })}
                  >
                    <IconTrash className="w-4 h-4" />
                  </button>
                </div>

                {                             }
                <div className="mx-auto" style={{ width: "210mm", maxWidth: "100%" }}>
                  <WorkReportDocument
                    report={selected}
                    onChange={(updated) => setReports((prev) => prev.map((r) => r.id === updated.id ? updated : r))}
                  />
                </div>

                <div className="mx-auto" style={{ width: "210mm", maxWidth: "100%" }}>
                  <div className="font-mono text-[9px] uppercase tracking-[0.18em] text-neutral-400 pl-1">
                    {Lq({ fr: "* Édition inline du contenu arrive en Phase 2", pt: "* Edição inline do conteúdo chega na Fase 2", en: "* Inline content editing in Phase 2", de: "* Inline-Bearbeitung in Phase 2", it: "* Modifica inline in Fase 2" })}
                  </div>
                </div>
              </div>
            ) : (
              <div className="bg-neutral-50 border-2 border-dashed border-neutral-300 p-12 text-center text-sm text-neutral-500">
                {Lq({ fr: "Sélectionne un rapport à gauche pour voir le PDF A4 complet.", pt: "Selecciona um relatório à esquerda para ver o PDF A4 completo.", en: "Select a report on the left to see the full A4 PDF.", de: "Bericht links wählen.", it: "Seleziona un rapporto a sinistra." })}
              </div>
            )}
          </div>
        </div>
      )}

      {                                                                                           }
      <WorkReportWizardModal
        open={wizardOpen}
        onClose={() => { closeWizard(); setEditingReportId(null); }}
        presentation={wizardPresId ? (presentations.find((p) => p.id === wizardPresId) || null) : null}
        leads={leads}
        availablePresentations={editingReportId ? undefined : presentations}
        onPickPresentation={editingReportId ? undefined : (id) => setWizardPresId(id || null)}
        existingReport={editingReportId ? (reports.find((r) => r.id === editingReportId) || null) : null}
        onCreate={(wr) => {
          if (editingReportId) {
            setReports((prev) => prev.map((r) => r.id === wr.id ? wr : r));
            showToast?.(Lq({ fr: `Rapport mis à jour: ${wr.ref}`, pt: `Relatório atualizado: ${wr.ref}`, en: `Report updated: ${wr.ref}`, de: `Bericht aktualisiert`, it: `Rapporto aggiornato` }));
          } else {
            setReports((prev) => [wr, ...prev]);
            setSelectedId(wr.id);
            showToast?.(Lq({ fr: `Rapport généré : ${wr.ref}`, pt: `Relatório gerado: ${wr.ref}`, en: `Report generated: ${wr.ref}`, de: `Bericht erstellt: ${wr.ref}`, it: `Rapporto generato: ${wr.ref}` }));
          }
          closeWizard();
          setEditingReportId(null);
        }}
      />
    </div>
  );
}


                                                                                                      
                                                                                                     
                                                                                                      
                                                                                                        
                                                                                                       
                                                                                                     
function AbilSegmentsEditorModal({ onClose, showToast, lang }: { onClose: () => void; showToast: (m: string) => void; lang: Lang }) {
  const tn = (k: I18nNewKey) => tNew(lang, k);
  const tl = (o: Record<string, string>) => _trO(o, lang);
  const clone = (s: LeadSegment): LeadSegment => ({ ...s, keywords: [...(s.keywords || [])], dores: [...(s.dores || [])], oportunidades: [...(s.oportunidades || [])], projetos: [...((s.projetos as { nome: string; porque: string; thumb: string }[]) || [])].map((p) => ({ ...p })) });
  const [segs, setSegs] = useState<LeadSegment[]>(() => getLeadSegments().map(clone));
  const [sel, setSel] = useState<string>(() => getLeadSegments()[0]?.key || "");
                                                                                    
                                                                                                       
                                                                                                      
                                                                                                            
                                                                                                      
  const [cloudOk, setCloudOk] = useState<boolean | null>(null);
  useEffect(() => {
    let alive = true;
    void ensureCloudRead().then((ok) => {
      if (!alive) return;
      setCloudOk(ok);
      if (!ok) return;
      const fresh = getLeadSegments();                                                                                               
      setSegs(fresh.map(clone));
      setSel((s) => (fresh.some((x) => x.key === s) ? s : (fresh[0]?.key || "")));
    });
    return () => { alive = false; };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  const cur = segs.find((s) => s.key === sel);
  const upd = (patch: Partial<LeadSegment>) => setSegs((p) => p.map((s) => (s.key === sel ? { ...s, ...patch } : s)));
  const novoSegmento = () => {
    const label = window.prompt(tn("segNewPrompt")); if (!label || !label.trim()) return;
    const key = label.trim().toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g, "").replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "").slice(0, 40) || ("seg-" + label.length);
    if (segs.some((s) => s.key === key)) { showToast(tn("segDupWarn")); return; }
    const ns: LeadSegment = { key, label: label.trim(), keywords: [label.trim().toLowerCase()], dores: [], oportunidades: [], angulo: "", projetos: [] };
    setSegs((p) => [...p, ns]); setSel(key); showToast(tn("segCreated"));
  };
  const save = () => {
                                                                                                              
    if (cloudOk !== true) { showToast(tl({ pt: "Não gravei: não consegui ler a configuração no servidor, e gravar agora apagava os segmentos reais. Verifica a ligação e reabre o editor.", fr: "Rien enregistré : impossible de lire la configuration sur le serveur, et enregistrer maintenant effacerait les segments réels. Vérifiez la connexion et rouvrez l'éditeur.", en: "Nothing saved: could not read the configuration from the server, and saving now would wipe the real segments. Check the connection and reopen the editor.", de: "Nicht gespeichert: Konfiguration vom Server nicht lesbar, Speichern würde die echten Segmente löschen. Verbindung prüfen und Editor neu öffnen.", it: "Non salvato: non riesco a leggere la configurazione dal server, e salvare ora cancellerebbe i segmenti reali. Controlla la connessione e riapri l'editor.", es: "No guardé: no pude leer la configuración del servidor, y guardar ahora borraría los segmentos reales. Revisa la conexión y reabre el editor." })); return; }
                                                                                         
    const limpos = (Array.isArray(segs) ? segs : []).filter((s) => s && String(s.key || "").trim() && String(s.label || "").trim());
    if (!limpos.length) { showToast(tl({ pt: "Não gravei: a lista está vazia e isso apagaria todos os segmentos no servidor.", fr: "Rien enregistré : la liste est vide, cela effacerait tous les segments sur le serveur.", en: "Nothing saved: the list is empty and that would wipe every segment on the server.", de: "Nicht gespeichert: Die Liste ist leer, das würde alle Segmente auf dem Server löschen.", it: "Non salvato: la lista è vuota e cancellerebbe tutti i segmenti sul server.", es: "No guardé: la lista está vacía y eso borraría todos los segmentos del servidor." })); return; }
                                                                                                      
                                                                                                             
                                                                                              
    cloudSet("abil_lead_segments_v1", limpos);
    void (async () => {
      const ok = await cloudFlushNow();
      if (ok) { showToast(tn("segSaved")); onClose(); }
      else showToast(tl({ pt: "Não guardei no servidor: sessão expirada ou sem rede. Faz login de novo e tenta outra vez (as edições continuam neste editor).", fr: "Non enregistré sur le serveur : session expirée ou hors ligne. Reconnectez-vous et réessayez (les modifications restent dans cet éditeur).", en: "Not saved on the server: session expired or offline. Log in again and retry (your edits stay in this editor).", de: "Nicht auf dem Server gespeichert: Sitzung abgelaufen oder offline. Erneut anmelden und noch einmal versuchen (die Änderungen bleiben in diesem Editor).", it: "Non salvato sul server: sessione scaduta o offline. Rifai il login e riprova (le modifiche restano in questo editor).", es: "No se guardó en el servidor: sesión caducada o sin red. Vuelve a entrar e inténtalo de nuevo (las ediciones siguen en este editor)." }));
    })();
  };
  const reset = () => { const d = ABIL_LEAD_SEGMENTS.find((s) => s.key === sel); if (d) upd({ label: d.label, keywords: [...d.keywords], dores: [...d.dores], oportunidades: [...d.oportunidades], angulo: d.angulo, projetos: [...((d.projetos as { nome: string; porque: string; thumb: string }[]) || [])].map((p) => ({ ...p })) }); showToast(tn("segReset")); };
  const inp = "w-full bg-white border border-neutral-200 px-3 py-2 text-sm text-noir focus:outline-none focus:border-rouge";
  return (
    <div className="fixed inset-0 z-[200] bg-noir/95 backdrop-blur-sm flex items-start justify-center overflow-y-auto p-4 sm:p-6" onClick={onClose}>
      <div className="bg-white border border-neutral-200 w-full max-w-2xl my-6" onClick={(e) => e.stopPropagation()}>
        <div className="flex items-center justify-between border-b border-neutral-200 px-6 py-4">
          <div><div className="eyebrow text-neutral-500">{tn("segEditorTitle")}</div><div className="text-neutral-400 text-xs mt-1">{tn("segEditorDesc")}</div></div>
          <button onClick={onClose} className="text-neutral-400 hover:text-noir text-xl leading-none">×</button>
        </div>
        <div className="px-6 py-5 space-y-4">
          <div className="flex items-end gap-2">
            <label className="block space-y-1 flex-1"><span className="eyebrow text-neutral-500">{tn("segSegment")}</span><select value={sel} onChange={(e) => setSel(e.target.value)} className={inp}>{segs.map((s) => (<option key={s.key} value={s.key}>{s.label}</option>))}</select></label>
            <button type="button" onClick={novoSegmento} className="border border-neutral-200 text-neutral-600 px-3 py-2 eyebrow hover:border-rouge hover:text-rouge transition-colors whitespace-nowrap">{tn("segNew")}</button>
          </div>
          {cur && (<>
            <label className="block space-y-1"><span className="eyebrow text-neutral-500">{tn("segLabel")}</span><input value={cur.label} onChange={(e) => upd({ label: e.target.value })} className={inp} /></label>
            <label className="block space-y-1"><span className="eyebrow text-neutral-500">{tn("segKeywords")}</span><input value={cur.keywords.join(", ")} onChange={(e) => upd({ keywords: e.target.value.split(",").map((x) => x.trim()).filter(Boolean) })} className={inp} /></label>
            <label className="block space-y-1"><span className="eyebrow text-neutral-500">{tn("segPains")}</span><textarea rows={3} value={cur.dores.join("\n")} onChange={(e) => upd({ dores: e.target.value.split("\n").map((x) => x.trim()).filter(Boolean) })} className={inp} /></label>
            <label className="block space-y-1"><span className="eyebrow text-neutral-500">{tn("segOpps")}</span><textarea rows={3} value={cur.oportunidades.join("\n")} onChange={(e) => upd({ oportunidades: e.target.value.split("\n").map((x) => x.trim()).filter(Boolean) })} className={inp} /></label>
            <label className="block space-y-1"><span className="eyebrow text-neutral-500">{tn("segAngle")}</span><textarea rows={2} value={cur.angulo} onChange={(e) => upd({ angulo: e.target.value })} className={inp} /></label>
          </>)}
        </div>
        <div className="flex items-center justify-between gap-3 border-t border-neutral-200 px-6 py-4">
          <button type="button" onClick={reset} className="border border-neutral-200 text-neutral-600 px-4 py-2 eyebrow hover:bg-neutral-100 transition-colors">{tn("segResetBtn")}</button>
          <div className="flex items-center gap-3">
            {                                                                                                          }
            {cloudOk === null && <span className="font-mono text-[10px] text-neutral-400">{tl({ pt: "A ler a configuração do servidor…", fr: "Lecture de la configuration…", en: "Reading the server configuration…", de: "Konfiguration wird gelesen…", it: "Lettura della configurazione…", es: "Leyendo la configuración…" })}</span>}
            {cloudOk === false && <span className="font-mono text-[10px] text-amber-600 max-w-[260px] leading-snug">{tl({ pt: "Servidor ilegível: gravar apagaria os segmentos reais. Guardar desligado.", fr: "Serveur illisible : enregistrer effacerait les segments réels. Enregistrement désactivé.", en: "Server unreadable: saving would wipe the real segments. Save disabled.", de: "Server nicht lesbar: Speichern würde die echten Segmente löschen. Speichern deaktiviert.", it: "Server illeggibile: salvare cancellerebbe i segmenti reali. Salvataggio disattivato.", es: "Servidor ilegible: guardar borraría los segmentos reales. Guardar desactivado." })}</span>}
            <button type="button" onClick={save} disabled={cloudOk !== true} className="bg-rouge text-white px-5 py-2 eyebrow hover:bg-noir transition-colors disabled:opacity-40 disabled:cursor-not-allowed disabled:hover:bg-rouge">{tn("segSaveBtn")}</button>
          </div>
        </div>
      </div>
    </div>
  );
}

                                                                                              
                                                                                                           
                                                                                                                       
