  type ReplyEvent = { msgId: string; fromEmail: string; fromName?: string; subject?: string; snippet?: string; date?: string; seenAt?: string; leadId?: string; replyClass?: string };
  const [replyEvents, setReplyEvents] = useState<ReplyEvent[]>([]);
  const loadReplies = useCallback(async () => {
    let tok = ""; try { tok = localStorage.getItem("abil_vault_token") || ""; } catch {       }
    if (!tok) return;
    try { const r = await fetch("/api/reply-scan", { headers: { "x-abil-admin": tok }, cache: "no-store" }); if (r.ok) { const d = await r.json(); if (Array.isArray(d?.events)) setReplyEvents(d.events as ReplyEvent[]); } } catch {       }
  }, []);
  useEffect(() => { void loadReplies(); const iv = window.setInterval(() => { void loadReplies(); }, 60000); return () => window.clearInterval(iv); }, [loadReplies]);
                                                                                                  
                                                                                                 
  const resolveReplyLead = useCallback((ev: ReplyEvent): Lead | undefined => {
    const ls = Array.isArray(leads) ? leads : [];
    if (ev.leadId) { const byId = ls.find((l) => String(l.id) === String(ev.leadId)); if (byId) return byId; }
    const em = String(ev.fromEmail || "").trim().toLowerCase();
    if (!em) return undefined;
    return ls.find((l) => String(l.email || "").trim().toLowerCase() === em);
  }, [leads]);
                                                                                        
  const marcarTratado = useCallback(async (ids: string[]): Promise<boolean> => {
    const validos = ids.filter(Boolean);
    if (!validos.length) return false;
    try {
      const r = await fetch("/api/reply-scan?action=mark-read", { method: "POST", headers: { ...getAIHeaders(), "Content-Type": "application/json" }, body: JSON.stringify({ msgIds: validos }) });
      const d: any = await r.json().catch(() => ({}));
      if (d?.ok) { const set = new Set(validos); setReplyEvents((prev) => prev.filter((x) => !set.has(x.msgId))); return true; }
    } catch {                                                  }
    return false;
  }, []);
                                                                                                    
                                                                                                  
                                                                                                 
                                                                                                
                                                                                                  
