        if (lastAborted === "budget_reached") { showToast(tl({ pt: "Teto diario de diagnosticos atingido. Continua amanha ou sobe o limite.", fr: "Plafond quotidien de diagnostics atteint. Reprenez demain ou augmentez la limite.", en: "Daily diagnostics cap reached. Continue tomorrow or raise the limit." })); break; }
        if (lastAborted === "circuit_break_infra") { showToast(tl({ pt: "IA/infra indisponivel agora: lote pausado para NAO publicar diagnosticos vazios.", fr: "IA/infra indisponible : lot en pause pour NE PAS publier des diagnostics vides.", en: "AI/infra unavailable: batch paused to NOT publish empty diagnostics." })); break; }
        const s = lastSummary;
                                                                                                                           
