    setBatchState((p: any) => ({ ...(p || {}), running: false, done: true, phase: null, summary: lastSummary, aborted: lastAborted || null, failedItems: lastFailed }));
    if (batchAbortRef.current) showToast(tl({ pt: "Lote parado. Os ja diagnosticados estao guardados.", fr: "Lot arrêté. Les diagnostics déjà faits sont conservés.", en: "Batch stopped. Finished diagnostics are kept." }));
    else if (lastAborted === "circuit_break_infra" || lastAborted === "budget_reached") {                               }
    else if (restantes > 0) showToast(tl({ pt: `Lote terminou com ${restantes} por correr. Volta a clicar ou aguarda o cron.`, fr: `Lot terminé avec ${restantes} restants. Cliquez à nouveau ou attendez le cron.`, en: `Batch ended with ${restantes} pending. Click again or wait for the cron.` }));
    else if (falhados > 0) { const br: Record<string, number> = {}; lastFailed.forEach((f) => { br[f.reason] = (br[f.reason] || 0) + 1; }); const brStr = Object.entries(br).map(([r, c]) => `${failReasonT(r)} ×${c}`).join(", "); showToast(tl({ pt: `Lote concluido: ${fs.done || 0} ricos, ${fs.partial || 0} parciais, ${falhados} falhados${brStr ? ` (${brStr})` : ""}. Abre cada um para re-tentar.`, fr: `Lot terminé : ${fs.done || 0} riches, ${fs.partial || 0} partiels, ${falhados} en échec${brStr ? ` (${brStr})` : ""}. Ouvrez chacun pour réessayer.`, en: `Batch done: ${fs.done || 0} rich, ${fs.partial || 0} partial, ${falhados} failed${brStr ? ` (${brStr})` : ""}. Open each to retry.` })); }
    else showToast(tl({ pt: `Lote concluido: ${fs.done || 0} ricos, ${fs.partial || 0} parciais.`, fr: `Lot terminé : ${fs.done || 0} riches, ${fs.partial || 0} partiels.`, en: `Batch done: ${fs.done || 0} rich, ${fs.partial || 0} partial.` }));
