              <button type="button" disabled={supBusy || !supAdd.trim()} onClick={() => { const v = supAdd.trim().toLowerCase(); if (!v) return; const isEmail = v.includes("@"); void supWrite(isEmail ? { email: v } : { domain: v.replace(/^@/, "") }).then(() => setSupAdd("")); }} className="bg-rouge text-white px-4 py-2 eyebrow hover:bg-noir transition-colors disabled:opacity-40 disabled:cursor-not-allowed">{tl({ pt: "Bloquear", fr: "Bloquer", en: "Block", de: "Sperren", it: "Blocca", es: "Bloquear" })}</button>
