    if (_removed.length) { try { console.warn("[claim-check] frases removidas (nao sustentadas pelos factos):", _removed); } catch {       } if (!silent) showToast(L("pubClaimCheck").replace("{n}", String(_removed.length))); }
                                                                                                              
                                                                                                                
                                                                                                              
