        copy.sections.branding.t = g("branding", copy.sections.branding.t); copy.sections.digital.t = g("digital", copy.sections.digital.t); copy.sections.web.t = g("web", copy.sections.web.t); copy.sections.creative.t = g("creative", copy.sections.creative.t);
        if (Array.isArray(cv.removed) && cv.removed.length) { try { console.warn("[trava claim-verify] removido:", cv.removed); } catch {       } if (!silent) showToast(L("pubGuardrail").replace("{n}", String(cv.removed.length))); }
        if (cv.blocked) { if (silent) { try { console.warn("[lote] LP publicada na versao limpa (trava bloqueou):", C, cv.reason); } catch {       } } else if (!window.confirm(L("pubBlockedConfirm").replace("{reason}", String(cv.reason ?? "")))) { showToast(L("pubBlockedPostponed")); return; } }
