            <select value={lead.idioma || "fr"} onChange={(e) => onPatch({ idioma: e.target.value as Lang })} className="w-full text-sm focus:outline-none bg-white text-noir">
              {(["fr", "de", "en", "pt", "it", "es"] as Lang[]).map((l2) => <option key={l2} value={l2}>{l2.toUpperCase()}</option>)}
            </select>
