type AutoPlan = {
  enabled: boolean;                                                                                 
  qty: number;
  period: "day" | "week" | "month";
  autoApprove?: boolean;                                                                                           
                                                                                                         
                                                                                                              
  templates?: string[];
                                                                                                      
                                                                                                     
                                                                                                   
                                                       
  imageSource?: "catalog" | "ai" | "stock";
};
                                                                                  
                                                                                       
type CatalogImage = { url: string; name: string; addedAt: string };
const IMAGE_CATALOG_KEY = "abil_image_catalog_v1";

                                                                                                    
                                                                                                    
                                                                                              
                                                                                                         
const AUTOPLAN_SOCIAL_TAGS = ["frases-criativas", "dicas-marketing", "servicos", "repost-blog", "repost-projeto", "curiosidades", "diferenciais", "bastidores"] as const;
                                                                                                    
const AUTOPLAN_TAG_SLOTS: Record<string, { main: string; support: string; supportMax: number }> = {
  "frases-criativas": { main: "titulo", support: "apoio", supportMax: 37 },
  "dicas-marketing": { main: "titulo", support: "apoio", supportMax: 90 },
  "servicos": { main: "titulo", support: "apoio", supportMax: 113 },
  "repost-blog": { main: "titulo", support: "apoio", supportMax: 139 },
  "curiosidades": { main: "titulo", support: "apoio", supportMax: 95 },
  "diferenciais": { main: "titulo", support: "apoio", supportMax: 100 },
  "bastidores": { main: "titulo", support: "apoio", supportMax: 108 },
};
                                                                                                        
                                                                                                           
function cardTagSlots(tag?: string): { main: string; support: string } | null {
  if (!tag) return null;
  if (tag === "repost-projeto") return { main: "titulo", support: "apoio" };
  const s = AUTOPLAN_TAG_SLOTS[tag];
  return s ? { main: s.main, support: s.support } : null;
}
function cardMainCap(tag?: string): number {
  const s = cardTagSlots(tag);
  return s ? (templateFieldCap(String(tag), s.main) || 0) : 0;
}
function cardSupportCap(tag?: string): number {
  const s = cardTagSlots(tag);
  return s ? (templateFieldCap(String(tag), s.support) || 0) : 0;
}
                                                                                                   
                                                                                                   
                                                                                                   
                                                                               
const TEMPLATE_DEFAULTS_KEY = "abil_template_defaults_v1";
function templateDefaultBg(tag?: string): string {
  try {
    const m = JSON.parse(localStorage.getItem(TEMPLATE_DEFAULTS_KEY) || "{}") as Record<string, { bg?: string }>;
    const v = m && m[String(tag)] && m[String(tag)].bg;
    if (typeof v === "string" && v) return v;
  } catch {       }
  try {
    const p = (TEMPLATE_META as Record<string, { bgPreferred?: string }>)[String(tag)]?.bgPreferred;
    if (typeof p === "string" && p) return p;
  } catch {       }
  return "noir";
}
function autoplanTemplateRotation(planTemplates?: string[]): string[] {
  const valid = (Array.isArray(planTemplates) ? planTemplates : []).filter((t) => (AUTOPLAN_SOCIAL_TAGS as readonly string[]).includes(t));
  return valid.length ? valid : [...AUTOPLAN_SOCIAL_TAGS];
}

                                                                                                                                                                                                                                          
                                                                                                     
                                                                                                        
                                                                                                                                
                                                                                                                                                                                                                                          
const AUTOPLAN_CHANNELS: { key: string; label: string }[] = [
  { key: "abil_blog_autoplan_v2", label: "Blog" },
  { key: "abil_social_autoplan_instagram", label: "Instagram" },
  { key: "abil_social_autoplan_linkedin", label: "LinkedIn" },
  { key: "abil_social_autoplan_facebook", label: "Facebook" },
  { key: "abil_email_autoplan", label: "Email" },
];
const AUTOPLAN_DEFAULT: AutoPlan = { enabled: false, qty: 1, period: "month", autoApprove: false };
function readAutoplanOne(key: string): AutoPlan {
  try { const p = cloudGet<AutoPlan>(key, AUTOPLAN_DEFAULT); return (p && typeof p === "object") ? { ...AUTOPLAN_DEFAULT, ...p } : { ...AUTOPLAN_DEFAULT }; } catch { return { ...AUTOPLAN_DEFAULT }; }
}
type AutoplanAggregate = { per: { key: string; label: string; plan: AutoPlan }[]; creationOn: boolean; approvalOn: boolean; onCount: number; approveCount: number; total: number };
function readAutoplanAggregate(): AutoplanAggregate {
  const per = AUTOPLAN_CHANNELS.map((c) => ({ ...c, plan: readAutoplanOne(c.key) }));
  return { per, creationOn: per.some((c) => c.plan.enabled), approvalOn: per.some((c) => c.plan.autoApprove), onCount: per.filter((c) => c.plan.enabled).length, approveCount: per.filter((c) => c.plan.autoApprove).length, total: per.length };
}
                                                                                                       
                                                                                                              
function setAutoplanField(field: "enabled" | "autoApprove", value: boolean, only?: string): void {
  for (const c of AUTOPLAN_CHANNELS) {
    if (only && c.key !== only) continue;
    const cur = readAutoplanOne(c.key);
    const next: AutoPlan = { ...cur };
    if (field === "enabled") { next.enabled = value; if (!value) next.autoApprove = false; }
    else { next.autoApprove = value; if (value) next.enabled = true; }
    try { cloudSet(c.key, next); } catch {       }
  }
  try { if (typeof window !== "undefined") window.dispatchEvent(new CustomEvent("abil:autoplan-changed")); } catch {       }
}
                                                                                                                 
function useAutoplanAggregate(): AutoplanAggregate {
  const [tick, setTick] = useState(0);
  useEffect(() => {
    if (typeof window === "undefined") return undefined;
    const h = () => setTick((t) => t + 1);
    window.addEventListener("abil:autoplan-changed", h);
    window.addEventListener("storage", h);
    window.addEventListener("abil:cloud", h);
    return () => { window.removeEventListener("abil:autoplan-changed", h); window.removeEventListener("storage", h); window.removeEventListener("abil:cloud", h); };
  }, []);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  return useMemo(() => readAutoplanAggregate(), [tick]);
}

                                                                                                                                                                                                                                          
                                                                                               
                                                                                                      
                                                                                                        
                                                                                                         
                                                                                                  
                                                                                                              
                                                                                                                                                                                                                                          
const AUTOPLAN_PERIOD_MS: Record<AutoPlan["period"], number> = { day: 86_400_000, week: 604_800_000, month: 2_592_000_000 };
const AUTOPLAN_SOCIAL_PLATFORMS: SocialPlatform[] = ["instagram", "linkedin", "facebook"];
let autoCreatorTickRunning = false;
                                                                                                 
                                                                                                  
                                                                                           
let lastPersonaSnapJson = "";

function readAutoPlanRaw(key: string): AutoPlan | null {
  try { const raw = typeof localStorage !== "undefined" ? localStorage.getItem(key) : null; if (!raw) return null; const p = JSON.parse(raw); return (p && typeof p === "object") ? (p as AutoPlan) : null; } catch { return null; }
}
                                                                                                
                                                                                             
const AUTOPLAN_LASTRUN_KEY = "abil_autoplan_lastrun_v1";
function readAutoPlanLastRun(storageKey: string): number {
  try { const m = cloudGet<Record<string, string>>(AUTOPLAN_LASTRUN_KEY, {}); const v = m && m[storageKey]; return v ? (Date.parse(v) || 0) : 0; } catch { return 0; }
}
function stampAutoPlanRun(storageKey: string): void {
  try { const m = cloudGet<Record<string, string>>(AUTOPLAN_LASTRUN_KEY, {}); cloudSet(AUTOPLAN_LASTRUN_KEY, { ...(m && typeof m === "object" ? m : {}), [storageKey]: new Date().toISOString() }); } catch {       }
}
function autoPlanIsDue(p: AutoPlan, storageKey: string): boolean {
  const last = readAutoPlanLastRun(storageKey);
  if (!last) return true;
  return (Date.now() - last) >= (AUTOPLAN_PERIOD_MS[p.period] || AUTOPLAN_PERIOD_MS.month);
}
                                                                                                  
                                                                                                          
const AUTOPLAN_ROTIDX_KEY = "abil_autoplan_rotidx_v1";
function readAutoPlanRotIdx(storageKey: string): number {
  try { const m = cloudGet<Record<string, number>>(AUTOPLAN_ROTIDX_KEY, {}); const v = m && m[storageKey]; return Number.isFinite(v) ? Math.max(0, Math.floor(Number(v))) : 0; } catch { return 0; }
}
function bumpAutoPlanRotIdx(storageKey: string, by: number): void {
  if (!by) return;
  try { const m = cloudGet<Record<string, number>>(AUTOPLAN_ROTIDX_KEY, {}); const cur = m && Number.isFinite(m[storageKey]) ? Number(m[storageKey]) : 0; cloudSet(AUTOPLAN_ROTIDX_KEY, { ...(m && typeof m === "object" ? m : {}), [storageKey]: (cur + by) % 9999 }); } catch {       }
}
                                                                                         
function autonomousTheme(idx: number): string {
  try {
    const persona = getAIPersonaContext();
    let kws: unknown = persona?.brandPersona?.keywords;
    if (typeof kws === "string") kws = (kws as string).split(/[,;\n]/);
    if (Array.isArray(kws)) {
      const clean = (kws as unknown[]).filter((k): k is string => typeof k === "string" && k.trim().length > 1).map((k) => k.trim());
      if (clean.length) return clean[idx % clean.length];
    }
  } catch {       }
  const fallback = ["branding e estratégia", "direção de arte", "marca e humanização", "criatividade com método"];
  return fallback[idx % fallback.length];
}

                                                                                                    
                                                                                                 
                                                                                                          
const PAUTA_CLOUD_KEY = "abil_content_pauta_v1";
type PautaItemC = { id: string; tag: string; gancho: string; angulo?: string; fonte?: { titulo?: string; url?: string }; persona?: string; personaDica?: string; usado?: boolean };
type PautaC = { date: string; madeAt: string; items: PautaItemC[] };
function readPautaHoje(): PautaC | null {
  try {
    const p = cloudGet<PautaC | null>(PAUTA_CLOUD_KEY, null);
    if (!p || !Array.isArray(p.items)) return null;
    return p.date === new Date().toISOString().slice(0, 10) ? p : null;
  } catch { return null; }
}
function takeClientPautaItem(tag: string): PautaItemC | null {
  const p = readPautaHoje();
  if (!p) return null;
  const it = p.items.find((x) => !x.usado && x.tag === tag) || null;
  if (it) { it.usado = true; try { cloudSet(PAUTA_CLOUD_KEY, p); } catch {       } }
  return it;
}
function pautaTema(it: PautaItemC): string {
  return `${it.gancho}${it.angulo ? ` (ângulo: ${it.angulo})` : ""}${it.fonte?.titulo ? ` [baseado na notícia real: ${it.fonte.titulo}${it.fonte.url ? " " + it.fonte.url : ""}]` : ""}`;
}
                                                                                         
function personaAlvoCtx(ctx: AIPersonaContext, it: PautaItemC | null): AIPersonaContext {
  if (!it || !it.persona) return ctx;
  const ref = String(ctx?.referenceNotes || "");
  return { ...ctx, referenceNotes: (ref ? ref + "\n\n" : "") + `PERSONA-ALVO desta peça: ${it.persona}${it.personaDica ? ` (${it.personaDica})` : ""}. Escreve PARA esta pessoa.` };
}

async function autoCreateBlog(lang: Lang, qty: number, autoApprove: boolean): Promise<number> {
  let made = 0;
  for (let i = 0; i < Math.max(1, Math.min(qty, 5)); i++) {
    let gen: { title: string; excerpt: string; body: string; cover: string; images: string[] } | null = null;
                                                                                                       
    const pitBlog = takeClientPautaItem("blog");
    try { gen = await aiBlogContentRich(pitBlog ? pautaTema(pitBlog) : autonomousTheme(i), "Calme & éditorial", [], lang); } catch { gen = null; }
    if (!gen || !gen.title) continue;
    const now = new Date().toISOString();
    const base: BlogDraft = { id: `autoplan-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`, title: gen.title, excerpt: gen.excerpt, body: gen.body, cat: "Atelier", tone: "Calme & éditorial", keywords: [], status: autoApprove ? "published" : "draft", createdAt: now, source: "ai", cover: gen.cover, images: gen.images, sourceLang: lang };
    const draft = { ...base, ...(autoApprove ? { approvedAt: now, publishedAt: now } : {}) } as BlogDraft;
    try { const ex = cloudGet<BlogDraft[]>("abil_blog_drafts", []); cloudSet("abil_blog_drafts", [draft, ...(Array.isArray(ex) ? ex : [])]); made++; } catch {       }
                                                                                                        
    if (!autoApprove) { try { enqueueGeneratedOutputPreview({ card: "blog", sourceId: draft.id, title: draft.title, body: (draft.excerpt || draft.body || "").slice(0, 200), previewImage: draft.cover }); } catch {       } }
  }
  return made;
}

async function autoCreateSocial(platform: SocialPlatform, navLang: Lang, qty: number, autoApprove: boolean): Promise<number> {
  let made = 0;
                                                                                                  
                                                                                        
                                                                             
  const lang = (cloudGet<Lang>("abil_social_send_lang", navLang) || navLang) as Lang;
                                                                                                      
                                                                                                 
                                                        
  const rotKey = `abil_social_autoplan_${platform}`;
  const plan = readAutoPlanRaw(rotKey);
  const rotation = autoplanTemplateRotation(plan?.templates);
                                                                                                    
                                                                      
  const rotBase = readAutoPlanRotIdx(rotKey);
  let iters = 0;
  for (let i = 0; i < Math.max(1, Math.min(qty, 12)); i++) {
    iters = i + 1;
    const tag = rotation[(rotBase + i) % rotation.length];
                                                                                                       
                                                                                                 
                                                                                                  
                                                                                                           
                                                                                       
    if (tag === "repost-projeto") {
      try {
        const projects = (await idbGetProjects()) || [];
        const cards = cloudGet<any[]>("abil_social_cards_v2", []);
        const purged = new Set(cloudGet<string[]>("abil_social_purged_sids_v1", []) || []);
                                                                                                        
                                                                                                              
        const sidsOf = (pid: string) => [`project-${pid}`, `project-${pid}-li`, `project-${pid}-fb`];
        const existing = new Set((Array.isArray(cards) ? cards : []).map((c) => String(c?.sourceId || "")));
        const withImgs = projects.filter((p) => p && projectGalleryImageUrls(p as any, 5).length > 0);
        const target = withImgs.find((p) => sidsOf(String(p.id)).every((s) => !purged.has(s)) && sidsOf(String(p.id)).some((s) => !existing.has(s)));
        if (target) { await autoGenProjectCarousel(target as any, { skipAICaptions: true }); made++; }
                                                                       
      } catch {       }
      continue;
    }
                                                                                                  
    const pautaItem = takeClientPautaItem(tag);
    const theme = pautaItem ? pautaTema(pautaItem) : autonomousTheme(i);
    const slots = AUTOPLAN_TAG_SLOTS[tag] || AUTOPLAN_TAG_SLOTS["frases-criativas"];
                                                                                              
                                                                                                  
                                  
    const capMain = templateFieldCap(tag, slots.main) || 40;
    const capSup = templateFieldCap(tag, slots.support) || slots.supportMax;
                                                                                                         
                                                                                                           
                                                                 
    const tplLinha = getAiTemplatePrompt(tag).slice(0, 1200);
    const tplExtra = tplLinha ? ` Linha editorial deste template: ${tplLinha}` : "";
                                                                                               
                                                                                                          
    const imgMode: NonNullable<AutoPlan["imageSource"]> = plan?.imageSource || "ai";
    let imageSrc: string | undefined;
    const querFoto = templateHasPhoto(tag as TemplateTag);
                                                                                                 
                                                                                                      
                                                                                                
                                                                                     
    const uploadOnly = (TEMPLATE_META as Record<string, { imageMode?: string }>)[tag as string]?.imageMode === "upload-required";
    if (querFoto && (imgMode === "catalog" || (uploadOnly && imgMode === "ai"))) {
      try { const cat = cloudGet<{ url?: string }[]>(IMAGE_CATALOG_KEY, []); if (Array.isArray(cat) && cat.length) imageSrc = String(cat[(rotBase + i) % cat.length]?.url || "") || undefined; } catch {       }
    } else if (querFoto && imgMode === "stock") {
                                                                                                                   
      try { const r = await fetch(`/api/stock-image?q=${encodeURIComponent(String(pautaItem?.gancho || theme).slice(0, 80))}&orientation=portrait`, { headers: getAIHeaders() }); const d = await r.json().catch(() => null); if (r.ok && d?.url) imageSrc = String(d.url); } catch {       }
    }
    const visao = imageSrc ? { imageUrl: imageSrc } : {};
                                                                                                     
                                                                                  
    let title = "";
    try {
      const comCombine = imageSrc ? ` Olha a imagem em anexo: a frase tem de COMBINAR com ela.` : "";
                                                                                                     
                                             
      const mainPrompt = `Escreve um título para a ARTE de um post ${platform} sobre "${theme}". Estrutura OBRIGATÓRIA da arte: ${fieldLineSpecHint(tag, slots.main)}.${comCombine}${tplExtra} Só o título, sem aspas, sem hashtags, sem ponto final.`;
                                                                                                  
      const r = await fetch("/api/regenerate-text", { method: "POST", headers: getAIHeaders(), body: JSON.stringify({ currentText: "", userPrompt: mainPrompt, maxLength: capMain + 6, path: "social/title", lang, ...visao, ...personaAlvoCtx(getAIPersonaContext("social", lang), pautaItem) }) });
      const d = await r.json().catch(() => null); title = String(d?.text || "").trim();
    } catch {       }
    if (!title) continue;
                                                                                                   
    title = fitFieldText(tag, slots.main, title);
    const titleFlat = title.replace(/\n+/g, " ").trim();
    let supportText = "";
    try {
      const supPrompt = `Escreve um apoio muito curto que acompanha "${titleFlat}" num post ${platform} sobre "${theme}". Estrutura da arte: ${fieldLineSpecHint(tag, slots.support)}.${imageSrc ? " Tem de combinar com a imagem em anexo." : ""}${tplExtra} Voz da marca, sem hashtags.`;
      const r = await fetch("/api/regenerate-text", { method: "POST", headers: getAIHeaders(), body: JSON.stringify({ currentText: "", userPrompt: supPrompt, maxLength: capSup + 12, path: "social/supportText", lang, ...visao, ...personaAlvoCtx(getAIPersonaContext("social", lang), pautaItem) }) });
      const d = await r.json().catch(() => null); supportText = String(d?.text || "").trim();
    } catch {       }
    const supCut = fitFieldText(tag, slots.support, supportText);
    const supFlat = supCut.replace(/\n+/g, " ").trim();
                                                                                                  
                                                                                                       
                                                                                                      
    let caption = "";
    try {
      const capPrompt = `Escreve a LEGENDA da publicação para um post ${platform} sobre "${theme}", cuja arte diz "${titleFlat}". ${getAiChannelPrompt("legenda")}${imageSrc ? " Tem de combinar com a imagem em anexo." : ""}`;
      const r = await fetch("/api/regenerate-text", { method: "POST", headers: getAIHeaders(), body: JSON.stringify({ currentText: "", userPrompt: capPrompt, maxLength: 600, path: "social/caption", lang, ...visao, ...personaAlvoCtx(getAIPersonaContext("social", lang), pautaItem) }) });
      const d = await r.json().catch(() => null); caption = String(d?.text || "").trim().slice(0, 600);
    } catch {       }
                                                                                               
                                                                                     
                                                                                                    
                                                                                                
                                    
    if (querFoto && imgMode === "ai" && !imageSrc && !uploadOnly) {
      try {
        const ir = await fetch("/api/generate-image", { method: "POST", headers: getAIHeaders(), body: JSON.stringify({ prompt: `Imagem editorial para um post ${platform} sobre "${theme}". Sem texto, sem logotipos.`, size: "1024x1024", context: `Social ${platform} post, ${title}`, ...getAIPersonaContext("social", lang) }) });
        const idd = await ir.json().catch(() => null);
        const raw = idd?.url || idd?.dataUrl;
        if (ir.ok && raw) imageSrc = await compressDataUrl(raw);
      } catch {                                                                              }
    }
    const id = `autoplan-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`;
    const now = new Date().toISOString();
    const card = { id, sourceId: id, platform, format: platform === "linkedin" ? "feed" : "square", layout: "hero-quote", tag, title: titleFlat, subtitle: "", supportText: supFlat, caption, imageSrc, asteriskColor: "#d2ff01", bg: templateDefaultBg(tag), date: now.slice(0, 10), status: autoApprove ? "scheduled" : "draft", isAIGenerated: true, ...(autoApprove ? { approvedAt: now } : {}) } as unknown as SocialCard;
    if (autoApprove) {
      try { await enqueueApprovedSocialPost({ id, kind: "single", platforms: [platform], caption: caption || `${titleFlat}${supFlat ? "\n\n" + supFlat : ""}`, slides: [], scheduledAt: now.slice(0, 10), status: "scheduled", source: "manual", hashtags: [] } as SocialPost); } catch {       }
    }
    try { const ex = cloudGet<SocialCard[]>("abil_social_cards_v2", []); cloudSet("abil_social_cards_v2", [card, ...(Array.isArray(ex) ? ex : [])]); made++; } catch {       }
                                                                                                        
                                                                                                        
    if (!autoApprove) { try { enqueueGeneratedOutputPreview({ card: "social", sourceId: id, title: titleFlat, body: (caption || supFlat).slice(0, 600), previewImage: (card as { imageSrc?: string }).imageSrc }); } catch {       } }
  }
                                                                                                           
                                                                   
  if (made > 0) bumpAutoPlanRotIdx(rotKey, iters);
  return made;
}

async function autoCreateEmail(navLang: Lang, qty: number, autoApprove: boolean): Promise<number> {
  let made = 0;
                                                                                                    
                                                                                                           
  const lang = (cloudGet<Lang>("abil_email_send_lang_v1", navLang) || navLang) as Lang;
                                                             
  const emailPlan = readAutoPlanRaw("abil_email_autoplan");
  const emailImgMode: NonNullable<AutoPlan["imageSource"]> = emailPlan?.imageSource || "ai";
  const emailRotBase = readAutoPlanRotIdx("abil_email_autoplan");
  let emailIters = 0;
  for (let i = 0; i < Math.max(1, Math.min(qty, 5)); i++) {
    emailIters = i + 1;
    const theme = autonomousTheme(i);
                                                                                        
    let heroImage: string | undefined;
    if (emailImgMode === "catalog") {
      try { const cat = cloudGet<{ url?: string }[]>(IMAGE_CATALOG_KEY, []); if (Array.isArray(cat) && cat.length) heroImage = String(cat[(emailRotBase + i) % cat.length]?.url || "") || undefined; } catch {       }
    } else if (emailImgMode === "stock") {
      try { const r = await fetch(`/api/stock-image?q=${encodeURIComponent(theme.slice(0, 80))}&orientation=landscape`, { headers: getAIHeaders() }); const d = await r.json().catch(() => null); if (r.ok && d?.url) heroImage = String(d.url); } catch {       }
    }
    let subject = "", body = "";
    try {
                                                                       
      const r = await fetch("/api/regenerate-text", { method: "POST", headers: getAIHeaders(), body: JSON.stringify({ currentText: "", userPrompt: `Escreve uma newsletter curta da marca sobre "${theme}".${heroImage ? " Olha a imagem em anexo (é o banner do email): o texto tem de combinar com ela." : ""} Linha 1 = assunto curto; depois 2-3 parágrafos no tom da marca. Nunca inventes preço nem prazo.`, maxLength: 900, path: "email/newsletter", lang, ...(heroImage ? { imageUrl: heroImage } : {}), ...getAIPersonaContext("email", lang) }) });
      const d = await r.json().catch(() => null); const txt = String(d?.text || "").trim();
      const parts = txt.split("\n").map((s) => s.trim()).filter(Boolean);
      subject = (parts[0] || theme).slice(0, 90); body = parts.slice(1).join("\n\n") || txt;
    } catch {       }
    if (!body) continue;
                                                                                        
    if (!heroImage && emailImgMode === "ai") {
      try {
        const ir = await fetch("/api/generate-image", { method: "POST", headers: getAIHeaders(), body: JSON.stringify({ prompt: `Banner editorial para uma newsletter sobre "${theme}". Sem texto, sem logotipos.`, size: "1536x1024", context: `Email newsletter, ${subject}`, ...getAIPersonaContext("email", lang) }) });
        const idd = await ir.json().catch(() => null);
        const raw = idd?.url || idd?.dataUrl;
        if (ir.ok && raw) heroImage = await compressDataUrl(raw);
      } catch {                                                                      }
    }
    const now = new Date().toISOString();
    const tplId = `autoplan-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`;
    let tpl = { id: tplId, linkedProjectId: tplId, phase: "newsletter", name: subject.slice(0, 80), subject, preheader: body.slice(0, 140), body, tag: "NEWSLETTER", status: autoApprove ? "active" : "draft", lastEdit: new Date().toLocaleDateString("fr-CH"), colorTheme: "noir", sourceLang: lang, blocks: [], ...(heroImage ? { heroImage } : {}) } as unknown as EmailTemplate;
    if (autoApprove) { try { await enqueueApprovedEmailTemplate(tpl); tpl = { ...tpl, status: "active" } as EmailTemplate; } catch {       } }
    try { const ex = cloudGet<EmailTemplate[]>("abil_email_template_extras_v2", []); cloudSet("abil_email_template_extras_v2", [tpl, ...(Array.isArray(ex) ? ex : [])]); made++; } catch {       }
                                                                                                        
    if (!autoApprove) { try { enqueueGeneratedOutputPreview({ card: "email", sourceId: tplId, title: subject, body: body.slice(0, 200), previewImage: (tpl as { heroImage?: string }).heroImage }); } catch {       } }
  }
                                                                                      
  if (made > 0 && emailImgMode === "catalog") bumpAutoPlanRotIdx("abil_email_autoplan", emailIters);
  return made;
}

                                                                                                              
                                                                                                                 
                                                                                                            
                                                                                                                 
                                                                                                                
                                                                                                         
let _snapPushTimer: number | null = null;
async function pushPersonaSnapshotNow(lang: Lang): Promise<boolean> {
  try {
    if (typeof window === "undefined" || !abilVaultUnlocked()) return false;
    const prev = (await vaultGet<Record<string, unknown>>("agent_persona_snapshot")) || {};
    const snap = { ...prev, ...getAIPersonaContext(), __lang: lang, __ts: new Date().toISOString() };
    return await vaultSet("agent_persona_snapshot", snap);
  } catch { return false; }
}
                                                                                                       
                                                                                                      
                                                                                                           
                                                                                                             
                                                                                                             
                                                                                                          
function schedulePersonaSnapshotPush(lang: Lang, mirrorKey?: string): void {
  if (typeof window === "undefined") return;
  if (mirrorKey) {
    try { if (window.localStorage.getItem(mirrorKey) === null) return; } catch { return; }
  }
  if (_snapPushTimer) window.clearTimeout(_snapPushTimer);
  _snapPushTimer = window.setTimeout(() => { void pushPersonaSnapshotNow(lang); }, 2000);
}
async function runAutoCreatorTick(lang: Lang): Promise<void> {
  if (autoCreatorTickRunning || typeof window === "undefined") return;
  try { if (!abilVaultUnlocked()) return; } catch { return; }
  autoCreatorTickRunning = true;
  try {
                                                                                                    
                                                                                                        
    try {
      const anyOn = ["abil_blog_autoplan_v2", "abil_social_autoplan_instagram", "abil_social_autoplan_linkedin", "abil_social_autoplan_facebook", "abil_email_autoplan"].some((k) => { const p = readAutoPlanRaw(k); return !!(p && (p.enabled || p.autoApprove)); });
                                                                                                    
                                                                                                       
                                                 
                                                                                                        
                                                                                                      
                                                                                 
      if (anyOn) {
                                                                                      
                                                                                                  
                                                                                                   
                                                                                        
        type PersonaSnap = { __channelPrompts?: Record<string, string>; __templatePrompts?: Record<string, string>; __promptMaps?: Record<string, Record<string, string>>; __imageRefsSuffix?: string } | null;
        const prevSnap: PersonaSnap = (await vaultGet<PersonaSnap>("agent_persona_snapshot")) ?? cloudGet<PersonaSnap>("abil_agent_persona_snapshot_v1", null);
        let rawCh: Record<string, string> = {};
        try { const v = JSON.parse(localStorage.getItem("abil_ai_channel_prompts_v1") || "{}"); if (v && typeof v === "object") rawCh = v; } catch {       }
        const rawTpl = getAiTemplatePromptsAll();
        const chOut = Object.keys(rawCh).length ? getAiChannelPromptsAll() : ((prevSnap?.__channelPrompts && Object.keys(prevSnap.__channelPrompts).length) ? prevSnap.__channelPrompts : getAiChannelPromptsAll());
        const tplOut = Object.keys(rawTpl).length ? rawTpl : ((prevSnap?.__templatePrompts && typeof prevSnap.__templatePrompts === "object") ? prevSnap.__templatePrompts : {});
                                                                                               
                                                                                           
                                                                                                  
                                                                                                     
                                                                                               
        const readLangMap = (k: string): Record<string, string> => { try { const v = JSON.parse(localStorage.getItem(k) || "{}"); return (v && typeof v === "object" && !Array.isArray(v)) ? v : {}; } catch { return {}; } };
        const pmRaw = { global: readLangMap("abil_ai_global_prompt_v1"), image: readLangMap("abil_ai_image_prompt_v1"), safeguards: readLangMap("abil_ai_safeguards_v1") };
        const prevPm = (prevSnap?.__promptMaps && typeof prevSnap.__promptMaps === "object") ? prevSnap.__promptMaps : {};
        const pmOut = {
          global: Object.keys(pmRaw.global).length ? pmRaw.global : (prevPm.global || {}),
          image: Object.keys(pmRaw.image).length ? pmRaw.image : (prevPm.image || {}),
          safeguards: Object.keys(pmRaw.safeguards).length ? pmRaw.safeguards : (prevPm.safeguards || {}),
        };
        let refsSuffix = "";
        try {
          const refsArr = JSON.parse(localStorage.getItem("abil_ai_image_refs_v1") || "[]") as Array<{ desc?: string }>;
          const refDescs = (Array.isArray(refsArr) ? refsArr : []).map((r) => String(r?.desc || "").trim()).filter(Boolean).slice(0, 6);
          if (refDescs.length) refsSuffix = `\n\nREFERÊNCIAS VISUAIS (seguir este estilo): ${refDescs.join(" · ")}`;
        } catch {       }
        const refsOut = refsSuffix || String(prevSnap?.__imageRefsSuffix || "");
        const snapBody = { ...getAIPersonaContext(), __lang: lang, __blogPrompt: getBlogEditorialPrompt(), __channelPrompts: chOut, __templatePrompts: tplOut, __promptMaps: pmOut, __imageRefsSuffix: refsOut };
                                                                                                   
                                                                                              
        const snapJson = JSON.stringify(snapBody);
        if (snapJson !== lastPersonaSnapJson) {
                                                                                               
                                                                                               
                                                                                    
                                                              
          const okVault = await vaultSet("agent_persona_snapshot", { ...snapBody, __ts: new Date().toISOString() });
          if (okVault) {
            lastPersonaSnapJson = snapJson;
            try {
              const pub = cloudGet<Record<string, unknown> | null>("abil_agent_persona_snapshot_v1", null);
              if (pub && typeof pub === "object" && Object.keys(pub).length > 0) cloudSet("abil_agent_persona_snapshot_v1", {});
            } catch {                           }
          }
        }
      }
    } catch {       }
                                                                                                                            
    try { const ck = await fetch("/api/agent-cost?action=check", { method: "POST", headers: getAIHeaders(), body: JSON.stringify({ estimated_cost: 0.1 }) }).then((r) => r.ok ? r.json() : null).catch(() => null); if (ck && ck.allowed === false) return; } catch {       }
    const blog = readAutoPlanRaw("abil_blog_autoplan_v2");
    if (blog && (blog.enabled || blog.autoApprove) && autoPlanIsDue(blog, "abil_blog_autoplan_v2")) {
      const n = await autoCreateBlog(lang, blog.qty || 1, !!blog.autoApprove);
      if (n > 0) stampAutoPlanRun("abil_blog_autoplan_v2");
    }
    for (const platform of AUTOPLAN_SOCIAL_PLATFORMS) {
      const key = `abil_social_autoplan_${platform}`;
      const sp = readAutoPlanRaw(key);
      if (sp && (sp.enabled || sp.autoApprove) && autoPlanIsDue(sp, key)) {
        const n = await autoCreateSocial(platform, lang, sp.qty || 1, !!sp.autoApprove);
        if (n > 0) stampAutoPlanRun(key);
      }
    }
    const email = readAutoPlanRaw("abil_email_autoplan");
    if (email && (email.enabled || email.autoApprove) && autoPlanIsDue(email, "abil_email_autoplan")) {
      const n = await autoCreateEmail(lang, email.qty || 1, !!email.autoApprove);
      if (n > 0) stampAutoPlanRun("abil_email_autoplan");
    }
  } finally { autoCreatorTickRunning = false; }
}

                                                                                                             
function useAutoCreatorEngine(lang: Lang): void {
  useEffect(() => {
    if (typeof window === "undefined") return undefined;
    let stopped = false;
    const tick = () => { if (!stopped) void runAutoCreatorTick(lang); };
                                                                                                      
    try { (window as unknown as { __autoCreatorTick?: () => Promise<void> }).__autoCreatorTick = () => runAutoCreatorTick(lang); } catch {       }
    const t0 = window.setTimeout(tick, 8000);
    const iv = window.setInterval(tick, 5 * 60 * 1000);
    return () => { stopped = true; window.clearTimeout(t0); window.clearInterval(iv); };
  }, [lang]);
}

                                                                                                  
                                                                                                    
                                                                                              
                                           
