function FormField({
  label,
  defaultValue,
  value,
  onChange,
  textarea = false,
  rows = 2,
  placeholder,
  action,
  dark = false,
}: {
  label: string;
  defaultValue?: string;
  value?: string;
  onChange?: (v: string) => void;
  textarea?: boolean;
  rows?: number;
  placeholder?: string;
                                                                                         
  action?: React.ReactNode;
                                                                                     
  dark?: boolean;
}) {
  const isControlled = value !== undefined && onChange !== undefined;
  const inputDark = dark ? " bg-transparent text-white placeholder:text-white/30" : "";
  return (
    <div className={dark ? "bg-white/5 border border-white/15 p-4" : "bg-white border border-neutral-200 p-4"}>
      <div className={`eyebrow mb-2 flex items-center justify-between gap-2 ${dark ? "text-white/50" : "text-neutral-500"}`}>
        <span>{label}</span>
        {action}
      </div>
      {textarea ? (
        <textarea
          {...(isControlled
            ? { value, onChange: (e) => onChange!(e.target.value) }
            : { defaultValue: defaultValue ?? "" })}
          rows={rows}
          placeholder={placeholder}
          className={`w-full border-0 px-0 text-sm focus:outline-none focus:ring-0 resize-none${inputDark}`}
        />
      ) : (
        <input
          {...(isControlled
            ? { value, onChange: (e) => onChange!(e.target.value) }
            : { defaultValue: defaultValue ?? "" })}
          placeholder={placeholder}
          className={`w-full border-0 px-0 text-sm focus:outline-none focus:ring-0${inputDark}`}
        />
      )}
    </div>
  );
}

                                                                                                                                          
                                                        
                                                                                                                                             
function Toast({
  visible,
  message,
  onClose,
}: {
  visible: boolean;
  message: string;
  onClose: () => void;
}) {
  const [leaving, setLeaving] = useState(false);
  useEffect(() => {
    if (!visible) { setLeaving(false); return; }
    setLeaving(false);
    const t = setTimeout(() => setLeaving(true), 4500);
    return () => clearTimeout(t);
  }, [visible, message]);
  useEffect(() => {
    if (!leaving) return;
    const t = setTimeout(onClose, 320);
    return () => clearTimeout(t);
  }, [leaving, onClose]);
  if (!visible) return null;
  return (
    <div className={`fixed bottom-6 right-6 z-[200] bg-noir text-white px-6 py-4 shadow-2xl flex items-center gap-3 max-w-sm ${leaving ? "fade-down-out" : "fade-up"}`}>
      <Asterisque className="w-4 h-4 flex-shrink-0" color="#d2ff01" />
      <span className="text-sm leading-snug">{message}</span>
      <button onClick={() => setLeaving(true)} className="ml-2 text-white/50 hover:text-white transition-colors duration-300 text-lg leading-none">
        ×
      </button>
    </div>
  );
}

function Modal({
  open,
  onClose,
  children,
  size = "md",
}: {
  open: boolean;
  onClose: () => void;
  children: React.ReactNode;
  size?: "md" | "lg" | "xl" | "2xl" | "3xl";
}) {
  const { t } = useApp();
  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
    };
    document.body.style.overflow = "hidden";
    document.addEventListener("keydown", onKey);
    return () => {
      document.body.style.overflow = "";
      document.removeEventListener("keydown", onKey);
    };
  }, [open, onClose]);
  if (!open) return null;
  const sizeClass =
    size === "3xl"
      ? "max-w-[1498px]"                                                       
      : size === "2xl"
      ? "max-w-[1165px]"                        
      : size === "xl"
      ? "max-w-6xl"
      : size === "lg"
      ? "max-w-4xl"
      : "max-w-2xl";
                                                                        
                                                               
  return createPortal(
    <div className="fixed inset-0 z-[300] flex items-start md:items-center justify-center p-3 md:p-6 overflow-y-auto">
      <div
        className="absolute inset-0 bg-black/80 backdrop-blur-sm"
        onClick={onClose}
      />
      <div
        className={`relative bg-white w-full ${sizeClass} my-6 max-h-[92vh] flex flex-col overflow-hidden`}
      >
        <button
          onClick={onClose}
          aria-label={t.common.close}
          className="absolute top-4 right-4 z-30 w-9 h-9 bg-noir text-white flex items-center justify-center hover:bg-rouge transition-colors shadow-md"
        >
          <IconX className="w-4 h-4" />
        </button>
        {                                                                         
                                                                                       }
        <div className="flex-1 min-h-0 overflow-y-auto">
          {children}
        </div>
      </div>
    </div>,
    document.body
  );
}

function NewsletterForm() {
  const { t, showToast } = useApp();
  const [email, setEmail] = useState("");
  const [state, setState] = useState<"idle" | "loading" | "ok">("idle");

  const submit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!email.includes("@")) return;
    setState("loading");
    setTimeout(() => {
      setState("ok");
      showToast(t.newsletter.toastOk(email));
      setTimeout(() => {
        setState("idle");
        setEmail("");
      }, 2500);
    }, 800);
  };

  return (
    <form onSubmit={submit}>
      <input
        type="email"
        required
        value={email}
        onChange={(e) => setEmail(e.target.value)}
        placeholder={t.newsletter.placeholder}
        disabled={state !== "idle"}
        className="w-full bg-transparent border-b border-white/30 px-0 py-3 text-sm text-white placeholder:text-white/40 focus:outline-none focus:border-rouge transition-colors mb-4 disabled:opacity-50"
      />
      <button
        type="submit"
        disabled={state !== "idle"}
        className="w-full bg-rouge text-white py-3 eyebrow eyebrow-sm hover:bg-white hover:text-noir transition-colors disabled:opacity-60"
      >
        {state === "loading" ? "···" : state === "ok" ? t.newsletter.success : t.newsletter.cta}
      </button>
    </form>
  );
}

                                                                                                                                          
                                                            
                                                                                                                                             
function ChatbotWidget() {
  const { view, t, lang, chatbotOpen, setChatbotOpen } = useApp();
  const open = chatbotOpen;
  const setOpen = setChatbotOpen;
  const [closingChat, setClosingChat] = useState(false);
  const closeTimer = useRef<number | null>(null);
  const closeChat = () => {
    if (closeTimer.current) window.clearTimeout(closeTimer.current);
    setClosingChat(true);
    closeTimer.current = window.setTimeout(() => { setOpen(false); setClosingChat(false); closeTimer.current = null; }, 340);
  };
  const openChat = () => {
    if (closeTimer.current) { window.clearTimeout(closeTimer.current); closeTimer.current = null; }
    setClosingChat(false);
    setOpen(true);
  };
  const [input, setInput] = useState("");
  const [typing, setTyping] = useState(false);
  const [messages, setMessages] = useState<{ from: "bot" | "user"; text: string }[]>([
    {
      from: "bot",
      text: t.chatbotWidget.greeting,
    },
  ]);
  const msgsEndRef = useRef<HTMLDivElement | null>(null);
  const [inputFocused, setInputFocused] = useState(false);

                                                                                       
  useEffect(() => {
    const id = window.setTimeout(() => setMessages((prev) => {
                                                                                     
      if (prev.length <= 1) {
        return [{ from: "bot", text: t.chatbotWidget.greeting }];
      }
      return prev;
    }), 0);
    return () => window.clearTimeout(id);
  }, [lang, t.chatbotWidget.greeting]);

                                                                                
  useEffect(() => {
    if (!open) return;
    const el = msgsEndRef.current;
    if (el) el.scrollIntoView({ behavior: "smooth", block: "end" });
  }, [messages, typing, open]);

                                                                                                            
  const [listening, setListening] = useState(false);
  const [speaking, setSpeaking] = useState(false);
  const [convoMode, setConvoMode] = useState(false);
  const convoRef = useRef(false);
  const recRef = useRef<any>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const speakSeqRef = useRef(0);
                                                                        
  useEffect(() => {
    if (open) return;
    speakSeqRef.current++;
    convoRef.current = false;
    try { audioRef.current?.pause(); } catch { /* */ }
    try { window.speechSynthesis?.cancel(); } catch {       }
    try { recRef.current?.stop(); } catch {       }
    const id = window.setTimeout(() => { setConvoMode(false); setSpeaking(false); setListening(false); }, 0);
    return () => window.clearTimeout(id);
  }, [open]);

                                      
  if (view === "dashboard") return null;

                                                                
  const vlabels: Record<string, { talk: string; stopHear: string; convoOn: string; convoOff: string; stopV: string }> = {
    pt: { talk: "Falar", stopHear: "Parar de ouvir", convoOn: "Modo conversa", convoOff: "Desligar conversa", stopV: "Parar voz" },
    en: { talk: "Speak", stopHear: "Stop listening", convoOn: "Conversation mode", convoOff: "Stop conversation", stopV: "Stop voice" },
    fr: { talk: "Parler", stopHear: "Arrêter l'écoute", convoOn: "Mode conversation", convoOff: "Arrêter", stopV: "Couper la voix" },
    de: { talk: "Sprechen", stopHear: "Zuhören beenden", convoOn: "Gesprächsmodus", convoOff: "Beenden", stopV: "Stimme stoppen" },
    it: { talk: "Parla", stopHear: "Ferma ascolto", convoOn: "Modalità conversazione", convoOff: "Ferma", stopV: "Ferma voce" },
  };
  const vl = vlabels[lang] || vlabels.en;

  const stopVoice = () => {
    speakSeqRef.current++;
    try { audioRef.current?.pause(); } catch {       }
    try { window.speechSynthesis?.cancel(); } catch {       }
    setSpeaking(false);
  };
                                                                                                  
  const speakClient = async (text: string) => {
    stopVoice();
    if (!text || !text.trim()) return;
    const seq = speakSeqRef.current;
    setSpeaking(true);
    const ttsBlob = async (s: string): Promise<Blob> => {
      const r = await fetch("/api/public-tts", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ text: s.slice(0, 800), voice: "nova", speed: 1.05 }) });
      if (!r.ok) throw new Error("tts " + r.status);
      return r.blob();
    };
    try {
      const chunks = chunkForTTS(text.slice(0, 3000));
      if (!chunks.length) { setSpeaking(false); return; }
      let nextP: Promise<Blob> | null = ttsBlob(chunks[0]);
      for (let i = 0; i < chunks.length; i++) {
        let blob: Blob | null = null;
        try { blob = await nextP!; } catch { if (i === 0) throw new Error("tts-first"); break; }
        if (!blob) break;
        if (seq !== speakSeqRef.current) { setSpeaking(false); return; }
        nextP = i + 1 < chunks.length ? ttsBlob(chunks[i + 1]).catch(() => null as any) : null;
        const url = URL.createObjectURL(blob);
        const audio = new Audio(url);
        audioRef.current = audio;
        await new Promise<void>((resolve) => {
          audio.onended = () => { try { URL.revokeObjectURL(url); } catch {       } resolve(); };
          audio.onerror = () => { try { URL.revokeObjectURL(url); } catch {       } resolve(); };
          audio.onpause = () => resolve();
          if (seq !== speakSeqRef.current) { resolve(); return; }
          audio.play().catch(() => resolve());
        });
        if (seq !== speakSeqRef.current) { setSpeaking(false); return; }
        if (!nextP) break;
      }
      setSpeaking(false);
    } catch { setSpeaking(false); }
  };
  const startListening = () => {
    try {
      const SR = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
      if (!SR) return;
      stopVoice();
      const rec = new SR();
      recRef.current = rec;
      const langMap: Record<string, string> = { pt: "pt-BR", fr: "fr-FR", en: "en-GB", de: "de-DE", it: "it-IT" };
      rec.lang = langMap[lang] || "en-GB";
      rec.interimResults = false;
      rec.maxAlternatives = 1;
      rec.onresult = (e: any) => {
        const txt = (e.results?.[0]?.[0]?.transcript || "").trim();
        if (txt) { setInput(""); send(txt, true); }
      };
      rec.onend = () => setListening(false);
      rec.onerror = () => setListening(false);
      setListening(true);
      rec.start();
    } catch { setListening(false); }
  };
  const stopListening = () => { try { recRef.current?.stop(); } catch {       } setListening(false); };
  const toggleConvo = () => {
    const next = !convoRef.current;
    convoRef.current = next; setConvoMode(next);
    if (next) { startListening(); } else { stopListening(); stopVoice(); }
  };

  const send = async (override?: string, spoken?: boolean) => {
    const userText = (typeof override === "string" ? override : input).trim();
    if (!userText || typing) return;
    setMessages((m) => [...m, { from: "user", text: userText }]);
    setInput("");
    setTyping(true);
                                                                              
                                                                                                           
                                                                        
                                                                                                            
                                                                                                
    let botText = "";
    try {
                                                                                                            
                                                                                                            
                                                                                                                   
                                                                                                         
                                                          
      const history = messages.slice(-6).map((mm) => ({ role: (mm.from === "user" ? "user" : "assistant") as "user" | "assistant", content: mm.text }));
      const r = await fetch("/api/public-agent", {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ message: userText, brand: "abil", mode: "client", lang, langVariant: lang === "pt" ? "pt-BR" : undefined, history }),
      });
      const d = await r.json().catch(() => null);
      if (r.ok && d?.reply) botText = String(d.reply);
    } catch {                       }
    setTyping(false);
    const reply = botText || (({ pt: "O assistente esta indisponivel neste momento. Escreva para sam@abil.ch e respondemos em 48h.", en: "The site AI is unavailable right now. Check the key in AI Agent or email sam@abil.ch.", fr: "L IA du site est indisponible pour le moment. Verifie la cle dans Agent IA ou ecris a sam@abil.ch.", de: "Die Website-KI ist gerade nicht verfuegbar. Pruefe den Schluessel im AI Agent oder schreibe an sam@abil.ch.", it: "La IA del sito non e disponibile ora. Controlla la chiave in Agente IA o scrivi a sam@abil.ch." } as Record<string, string>)[lang] || "IA indisponivel.");
    setMessages((m) => [...m, { from: "bot", text: reply }]);
                                                                                                        
    if (spoken || convoRef.current) {
      await speakClient(reply);
      if (convoRef.current && open) { try { startListening(); } catch {       } }
    }
  };

  return (
    <>
      {                      }
      <button
        onClick={() => (open ? closeChat() : openChat())}
        className={`fixed bottom-6 right-6 z-[140] w-14 h-14 rounded-full bg-noir text-rouge ring-1 ring-rouge/50 shadow-2xl flex items-center justify-center hover:scale-105 transition-transform duration-300`}
        aria-label={t.chatbotWidget.ariaOpen}
      >
        {open ? (
          <span className="text-xl"></span>
        ) : (
          <Asterisque className="w-7 h-7" color="#d2ff01" />
        )}
      </button>

      {                 }
      {open && (
        <div className={`fixed bottom-24 right-6 z-[140] w-[468px] max-w-[calc(100vw-3rem)] h-[560px] max-h-[calc(100vh-8rem)] bg-white border border-neutral-200 shadow-2xl flex flex-col ${closingChat ? "fade-down-out" : "fade-up"}`}>
          {            }
          <div className="bg-noir text-white p-4 flex items-center gap-3">
            <div className="w-10 h-10 bg-rouge flex items-center justify-center flex-shrink-0">
              <Asterisque className="w-5 h-5" color="#ffffff" />
            </div>
            <div className="flex-1 min-w-0">
              <div className="font-semibold text-sm">ABiL Assistant</div>
              <div className="eyebrow text-white/60 flex items-center gap-1.5">
                <span className="w-1.5 h-1.5 bg-emerald-400 rounded-full" />
                {t.chatbotWidget.online}
              </div>
            </div>
            <button
              onClick={closeChat}
              aria-label={t.chatbotWidget.ariaClose}
              className="text-white/50 hover:text-white transition-colors duration-300 text-xl leading-none"
            >
              ×
            </button>
          </div>

          {              }
          <div className="flex-1 overflow-y-auto p-4 space-y-3 bg-neutral-50">
            {messages.map((m, i) => (
              <div
                key={i}
                className={`flex ${m.from === "user" ? "justify-end" : "justify-start"}`}
              >
                <div
                  className={`max-w-[88%] px-3.5 py-2.5 text-[13px] leading-relaxed ${
                    m.from === "user"
                      ? "bg-noir text-white"
                      : "bg-white border border-neutral-200 text-noir"
                  }`}
                >
                  {m.from === "user" ? m.text : <AgentRichText text={m.text} />}
                </div>
              </div>
            ))}
            {typing && (
              <div className="flex justify-start">
                <div className="bg-white border border-neutral-200 px-3.5 py-3">
                  <span className="inline-flex gap-1">
                    <span className="w-1.5 h-1.5 bg-neutral-400 rounded-full abil-dot" />
                    <span
                      className="w-1.5 h-1.5 bg-neutral-400 rounded-full abil-dot"
                      style={{ animationDelay: "0.15s" }}
                    />
                    <span
                      className="w-1.5 h-1.5 bg-neutral-400 rounded-full abil-dot"
                      style={{ animationDelay: "0.3s" }}
                    />
                  </span>
                </div>
              </div>
            )}
            <div ref={msgsEndRef} />
          </div>

          {                      }
          <div className="px-4 py-2 bg-neutral-50 border-t border-neutral-200 eyebrow eyebrow-xs text-neutral-500 text-center">
            {t.chatbotWidget.footer}
          </div>

          {                           }
          <form
            onSubmit={(e) => {
              e.preventDefault();
              send();
            }}
            className="p-3 border-t border-neutral-200 flex items-end gap-1.5 bg-white"
          >
            <button
              type="button"
              onClick={() => (listening ? stopListening() : startListening())}
              aria-label={listening ? vl.stopHear : vl.talk}
              title={listening ? vl.stopHear : vl.talk}
              className={`w-9 h-9 flex-shrink-0 rounded-md flex items-center justify-center transition-colors duration-300 ${listening ? "bg-rose-500 text-white animate-pulse" : "bg-neutral-100 text-neutral-500 hover:text-ink"}`}
            >
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M12 2a3 3 0 0 0-3 3v7a3 3 0 0 0 6 0V5a3 3 0 0 0-3-3z"/><path d="M19 10v2a7 7 0 0 1-14 0v-2"/><path d="M12 19v3"/></svg>
            </button>
            <button
              type="button"
              onClick={toggleConvo}
              aria-label={convoMode ? vl.convoOff : vl.convoOn}
              title={convoMode ? vl.convoOff : vl.convoOn}
              className={`w-9 h-9 flex-shrink-0 rounded-md flex items-center justify-center transition-colors duration-300 ${convoMode ? "bg-rouge text-white" : "bg-neutral-100 text-neutral-500 hover:text-ink"}`}
            >
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"><path d="M4 12h1.5M9 7v10M14 4v16M19 9v6M21.5 11v2"/></svg>
            </button>
            <textarea
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === "Enter" && !e.shiftKey) {
                  e.preventDefault();
                  send();
                }
              }}
              onFocus={() => setInputFocused(true)}
              onBlur={() => setInputFocused(false)}
              rows={inputFocused || input.trim() ? 2 : 1}
              placeholder={t.chatbotWidget.inputPlaceholder}
              className="flex-1 resize-none border border-neutral-300 px-3 py-2 text-sm leading-snug focus:outline-none focus:border-rouge transition-colors duration-300"
            />
            {speaking ? (
              <button
                type="button"
                onClick={stopVoice}
                aria-label={vl.stopV}
                title={vl.stopV}
                className="w-9 h-9 flex-shrink-0 rounded-md bg-neutral-800 text-white flex items-center justify-center hover:bg-neutral-700 transition-colors duration-300"
              >
                <svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor"><rect x="6" y="6" width="12" height="12" rx="1.5"/></svg>
              </button>
            ) : (
              <button
                type="submit"
                disabled={!input.trim() || typing}
                className="w-9 h-9 flex-shrink-0 rounded-md bg-rouge text-white flex items-center justify-center text-lg hover:bg-noir transition-[background-color,opacity] duration-300 disabled:opacity-40"
              >
                →
              </button>
            )}
          </form>
        </div>
      )}
    </>
  );
}

                                                                                        
                                                                                        
                                                                                          
                                                                                           
                                                                                      
function abrirLegalV3(alvo: "confidentialite" | "conditions", setView: (v: View) => void) {
  if (typeof window === "undefined") return;
  const path = `/v3/${alvo}`;
  if (window.location.pathname !== path) window.history.pushState({}, "", path);
  window.dispatchEvent(new PopStateEvent("popstate"));
  setView("homev3");
  window.scrollTo({ top: 0, behavior: "instant" as ScrollBehavior });
}

function CookieBanner() {
  const { t, setView } = useApp();
  const [show, setShow] = useState(() => {
    try {
      const saved = localStorage.getItem("abil_cookies_v1");
      return !saved;
    } catch {
      return true;
    }
  });
  const [details, setDetails] = useState(false);
  const [leaving, setLeaving] = useState(false);
  const [analytics, setAnalytics] = useState(false);
  const [marketing, setMarketing] = useState(false);
                                                                                                     
  const tc = t.cookies as Record<string, string>;
  const lbl = (k: string, fb: string) => tc[k] ?? fb;
  const save = (cfg: { analytics: boolean; marketing: boolean }) => {
    try {
      localStorage.setItem(
        "abil_cookies_v1",
        JSON.stringify({ essential: true, analytics: cfg.analytics, marketing: cfg.marketing, ts: new Date().toISOString() }),
      );
    } catch {            }
    setLeaving(true);
    window.setTimeout(() => setShow(false), 340);
  };
  if (!show) return null;
  return (
    <div role="dialog" aria-label="Cookies" className={`fixed bottom-0 left-0 right-0 z-[120] bg-noir text-white px-6 py-5 border-t border-white/10 ${leaving ? "fade-down-out" : "fade-up"}`}>
      <div className="mx-auto max-w-[1480px] flex flex-col gap-4">
        <div className="flex items-start gap-3">
          <Asterisque className="w-4 h-4 flex-shrink-0 mt-0.5" color="#d2ff01" />
          <p className="text-sm flex-1 leading-snug">
            {t.cookies.text}{" "}
            <button type="button" onClick={() => abrirLegalV3("confidentialite", setView)} className="underline text-rouge hover:text-white transition-colors duration-300">
              {lbl("privacy", "Privacy")}
            </button>{" "}
            ·{" "}
            <button type="button" onClick={() => setView("cookies")} className="underline text-rouge hover:text-white transition-colors duration-300">
              {lbl("details", "Cookie details")}
            </button>
          </p>
        </div>
        <div style={{ display: "grid", gridTemplateRows: details ? "1fr" : "0fr", marginTop: details ? 0 : -16, transition: "grid-template-rows var(--ab-d-reveal) var(--ab-e-out), margin-top var(--ab-d-reveal) var(--ab-e-out)" }}>
        <div style={{ overflow: "hidden", minHeight: 0 }}>
        {details && (
          <div className="border-t border-b border-white/10 py-3 flex flex-col gap-2 text-sm">
            <label className="flex items-center gap-2 text-white/60">
              <input type="checkbox" checked disabled /> {lbl("essentialsLabel", "Essential (required)")}
            </label>
            <label className="flex items-center gap-2 cursor-pointer">
              <input type="checkbox" checked={analytics} onChange={(e) => setAnalytics(e.target.checked)} /> {lbl("analyticsLabel", "Analytics")}
            </label>
            <label className="flex items-center gap-2 cursor-pointer">
              <input type="checkbox" checked={marketing} onChange={(e) => setMarketing(e.target.checked)} /> {lbl("marketingLabel", "Marketing / third-party")}
            </label>
          </div>
        )}
        </div>
        </div>
        <div className="flex flex-wrap justify-end gap-2 text-xs">
          {!details && (
            <button
              type="button"
              onClick={() => setDetails(true)}
              className="border border-white/30 text-white px-5 py-2.5 eyebrow hover:border-white hover:bg-white/5 transition-colors duration-300"
            >
              {lbl("customize", "Customize")}
            </button>
          )}
          <button
            type="button"
            onClick={() => save({ analytics: false, marketing: false })}
            className="border border-white/30 text-white px-5 py-2.5 eyebrow hover:border-white hover:bg-white/5 transition-colors duration-300"
          >
            {t.cookies.decline}
          </button>
          <button
            type="button"
            onClick={() => save(details ? { analytics, marketing } : { analytics: true, marketing: true })}
            className="bg-rouge text-white px-5 py-2.5 eyebrow hover:bg-white hover:text-noir transition-colors duration-300"
          >
            {details ? lbl("save", "Save") : t.cookies.accept}
          </button>
        </div>
      </div>
    </div>
  );
}

                                                                                                                                          
                                                
                                                                                                                                             
